(1, 'BCS-52-FREE', 'bcs-52-preliminary', '52nd BCS Preliminary', '৫২তম বিসিএস প্রিলিমিনারি', 'ফ্রি এক্সাম ব্যাচ', 'বিষয়: বিগত বিসিএস প্রশ্নের উপর ফ্রি মডেল  টেস্ট', NULL, NULL, NULL, NULL, 'bn', NULL, 'BCS', '৮0%', 5, 'ভর্তি চলছে...', 'linear-gradient(135deg,#00693e 0%,#0a8f55 100%)', 1, 1, 3, 6, 500.00, 100.00, 30, 0, 1, NULL, NULL, 'N', 'admin', '2026-10-07', '2026-10-07 11:35:36', 'admin', '2026-10-07', 'softadmin', NULL, NULL, 90),
(2, 'BCS-52-PAID', 'bcs-52-paid', '52nd BCS Preliminary', '৫২তম বিসিএস প্রিলিমিনারি', 'পেইড এক্সাম ব্যাচ', 'বিষয়: বিসিএস মডেল  টেস্ট', 'বিগত ৫২তম বিসিএস প্রিলিমিনারি পরীক্ষার উপর মডেল টেস্ট সিরিজ।', 'এই কোর্সে থাকছে ৫২তম বিসিএস প্রিলিমিনারি পরীক্ষার উপর ভিত্তি করে সাজানো মডেল টেস্ট। প্রতিটা টেস্টে থাকবে বাস্তবসম্মত প্রশ্ন, সময়সীমা, ও বিশ্লেষণ।', NULL, NULL, 'bn', NULL, 'BCS', '৮০%', 5, 'ভর্তি চলছে...', 'linear-gradient(135deg,#7a1122 0%,#a31528 100%)', 1, 1, 3, 3, 500.00, 100.00, 0, 0, 1, NULL, NULL, 'Y', 'admin', '2026-10-07', '2026-10-07 22:10:06', 'admin', '2026-10-07', 'softadmin', NULL, NULL, 90),
(3, 'HSC-ICT-FREE', 'hsc-ict-free', 'HSC ICT', 'এইচএসসি আইসিটি', 'এক্সাম ব্যাচ', 'বিষয়: বিগত আইসিটি বোর্ড প্রশ্নের উপর পরীক্ষা', 'এইচএসসি আইসিটি বোর্ড প্রশ্নের উপর ফ্রি পরীক্ষা।', 'এইচএসসি আইসিটি বিষয়ের বিগত বোর্ড প্রশ্নের উপর ভিত্তি করে সাজানো পরীক্ষা। সম্পূর্ণ বিনামূল্যে।', NULL, NULL, 'bn', NULL, 'HSC', '০%', 5, 'ভর্তি চলছে...', 'linear-gradient(135deg,#0a3d62 0%,#1565a0 100%)', 2, 1, 7, 3, 0.00, NULL, 0, 0, 1, NULL, NULL, 'Y', 'admin', '2026-10-07', '2026-10-07 22:10:06', 'admin', NULL, NULL, NULL, NULL, 90),
