INSERT INTO `questions` (`id`, `topic_id`, `question`, `option_a`, `image_url_option_a`, `option_b`, `image_url_option_b`, `option_c`, `image_url_option_c`, `option_d`, `image_url_option_d`, `correct_option`, `explanation`, `explanation_image_url`, `referance_exam_id`, `exam_reference`, `BR_CODE`, `ORG_CODE`, `AUTHORIZED_STATUS`, `AUTHORIZED_USER`, `AUTHORIZED_DATE`, `ENTRY_DATE`, `ENTRY_USER`, `EDIT_DATE`, `EDIT_USER`, `DELETE_USER`, `DELETE_DATE`, `upload_process_id`, `exam_year`, `exam_date`, `exam_taker`, `remarks`, `image_url`, `question_hash`) VALUES
(17, 18, 'Cellular Data Network এর ক্ষেত্রে GPRS বলতে কী বুঝায়?', 'Global Positioning Radio Service', NULL, 'General Positioning Radio Service', NULL, 'Global Packet Radio Service', NULL, 'General Packet Radio Service', NULL, 'D', 'GPRS (General Packet Radio Service) চালু হয় 2G (second generation) মোবাইল ফোন প্রজন্মে। 2G প্রযুক্তি মূলত ডিজিটাল টেলিকমিউনিকেশন ব্যবস্থা হিসাবে পরিচিত এবং এর মাধ্যমে GSM (Global System for Mobile Communications) নেটওয়ার্কের উন্নতি সাধন করা হয়েছিল। GPRS প্রযুক্তি 2G নেটওয়ার্কের সাথে ইন্টিগ্রেটেড হয়ে মোবাইল ফোনে ডেটা সার্ভিস প্রদান করে, যা মূলত ইন্টারনেট অ্যাক্সেস, ইমেইল, এবং মাল্টিমিডিয়া মেসেজিং সার্ভিস (MMS) এর সুবিধা দেয়।', NULL, NULL, NULL, '100-100', '100', 'N', 'softadmin', '2026-06-02', NULL, NULL, NULL, NULL, NULL, NULL, '0', 0, NULL, NULL, NULL, NULL, '0293313e77054cea57bcafeae7c8fc40'),
(235, 23, 'A Terabyte is equal to', '1024 Megabytes', NULL, '1024 Kilobytes', NULL, '1024 Gigabytes', NULL, '1024 Bits', NULL, 'C', 'Computer memory units are typically powers of 2. $1 \\text{ Terabyte (TB)} = 1024 \\text{ Gigabytes (GB)}$.', NULL, NULL, 'Combined 9 Bank & FI - SO\'23', '100-100', '100', 'N', 'softadmin', '2026-05-28', '2025-12-11', 'softadmin', '2026-05-28', 'softadmin', NULL, NULL, 'UPL-100-100-20251211101512-1648', 2023, '0000-00-00', '', '', NULL, 'b2adfbc1a99e3a2c1a09bbb64b4d89bd'),
(236, 23, 'A Gigabyte is equal to', '1024 Bytes', NULL, '1024 Kilobytes', NULL, '1024 Megabytes', NULL, '1024 Terabytes', NULL, 'C', '$1 \\text{ Gigabyte (GB)} = 1024 \\text{ Megabytes (MB)}$.', NULL, NULL, 'Combined Bank Exam - Officer Cash \'23', '100-100', '100', 'N', 'softadmin', '2026-05-28', '2025-12-11', 'softadmin', NULL, NULL, NULL, NULL, 'UPL-100-100-20251211101512-1648', 0, NULL, NULL, NULL, NULL, 'e153fda9f2962b96a0eae1c46b7466a8'),
(237, 23, 'Which of the following is correct?', '1 Kilobyte = 1024 bytes', NULL, '1 Megabyte = 1024 bytes', NULL, '1 Kilobyte = 1000 bytes', NULL, '1 megabyte = 1000 bytes', NULL, 'A', 'In computing, standard binary prefixes are used: $1 \\text{ Kilobyte (KB)} = 1024 \\text{ Bytes (B)}$. (Note: In some contexts, particularly networking, 1000 may be used, but 1024 is the standard for storage/memory.)', NULL, NULL, 'Janata Bank PLC - Rural Credit \'23', '100-100', '100', 'N', NULL, NULL, '2025-12-11', 'softadmin', NULL, NULL, NULL, NULL, 'UPL-100-100-20251211101512-1648', 0, NULL, NULL, NULL, NULL, '9fcc91197bdf76ce5e9dc4e38495b2fa'),
(238, 23, 'One Tera Byte equal to how many bytes?', '10^9Bytes', NULL, '10^12Bytes', NULL, '10^15 Bytes', NULL, '10^18 Bytes', NULL, 'B', 'While $1 \\text{ TB}$ is $1024^4$ Bytes exactly, $1 \\text{ TB}$ is also commonly approximated as $10^{12}$ Bytes (or $1$ trillion bytes) in the decimal sense used for hard drive marketing. The options suggest the decimal (SI) definition, where $1 \\text{ TB} = 10^{12} \\text{ Bytes}$.', NULL, NULL, 'Bangladesh Bank - AD \'22', '100-100', '100', 'N', NULL, NULL, '2025-12-11', 'softadmin', '2025-12-11', 'softadmin', NULL, NULL, 'UPL-100-100-20251211101512-1648', 0, NULL, NULL, NULL, NULL, '439bcac946918273c20fed77de40a812'),
(239, 23, 'The smallest unit in a digital system is a', 'Byte', NULL, 'Bit', NULL, 'Character', NULL, 'Kilobyte', NULL, 'B', 'A Bit is the smallest unit, representing a binary 0 or 1, which forms the basis of all digital data.', NULL, NULL, 'Bangladesh Bank - Officer Cash \'23', '100-100', '100', 'N', NULL, NULL, '2025-12-11', 'softadmin', NULL, NULL, NULL, NULL, 'UPL-100-100-20251211101512-1648', 0, NULL, NULL, NULL, NULL, '0f891523e6535d832de9f9e254ceb3cd'),
(240, 23, 'The smallest unit of data in a computer', 'Byte', NULL, 'Bit', NULL, 'Nibble', NULL, 'Word', NULL, 'B', 'A Bit (Binary Digit) is the fundamental and smallest unit of data, representing a 0 or a 1. A Byte is typically 8 Bits.', NULL, NULL, 'Combined 8 Bank Exam - SO \'25', '100-100', '100', 'N', 'softadmin', '2026-05-28', '2025-12-11', 'softadmin', NULL, NULL, NULL, NULL, 'UPL-100-100-20251211101554-8945', 0, NULL, NULL, NULL, NULL, '2cbc2a5894353170bfd93db6a06dc32c'),
