(2632, 39, 'উদ্দীপক:\r\nক্লাসে গ্রিনহাউস ইফেক্ট নিয়ে একটি প্রতিবেদন তৈরি করতে বলা হলো। মুনিম সময়মতো প্রতিবেদন তৈরি করে জমা দিল। কিন্তু শিক্ষক তার বিরুদ্ধে প্লেজিয়ারিজমের অভিযোগ তুললেন। প্রশ্নঃ মুনিম যে অপরাধটি করেছে তা শনাক্ত করা যায় কোনটির সাহায্যে?', 'হার্ডওয়্যার', NULL, 'সফটওয়্যার', NULL, 'কার্ড রিডার', NULL, 'OMR', NULL, 'B', NULL, NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '76fdc757608ef4ceaad7406fe59ac159'),
(2633, 39, 'উদ্দীপক: ক্লাসে গ্রিনহাউস ইফেক্ট নিয়ে একটি প্রতিবেদন তৈরি করতে বলা হলো। মুনিম সময়মতো প্রতিবেদন তৈরি করে জমা দিল। কিন্তু শিক্ষক তার বিরুদ্ধে প্লেজিয়ারিজমের অভিযোগ তুললেন। প্রশ্নঃ মুনিমের অপরাধটি এখন প্রায়ই হচ্ছে, কারণ— i. তথ্যের সহজলভ্যতা ii. এ বিষয়ে অজ্ঞতা iii. তথ্যপ্রযুক্তির অবাধ স্বাধীনতা নিচের কোনটি সঠিক?', 'i ও ii', NULL, 'i ও iii', NULL, 'ii ও iii', NULL, 'i, ii ও iii', NULL, 'D', '', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', '2026-08-05', 'softadmin', NULL, NULL, '1', 2026, '0000-00-00', 'e360', '', NULL, '67e04f1ba6a3a759403d9f73bdb56b5b'),
(3483, 389, 'সার্ক-এর প্রথম শীর্ষ বৈঠক অনুষ্ঠিত হয়–', '১৯৮৪ সালে', NULL, '১৯৮৭ সালে', NULL, '১৯৮৫ সালে', NULL, '১৯৮৬ সালে', NULL, 'C', 'দক্ষিণ এশীয় সহযোগিতা সংস্থা সার্ক-এর প্রথম শীর্ষ বৈঠক ১৯৮৫ সালের ৭-৮ ডিসেম্বর ঢাকায় অনুষ্ঠিত হয়। উল্লেখ্য, ২০১৬ সালে ১৯তম সম্মেলন পাকিস্তানের অনুষ্ঠিত হওয়ার কথা থাকলেও তা স্থগিত করা হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '92209776499460c07a7a0bc46dcb8996'),
(3484, 390, 'আরব রাষ্ট্রগুলোর মধ্যে কোনটি বাংলাদেশকে প্রথম স্বীকৃতি দেয়?', 'ইরাক', NULL, 'আলজেরিয়া', NULL, 'সৌদি আরব', NULL, 'জর্ডান', NULL, 'A', 'আরব রাষ্ট্রগুলোর মধ্যে প্রথম বাংলাদেশকে স্বীকৃতি দেয় ইরাক (৮ জুলাই, ১৯৭২)। আলজেরিয়া বাংলাদেশকে স্বীকৃতি দেয় ১৩ জুলাই, ১৯৭৩ এবং সৌদি আরব স্বীকৃতি দেয় ১৬ আগস্ট, ১৯৭৫।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '232a809426b70d13cab944e369ed7364'),
(3485, 395, 'পিএলও-এর সদর দপ্তর–', 'তিউনিস', NULL, 'রাবাত', NULL, 'বেনগাজি', NULL, 'মরক্কো', NULL, 'A', 'বর্তমানে পিএলও’র সদর দপ্তর ফিলিস্তিনের রামাল্লায় অবস্থিত। ইসরাইল ১৯৬৪ সালে PLO’র ওপর হামলা চালালে এর সদর দপ্তর তিউনিসিয়ার তিউনিসে স্থানান্তর করা হয়েছিল।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4f2fcb7a18e2a459e7f024c29530edfb'),
(3486, 391, 'জাতিসংঘের প্রথম মহাসচিব ছিলেন–', 'উ থান্ট', NULL, 'ট্রিগভেলি', NULL, 'দ্যাগ হ্যামারশোল্ড', NULL, 'কুট ওয়াল্ডহেইম', NULL, 'B', 'জাতিসংঘের নির্বাচিত প্রথম মহাসচিব হলেন ট্রিগভেলি। তিনি নরওয়ের অধিবাসী। দ্যাগ হ্যামারশোল্ড, উ থান্ট ও কুট ওয়াল্ডহেইম যথাক্রমে দ্বিতীয়, তৃতীয় ও চতুর্থ মহাসচিব ছিলেন। উল্লেখ্য, জাতিসংঘের বর্তমান মহাসচিব পর্তুগালের সাবেক প্রধানমন্ত্রী অ্যান্টেনিও গুতেরেস।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8c6e87124b53582e509af9c367cca923'),
(3487, 393, 'নিরাপত্তা পরিষদের এশীয় আসনে বাংলাদেশের প্রতিদ্বন্দ্বী ছিল–', 'ফিলিপাইন', NULL, 'জাপান', NULL, 'ইন্দোনেশিয়া', NULL, 'থাইল্যান্ড', NULL, 'B', '১৯৭৮ সালে নিরাপত্তা পরিষদের অস্থায়ী আসনে বাংলাদেশ শক্তিশালী জাপানের সাথে প্রতিদ্বন্দ্বিতা করে এবং জয়লাভ করে। অবশ্য ২০০০-২০০১ সালের জন্য বাংলাদেশ বিনা প্রতিদ্বন্দ্বিতায় অস্থায়ী সদস্য নির্বাচিত হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9c7a7ef0d4d8c5935f2665a175fa38d6'),
(3488, 391, 'সাধারণ পরিষদের নিয়মিত অধিবেশন শুরু হয়–', 'সেপ্টেম্বর মাসের তৃতীয় মঙ্গলবার', NULL, 'সেপ্টেম্বর মাসের প্রথম সোমবার', NULL, 'সেপ্টেম্বর মাসের দ্বিতীয় বুধবার', NULL, 'সেপ্টেম্বর মাসের চতুর্থ মঙ্গলবার', NULL, 'A', 'জাতিসংঘ সাধারণ পরিষদের নিয়মিত বার্ষিক অধিবেশন শুরু হয় প্রতি বছর সেপ্টেম্বর মাসের তৃতীয় মঙ্গলবার এবং মধ্য ডিসেম্বর পর্যন্ত তা চলে। নিয়মিত অধিবেশন ছাড়াও সাধারণ পরিষদ জরুরি অধিবেশন ও বিশেষ অধিবেশনে মিলিত হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '184863faac29f9155a6f33078150a1b3'),
(3489, 391, 'বর্তমান জাতিসংঘের সদস্য সংখ্যা–', '১৫৬', NULL, '১৫৭', NULL, '১৫৮', NULL, '১৯৩', NULL, 'D', 'বর্তমান জাতিসংঘের সদস্য ১৯৩ এবং সর্বশেষ সদস্য রাষ্ট্র হলো দক্ষিণ সুদান (সদস্যপদ লাভ ১৪ জুলাই, ২০১১)।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c29491aeaa9a58ebdb2672745dbe0b11'),
(3490, 395, 'ইসলাম সম্মেলন সংস্থার সচিবালয় অবস্থিত–', 'রিয়াদ', NULL, 'জেদ্দা', NULL, 'দামেস্ক', NULL, 'মক্কা', NULL, 'B', '২৫ সেপ্টেম্বর, ১৯৬৯ মরক্কোর রাজধানী রাবাতে OIC গঠিত হয় এবং সদর দপ্তর সৌদি আরবের জেদ্দাতে প্রতিষ্ঠিত হয়। উল্লেখ্য, ইসলামী সম্মেলন সংস্থার বর্তমান নাম ইসলামী সহযোগীতা সংস্থা।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '705b8168b173b3bab9150c116479dbd6'),
(3491, 397, 'যে দেশ এসডিআই প্রতিরক্ষা কর্মসূচি গ্রহণ করেছে–', 'ব্রিটেন', NULL, 'ফ্রান্স', NULL, 'যুক্তরাষ্ট্র', NULL, 'রাশিয়া', NULL, 'C', '১৯৮৩ সালে মার্কিন যুক্তরাষ্ট্র কৌশলগত প্রতিরক্ষা কর্মসূচি বা Strategic Defence Initiative কর্মসূচি ঘোষণা করে। মার্কিন সিনেটর অ্যাডওয়ার্ড কেনেডি একে তারকা যুদ্ধ (Star war) বলে অভিহিত করেন।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '71c38644f15a24647f74c1bb1ba36b68'),
(3492, 391, 'ব্রিটেনের প্রশাসনিক সদর দপ্তরকে বলা হয়–', 'ওয়েস্ট মিনিস্টার অ্যাবে', NULL, 'হোয়াইট হল', NULL, 'মার্বেল চার্চ', NULL, 'বুশ হাউজ', NULL, 'B', 'ব্রিটেনের প্রশাসনিক সদর দপ্তর হোয়াইট হল লন্ডনে অবস্থিত। এটি ব্রিটেনের রানীর সাবেক সরকারি বাসভবন। ওয়েস্ট মিনিস্টার অ্যাবে বিখ্যাত ব্রিটিশ নাগরিকদের সমাধিস্থল। বুশ হাউজ বিবিসি’র সাবেক প্রধান কার্যালয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c0592b2769498c67cd608ca7dd36df89'),
(3493, 389, 'দ্বিতীয় মহাযুদ্ধে জার্মানি আত্মসমর্পণ করে–', '১৯৪২ সালের নভেম্বর মাসে', NULL, '১৯৪৩ সালের ফেব্রুয়ারি মাসে', NULL, '১৯৪৫ সালের মে মাসে', NULL, '১৯৪৫ সালের সেপ্টেম্বর মাসে', NULL, 'C', '১৯৪৫ সালের ৩০ এপ্রিল হিটলার আত্মহত্যা করলে জার্মানির পতন ঘটে। তবে আনুষ্ঠানিকভাবে জার্মানি ৭ মে, ১৯৪৫ সোভিয়েত জেনারেল জর্জ জোকভের নিকট আত্মসমর্পন করে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cc19a5c4266a2e91a208fbabda3f4b4c'),
(3494, 390, 'কঙ্গোকে বিদেশি শাসন থেকে মুক্ত করার লড়াইয়ে চিরস্থায়ী নাম–', 'কাশাভুবু', NULL, 'প্যাট্রিক লুমুম্বা', NULL, 'শোম্বে', NULL, 'মবুতু', NULL, 'B', 'কঙ্গোতে দখলদার ঔপনিবেশিক শক্তির বিরুদ্ধে জাতীয়তাবাদ আন্দোলনে নেতৃত্ব দেন প্যাট্রিক লুমুম্বা। তিনি জয়লাভ করলে কঙ্গো স্বাধীন রাষ্ট্রে পরিণত হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2d41bf511f3b2dcdc67f5bce97a9390b'),
(3495, 389, 'হিরোশিমায় এটম বোম ফেলা হয়েছিল–', '১৯৪৫ সালের আগস্ট মাসে', NULL, '১৯৪৫ সালের মে মাসে', NULL, '১৯৪৫ সালের সেপ্টেম্বর মাসে', NULL, '১৯৪৪ সালের আগস্ট মাসে', NULL, 'A', 'মার্কিন যুক্তরাষ্ট্র ১৯৪৫ সালের ৬ আগস্ট হিরোশিমায় ‘লিটলবয়’ এবং ৯ আগস্ট নাগাসাকিতে ‘ফ্যাটম্যান’ বোমার বিস্ফোরণ ঘটালে জাপানের পতন ত্বরান্বিত হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7e890c9ce7965f20763c57b7379e8ce7'),
(3496, 412, 'আইএমএফ-এর সদর দপ্তর কোথায়?', 'ওয়াশিংটন', NULL, 'মস্কো', NULL, 'লন্ডন', NULL, 'নিউইয়র্ক', NULL, 'A', 'IMF (International Monetary Fund)-এর সদর দপ্তর যুক্তরাষ্ট্রের ওয়াশিংটন ডিসিতে। ১-২২ জুলাই, ১৯৪৪ ব্রেটন উডসের জাতিসংঘ মনিটারি এন্ড ফিনান্সিয়াল কনফারেন্সে IMF গঠিত হয়। কার্যক্রম শুরু করে ১৯৪৭ সালের ১ মার্চ থেকে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '278313a12b5e6ab0f9f186775fe50216'),
(3497, 393, 'নিকারাগুয়ায় যে বিদ্রোহীদের যুক্তরাষ্ট্র সমর্থন করে তার নাম–', 'ইউনিটা', NULL, 'সান্ডিনিস্টা', NULL, 'কন্ট্রা', NULL, 'সোয়াপো', NULL, 'C', 'মধ্য আমেরিকার হ্রদ ও আগ্নেয়গিরির দেশ নিকারাগুয়ার বিদ্রোহী গ্রুপ কন্ট্রা মার্কিন যুক্তরাষ্ট্রের সমর্থনপুষ্ট। ১৯৯০ সালে জাতিসংঘের নিরাপত্তা পরিষদ এ অঞ্চলে শান্তি আনয়নে গঠন করে মধ্য আমেরিকায় জাতিসংঘ পর্যবেক্ষক দল (ONUCA) এবং পর্যবেক্ষক দলটি কন্ট্রা বিদ্রোহীদের স্বেচ্ছা তদারক করে। ফলশ্রুতিতে হন্ডুরাস ও নিকারাগুয়ায় প্রায় ২২ হাজার কন্ট্রা বিদ্রোহী জাতিসংঘ পর্যবেক্ষকদের কাছে অস্ত্র সমর্পণ করে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd465d5f2e7741199f48f19714ebf352f'),
(3498, 394, '‘ব্যাবিলনের ঝুলন্ত উদ্যান’ কোন দেশে অবস্থিত?', 'ইরান', NULL, 'ইরাক', NULL, 'মিশর', NULL, 'সিরিয়া', NULL, 'B', '‘ব্যাবিলনের ঝুলন্ত উদ্যান’ ইরাকে অবস্থিত। রাজা নেবুচাদনেজার তার স্ত্রীর মনোরঞ্জনের জন্য প্রায় ৩০০ মিটার উঁচু এ উদ্যান নির্মাণ করেন।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a7874e07fe80bc98043009c37b24e7eb'),
(3499, 394, 'ইতিহাস বিখ্যাত ট্রয় নগরী কোথায়?', 'ইতালি', NULL, 'স্পেন', NULL, 'তুরস্ক', NULL, 'গ্রিস', NULL, 'C', 'ইতিহাস বিখ্যাত ট্রয় নগরী তুরস্কে অবস্থিত। ট্রয় নগরীর সাথে মহাবীর হেক্টরের বীরত্ব ও আত্মত্যাগের ইতিহাস জড়িয়ে আছে। সুন্দরী হেলেনকে কেন্দ্র করে সংঘটিত এ যুদ্ধে হেক্টরকে পরাস্ত করে গ্রিকরা ট্রয় দখল করে আগুন ধরিয়ে দেয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1f69d80d7c51c86845559ef605a98870'),
(3500, 412, 'আন্তর্জাতিক আণবিক শক্তি সংস্থা (IAEA) এর সদর দপ্তর–', 'ভিয়েনা', NULL, 'বন', NULL, 'জেনেভা', NULL, 'রোত', NULL, 'A', 'আন্তর্জাতিক আণবিক শক্তি সংস্থা প্রতিষ্ঠিত হয় ২৯ জুলাই, ১৯৫৭। এটি জাতিসংঘের অন্তর্ভুক্ত হয় ১৪ নভেম্বর ১৯৫৭। এর সদর দপ্তর অস্ট্রিয়ার রাজধানী ভিয়েনায়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9d19b1e9fe8731f2d9af182823da093e'),
(3501, 391, 'জাপানের পার্লামেন্টের নাম–', 'ডায়েট', NULL, 'পিনসাস', NULL, 'নেসেট', NULL, 'শুরা', NULL, 'A', 'জাপানের পার্লামেন্টের নাম ডায়েট, নেসেট ইসরাইলের পার্লামেন্টের নাম। সৌদি কনসালটেটিভ অ্যাসেম্বলি (মজলিস আল শুরা আল সৌদ) হলো সৌদি আরবের এবং কনসালটেটিভ অ্যাসেম্বলি (মজলিশ-আল শুরা) কাতারের পার্লামেন্টের নাম।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b51aa21f94ba865a1d1864870e2ca959'),
(3502, 394, 'আমেরিকাকে এশিয়া থেকে পৃথক করেছে কোন প্রণালী?', 'ফ্লোরিডা', NULL, 'পক', NULL, 'জিব্রাল্টার', NULL, 'বেরিং', NULL, 'D', 'বেরিং প্রণালী পৃথক করেছে আমেরিকা ও এশিয়া মহাদেশকে এবং সংযুক্ত করেছে উত্তর সাগর ও বেরিং সাগর তথা প্রশান্ত মহাসাগরকে। ফ্লোরিডা প্রণালী কিউবাকে ফ্লোরিডা থেকে পৃথক করেছে। পক প্রণালী শ্রীলংকাকে ভারত থেকে পৃথক করেছে। জিব্রাল্টার প্রণালী স্পেনকে (ইউরোপ) মরক্কো (আফ্রিকা) থেকে পৃথক করেছে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '651de94c1e5af3d55fb4d76555682084'),
(3503, 391, 'সাউথ কমিশনের চেয়ারম্যান–', 'জেনারেল সুহার্তো', NULL, 'রবার্ট মুগাবে', NULL, 'জুলিয়াস নায়ারে', NULL, 'ফিডেল ক্যাস্ট্রো', NULL, 'C', 'বিশ্বের দক্ষিণের ২৮টি দেশ তাদের স্বার্থ সংশ্লিষ্ট বিষয়ে সমন্বয় সাধনের জন্য ১৯৮৬ সালে জিম্বাবুয়ের রাজধানী হারারেতে বৈঠক করে, যা ১৯৮৭ সালে ‘সাউথ কমিশন’ নামে সাংগঠনিক রূপ লাভ করে। তাঞ্জানিয়ার সাবেক প্রেসিডেন্ট জুলিয়াস কে নায়ারে এ কমিশনের প্রতিষ্ঠাতা সভাপতি ছিলেন। বর্তমানে সাউথ কমিশনের পরিবর্তিত রূপ হলো সাউথ সেন্টার, যা আফ্রিকা, এশিয়া, ল্যাটিন আমেরিকা ও ক্যারিবিয়ান অঞ্চলের ৫৪টি উন্নয়নশীল রাষ্ট্র নিয়ে গঠিত। এ সংগঠনের বর্তমান চেয়ারপার্সন থাবো মভায়েলা এমবেকি (দ. আফ্রিকা) ও নির্বাহী পরিচালক কার্লোস এম. কোরেয়া।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b6b7ab91cd4b405d2baf172088bf76d8');
INSERT INTO `questions` (`id`, `topic_id`, `question`, `option_a`, `image_url_option_a`, `option_b`, `image_url_option_b`, `option_c`, `image_url_option_c`, `option_d`, `image_url_option_d`, `correct_option`, `explanation`, `explanation_image_url`, `referance_exam_id`, `exam_reference`, `BR_CODE`, `ORG_CODE`, `AUTHORIZED_STATUS`, `AUTHORIZED_USER`, `AUTHORIZED_DATE`, `ENTRY_DATE`, `ENTRY_USER`, `EDIT_DATE`, `EDIT_USER`, `DELETE_USER`, `DELETE_DATE`, `upload_process_id`, `exam_year`, `exam_date`, `exam_taker`, `remarks`, `image_url`, `question_hash`) VALUES
(3504, 406, 'আন্তর্জাতিক পরিবেশ দিবস পালিত হয়–', '৭ জুলাই', NULL, '৯ মার্চ', NULL, '৫ জুন', NULL, '২১ মে', NULL, 'C', '৫ জুন বিশ্ব পরিবেশ দিবস। ১৯৭২ সালের জুনে সুইডেনের স্টকহোমে অনুষ্ঠিত মানব পরিবেশের ওপর প্রথম জাতিসংঘ সম্মেলনে পরিবেশ বিষয়ে ব্যাপক আলোচনার সূত্রপাত ঘটে। এর প্রেক্ষিতে বিশ্বব্যাপী জনসচেতনতা সৃষ্টির লক্ষ্যে জাতিসংঘের সাধারণ পরিষদের ২৭তম অধিবেশনে প্রতি বছর ৫ জুন ‘বিশ্ব পরিবেশ দিবস’ পালনের সিদ্ধান্ত গৃহীত হয়। ১৯৯০ সাল থেকে প্রতি বছর ৫ জুন জাতিসংঘভুক্ত দেশগুলোতে দিবসটি পালিত হয়ে আসছে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c275ea67f27a237a03a79474f68b206c'),
(3505, 391, 'জাতিসংঘ দিবস পালিত হয়–', '২৪ অক্টোবর', NULL, '২৪ আগস্ট', NULL, '২৪ ডিসেম্বর', NULL, '২৪ নভেম্বর', NULL, 'A', '১৯৪১ থেকে ১৯৪৫ সাল পর্যন্ত সময়কাল জাতিসংঘ প্রতিষ্ঠার লক্ষ্যে নানা পদক্ষেপ গৃহীত হয় এবং ১৫ অক্টোবর, ১৯৪৫ সনদ স্বাক্ষরিত হয়। ২৪ অক্টোবর ১৯৪৫ আনুষ্ঠানিকভাবে জাতিসংঘ যাত্রা শুরু করে এবং প্রতি বছর এ দিনটিকে জাতিসংঘ দিবস হিসেবে পালন করা হয়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '57a064c58f4a66a2e81265aef2e634a7'),
(3506, 394, 'নামিবিয়ার রাজধানী–', 'কারাভু', NULL, 'উইন্ডহুক', NULL, 'প্রিটোরিয়া', NULL, 'কোটাভি', NULL, 'B', 'প্রিটোরিয়া দক্ষিণ আফ্রিকার (প্রশাসনিক) রাজধানী। নামিবিয়ার রাজধানী উইন্ডহুক। কারাভু ও কোটাভি নামে বিশ্বে কোনো রাজধানী নেই।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b6a4e76778d8b93f5eb727c736fb8587'),
(3507, 412, 'ইসলামী উন্নয়ন ব্যাংক ঋণ প্রদান করে–', 'স্বাভাবিক সুদে', NULL, 'বিনা সুদে', NULL, 'অল্প সুদে', NULL, 'অতি সামান্য সুদে', NULL, 'B', 'ইসলামী ব্যাংক পরিচালনার কয়েকটি মূলনীতি হলো বিনা সুদে ঋণ প্রদান, মুনাফায় অংশগ্রহণ কর্মসূচি, অংশীদারী বিনিয়োগ, ইক্যুইটি লাইন প্রভৃতি। এটি ইসলামী শরীয়াহ্ মোতাবেক পরিচালিত। ২০ অক্টোবর, ১৯৭৫ IsDB -এর কার্যক্রম শুরু হলেও এর লেনদেন শুরু হয় ১৯৭৬ সালের জানুয়ারি মাসে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '695f6519c5abcd31a5fc5ef2ddb7a687'),
(3508, 394, 'ওডারনীস নদী–', 'পূর্ব জার্মানি ও পোল্যান্ডের মধ্যে সীমা নির্ধারক', NULL, 'পশ্চিম জার্মানি ও চেক প্রজাতন্ত্রের মধ্যে সীমা নির্ধারক', NULL, 'পশ্চিম জার্মানি ও পোল্যান্ডের মধ্যে সীমা নির্ধারক', NULL, 'সংযুক্ত জার্মানি ও ফ্রান্সের মধ্যে সীমা নির্ধারক', NULL, 'A', 'ওডারনীস লাইন দ্বিতীয় বিশ্বযুদ্ধের পর পূর্ব জার্মানি ও পোল্যান্ডের মধ্যে নিরূপিত সীমারেখা। জার্মানি কর্তৃক জার্মানি-ফ্রান্স সীমান্তে সুরক্ষিত সীমারেখা সিগফ্রিড লাইন এবং ফ্রান্স কর্তৃক জার্মানি-ফ্রান্স সীমান্তে নির্মিত সুরক্ষিত সীমারেখা ম্যাজিনো লাইন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4ff3418b9e81fed4422eb1ee13805b35'),
(3509, 124, 'হারারে এর পুরাতন নাম–', 'সলসবেরি', NULL, 'ফরমোজা', NULL, 'পেট্রোগ্রাড', NULL, 'রোডেসিয়া', NULL, 'A', 'ফরমোজা হলো তাইওয়ানের পুরাতন নাম। উত্তর রোডেসিয়া জাম্বিয়ার এবং দক্ষিণ রোডিসিয়া জিম্বাবুয়ের পুরাতন নাম। পেট্রোগ্রাড লেনিনগ্রাদের পুরাতন নাম।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ce245ff3f3708516f666b278b5b0954'),
(3510, 393, 'পবিত্রভূমি কোনটিকে বলা হয়?', 'প্যালেস্টাইন', NULL, 'জেরুজালেম', NULL, 'জেদ্দা', NULL, 'তায়েফ', NULL, 'B', 'প্যালেস্টাইন, জেরুজালেম, জেদ্দা, তায়েফ সবগুলোই মুসলমানদের পবিত্র স্থান। প্যালেস্টাইন ও জেরুজালেম এ দুটো স্থান মুসলমান ও খ্রিস্টানদের জন্য পবিত্র স্থান। কিন্তু মুসলমান, ইহুদি ও খ্রিস্টান-এ তিন জাতির নিকট জেরুজালেম পবিত্র।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '803d8a06d9f5138270a73891bb8f9f55'),
(3511, 394, 'এডেন কোন দেশের সমুদ্রবন্দর?', 'ইয়েমেন', NULL, 'কাতার', NULL, 'ওমান', NULL, 'ইরাক', NULL, 'A', 'এডেন উপসাগরের তীরে অবস্থিত এটি দক্ষিণ ইয়েমেনের একটি পোতাশ্রয়, নৌ ও বিমানঘাঁটি। এটি একটি গুরুত্বপূর্ণ বন্দরও বটে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fb7134b17794d9f165ba0b0f0bdfff0e'),
(3512, 412, 'মালদ্বীপের মুদ্রার নাম কি?', 'রুপী', NULL, 'ডলার', NULL, 'পাউন্ড', NULL, 'রুপাইয়া', NULL, 'D', 'ভারত, পাকিস্তান ও নেপালের মুদ্রার নাম রুপী। মালদ্বীপ ও ইন্দোনেশিয়ার মুদ্রার নাম রুপাইয়া। মার্কিন যুক্তরাষ্ট্র, সিঙ্গাপুর, অস্ট্রেলিয়া, জিম্বাবুয়ে, কানাডার মুদ্রার নাম ডলার। যুক্তরাজ্য, লেবানন, সিরিয়া, সুদানের মুদ্রার নাম পাউন্ড।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b61efc4eded19bdec6e7ea845c74a4ac'),
(3513, 401, '১৯৯২ সালে বিশ্ব অলিম্পিক অনুষ্ঠিত হয় কোথায়?', 'বার্সালোনা', NULL, 'জুরিখ', NULL, 'বার্লিন', NULL, 'ব্রাসেলস', NULL, 'A', 'বার্সিলোনা অলিম্পিক অনুষ্ঠিত হয় ১৯৯২ সালে। বার্লিনে অনুষ্ঠিত হয় ১৯৩৬ সালে। জুরিখ ও ব্রাসেলসে কখনও অলিম্পিক অনুষ্ঠিত হয়নি। ২০১৬ সালে অলিম্পিক গেমস অনুষ্ঠিত হয় ব্রাজিলের রিও ডি জেনেরিওতে এবং ২০২০ সালে অনুষ্ঠিত হবে জাপানের টোকিওতে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6d68f04d18ef34b964e55a48c5106cb0'),
(3514, 413, 'আফটা (AFTA) বলতে কি বোঝায়–', 'একটি বাণিজ্যিক গোষ্ঠী', NULL, 'পূর্ব আফ্রিকার একটি সংবাদ সংস্থা', NULL, 'একটি বিমান সংস্থা', NULL, 'একটি সামরিক চুক্তি', NULL, 'A', 'আফটা (AFTA)-এর পূর্ণরূপ হলো ASEAN Free Trade Area। ১৯৯২ সালে ২৮ জানুয়ারি সিঙ্গাপুরে এটি স্বাক্ষরিত হয়। মালয়েশিয়া, থাইল্যান্ড, ফিলিপাইন, সিঙ্গাপুর, ইন্দোনেশিয়া, ব্রুনাই, ভিয়েতনাম, লাওস, মিয়ানমার ও কম্বোডিয়া এ দশটি দেশ AFTA-এর সদস্য।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '433d2e0b7c9de96a25530e13a78b0506'),
(3515, 391, 'আন্তর্জাতিক রোটারি সংস্থার প্রতিষ্ঠাতা–', 'পল পি হ্যারিস', NULL, 'আলফ্রেড গ্রুপ', NULL, 'মার্শাল হাস', NULL, 'হেনরি ল্যাং', NULL, 'A', '২৩ ফেব্রুয়ারি, ১৯০৫ যুক্তরাষ্ট্রের শিকাগোতে রোটারি ইন্টারন্যাশনাল প্রতিষ্ঠিত হয়। এর প্রতিষ্ঠাতা মার্কিন আইনজীবী পল.পি. হ্যারিস।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a1d9eca58814438c75779b52a5dd3a74'),
(3516, 389, 'জাপান পার্ল হারবার আক্রমণ করে–', '৭ ডিসেম্বর, ১৯৪১', NULL, '২৩ জুন, ১৯৪২', NULL, '৩ নভেম্বর, ১৯৪২', NULL, '২৬ জুলাই, ১৯৪৩', NULL, 'A', 'দ্বিতীয় বিশ্বযুদ্ধকালীন অক্ষশক্তির অন্যতম জাপান নিজস্ব প্রভাব বলয় সম্প্রসারণের জন্য মার্কিন নৌ ঘাঁটি পার্ল হারবারে ৭ ডিসেম্বর, ১৯৪১ বোমা বর্ষণ করে। প্রতিক্রিয়ায় ৮ ডিসেম্বর, ১৯৪১ যুক্তরাষ্ট্র সক্রিয়ভাবে দ্বিতীয় বিশ্বযুদ্ধে অংশ নেয়।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0655aefac49fe0b8bdc4d596f3da5808'),
(3517, 393, 'সৌদি আরবে আমেরিকান সৈন্য মোতায়েনের উদ্দেশ্য–', 'ইরাকের আক্রমণ হতে সৌদি আরবকে রক্ষা করা', NULL, 'ইরাকের কুয়েত দখল অবসান করা', NULL, 'স্বল্পমূল্যে জ্বালানি তেলের সরবরাহ নিশ্চিত করা', NULL, 'উপরের সবকটি', NULL, 'D', '১৯৯০ সালের ২ আগস্ট ইরাক কুয়েত দখল করলে সৌদি আরবের নিরাপত্তা বিধানকল্পে যুক্তরাষ্ট্র সৌদি ভূখণ্ডে সৈন্য মোতায়েন করে এবং পরবর্তীতে কুয়েত মুক্তকরণকে অন্যতম লক্ষ্য নির্ধারণ করে। শিল্পোন্নত দেশগুলোর প্রধান জ্বালানি উপাদান খনিজ তেলের নিরাপদ সরবরাহ নিশ্চিতকরণ এবং তেলের মূল্য যাতে না বাড়ে সেজন্য যথাযথ পদক্ষেপ গ্রহণ ছিল মার্কিন সৈন্য মোতায়েনের প্রচ্ছন্ন উদ্দেশ্য।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ee8902a908d2d57580e5ae43355a1c83'),
(3518, 401, '১১তম এশিয়ান গেমসের উদ্বোধনী ও সমাপনী অনুষ্ঠান যে স্টেডিয়ামে অনুষ্ঠিত হয় তার নাম–', 'পিকিং স্পোর্টস স্টেডিয়াম', NULL, 'বেইজিং স্পোর্টস স্টেডিয়াম', NULL, 'ওয়ার্কার্স স্টেডিয়াম, বেইজিং', NULL, 'চায়না স্পোর্টস স্টেডিয়াম', NULL, 'C', 'উল্লেখ্য, ১৮ তম এশিয়ান গেমস ২০১৮ সালে ইন্দোনেশিয়ার জাকার্তায় অনুষ্ঠিত হয়। ১৯তম এশিয়ান গেমস ২০২২ সালে চীনের হাংসুতে অনুষ্ঠিত হয়। ২০তম এশিয়ান গেমস ২০২৬ সালে জাপানে অনুষ্ঠিত হবে।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '34162be343fdee6e808737e29ec020f3'),
(3519, 405, 'জাতিসংঘে রাষ্ট্রপতির ভাষণ অনুযায়ী বাংলাদেশে শিশুমৃত্যুর হার কমিয়ে আনা হয়েছে প্রতি হাজারে–', '১৩৭', NULL, '১২১', NULL, '১১৭', NULL, '১১০', NULL, 'D', 'অর্থনৈতিক সমীক্ষা ২০২২ অনুসারে বর্তমানে বাংলাদেশে শিশুমৃত্যুর হার প্রতি হাজারে ২১ জন।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b2d81d321869b85090710a1eb0f995e7'),
(3520, 393, 'শাত-ইল-আরবকে কেন্দ্র করে ইরাক ও ইরানের মধ্যে স্বাক্ষরিত চুক্তির নাম–', 'দামেস্ক চুক্তি', NULL, 'আলজিয়ার্স চুক্তি', NULL, 'কায়রো চুক্তি', NULL, 'বৈরুত চুক্তি', NULL, 'B', 'ইরাক-ইরান উপসাগরীয় যুদ্ধ শুরু হয় ১৯৮০ সালের ২২ সেপ্টেম্বর। শাত-ইল-আরব জলপথের অধিকার নিয়ে এই দুটি উপসাগরীয় দেশের মধ্যে যুদ্ধের সূত্রপাত। জাতিসংঘের আহ্বানে ২৯ আগস্ট ১৯৮৮ ইরাক-ইরান যুদ্ধবিরতি মেনে নেয়।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '797451d51067f438c40e4585fb71451e'),
(3521, 391, '৫০০ দিনের প্ল্যান বলতে বোঝায় যে এ সময়ের মধ্যে–', 'ওয়ারশ জোট ভেঙ্গে দেয়ার প্রকল্প সম্পন্ন করা', NULL, 'রুমানিয়াতে গণতান্ত্রিক প্রথা প্রচলন সম্পন্ন করা', NULL, 'সোভিয়েত ইউনিয়নে প্রস্তাবিত বাজার অর্থনীতি প্রচলন সম্পন্ন করা', NULL, 'পূর্ব জার্মানি হতে সোভিয়েত সৈন্য প্রত্যাহার সম্পন্ন করা', NULL, 'C', 'কমিউনিস্ট অর্থনীতিকে বাজার অর্থনীতিতে রূপান্তরের জন্য সোভিয়েত ইউনিয়নে যে প্রকল্প হাতে নেয়া হয় তা হলো ৫০০ দিনের প্ল্যান।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dad5a953e1542dfa17695b585c1068be'),
(3522, 405, 'জেমস গ্রান্টের মতে প্রতিরোধযোগ্য পীড়ায় বিশ্বে প্রতিদিন শিশু মৃত্যুর সংখ্যা–', '৪,০০,০০০', NULL, '৪০,০০০', NULL, '৪৪,০০০', NULL, '৫৪,০০০', NULL, 'B', 'জেমস গ্রান্টের মতে প্রতিরোধযোগ্য পীড়ায় বিশ্বে প্রতিদিন প্রায় ৪০,০০০ শিশু মৃত্যুবরণ করে।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '23fb86cbaae9f8ab9f20d78ec18b67d4'),
(3523, 394, 'হাজার হ্রদের দেশ কোনটি?', 'নরওয়ে', NULL, 'ফিনল্যান্ড', NULL, 'ইন্দোনেশিয়া', NULL, 'জাপান', NULL, 'B', 'হাজার হ্রদের দেশ হলো ফিনল্যান্ডের ভৌগোলিক উপনাম। নরওয়ের ভৌগোলিক উপনাম নিশীথ সূর্যের দেশ। জাপানকে বলা হয় প্রাচ্যের গ্রেট ব্রিটেন বা সূর্যোদয়ের দেশ।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '399fa986b0b916ee7a6e52698b8eda34'),
(3524, 395, 'পারস্য উপসাগরের আঞ্চলিক জোটের নাম–', 'ওএইউ', NULL, 'আরব লীগ', NULL, 'জিসিসি', NULL, 'ওএএস', NULL, 'C', 'ওএইউ-এর পূর্ণরূপ হলো অর্গানাইজেশন অব আফ্রিকান ইউনিয়ন। জিসিসি হলো গালফ কো-অপারেশন কাউন্সিল। জিসিসি কে পারস্য উপসাগরে আঞ্চলিক জোট বলা হয়। ওএএস হলো অর্গানাইজেশন অব আমেরিকান স্টেটস। আরব লীগ আরব দেশগুলোর একটি সংগঠন।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2c649c0b04a500d806278d519f0e62f6'),
(3525, 389, 'বাস্তিল দুর্গের পতন ঘটেছিল–', '১৪ জুলাই, ১৭৮৯', NULL, '৭ জুন, ১৭৮৮', NULL, '৫ অক্টোবর, ১৭৮৮', NULL, '২৬ আগস্ট, ১৭৮৮', NULL, 'A', 'ফ্রান্সের রাজা ষোড়শ লুইয়ের শাসনামলের অসাম্য ও অনাচারপূর্ণ সমাজব্যবস্থা এবং রানি অ্যান্টোনয়েটের অপরিণামদর্শী বিলাসিতা ও অর্থব্যয়ের কারণে শ্রমজীবী মানুষের মধ্যে ক্ষুধা, অনাহার ও দারিদ্র্য বৃদ্ধি পায়। এ অবস্থার প্রেক্ষিতে দার্শনিক রুশো, ভলতেয়ার ও মন্টেস্কুর হৃদয়স্পর্শী আহ্বানে জনগণ ১৪ জুলাই, ১৭৮৯ সালে ক্ষমতার কেন্দ্রবিন্দু বাস্তিল দুর্গ ধ্বংস করে।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '10f8d94972570ec5431b3e2154729dbd'),
(3526, 390, 'কঙ্গো প্রজাতন্ত্রের বর্তমান নাম–', 'লিওপোন্ডভিল', NULL, 'জিম্বাবুয়ে', NULL, 'জিবুতি', NULL, 'জায়ারে', NULL, 'D', 'স্বাধীনতাকালীন অর্থাৎ ১৯৬০-১৯৬৪ সাল পর্যন্ত দেশটির নাম ছিল রিপাবলিক অব দ্যা কঙ্গো। পরবর্তীতে ১৯৬৪ সালে নামকরণ করা হয় ডেমোক্রেটিক রিপাবলিক অব দ্যা কঙ্গো। আবার ১৯৭১ সালে নামকরণ করা হয় জায়ার। পুনরায় ১৯৯৭ সালের ১৭ মে নামকরণ করা হয় ডেমোক্রেটিক রিপাবলিক অব দ্যা কঙ্গো বা গণতান্ত্রিক কঙ্গো প্রজাতন্ত্র।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2b285469c19b248767b23302ef7d125b'),
(3527, 391, 'ট্রাফালগার স্কোয়ার কোন শহরে অবস্থিত?', 'ওয়াশিংটন', NULL, 'প্যারিস', NULL, 'মস্কো', NULL, 'লন্ডন', NULL, 'D', 'ট্রাফালগার স্কোয়ার লন্ডন শহরে অবস্থিত। এটি ব্রিটেনের অন্যতম বিখ্যাত পাবলিক স্কোয়ার।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '72090140620be9e82d383c597955a9b5'),
(3528, 393, 'মিশর সুয়েজ খাল জাতীয়করণ করেছিল–', '১৯৫৬ সালে', NULL, '১৯৫৫ সালে', NULL, '১৯৫৪ সালে', NULL, '১৯৫৩ সালে', NULL, 'A', 'সুয়েজ খাল মিশরের সিনাই উপদ্বীপের পশ্চিমে অবস্থিত একটি কৃত্রিম খাল। এটি লোহিত সাগরকে ভূমধ্যসাগরের সাথে সংযুক্ত করেছে। ১৮৫৯ সালে খননকাজ শুরু হয়ে ১৮৬৯ সালে শেষ হয়। ২৬ জুলাই ১৯৫৬ মিসরের প্রেসিডেন্ট জামাল আবদেল নাসের জাতীয়করণ করলে ইসরাইল মিশর আক্রমণ করে এবং দ্বিতীয় আরব-ইসরাইল যুদ্ধ সংঘটিত হয়।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd25593cbfd368f93145b2da9f4831548'),
(3529, 412, '১৯৯১ সালের Business International-এর সমীক্ষায় জীবনযাত্রার ব্যয়ভার (Living cost) সবচেয়ে বেশি–', 'টোকিওতে', NULL, 'নিউইয়র্কে', NULL, 'তেহরানে', NULL, 'আবিদজানে', NULL, 'A', 'ডিসেম্বর ২০২২ ইকোনমিস্ট ইনটেলিজেন ইউনিট (EIU) এর বার্ষিক জরিপে বিশ্বের সবচেয়ে ব্যয়বহুল শহরের তালিকায় যৌথভাবে স্থান পেয়েছে সিঙ্গাপুর ও যুক্তরাষ্ট্রের নিউইয়র্ক। তৃতীয় স্থানে রয়েছে ইসরায়েলের শহর তেল আবিব এবং চতুর্থ স্থানে রয়েছে হংকং শহর।', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0d47f66421d9dde109aa8192f5709c30'),
(3530, 412, 'উৎপাদিত পণ্য বিক্রয় হিসাব অনুসারে ১৯৯০ সালে সর্ববৃহৎ বিক্রেতা–', 'আইবিএম', NULL, 'জেনারেল মটরস', NULL, 'রয়াল ডাচ/শেল', NULL, 'ইক্সন', NULL, 'A', 'ইন্টারন্যাশনাল বিজনেস মেশিনস (আইবিএম) কর্পোরেশন একটি আমেরিকান বহুজাতিক প্রযুক্তি কোম্পানি। ১৭০টি দেশে কোম্পানিটি তার কার্যক্রম পরিচালনা করে। যার সদর দপ্তর আরমংক নিউইয়র্ক যুক্তরাষ্ট্রে অবস্থিত।', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4b6155e3033f61d355ef3b4c0a6e93c7'),
