(3571, 389, 'পৃথিবীর বিভিন্ন দেশের মধ্যে জনসংখ্যার দিক থেকে বাংলাদেশের স্থান কততম?', 'অষ্টম', NULL, 'নবম', NULL, 'দ্বাদশ', NULL, 'চতুর্দশ', NULL, 'A', 'UNFPA-এর বিশ্ব জনসংখ্যা রিপোর্ট ২০২২ অনুযায়ী বাংলাদেশ বিশ্বের ৮ম জনসংখ্যার দেশ। জনসংখ্যা ১৬ কোটি ৭৯ লাখ।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4e4d541212d907d924aaac2151a6c950'),
(3572, 412, 'ওয়াল স্ট্রিট কোথায় অবস্থিত?', 'ডালাস', NULL, 'লন্ডন', NULL, 'নিউইয়র্ক', NULL, 'হংকং', NULL, 'C', 'ওয়াল স্ট্রিট যুক্তরাষ্ট্রের বৃহত্তম শহর নিউইয়র্কে অবস্থিত। পৃথিবীর সবচেয়ে বড় শেয়ার-বাজার ওয়াল স্ট্রিটে অবস্থিত।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '79c2b5381fe5a7ed3e27a38facacb69d'),
(3573, 412, 'ইসলামিক উন্নয়ন ব্যাংকে (IDB) দেয়া বাংলাদেশের চাঁদার হার কত?', '২৫.০ মিলিয়ন ইসলামিক দিনার', NULL, '১৫.৫ মিলিয়ন ইসলামিক দিনার', NULL, '১০.০ মিলিয়ন ইসলামিক দিনার', NULL, 'কোনো চাঁদা দিতে হয় না', NULL, 'C', 'IDB কার্যক্রম শুরু ২০ অক্টোবর ১৯৭৫। বর্তমান সদস্য ৫৭। এর সদর দপ্তর- জেদ্দা, সৌদি আরব। IDB-কে দেয়া বাংলাদেশের চাঁদার হার ১০ মিলিয়ন ইসলামিক দিনার।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '232bdbf3fc48739a54f1b5f70f645d17'),
(3574, 124, 'বিশ্বব্যাংকের কোন অঙ্গ সংগঠনটি Soft loan Window নামে পরিচিত?', 'IBRD', NULL, 'IDA', NULL, 'IFC', NULL, 'EDI', NULL, 'B', 'IDA-এর পূর্ণরূপ International Development Association. ১৯৬০ সালের সেপ্টেম্বরে এটি প্রতিষ্ঠিত হয়। বিশ্বব্যাংকের ঋণ যতটা সম্ভব সহজ শর্তে দারিদ্র দেশসমূহকে প্রদানের লক্ষ্যে এ সংস্থাটি গঠিত হয়।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '10450efe819d7c3a1c03914b1e2a0af9'),
(3575, 122, 'আফ্রিকা মহাদেশের মানচিত্রে Horns of Africa-তে কোন দেশটি অবস্থিত?', 'ইথিওপিয়া', NULL, 'নাইজেরিয়া', NULL, 'কেনিয়া', NULL, 'সুদান', NULL, 'A', 'Horns of Africa মূলত একটি অঞ্চল, যাকে মানচিত্র দেখতে Horn বা শিং-এর মতো মনে হয়। এ অঞ্চলে সোমালিয়া, ইথিওপিয়া ও জিবুতি- তিনটি দেশ অবস্থিত। তবে Horn-এর শীর্ষে অবস্থিত সোমালিয়া।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cf6d35fc5cd804b8188fd64d3b9baf5b'),
