(3678, 124, 'শতাব্দীর সর্বশেষ অলিম্পিক কোথায় অনুষ্ঠিত হবে?', 'রোম', NULL, 'সিডনি', NULL, 'মস্কো', NULL, 'টরেন্টো', NULL, 'B', '২০০০ সালের অলিম্পিক গেমস অস্ট্রেলিয়ার সিডনিতে অনুষ্ঠিত হয় যা ছিল ২০শ শতাব্দীর সর্বশেষ অলিম্পিক।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0938c8d7b7046118ffecd92eb400088c'),
(3679, 124, 'কোন চুক্তিতে পারমাণবিক পরীক্ষা বন্ধ হওয়ার কথা বলা হয়েছে?', 'ন্যাটো (NATO)', NULL, 'সিটিবিটি (CTBT)', NULL, 'এনপিটি (NPT)', NULL, 'সল্ট (SALT)', NULL, 'B', 'CTBT (Comprehensive Nuclear Test Ban Treaty) হলো সর্বাত্মক পারমাণবিক পরীক্ষা নিষিদ্ধকরণ চুক্তি যা স্বাক্ষরিত হয় ২৪ সেপ্টেম্বর, ১৯৯৬। NPT (Nuclear Non-Proliferation Treaty) হলো পারমাণবিক অস্ত্র বিস্তার রোধ চুক্তি যা কার্যকর হয় ৫ মার্চ, ১৯৭০।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '863b8aecc4adce7ac9d225894a414377'),
(3680, 391, 'কয়টি দেশ নিয়ে জাতিসংঘ শুরু হয়েছিল?', '৪৮টি', NULL, '৫০টি', NULL, '৫১টি', NULL, '৬০টি', NULL, 'C', '১৯৪৫ সালের ২৪ অক্টোবর মোট ৫১টি দেশ নিয়ে জাতিসংঘ সনদ অনুমোদনের মধ্যে দিয়ে জাতিসংঘ প্রতিষ্ঠিত হয়।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '261fe423d204539393cc61b93fba7003'),
(3681, 394, 'বেনিন প্রজাতন্ত্র কোন মহাদেশে অবস্থিত?', 'এশিয়া', NULL, 'ইউরোপ', NULL, 'দক্ষিণ আমেরিকা', NULL, 'আফ্রিকা', NULL, 'D', 'বেনিন প্রজাতন্ত্র আফ্রিকা মহাদেশের একটি দেশ। দেশটির রাজধানী পোর্তো-নোভো এবং আয়তন ১,১৪,৭৬৩ বর্গ কিমি।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fde8cfda93483c533700b2286e37ab7b'),
(3682, 412, 'গ্রুপ-৭৭ কোন ধরনের দেশ নিয়ে গঠিত?', 'উন্নত', NULL, 'উন্নয়নশীল', NULL, 'ঔপনিবেশিক', NULL, 'অনুন্নত', NULL, 'B', 'তৃতীয় বিশ্বের উন্নয়নশীল দেশগুলোর অর্থনৈতিক ও বাণিজ্যিক স্বার্থরক্ষায় ১৫ জুন ১৯৬৪ সালে গঠিত হয় গ্রুপ-৭৭। বর্তমানে এর সদস্য ১৩৪।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3409e117d18af12f0fe74f9dea2e4b29'),
(3683, 391, '১৯৯৯ সালে নোবেল সাহিত্য পুরস্কার কে পেয়েছেন?', 'আর কে নারায়ণ', NULL, 'অরুন্ধতি রায়', NULL, 'হারমান হেস', NULL, 'গুন্টার গ্রাস', NULL, 'D', 'গুন্টার গ্রাস তার প্রথম উপন্যাস দ্য টিন ড্রাম-এর জন্য ১৯৯৯ সালে সাহিত্যে নোবেল পুরস্কার লাভ করেন। ২০২২ সালে সাহিত্য নোবেল পুরস্কার লাভ করেন ফ্রান্সের অ্যানি অর্নো।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '976883f4f83adbad2b28737b678cd83f'),
(3684, 391, 'আইফেল টাওয়ার কোথায় অবস্থিত?', 'লন্ডনে', NULL, 'মিউনিখে', NULL, 'হংকং-এ', NULL, 'প্যারিসে', NULL, 'D', 'প্রখ্যাত ফরাসি সেতু প্রকৌশলী আলেকজান্ডার গুস্তাভ আইফেলের নকশাকৃত প্রায় ৩২০ মিটার উঁচু আইফেল টাওয়ার তৈরি করা হয় ফ্রান্সের প্যারিস নগরীতে ১৮৮৯ সালে।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6834fa229b7c91815e177ba4ef6ddcee'),
(3685, 412, 'আন্তর্জাতিক আণবিক শক্তি কমিশনের সদর দপ্তর কোথায় অবস্থিত?', 'জেনেভায়', NULL, 'ওয়াশিংটনে', NULL, 'ভিয়েনায়', NULL, 'ব্রাসেলসে', NULL, 'C', 'সুইজারল্যান্ডের জেনেভায় WTO, Red Cross, ILO, ITU, WIPO, UNCTAD, WHO, UNHCR; যুক্তরাষ্ট্রের ওয়াশিংটনে IMF, IBRD, IDA, MIGA, IFC ও ICSID; অস্ট্রিয়ার ভিয়েনায় OPEC, IAEA ও UNIDO-এর সদর দপ্তর এবং ফ্রান্সের প্যারিসে UNESCO-এর সদর দপ্তর অবস্থিত।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3410e54e4141357fd959ac910f1f1de8'),
(3686, 391, '১৯৯৫ সালে বেইজিং-এ অনুষ্ঠিত চতুর্থ বিশ্ব নারী সম্মেলনের মূল শ্লোগান কি ছিল?', 'নারীর দৃষ্টিতে বিশ্বকে দেখ', NULL, 'বিশ্বের নারীরা এক হও', NULL, 'নারীর অধিকার মানবাধিকার', NULL, 'নারী নির্যাতন বন্ধ কর', NULL, 'C', '১৯৯৫ সালের সেপ্টেম্বর মাসে চীনের বেইজিংয়ে অনুষ্ঠিত চতুর্থ বিশ্ব নারী সম্মেলনের মূল প্রতিপাদ্য ছিল নারীর অধিকার মানবাধিকার এবং এই সম্মেলনে গৃহীত হয় বেইজিং কর্মপরিকল্পনা।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f507d574ae8b0adcc74edb3315dbf536'),
(3687, 406, 'ধরিত্রী সম্মেলন কোন শহরে অনুষ্ঠিত হয়?', 'জেনেভা', NULL, 'মেক্সিকো সিটি', NULL, 'নিউইয়র্ক', NULL, 'রিও ডি জেনেরিও', NULL, 'D', 'প্রথম ধরিত্রী সম্মেলন ১৯৯২ সালে ব্রাজিলের রিও ডি জেনেরিওতে অনুষ্ঠিত হয়। ২০০২ সালের ২৬ আগস্ট দক্ষিণ আফ্রিকার জোহানেসবার্গে অনুষ্ঠিত হয় দ্বিতীয় ধরিত্রী সম্মেলন।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c948484604a77f576415c285966c4e8f'),
(3688, 389, 'কোন দেশে নারীরা পুরুষের চেয়ে কম সময় বাঁচে?', 'বাংলাদেশে', NULL, 'জাপানে', NULL, 'সুইডেনে', NULL, 'সিঙ্গাপুরে', NULL, 'A', '২১তম বিসিএস প্রিলিমিনারি পরীক্ষাটি অনুষ্ঠিত হয় ২০০০ সালে। ২০০১ সালের অর্থনৈতিক সমীক্ষা অনুযায়ী বাংলাদেশের প্রত্যাশিত গড় আয়ুষ্কাল ছিল ৬১.৮ বছর। এর মধ্যে পুরুষ ৬২.৯ ও নারী ৬১.২ বছর। বর্তমানে বাংলাদেশেও নারীরা পুরুষের চেয়ে বেশি সময় বাঁচে।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c7702d47e4dfe6fb53d430a3b326867'),
(3689, 395, 'ইসলামী সম্মেলন সংস্থার প্রধান কার্যালয় কোথায়?', 'তেহরান', NULL, 'জেদ্দা', NULL, 'কায়রো', NULL, 'রিয়াদ', NULL, 'B', 'ইসলামী সম্মেলন সংস্থা (OIC)-এর সদর দপ্তর সৌদি আরবের জেদ্দায়। উপসাগরীয় সহযোগিতা সংস্থা (GCC)-এর সদর দপ্তর রিয়াদে, ECO-এর সদর দপ্তর ইরানের তেহরানে। আরব লীগের সদর দপ্তর মিশরের কায়রোতে। বর্তমানে OIC-এর নাম ইসলামী সহযোগী সংস্থা।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8422ec7c607605a4be66b47b6768e93f'),
(3690, 412, 'অমর্ত্য সেন কোন বিষয়ে গবেষণা করে নোবেল পুরস্কার পান?', 'দুর্ভিক্ষ ও দারিদ্র্য', NULL, 'উন্নয়নের গতিধারা', NULL, 'মাইক্রোক্রেডিট', NULL, 'বৈদেশিক সাহায্য', NULL, 'A', 'অমর্ত্য সেন (ভারতীয় অর্থনীতিবিদ) ১৯৯৮ সালে নোবেল পুরস্কার লাভ করেন। যে বইটি অমর্ত্য সেনকে নোবেল পুরস্কারের ভূষিত করেছে তা হলো: Poverty and Famines: An Essay in Enlightment and Deprivation. তার গবেষণার বিষয় ছিল দুর্ভিক্ষ ও দারিদ্র্য।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '347e5de48a6f2ec247527d19a43e1c70'),
(3691, 395, 'জোট নিরপেক্ষ আন্দোলন (NAM)-এর আগামী শীর্ষ সম্মেলন কোন শহরে অনুষ্ঠিত হবে?', 'দিল্লী', NULL, 'ডারবান', NULL, 'ঢাকা', NULL, 'জাকার্তা', NULL, 'B', 'জোট নিরপেক্ষ আন্দোলনের ত্রয়োদশ সম্মেলন ঢাকায় অনুষ্ঠিত হওয়ার কথা থাকলেও বাংলাদেশ সরকার অপারগতা প্রকাশ করলে সম্মেলন পিছিয়ে যায় এবং ২০০৩ সালের ২০-২৫ ফেব্রুয়ারি কুয়ালালামপুরে অনুষ্ঠিত হয়। ২০২৩ সালে জোট নিরপেক্ষ আন্দোলন উগান্ডার রাজধানী কাম্পালায় অনুষ্ঠিত হবে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6e22518b954bdf00ab7512bc017bca2d'),
(3692, 395, 'উপসাগরীয় সহযোগিতা পরিষদ (GCC)-এর সদস্য সংখ্যা কত?', '৬', NULL, '৭', NULL, '৮', NULL, '৫', NULL, 'A', 'GCC-এর পূর্ণরূপ Gulf Co-operation Council. ৬টি উপসাগরীয় দেশ নিয়ে ১৯৮১ সালের ২৫ মে এ সংস্থা গঠিত হয়। সদস্য দেশগুলো হলো সৌদি আরব, কাতার, বাহরাইন, ওমান, কুয়েত এবং সংযুক্ত আরব আমিরাত। সদর দপ্তর সৌদি আরবের রিয়াদে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '35369f2479a59e3efaf156585231c0f5'),
(3693, 413, 'BIMSTEC কি ধরনের সংগঠন?', 'রাজনৈতিক', NULL, 'অর্থনৈতিক', NULL, 'বাণিজ্যিক', NULL, 'সামাজিক', NULL, 'B', 'BIMSTEC-এর পূর্ণরূপ Bay of Bengal Initiative for Multi Sectoral Technical and Economic Co-operation. বঙ্গোপসাগরের তীরবর্তী দেশগুলো অর্থনৈতিক এবং পারস্পরিক উন্নয়নের জন্য BIMSTEC গঠিত হয়। বর্তমানে এর সদর দপ্তর ঢাকায় অবস্থিত।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ae4193063e34e1d069c4576d1a007c7c'),
(3694, 124, 'সার্ক কোন সালে, কোথায় প্রতিষ্ঠিত হয়?', '১৯৮৫ সালে, ঢাকায়', NULL, '১৯৮৩ সালে, দিল্লীতে', NULL, '১৯৮৫ সালে, কলম্বোতে', NULL, '১৯৮৬ সালে, মালেতে', NULL, 'A', 'সার্ক প্রতিষ্ঠিত হয় ১৯৮৫ সালের ৭-৮ ডিসেম্বর ঢাকায় অনুষ্ঠিত প্রথম শীর্ষ সম্মেলনে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0259e23068fd748485d07e8662a05acf'),
(3695, 391, 'জাতিসংঘের বর্তমান সদস্য সংখ্যা কত?', '১৯৫', NULL, '১৮৯', NULL, '১৭০', NULL, '১৭৫', NULL, 'A', 'জাতিসংঘের বর্তমান সদস্য সংখ্যা ১৯৩টি। ২০১১ সালে দক্ষিণ সুদান সর্বশেষ সদস্যপদ লাভ করে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'aea00c341c3ef3ecf6a9b2b1adfe5b4a'),
(3696, 397, 'রাশিয়ার কুরস্ক নামক সাবমেরিনটির ওজন কত টন?', '১২,৮০০ টন', NULL, '১৩,৯০০ টন', NULL, '১৪,২০০ টন', NULL, '১৫,০০০ টন', NULL, 'C', '২০০০ সালের ১২ আগস্ট উত্তর মেরুর নিকটবর্তী ব্যারেন্টস সাগরে রাশিয়ার পরমাণু শক্তিচালিত সাবমেরিন কুরস্ক দুর্ঘটনার শিকার হয়। সাবমেরিনটির ওজন ছিল ১৪,২০০ টন। কুরস্ক ডুবে গেলে এর ১১৮ জন ক্রুর সকলেই মারা যান।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6d836b95141c3efc01e31a6fdca947f2'),
(3697, 391, 'ট্রান্সপারেন্সি ইন্টারন্যাশনালের মতো বিশ্বের সবচেয়ে বেশি দুর্নীতিগ্রস্ত দেশ কোনটি?', 'সুইডেন', NULL, 'নাইজেরিয়া', NULL, 'বাংলাদেশ', NULL, 'ভারত', NULL, 'B', 'ট্রান্সপারেন্সি ইন্টারন্যাশনালের বার্ষিক দুর্নীতির ধারণাসূচক ২০২২ অনুযায়ী বিশ্বের সবচেয়ে বেশি দুর্নীতিগ্রস্ত দেশ হলো সোমালিয়া। এবং সবচেয়ে কম দুর্নীতিগ্রস্ত দেশ ডেনমার্ক। দুর্নীতিগ্রস্ত দেশের মধ্যে বাংলাদেশের অবস্থান ১২তম।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '93dad9439613158a4b5c56924402aa02'),
(3698, 391, 'বিশ্বের জনসংখ্যা পরিস্থিতি ২০০০ রিপোর্ট অনুসারে নারী নির্যাতনের ক্ষেত্রে শীর্ষে রয়েছে কোন দেশ?', 'পাকিস্তান', NULL, 'কেনিয়া', NULL, 'পাপুয়া নিউগিনি', NULL, 'বাংলাদেশ', NULL, 'C', 'স্বামী অথবা সঙ্গীর হাতে নারী নির্যাতনের হার সবচেয়ে বেশি প্রশান্ত মহাসাগরীয় দ্বীপদেশ পাপুয়া নিউগিনিতে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '82107456e18c71f8c96d6f28be36d92d'),
