(3702, 121, 'কোন আরব দেশ সর্বপ্রথম বাংলাদেশকে স্বীকৃতি প্রদান করে?', 'ইরাক', NULL, 'মিশর', NULL, 'কুয়েত', NULL, 'জর্ডান', NULL, 'A', 'আরব ভূখণ্ডের দেশ হিসেবে প্রথম ইরাক বাংলাদেশকে স্বীকৃতি প্রদান করে ৮ জুলাই, ১৯৭২ এবং প্রথম মুসলিম দেশ হিসেবে সেনেগাল ১ ফেব্রুয়ারি, ১৯৭২ বাংলাদেশকে স্বীকৃতি প্রদান করে। বাংলাদেশকে স্বীকৃতিদানকারী প্রথম দেশ ভুটান (৬ ডিসেম্বর, ১৯৭১)।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '13a91d3b5f14c76466da2e11219a1b09'),
(3703, 412, 'সুইডেনের মুদ্রার নাম কি?', 'পাউন্ড', NULL, 'ডলার', NULL, 'ক্রোনা', NULL, 'পেসো', NULL, 'C', 'ইউরোপীয় ইউনিয়নভুক্ত পুরাতন সদস্য (১৫টি) রাষ্ট্রের মধ্যে যুক্তরাজ্য, ডেনমার্ক ও সুইডেন ইউরো গ্রহণ করেনি। সুইডেন এখনও মুদ্রা হিসেবে ক্রোনা ব্যবহার করছে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ad913b1f333725301307d220b8cdf6b3'),
(3704, 395, 'NAM-এর বর্তমান সদস্য সংখ্যা কত?', '১০০', NULL, '১১৫', NULL, '১১৪', NULL, '১১৮', NULL, 'D', 'NAM-এর বর্তমান সদস্য সংখ্যা ১২০। ২৫ মে, ২০১১ আজারবাইজান ও ফিজিকে সদস্যপদ দেয়া হলে সদস্য সংখ্যা ১২০-এ উন্নীত হয়।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6f0cbdc7f1a6a2457eeb6aede8cb8c22'),
(3705, 391, 'কমনওয়েলথ সেক্রেটারিয়েট যে অট্টালিকায় অবস্থিত তার নাম কি?', 'মার্লবোরো হাউজ', NULL, 'হোয়াইট হাউজ', NULL, 'বাকিংহাম প্রাসাদ', NULL, 'দি চেকার্স', NULL, 'A', 'মার্লবোরো হাউজ লন্ডনে অবস্থিত। মার্লবোরো হাউজের অপর নাম পলমল। হোয়াইট হাউজ ওয়াশিংটনে মার্কিন প্রেসিডেন্টের বাসভবন এবং বাকিংহাম প্রাসাদ লন্ডনে ইংল্যান্ডের রানীর বাসভবন।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1d1ad4286516b5d9453c087bcce4bdd4'),
(3706, 389, 'সতীদাহ প্রথা কবে রহিত হয়?', '১৮১৯ সালে', NULL, '১৮২৯ সালে', NULL, '১৮৩৯ সালে', NULL, '১৮৪৯ সালে', NULL, 'B', 'সতীদাহ প্রথা হলো সহমরণ বিষয়ক সনাতন ধর্মাবলম্বীদের এক বিশেষ প্রথা। স্বামীর মৃত্যু হলে স্বামীর চিতায় স্ত্রীকে জীবন্ত দাহ করা হতো। রাজা রামমোহন রায়ের অক্লান্ত পরিশ্রমের ফলে ১৮২৯ সালে লর্ড উইলিয়াম বেন্টিঙ্ক সতীদাহ প্রথা রহিত করেন।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '95cdbd4ae35946ca3010e5840f9d3e21'),
(3707, 401, 'প্রথম সাফ গেমস কোথায় অনুষ্ঠিত হয়?', 'ঢাকা', NULL, 'নয়াদিল্লী', NULL, 'কলম্বো', NULL, 'কাঠমান্ডু', NULL, 'D', 'প্রথম সাফ গেমস (বর্তমানে সাউথ এশিয়ান গেমস বা এসএ গেমস) ১৯৮৪ সালে অনুষ্ঠিত হয় নেপালের রাজধানী কাঠমান্ডুতে। এ গেমসে বাংলাদেশ দুটি স্বর্ণপদক জয় করে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-05', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b1552fe5bd31dffd723fb598e21eb36f'),
(3708, 401, 'ইন্দোনেশিয়ার নতুন রাষ্ট্রপতির নাম কি?', 'জেনারেল সুহার্তো', NULL, 'মেঘবতী সুকর্নপুত্রী', NULL, 'আব্দুর রহমান ওয়াহিদ', NULL, 'জেনারেল বিয়ান্তো', NULL, 'C', 'ইন্দোনেশিয়ার বর্তমান রাষ্ট্রপতি জোকো উইদোদো (২০১৪-বর্তমান)। আব্দুর রহমান ওয়াহিদ ছিলেন ইন্দোনেশিয়ার চতুর্থ প্রেসিডেন্ট, যার মেয়াদকাল ১৯ অক্টোবর, ১৯৯৯-২৩ জুলাই, ২০০১। স্বৈরশাসক জেনারেল সুহার্তো দেশটির দ্বিতীয় প্রেসিডেন্ট, যিনি ১২ মার্চ, ১৯৬৭-২১ মে, ১৯৯৮ দীর্ঘ ৩২ বছর ক্ষমতায় ছিলেন। মুসলিম বিশ্বের প্রথম নারী প্রেসিডেন্ট মেঘবতী সুকর্নপুত্রী ক্ষমতাসীন ছিলেন ২৩ জুলাই, ২০০১-২১ অক্টোবর, ২০০৪ পর্যন্ত।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0c7bb3f212f2676a1c29ef8b889b547f'),
(3709, 124, 'Food and Agricultural Organization-এর সদর দপ্তর কোথায় অবস্থিত?', 'রোম', NULL, 'জেনেভা', NULL, 'ব্যাংকক', NULL, 'প্যারিস', NULL, 'A', '১৯৪৫ সালের ১৬ অক্টোবর কুইবেকে অনুষ্ঠিত এক সম্মেলনে জাতিসংঘ খাদ্য ও কৃষি সংস্থা (FAO) প্রতিষ্ঠিত হয়। এর সদর দপ্তর ইতালির রোমে।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd2dc5401a28970a95317c2781dcc1afd'),
(3710, 391, 'The Asian Drama গ্রন্থটির রচয়িতা কে?', 'অমর্ত্য সেন', NULL, 'গুনার মিরডাল', NULL, 'মাইকেল লিফটন', NULL, 'উইলয়াম রস্টো', NULL, 'B', 'প্রখ্যাত লেখক গুনার মিরডালের একটি বিখ্যাত গ্রন্থ The Asian Drama। ভারতের প্রখ্যাত নোবেল বিজয়ী অর্থনীতিবিদ অধ্যাপক অমর্ত্য সেনের বিখ্যাত গ্রন্থের মধ্যে অন্যতম হলো ১৯৮১ সালে প্রকাশিত গবেষণা গ্রন্থ Poverty and Famines: An Essay on Entitlement and Deprivation।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4e2c3498a9c4556fd6241714b97fb98c'),
(3711, 391, 'নিম্নলিখিত শহরের কোনটি আলবেনিয়ার রাজধানী?', 'বুদাপেস্ট', NULL, 'প্রাগ', NULL, 'এথেন্স', NULL, 'তিরানা', NULL, 'D', 'তিরানা আলবেনিয়ার রাজধানী, বুদাপেস্ট হাঙ্গেরির রাজধানী, এথেন্স গ্রিসের রাজধানী এবং প্রাগ চেক প্রজাতন্ত্রের/চেকিয়ার রাজধানী।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9cb6130b7eed84a8dd978c881637b42e'),
(3712, 412, 'IFC বলতে কি বোঝায়?', 'ইন্টারন্যাশনাল ফিন্যান্স করপোরেশন', NULL, 'ইন্টারন্যাশনাল ফিন্যান্স ক্যাপিটাল', NULL, 'ইন্টারন্যাশনাল ফুড করপোরেশন', NULL, 'এগুলোর কোনোটিই নয়', NULL, 'A', 'IFC-এর পূর্ণরূপ International Finance Corporation. এটি বিশ্বব্যাংক গ্রুপের ৫টি অঙ্গ সংস্থার একটি। এটি প্রতিষ্ঠিত হয় ২০ জুলাই, ১৯৫৬ এবং এর সদর দপ্তর যুক্তরাষ্ট্রের রাজধানী ওয়াশিংটন ডিসিতে।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '60a5302d461d773466c0d4077547f472'),
(3713, 395, 'Organization of African Unity কত সালে প্রতিষ্ঠিত হয়?', '১৯৬০ সালে', NULL, '১৯৬২ সালে', NULL, '১৯৬৩ সালে', NULL, '১৯৬৪ সালে', NULL, 'C', '২০০২ সালের ৯ জুলাই পর্যন্ত African Union (AU)-এর নাম ছিল Organization of African Unity. এটি প্রতিষ্ঠিত হয় ২৫ মে, ১৯৬৩। এর প্রাথমিক সদস্য ছিল ৩২টি এবং বর্তমানে ৫৫টি। সংস্থার সদর দপ্তর ইথিওপিয়ার রাজধানী আদ্দিস আবাবায় অবস্থিত।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '54e471011a8467bb8027f5396507d0bc'),
(3714, 394, 'বান্দুং কোথায় অবস্থিত?', 'মালয়েশিয়ায়', NULL, 'ভিয়েতনামে', NULL, 'থাইল্যান্ডে', NULL, 'ইন্দোনেশিয়ায়', NULL, 'D', '৩৩ প্রদেশ বিশিষ্ট জনসংখ্যায় বিশ্বের বৃহত্তম মুসলিম দেশ ইন্দোনেশিয়ার জাভা বারাত প্রদেশের রাজধানীর নাম বান্দুং। ১৯৫৫ সালে জোট নিরপেক্ষ আন্দোলন বা NAM (Non Aligned Movement) প্রতিষ্ঠার লক্ষ্যে ২৯টি দেশের সম্মেলন বান্দুং-এ অনুষ্ঠিত হয়।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '601ac4c2f08430d53db587ccacacd422'),
(3715, 394, 'পানামা খাল কোন কোন মহাসাগরকে যুক্ত করেছে?', 'আটলান্টিক মহাসাগর ও ভূমধ্যসাগর', NULL, 'আটলান্টিক মহাসাগর ও প্রশান্ত মহাসাগর', NULL, 'প্রশান্ত মহাসাগর ও উত্তর মহাসাগর', NULL, 'ভারত মহাসাগর ও প্রশান্ত মহাসাগর', NULL, 'B', 'পানামা খালটি উত্তর ও দক্ষিণ আমেরিকার মধ্যে অবস্থিত একটি যোজক খাল। ১৯০৪ সালে খালটি খনন আরম্ভ হয় এবং ১৯১৪ সালে জাহাজ চলাচলের জন্য উন্মুক্ত করা হয়। এটি আটলান্টিক মহাসাগর ও প্রশান্ত মহাসাগরকে যুক্ত করেছে। খালটির দৈর্ঘ্য ৮০ কিমি, প্রস্থ ৯০ থেকে ৩০০ মিটার এবং গভীরতা ১৩ মিটার।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '354d98c2af69140a4f8e8b5536a166dd'),
(3716, 393, 'ইসরাইল কত সালে পূর্ব জেরুজালেম দখল করেছিল?', '১৯৪৮ সালে', NULL, '১৯৬০ সালে', NULL, '১৯৬৭ সালে', NULL, '১৯৭৩ সালে', NULL, 'C', '১৯৬৭ সালে তৃতীয় আরব-ইসরাইল যুদ্ধে ইসরাইল প্রতিপক্ষ- মিশর, সিরিয়া ও জর্ডানসহ আরব বিশ্বকে পরাজিত করে গাজা, সিনাই উপদ্বীপ, পশ্চিম তীর ও পূর্ব জেরুজালেম দখল করে রাখে।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '24b5a3e615b3cbd963dc960d8c2c5411'),
(3717, 393, 'No Fly Zone কোন দেশে অবস্থিত?', 'ইরাক', NULL, 'কুয়েত', NULL, 'আফগানিস্তান', NULL, 'ইসরাইল', NULL, 'A', 'No Fly Zone হচ্ছে বিমান চলাচলে নিষিদ্ধ এলাকা। আকাশসীমায় সংরক্ষিত এলাকায় কোনো ধরনের বিমান চলাচল করতে পারে না। ১৯৯২ থেকে ২০০৩ সাল পর্যন্ত উত্তর ইরাকে এমন একটি No Fly Zone স্থাপন করেছিল যুক্তরাজ্য ও যুক্তরাষ্ট্র। বর্তমানে বিশ্বের বহু দেশেই No Fly Zone রয়েছে যেমন: সিরিয়া, ক্রিমিয়া।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ff2bf4870a0117545ff463216eeed45b'),
(3718, 391, 'মাইকেল অ্যাঞ্জেলো কোন দেশের শিল্পী?', 'অস্ট্রিয়া', NULL, 'গ্রিস', NULL, 'সুইডেন', NULL, 'ইতালি', NULL, 'D', 'ইতালীয় ভাস্কর, চিত্রকর, স্থাপত্যবিদ, প্রকৌশলী ও কবি মাইকেল অ্যাঞ্জেলো বুওনারোত্তি ছিলেন ইতালীয় রেনেসাঁসের অন্যতম পুরোধা। তার বিশ্ববিখ্যাত ভাস্কর্য ও স্থাপত্যকর্মের মধ্যে উল্লেখযোগ্য হলো রোমের সেন্ট পিটারের পিয়েতো, ফ্লোরেন্সের আকাদেমিতে রক্ষিত ডেভিড, দ্বিতীয় পোপ জুলিয়াসের সমাধিসৌধ ইত্যাদি। তিনি জন্মগ্রহণ করেন ৬ মার্চ, ১৪৭৫ সালে এবং ১৫৬৪ সালে মৃত্যুবরণ করেন।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '05dbf02b503e8fd5390d1ebafdc4b2b5'),
(3719, 394, 'ম্যাকমোহন লাইন কোন কোন দেশের সীমানা নির্ধারণ করেছে?', 'চীন ও রাশিয়া', NULL, 'চীন ও ভারত', NULL, 'ভারত ও পাকিস্তান', NULL, 'পাকিস্তান ও আফগানিস্তান', NULL, 'B', 'ভারতের ১১২৬.৫৪ কিমি ব্যাপী অরুণাচল প্রদেশ এবং চীনের অন্তর্গত তিব্বতের সুবর্ণ সিঁড়ি, সিয়াং ও লোহিত সীমান্তজুড়ে ম্যাকমোহন লাইন অবস্থিত। অন্যদিকে ভারত ও পাকিস্তানের মধ্যে র‌্যাডক্লিফ লাইন এবং পাকিস্তান ও আফগানিস্তানের মধ্যে ডুরান্ড লাইন সংশ্লিষ্ট দেশসমূহের সীমানা নির্ধারণ করেছে।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '421290713c9cffd9737dc85d24bd5925'),
(3720, 394, 'কোনটি নিশীথ সূর্যের দেশ নামে পরিচিত?', 'হেমারফেস্ট', NULL, 'কুইবেক', NULL, 'তিব্বত', NULL, 'কোনোটিই নয়', NULL, 'A', 'নরওয়ের উত্তরাঞ্চলীয় হেমারফেস্ট শহরটি সাড়ে ৭০ উত্তর অক্ষাংশে অবস্থিত। ২১ জুন তারিখে সূর্য কর্কটক্রান্তি রেখার ওপর লম্বভাবে এবং নিরক্ষরেখার ওপর সাড়ে ৬৬ কোণে হেলে কিরণ দেয়। ৯০ উত্তর অক্ষাংশ পর্যন্ত যে কোনো স্থান সূর্যরশ্মিতে আলোকিত থাকে। তবে পৃথিবীর আবর্তনের ফলে এ অঞ্চলে স্থানীয় সময় মধ্যরাত হলেও এ অঞ্চলের হেমারফেস্ট থেকে দূর মহাকাশের দিগন্তে সূর্যকে দেখা যায়। তাই এ অঞ্চলকে নিশীথ সূর্যের দেশ বলা হয়।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f09b40aa6a144fae89957cf036a0d8b9'),
(3721, 412, 'ইসলামী উন্নয়ন ব্যাংকের সদর দপ্তর কোথায় অবস্থিত?', 'রিয়াদ', NULL, 'কায়রো', NULL, 'কুয়েত', NULL, 'জেদ্দা', NULL, 'D', 'ইসলামী উন্নয়ন ব্যাংক (IDB)-এর সদর দপ্তর সৌদি আরবের জেদ্দায়। এটি প্রতিষ্ঠিত হয় ১৯৭৩ সালে এবং কার্যক্রম শুরু হয় ২০ অক্টোবর, ১৯৭৫।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bd6bab8d3ae2db06af8bc9b8b2faa502'),
(3722, 412, 'বেলজিয়ামের মুদ্রার নাম কি?', 'শিলিং', NULL, 'ফ্রাংক', NULL, 'পাউন্ড', NULL, 'ক্রোনা', NULL, 'B', 'ফ্রাংক বেলজিয়ামের সাবেক মুদ্রা। ইউরো চালু হওয়ার পর ২০০২ সালের ১ জুলাই থেকে বেলজিয়ামের মুদ্রা ফ্রাংক বিলুপ্ত করা হয়। অন্যদিকে, শিলিং অস্ট্রিয়ার ইউরো গ্রহণের পূর্বের মুদ্রা, পাউন্ড স্টার্লিং যুক্তরাজ্যের মুদ্রা, সুইডিস ক্রোনা সুইডেনের মুদ্রা এবং ডেনিস ক্রোনা ডেনমার্কের মুদ্রা।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fc574a2aac181d0fdd51294c3264ddea'),
(3723, 391, 'কোনটি চির শান্তির শহর নামে পরিচিত?', 'রোম', NULL, 'ভেনিস', NULL, 'এথেন্স', NULL, 'ওসলো', NULL, 'A', 'রোম নীরব শহর, চির শান্তির শহর, পোপের শহর এবং সাত পাহাড়ের শহর নামে পরিচিত। অন্যদিকে ভেনিস রাজপ্রাসাদের নগরী, দ্বীপের নগরী, নিশ্চুপ সড়কের শহর, অ্যাড্রিয়াটিকের রানী নামে পরিচিত।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ab5466869c908e20abe8b1290fea7cf9'),
(3724, 394, 'বাবেল মান্দেব কোন ভাষার শব্দ?', 'ফারসি', NULL, 'উর্দু', NULL, 'আরবি', NULL, 'ইংরেজি', NULL, 'C', 'বাবেল মান্দেব একটি আরবি শব্দ। এখানে এক সময় প্রচুর জাহাজ ডুবি হতো ও অনেক মানুষ মারা যেত। এটি বর্তমানে একটি প্রণালী, যা এশিয়া থেকে আফ্রিকাকে পৃথক করেছে এবং এডেন সাগরকে লোহিত সাগরের সাথে যুক্ত করেছে।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '83b07a6e029908b6f968ebc3ad27edbd'),
(3725, 391, 'জাতিসংঘের সাধারণ পরিষদের অধিবেশনে প্রতিটি সদস্যরাষ্ট্র সর্বোচ্চ কত জন প্রতিনিধি পাঠাতে পারে?', 'তিনজন', NULL, 'চারজন', NULL, 'পাঁচজন', NULL, 'ছয়জন', NULL, 'C', 'জাতিসংঘের বিধান অনুযায়ী সাধারণ পরিষদে প্রত্যেক সদস্যরাষ্ট্র পাঁচজন করে প্রতিনিধি পাঠাতে পারে। তবে কোনো সিদ্ধান্তের ক্ষেত্রে প্রত্যেক সদস্যরাষ্ট্র শুধু একটি ভোট প্রদান করতে পারে।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ff34b230e68eba19ea03168a7a1f43a4'),
(3726, 124, 'পিএলও কখন গঠিত হয়?', '১৯৬৪ সালে', NULL, '১৯৬৫ সালে', NULL, '১৯৬৬ সালে', NULL, '১৯৬৭ সালে', NULL, 'A', 'দ্বিতীয় বিশ্বযুদ্ধের পর ব্রিটিশরা ইহুদিদের পক্ষে ফিলিস্তিন ত্যাগ করলে ১৯৪৮ সালে ফিলিস্তিনে ইহুদিরা ইসরাইল রাষ্ট্র প্রতিষ্ঠা করে। এমতাবস্থায় স্বদেশভূমি উদ্ধারের জন্য প্রখ্যাত গেরিলা নেতা ইয়াসির আরাফাত ১৯৬৪ সালে পিএলও প্রতিষ্ঠা করেন। পিএলও-এর পূর্ণরূপ প্যালেস্টাইন লিবারেশন অর্গানাইজেশন।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0b2a44ad1c3f81160a9eba0513cf1d5d'),
(3727, 390, 'নক্রুমা কোন দেশের প্রেসিডেন্ট ছিলেন?', 'নাইজেরিয়া', NULL, 'কঙ্গো', NULL, 'আবিসিনিয়া', NULL, 'ঘানা', NULL, 'D', 'কোয়ামে নক্রুমা ঘানার জাতীয়তাবাদী নেতা, প্রথম প্রধানমন্ত্রী ও প্রেসিডেন্ট এবং উপনিবেশবাদ ও নব্য উপনিবেশবাদের কট্টর বিরোধী ব্যক্তিত্ব।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '64566c34afa3ab98332b7b9ad78d3ab1'),
(3728, 406, 'IUCN-এর কাজ হলো বিশ্বব্যাপী–', 'প্রাকৃতিক সম্পদ সংরক্ষণ করা', NULL, 'মানবাধিকার সংরক্ষণ করা', NULL, 'পানি সম্পদ সংরক্ষণ করা', NULL, 'আন্তর্জাতিক সন্ত্রাস দমন করা', NULL, 'A', 'International Union for Conservation of Nature (IUCN) একটি আন্তর্জাতিক জীববৈচিত্র্য সংরক্ষণবাদী সংস্থা। এটি জীববৈচিত্র্য ও প্রাকৃতিক সম্পদ সংরক্ষণের উদ্দেশ্যে ১৯৪৮ সালের ৫ অক্টোবর প্রতিষ্ঠিত হয়। এর সদর দপ্তর সুইজারল্যান্ডের গ্লান্ডে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '05882cff0de3b8c36080efb233806a37'),
(3729, 413, 'SAPTA অর্থ–', 'SAARC Preferential Trading Arrangement', NULL, 'South Asian Preferential Trading Arrangement', NULL, 'SAARC Preferential Tariff Agreement', NULL, 'South Asian Preferential Tariff Agreement', NULL, 'A', 'SAPTA হলো দক্ষিণ এশীয় আঞ্চলিক সহযোগিতা সংস্থা SAARC দেশগুলোর মধ্যকার সম্পাদিত একটি বাণিজ্য চুক্তি। এর পূর্ণরূপ SAARC Preferential Trading Arrangement. ১৯৯৩ সালের ১১ এপ্রিল ঢাকায় অনুষ্ঠিত সার্কের সপ্তম শীর্ষ সম্মেলনে এই চুক্তিটি স্বাক্ষরিত হয় এবং ৮ ডিসেম্বর ১৯৯৫ থেকে SAPTA কার্যকর হয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f4ae6a1832b8ad0cea47c16cb39953ab'),
(3730, 401, 'ক্রিকেট টেস্টের ইতিহাসে কনিষ্ঠতম ব্যাটসম্যান হিসেবে সেঞ্চুরি করেছেন–', 'ভারতের শচীন টেন্ডুলকার', NULL, 'অস্ট্রেলিয়ার ডন ব্র্যাডম্যান', NULL, 'ইংল্যান্ডের বেন হার্টন', NULL, 'বাংলাদেশের মোঃ আশরাফুল', NULL, 'D', 'টেস্ট ক্রিকেটের সর্বকনিষ্ঠ সেঞ্চুরিয়ান হিসেবে মোহাম্মদ আশরাফুল এশিয়ান টেস্ট চ্যাম্পিয়নশীপে শ্রীলংকার বিরুদ্ধে প্রথম সেঞ্চুরী করেন। এ সময় তার বয়স ছিল ১৬ বছর ২৬৪ দিন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '32ab84f8f6fe5fca6eb8ea7954ee0773'),
(3731, 401, 'ফুটবল বিশ্বকাপে সবচেয়ে বেশি চ্যাম্পিয়ন হয়েছে–', 'আর্জেন্টিনা', NULL, 'ব্রাজিল', NULL, 'ইতালি', NULL, 'ফ্রান্স', NULL, 'B', 'ফুটবল বিশ্বকাপে সবচেয়ে বেশি চ্যাম্পিয়ন হয়েছে ব্রাজিল ৫ বার (১৯৫৮, ১৯৬২, ১৯৭০, ১৯৯৪ এবং ২০০২)। অন্যদিকে, আর্জেন্টিনা ৩ বার (১৯৭৮, ১৯৮৬, ২০২২), ইতালি ৪ বার (১৯৩৪, ১৯৩৮, ১৯৮২ ও ২০০৬) এবং ফ্রান্স ২ বার (১৯৯৮, ২০১৮) বিশ্বকাপ ফুটবলে চ্যাম্পিয়ন হয়েছে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '534d4f6bf173ebb50efaddcddde48dd9'),
(3732, 391, 'চন্দ্রপৃষ্ঠে প্রথম অবতরণকারী মানুষের নাম ও দেশ–', 'ইয়ুরি গ্যাগারিন, রাশিয়া', NULL, 'জন গ্লেন, যুক্তরাষ্ট্র', NULL, 'রিচার্ড এলড্রিন, যুক্তরাষ্ট্র', NULL, 'নীল আর্মস্ট্রং, যুক্তরাষ্ট্র', NULL, 'D', '১৯৬৯ সালের ২১ জুলাই নীল আর্মস্ট্রং প্রথম মানুষ হিসেবে চন্দ্রপৃষ্ঠে অবতরণ করেন। অ্যাপোলো-১১ নামক মহাকাশযানে তিনিসহ এডউইন অলড্রিন ও মাইকেল কলিন্স এ অভিযানে অংশ নেন। অন্যদিকে ইয়ুরি গ্যাগারিন (রাশিয়া) হলেন বিশ্বের প্রথম মহাকাশচারী।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2a5cc210d9e917b0aa7cd7caaa6603c7'),
(3733, 412, 'WTO-এর সদর দপ্তর কোন শহরে?', 'প্যারিস', NULL, 'টোকিও', NULL, 'জেনেভা', NULL, 'নিউইয়র্ক', NULL, 'C', '১৯৯৫ সালের ১ জানুয়ারি GATT (General Agreement on Tariffs and Trade) রূপান্তরের মাধ্যমে WTO (World Trade Organization) প্রতিষ্ঠিত হয়। এর সদর দপ্তর সুইজারল্যান্ডের জেনেভায়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '81e812d51084f536a34673d18ef3c1dd'),
(3734, 412, 'এনরন (ENRON) কি?', 'একটি যুদ্ধবিমানবাহী জাহাজ', NULL, 'একটি ঔষধের নাম', NULL, 'এক প্রকার রোগজীবাণু', NULL, 'পৃথিবীর অন্যতম বৃহত্তম দেউলিয়া ঘোষিত জ্বালানি কোম্পানি', NULL, 'D', 'যুক্তরাষ্ট্রভিত্তিক জ্বালানি কোম্পানি এনরন ১৯৮৫ সালে প্রতিষ্ঠিত হয় এবং ২০০৪ সালের নভেম্বরে এটি দেউলিয়া ঘোষিত হয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '341ae191b0c2fa5375fe3b72b99c7f4c'),
(3735, 124, '২০০২ সালে নোবেল শান্তি পুরস্কার পেয়েছেন–', 'ইয়াসির আরাফাত', NULL, 'জিমি কার্টার', NULL, 'কফি আনান', NULL, 'মাদার তেরেসা', NULL, 'B', 'জিমি কার্টার বিশ্বশান্তি রক্ষায় অবদান রাখার জন্য ২০০২ সালের নোবেল শান্তি পুরস্কার লাভ করেন। অন্যদিকে, ইয়াসির আরাফাত ১৯৯৪ সালে ও মাদার তেরেসা ১৯৭৯ সালে নোবেল শান্তি পুরস্কার লাভ করেন। কফি আনান ও জাতিসংঘ ২০০১ সালে যৌথভাবে নোবেল পুরস্কার লাভ করেন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '269f08c3f08f76304c5401f9805360ea'),
(3736, 391, 'অ্যামনেস্টি ইন্টারন্যাশনাল-এর সদর দপ্তর কোথায়?', 'প্যারিস', NULL, 'জেনেভা', NULL, 'রোম', NULL, 'লন্ডন', NULL, 'D', 'অ্যামনেস্টি ইন্টারন্যাশনাল বিশ্বব্যাপী একটি স্বেচ্ছাসেবী মানবাধিকার সংগঠন। ১৯৬১ সালে এটি ব্রিটেনে প্রতিষ্ঠিত হয়। এর সদর দপ্তর ইংল্যান্ডের লন্ডনে অবস্থিত।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0788e582445f1b23fd45fc79def93651'),
(3737, 412, 'ওপেকভুক্ত অ-আরব মুসলিম দেশ কোনটি?', 'ইন্দোনেশিয়া', NULL, 'মালয়েশিয়া', NULL, 'ইরাক', NULL, 'ইরান', NULL, 'D', 'অপশনে প্রদত্ত চারটি দেশের মধ্যে ১০ সেপ্টেম্বর ২০০৮ ইন্দোনেশিয়া OPEC ত্যাগ করায় একমাত্র ইরানই অ-আরব মুসলিম দেশ। তবে বর্তমানে OPEC-এর ১৩টি সদস্যের মধ্যে অ-আরব মুসলিম দেশ হলো ইরান ও নাইজেরিয়া। OPEC-এর পূর্ণরূপ Organization of the Petroleum Exporting Countries। ১৯৬০ সালের ১৩ সেপ্টেম্বর এই সংস্থাটি প্রতিষ্ঠিত হয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0a51634b50d614752416ba945972aaf7'),
(3738, 124, 'জাতিসংঘ সনদ স্বাক্ষর সম্মেলনে উপস্থিত না থেকেও কোন রাষ্ট্র প্রতিষ্ঠাতা সদস্য হিসেবে পরিগণিত হয়?', 'হাঙ্গেরি', NULL, 'জার্মানি', NULL, 'পোল্যান্ড', NULL, 'ব্রিটেন', NULL, 'C', 'দ্বিতীয় বিশ্বযুদ্ধের শেষের দিকে ১৯৪৫-এর এপ্রিল-জুন সানফ্রান্সিসকো সম্মেলনে জাতিসংঘ সনদ গ্রহণ এবং ২৬ জুন, ১৯৪৫ উপস্থিত ৫০টি দেশ সনদ স্বাক্ষরের মধ্য দিয়ে বিশ্ব সংস্থা জাতিসংঘের জন্ম হয়। পোল্যান্ড এ সম্মেলনে ছিল না। ১৫ অক্টোবর পোল্যান্ড স্বাক্ষর করে এবং ২৪ অক্টোবর জাতিসংঘ আনুষ্ঠানিকভাবে যাত্রা শুরু করে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6da110097ae1dd9f4d5ad6ccdefdd90c'),
