(3740, 389, 'কত সালে আফগানিস্তান থেকে সোভিয়েত সৈন্য প্রত্যাহার করা হয়?', '১৯৮৮ সালে', NULL, '১৯৮৯ সালে', NULL, '১৯৯০ সালে', NULL, '১৯৯১ সালে', NULL, 'B', 'সাবেক সোভিয়েত ইউনিয়ন ১৯৭৯ সালে আফগানিস্তান দখল করলে মার্কিন সমর্থনে আফগানিস্তানে বিভিন্ন গোষ্ঠী সোভিয়েত সৈন্যদের বিরুদ্ধে গেরিলা যুদ্ধ চালিয়ে যায়। ব্যাপক ক্ষয়ক্ষতির মুখোমুখি হয়ে ১৯৮৯ সালের ফেব্রুয়ারি মাসে সোভিয়েত ইউনিয়ন সৈন্য প্রত্যাহার করে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4729aef83a1e6b9ba05473af4f70b473'),
(3741, 393, 'নাগার্নো কারাবাখ কোন দুটি দেশের করিডোর?', 'আজারবাইজান-আর্মেনিয়া', NULL, 'আর্মেনিয়া-লাটভিয়া', NULL, 'কাজাখস্তান-আজারবাইজান', NULL, 'রাশিয়া-আর্মেনিয়া', NULL, 'A', 'আজারবাইজান ও আর্মেনিয়ার মধ্যে বিরোধ সৃষ্টিকারী খ্রিস্টান অধ্যুষিত একটি ছিটমহল নাগার্নো কারাবাখ। ২০২০ সালে এই ছিটমহল নিয়ে দুই দেশ সংঘর্ষে জড়িয়ে পড়ে এবং নাগার্নো কারাবাখের বেশির ভাগ এলাকা আজারবাইজান দখল করে নেয়। রাশিয়ার মধ্যস্থতায় এই যুদ্ধ শেষ হয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '01d3d931f65dfcc09c8fc553b216e03f'),
(3742, 401, 'ইন্দোনেশিয়ার পর্যটনকেন্দ্র বালি দ্বীপে কোন তারিখে শক্তিশালী বোমা হামলায় ব্যাপক প্রাণহানিসহ একটি নাইট ক্লাব ধ্বংস হয়ে গেছে?', '১০ অক্টোবর, ২০০২', NULL, '১২ অক্টোবর, ২০০২', NULL, '১০ নভেম্বর, ২০০২', NULL, '১২ নভেম্বর, ২০০২', NULL, 'B', 'ইন্দোনেশিয়ার পর্যটন শহর বালি দ্বীপের কতা জেলায় সারি নামক নাইট ক্লাবে ২০০২ সালের ১২ অক্টোবর স্থানীয় সময় রাত সাড়ে ১১ টায় গাড়ি বোমা বিস্ফোরিত হয়। এতে দু শতাধিক লোক নিহত এবং তিন শতাধিক লোক আহত হয়। যাদের অধিকাংশই ছিল অস্ট্রেলীয় ও ইউরোপীয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b514b747201b3ced0074909f1ac62510'),
(3743, 391, 'সুইজারল্যান্ড আনুষ্ঠানিকভাবে কখন জাতিসংঘের সদস্য হয়?', '৩০ আগস্ট, ২০০২', NULL, '৭ সেপ্টেম্বর, ২০০২', NULL, '১০ সেপ্টেম্বর, ২০০২', NULL, '১৫ সেপ্টেম্বর, ২০০২', NULL, 'C', 'সুইজারল্যান্ড ১৭ জুলাই, ২০০২ জাতিসংঘে সদস্যপদ প্রাপ্তির জন্য আবেদন করে এবং ২০০২ সালের ১০ সেপ্টেম্বর জাতিসংঘের ১৯০তম সদস্য হিসেবে সদস্যপদ লাভ করে। উল্লেখ্য, জাতিসংঘের সর্বশেষ সদস্য দক্ষিণ সুদান ১৯৩তম সদস্য হিসেবে ২০১১ সালের ১৪ জুলাই সদস্যপদ লাভ করে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fb1fbd75a3e2340ed0e84665f079fa8b'),
(3744, 391, 'আফগানিস্তানের প্রধান ভাষা কোনটি?', 'আফগানি', NULL, 'ফার্সি', NULL, 'পশতু', NULL, 'তুর্কি', NULL, 'C', 'আফগানি হলো আফগানিস্তানের মুদ্রার নাম। প্রধান ও সরকারি ভাষা পশতু।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c6d0a162874ff2910c30b43518a7981d'),
(3745, 122, 'কোন দেশটি ওশেনিয়া অঞ্চলের অন্তর্ভুক্ত?', 'নাউরু', NULL, 'কেনিয়া', NULL, 'কিউবা', NULL, 'গায়ানা', NULL, 'A', 'নাউরু ওশেনিয়াভুক্ত একটি দ্বীপ দেশ এবং জাতিসংঘ সদস্য দেশসমূহের মধ্যে ক্ষুদ্রতম। এটি মাইক্রোনেশিয়ার অন্তর্ভুক্ত।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e6965b642fa167cc0e780a9c8eff72c0'),
(3746, 413, 'ইউরোপীয় ইউনিয়নের সদর দপ্তর কোথায়?', 'কোপেনহেগেন', NULL, 'লন্ডন', NULL, 'রোম', NULL, 'ব্রাসেলস', NULL, 'D', 'ইউরোপীয় ইউনিয়ন (EU) ১৯৫৭ সালের ২৫ মার্চ রোমে স্বাক্ষরিত চুক্তি অনুযায়ী ১৯৫৮ সালের ১ জানুয়ারি প্রতিষ্ঠিত হয়। এর পূর্বনাম ছিল ইউরোপীয় কমিশন (EC)। এর সদর দপ্তর বেলজিয়ামের ব্রাসেলসে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a17dc7aa6c486caff4bb7fa7648404c9'),
(3747, 124, 'নিউজিল্যান্ডের আদিবাসীদের কি বলা হয়?', 'কুর্দি', NULL, 'তাতারু', NULL, 'রেড ইন্ডিয়ান', NULL, 'মাউরি', NULL, 'D', 'মাউরিরা নিউজিল্যান্ডের আদিবাসী। অন্যদিকে কুর্দিরা কুর্দিস্তানের অধিবাসী, যারা বর্তমানে তুর্কিয়ে, সিরিয়া, ইরান ও ইরাকে বসবাসরত, তাতারুরা এশিয়ার এক মিশ্রজাতি যারা বর্তমানে সাইবেরিয়া, তুর্কমেনিস্তান ও রাশিয়ায় বাস করে এবং রেড ইন্ডিয়ানরা উত্তর আমেরিকার আদিবাসী যাদের নামকরণ করেছিলেন ক্রিস্টোফার কলম্বাস।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fd7b5529a41392bc2c1e5a7fa0a1d867'),
(3748, 124, 'কানাডা কোন শিল্পের জন্য বিখ্যাত?', 'কার্পাস', NULL, 'লোহা', NULL, 'কাগজ', NULL, 'বস্ত্র', NULL, 'C', 'কানাডার প্রধান শিল্প কাগজ। আর এজন্য কানাডার রাজধানী অটোয়াকে কাগজের শহর বলা হয়। কাগজ উৎপাদনে যুক্তরাষ্ট্র প্রথম এবং কানাডা দ্বিতীয় স্থানে রয়েছে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '48cf5480fdd3450252c0216ae4878eae'),
(3749, 391, 'আন্তর্জাতিক সম্পর্কের ক্ষেত্রে শক্তি প্রয়োগ নিষিদ্ধকারী প্যারিস প্যাক্ট স্বাক্ষরিত হয়–', '১৯২৭ সালের ১২ আগস্ট', NULL, '১৯২৮ সালের ২৭ আগস্ট', NULL, '১৯২৮ সালের ৩ নভেম্বর', NULL, '১৯২৯ সালের ৫ জানুয়ারি', NULL, 'B', '১৯২৮ সালের ২৭ আগস্ট ফ্রান্সের প্যারিসে প্যারিস প্যাক্ট স্বাক্ষরিত হয়। চুক্তিটি কেলগ-ব্রিয়ান্ড প্যাক্ট নামেও পরিচিত। কার্যকর হয় ২৪ জুলাই, ১৯২৯। বহুপাক্ষিক এ চুক্তিটির মাধ্যমে জাতীয় নীতি বাস্তবায়নের ক্ষেত্রে যুদ্ধ পরিহারের কথা বলা হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0bfd75604dbd9d1d143748f7c1ed7430'),
(3750, 391, 'যুদ্ধ ও সশস্ত্র সংঘর্ষ সংক্রান্ত আইন প্রণয়ন বিষয়ে ১৯৪৯ সনের জেনেভা কনভেনশনসমূহ অভিহিত–', 'দুটি রেডক্রস কনভেনশন নামে', NULL, 'তিনটি রেডক্রস কনভেনশন নামে', NULL, 'চারটি রেডক্রস কনভেনশন নামে', NULL, 'পাঁচটি রেডক্রস কনভেনশন নামে', NULL, 'C', 'যুদ্ধ ও সশস্ত্র সংঘর্ষ সংক্রান্ত আইন প্রণয়ন বিষয়ে ১৯৪৯ সালের ১২ আগস্টের জেনেভা কনভেনশনে যুদ্ধাহত ও যুদ্ধবন্দিদের সাথে আচরণবিধির ওপর বিশ্বের ৫৮টি দেশের মধ্যে ৪টি আন্তর্জাতিক চুক্তি স্বাক্ষরিত হয়। উল্লেখ্য, ১৯৫৪ সালের ২০ জুলাই সুইজারল্যান্ডের জেনেভা শহরে ফ্রান্স ও ভিয়েতনামের মধ্যে চলমান বিক্ষিপ্ত যুদ্ধ বন্ধে একটি চুক্তি স্বাক্ষরিত হয়, যা জেনেভা চুক্তি নামে পরিচিত।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f06306924e9cec3dae99ba5a27fd835e'),
(3751, 391, 'স্থায়ী সালিসী আদালত কোথায় অবস্থিত?', 'জেনেভায়', NULL, 'লন্ডনে', NULL, 'প্যারিসে', NULL, 'হেগে', NULL, 'D', 'স্থায়ী সালিসী আদালত নেদারল্যান্ডের দ্য হেগ শহরে অবস্থিত। এটি বিভিন্ন দেশের মধ্যকার অমীমাংসিত বিষয় নিষ্পত্তিকারী বিশেষ সংস্থা। এটি ফার্স্ট হেগ পিস কনফারেন্সের একটি অ্যাক্টের অধীন ১৮৯৯ সালে প্রতিষ্ঠিত হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '74b2b356b941c612f1cbac62642a6748'),
(3752, 391, 'মানবাধিকার বাস্তবায়নের লক্ষ্যে কখন আন্তর্জাতিক চুক্তি স্বাক্ষরিত হয়?', '১৯৫০ সালে', NULL, '১৯৫৫ সালে', NULL, '১৯৬৫ সালে', NULL, '১৯৬৬ সালে', NULL, 'D', 'বিশ্বের প্রতিটি মানুষের অধিকার সংরক্ষণ তথা মানবাধিকার বাস্তবায়নের লক্ষ্যে ১৯৬৬ সালে দুটি আন্তর্জাতিক চুক্তি স্বাক্ষরিত হয়। যথা: আন্তর্জাতিক নাগরিক ও রাজনৈতিক অধিকার চুক্তি এবং আন্তর্জাতিক আর্থ-সামাজিক সাংস্কৃতিক অধিকার চুক্তি।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '879b620b523190d9e1a60a2d9592cae6'),
(3753, 412, 'ইসিএ (ECA)-এর সদর দপ্তর কোথায়?', 'আদ্দিস আবাবা', NULL, 'নাইরোবি', NULL, 'ডাকার', NULL, 'কায়রো', NULL, 'A', 'ECA (Economic Commission for Africa)-এর সদর দপ্তর ইথিওপিয়ার রাজধানী আদ্দিস আবাবায়। এটি ১৯৫৮ সালে প্রতিষ্ঠিত হয়। এ সংস্থার লক্ষ্য ও উদ্দেশ্য আফ্রিকার দেশসমূহের অর্থনৈতিক উন্নয়ন ও সুযোগ-সুবিধা বৃদ্ধি করা। আফ্রিকায় ৫৪টি দেশ বর্তমানে সদস্য।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a4c32e0ffdda216f51038e03a04c9640'),
(3754, 393, 'ডেটন শান্তিচুক্তি স্বাক্ষরিত হয়–', '১৯৯০ সালে', NULL, '১৯৯১ সালে', NULL, '১৯৯২ সালে', NULL, '১৯৯৩ সালে', NULL, 'C', 'বসনিয়া-হার্জেগোভিনায় শান্তি প্রতিষ্ঠার লক্ষ্যে যুক্তরাষ্ট্রের ওহিও অঙ্গরাজ্যের ডেটন শহরের রাইট-পেটারসন বিমানবাহিনী ঘাঁটিতে ১৯৯৫ সালের নভেম্বরে এক শান্তি চুক্তিতে উপনীত হওয়ার পর ১৪ ডিসেম্বর ১৯৯৫ সালে আনুষ্ঠানিকভাবে প্যারিসে যে শান্তি চুক্তি স্বাক্ষরিত হয় তাই ডেটন শান্তি চুক্তি নামে পরিচিত।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5805c5f7bd943ad19f05202043a227f8'),
(3755, 124, 'কোন চুক্তির মাধ্যমে ইইসি (EEC) প্রতিষ্ঠা লাভ করে?', 'রোম চুক্তি', NULL, 'ম্যাসট্রিক্ট চুক্তি', NULL, 'ভিয়েনা কনভেনশন', NULL, 'ব্রাসেলস কনভেনশন', NULL, 'A', '১৯৫৭ সালের ২৫ মার্চ রোম চুক্তির মাধ্যমে European Economic Community (EEC) গঠনের প্রস্তাব করা হলেও ১৯৫৮ সালের ১ জানুয়ারি European Community (EC) প্রতিষ্ঠা করা হয়। ১৯৯২ সালের ৭ ফেব্রুয়ারি ম্যাসট্রিক্ট চুক্তির মাধ্যমে EC-এর নাম পরিবর্তন করে European Union (EU) প্রতিষ্ঠা করা হয়, যা ১৯৯৩ সালের ১ জানুয়ারি যাত্রা শুরু করে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5f9d55544c1ad1f2a868fe456cccf17d'),
(3756, 412, 'MIGA কখন গঠিত হয়?', '১৯৮০ সালে', NULL, '১৯৮২ সালে', NULL, '১৯৮৫ সালে', NULL, '১৯৮৬ সালে', NULL, 'C', 'MIGA-এর পূর্ণরূপ Multilateral Investment Guarantee Agency. এটি বিশ্বব্যাংক গ্রুপের অঙ্গসংস্থা হিসেবে ১৯৮৮ সালের ১২ এপ্রিল প্রতিষ্ঠিত হয়। এর সদর দপ্তর যুক্তরাষ্ট্রের ওয়াশিংটন ডিসি। উন্নয়নশীল দেশসমূহে বৈদেশিক বিনিয়োগ উৎসাহিত করাই এ অঙ্গসংস্থার লক্ষ্য ও উদ্দেশ্য।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6ae2fb6dc894e5bd38a9d9bc22fbd248'),
(3757, 391, 'বিখ্যাত ল্যান্ডমার্ক টাওয়ার অবস্থিত–', 'নিউইয়র্কে', NULL, 'শিকাগোতে', NULL, 'টোকিওতে', NULL, 'লন্ডনে', NULL, 'C', 'জাপানের ইয়োকোহামা শহরে অবস্থিত ল্যান্ডমার্ক টাওয়ার ১৯৯৩ সালে নির্মিত হয়। ভূমিকম্প সহনীয় এই ভবনটির উচ্চতা ২৯৬.৩ মিটার বা ৯৭২ ফুট। এটা ৭৩ তলাবিশিষ্ট।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '745a67a2fbaa736262e627377238236f'),
(3758, 391, 'হ্যারিপটার কি?', 'এক জাতীয় ধাতব পাত্র', NULL, 'সাম্প্রতিককালে সর্বাধিক বিক্রিত একটি শিশুতোষ বই', NULL, 'একজাতীয় গুচ্ছবোমা', NULL, 'এক ধরনের খেলনা', NULL, 'B', 'হ্যারিপটার হলো সাম্প্রতিককালে সর্বাধিক বিক্রিত ও আলোচিত একটি শিশুতোষ সিরিজ বই। এর লেখিকা ইংল্যান্ডের জোয়ান ক্যাথরিন রোলিং।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4c2ff838155371bfabfe9319b9393644'),
(3759, 394, 'বিশ্বের সবচেয়ে প্রাচীন সভ্যতা কোথায় গড়ে উঠেছিল?', 'গ্রিসে', NULL, 'মেসোপটেমিয়ায়', NULL, 'রোমে', NULL, 'ভারতে', NULL, 'B', 'খ্রিস্টপূর্ব ৫০০০ অব্দে টাইগ্রিস ও ইউফ্রেটিস (বর্তমান দজলা ও ফোরাত) নদীর তীরে বর্তমান সময়ের ইরাক, সিরিয়া, তুরস্ক ও ইরানে গড়ে ওঠা সভ্যতাকে মেসোপটেমীয় সভ্যতা নামে অভিহিত করা হয়। মেসোপটেমীয় সভ্যতার চারটি পর্যায় ছিল: সুমেরীয় সভ্যতা, ব্যাবিলনীয় সভ্যতা, অ্যাশিরীয় সভ্যতা ও ক্যালডীয় সভ্যতা।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '23f13a437ab0b7c87892ed86ca4c0412'),
(3760, 395, 'ওআইসি-এর বর্তমান মহাসচিব কোন দেশের নাগরিক?', 'বাংলাদেশ', NULL, 'তুরস্ক', NULL, 'মালয়েশিয়া', NULL, 'মরক্কো', NULL, 'C', 'OIC-এর বর্তমান মহাসচিব নির্বাচিত হয়েছেন হুসেইন ইব্রাহিম তাহা। তিনি আফ্রিকার দেশ চাদের পররাষ্ট্রমন্ত্রী হিসেবে দায়িত্ব পালন করেছেন। এ সংস্থাটি ২৫ সেপ্টেম্বর ১৯৬৯ সালে প্রতিষ্ঠিত হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1781be8fd4bc4d78053e90d5b6e10962'),
(3761, 412, 'বিশ্ব বাণিজ্য সংস্থার (WTO) পঞ্চম মিনিস্টারিয়াল কনফারেন্স কোথায় এবং কখন অনুষ্ঠিত হবে?', 'নভেম্বর ২০০৩ ভারতের ব্যাঙ্গালোর', NULL, 'ডিসেম্বর ২০০৩ কানাডার অটোয়া', NULL, 'জানুয়ারি ২০০৪ পাকিস্তানের ইসলামাবাদ', NULL, 'সেপ্টেম্বর ২০০৩ মেক্সিকোর কানকুন', NULL, 'D', 'বিশ্ব বাণিজ্য সংস্থার (WTO) পঞ্চম মিনিস্টারিয়াল কনফারেন্স মেক্সিকোর পর্যটন নগরী কানকুনে ২০০৩ সালের ১০-১৪ সেপ্টেম্বর অনুষ্ঠিত হয়। ধনী ও দরিদ্র দেশগুলোর ব্যবধান হ্রাসকল্পে কোনো সিদ্ধান্ত ছাড়াই সম্মেলনের সমাপ্তি ঘটে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ad0edeb1e48a8d400c831861f611bf9'),
(3762, 393, 'নিকারাগুয়ার কন্ট্রা বিদ্রোহীরা কোন দেশের সমর্থনপুষ্ট ছিল?', 'যুক্তরাজ্য', NULL, 'যুক্তরাষ্ট্র', NULL, 'কোরিয়া', NULL, 'কিউবা', NULL, 'B', 'কন্ট্রা নিকারাগুয়ার বিদ্রোহী গ্রুপ। দীর্ঘদিন ধরে এ গ্রুপটি দেশের সরকারের বিরুদ্ধে বিদ্রোহ চালিয়ে আসছিল। ১৯৮৫ সালের আগস্টে মার্কিন যুক্তরাষ্ট্র ইরানের নিকট অস্ত্র বিক্রয়লব্ধ অর্থ দ্বারা কন্ট্রা বিদ্রোহীদের সাহায্য প্রদান করে। যদিও কালক্রমে ঘটনাটি ফাঁস হয়ে যায়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1eb1ccb555512d57c287d4b1ad9d6685'),
(3763, 393, 'ইসরাইল-প্যালেস্টাইন রোডম্যাপ কর্মসূচির উদ্দেশ্য কি?', 'সহিংসতা বন্ধ করে ২০০৫ সালের মধ্যে স্বাধীন প্যালেস্টাইন রাষ্ট্র প্রতিষ্ঠা করা', NULL, 'দুটি রাষ্ট্রের মধ্যে সড়ক যোগাযোগ ব্যবস্থা স্থাপন', NULL, 'দুটি রাষ্ট্রের মধ্যে অবাধ বাণিজ্য স্থাপন', NULL, 'দুটি রাষ্ট্রের মধ্যে সীমানা চিহ্নিতকরণ', NULL, 'A', 'ইসরাইল-ফিলিস্তিন সংঘাত অবসানের লক্ষ্যে প্রণীত একটি শান্তি পরিকল্পনা রোডম্যাপ। মার্কিন যুক্তরাষ্ট্র ৩০ এপ্রিল, ২০০৩ আনুষ্ঠানিকভাবে বহু প্রতীক্ষিত এই শান্তি পরিকল্পনা পেশ করে। জাতিসংঘ, যুক্তরাষ্ট্র, ইউরোপীয় ইউনিয়ন এবং রাশিয়া সমন্বিতভাবে প্রস্তাবিত এ রোডম্যাপের খসড়া প্রস্তুত ও অনুমোদন করে। কিন্তু ইসরাইল এই প্রস্তাব প্রত্যাখান করে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c5a41fcac4dfa50215ce6e6619c889fb'),
(3764, 412, 'নিচের কোন দেশটি G-8 ভুক্ত দেশ নয়?', 'ফ্রান্স', NULL, 'যুক্তরাজ্য', NULL, 'রাশিয়া', NULL, 'দি নেদারল্যান্ডস', NULL, 'D', 'বিশ্বের সবচেয়ে ধনী দেশগুলোর সংগঠন জি-৬ প্রতিষ্ঠিত হয় ১৯৭৫ সালের ১৫ নভেম্বর। প্রতিষ্ঠাতা সদস্য যুক্তরাষ্ট্র, ব্রিটেন, ফ্রান্স, ইতালি, জাপান ও জার্মানি। ১৯৭৬ সালের ২৭ জুন কানাডা যোগ দিলে এর নামকরণ হয় জি-৭। ১৯৯৮ সালের ১৫ মে রাশিয়া সদস্যপদ লাভ করলে এর নাম হয় জি-৮। ২৪ মার্চ ২০১৪ রাশিয়ার সদস্যপদ বাতিল করায় পুনরায় এর নাম হয় জি-৭।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7538295b8b1aef2a568a0029043d2050'),
(3765, 412, 'ব্রেটন উডস ইনস্টিটিউট নিচের কোন সংস্থাকে বোঝায়?', 'আইএমএফ', NULL, 'বিশ্বব্যাংক', NULL, 'এডিবি', NULL, 'আইডিবি', NULL, 'A', 'দ্বিতীয় বিশ্বযুদ্ধে ব্যাপকভাবে ধ্বংসপ্রাপ্ত ইউরোপের পুনর্গঠন এবং অর্থনৈতিক স্থিতিশীল অবস্থা বজায় রাখার জন্য ১৯৪৪ সালের ১-২২ জুলাই ব্রেটন উডসের জাতিসংঘ মনিটারি এন্ড ফিনান্সিয়াল কনফারেন্সে বিশ্বব্যাংক ও আইএমএফ গঠিত হয়। তাই আইএমএফ ও বিশ্বব্যাংক এ দুটি সংস্থাকেই ব্রেটন উডস ইনস্টিটিউট বলা হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e1899de267b73576bb8e060264db6ac6'),
(3766, 391, 'প্রথম ক্লোন শিশু ইভ-এর জন্ম তারিখ কত?', 'নভেম্বর ২০, ২০০২', NULL, 'ডিসেম্বর ২৬, ২০০২', NULL, 'জানুয়ারি ৭, ২০০৩', NULL, 'মার্চ ২৩, ২০০৩', NULL, 'B', '২০০২ সালের ২৬ ডিসেম্বর ড. ব্রিজিত বোইসেলিয়ার পৃথিবীর প্রথম ক্লোন মানব শিশু ইভ-এর জন্ম ঘটান। ৭ পাউন্ড ওজনের এই কন্যাশিশুটি সিজারিয়ান অপারেশনের মাধ্যমে পৃথিবীতে ভূমিষ্ঠ হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd95ffb997e97e9f353779efca05a5e30'),
(3767, 391, 'A Long Walk to Freedom বইটির লেখক কে?', 'হোসে গুসামাও', NULL, 'রবার্ট মুগাবে', NULL, 'নেলসন ম্যান্ডেলা', NULL, 'অং সান সুচি', NULL, 'C', 'বইটির প্রকৃত নাম Long Walk to Freedom। এটি আফ্রিকার বর্ণবাদবিরোধী আন্দোলনের অন্যতম পথিকৃৎ নেলসন ম্যান্ডেলার (১৯১৮-২০১৩) আত্মজীবনীমূলক বই। নেলসন ম্যান্ডেলা এই বইয়ে তার ১৯৬৩ হতে ১৯৯০ সাল পর্যন্ত দীর্ঘ ২৭ বছরের কারাজীবনসহ নানা ঘটনা বর্ণনা করেছেন।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '15a516688bbd94d9fdbd83a866e9a3cb');
INSERT INTO `questions` (`id`, `topic_id`, `question`, `option_a`, `image_url_option_a`, `option_b`, `image_url_option_b`, `option_c`, `image_url_option_c`, `option_d`, `image_url_option_d`, `correct_option`, `explanation`, `explanation_image_url`, `referance_exam_id`, `exam_reference`, `BR_CODE`, `ORG_CODE`, `AUTHORIZED_STATUS`, `AUTHORIZED_USER`, `AUTHORIZED_DATE`, `ENTRY_DATE`, `ENTRY_USER`, `EDIT_DATE`, `EDIT_USER`, `DELETE_USER`, `DELETE_DATE`, `upload_process_id`, `exam_year`, `exam_date`, `exam_taker`, `remarks`, `image_url`, `question_hash`) VALUES
(3768, 393, 'লাইন অব কন্ট্রোল বলতে কোন দুটি দেশের সীমান্তবর্তী রেখাকে চিহ্নিত করে?', 'ইসরাইল ও জর্ডান', NULL, 'দক্ষিণ কোরিয়া ও উত্তর কোরিয়া', NULL, 'চীন ও তাইওয়ান', NULL, 'ভারত ও পাকিস্তান', NULL, 'D', 'এটি কাশ্মীরের পাকিস্তান ও ভারতের সীমান্ত বরাবর কাশ্মীর নিয়ন্ত্রণ রেখা। কারগিল ও দ্রাস এ নিয়ন্ত্রণ রেখার দুটি শহর। ১৯৯৯ সালের মে মাসে একদল জঙ্গী কাশ্মীরী এ রেখা অতিক্রম করে কারগিল পাহাড়ে আশ্রয় নিয়ে ভারতীয় সেনাদের ওপর আক্রমণ চালালে ভারত-পাকিস্তান যুদ্ধ বেঁধে যায়। পরে বিশ্ব নেতৃবৃন্দের হস্তক্ষেপে এ যুদ্ধের অবসান ঘটে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '45b28d05a26235caaa08843ae550cd06'),
(3769, 395, 'জোট নিরপেক্ষ দেশসমূহের প্রথম শীর্ষ সম্মেলন কোথায় অনুষ্ঠিত হয়?', 'দিল্লি', NULL, 'কায়রো', NULL, 'বেলগ্রেড', NULL, 'জাকার্তা', NULL, 'C', 'জোট নিরপেক্ষ দেশসমূহের সংগঠন NAM (Non Aligned Movement) বা জোট নিরপেক্ষ আন্দোলন গঠিত হয় ১৯৫৫ সালে ইন্দোনেশিয়ার বান্দুং-এ অনুষ্ঠিত সম্মেলনের মাধ্যমে। এ সংগঠনের প্রথম শীর্ষ সম্মেলন ১৯৬১ সালে তৎকালীন যুগোশ্লাভিয়ার রাজধানী বেলগ্রেডে অনুষ্ঠিত হয়। ১৮তম শীর্ষ সম্মেলন ২৫-২৬ অক্টোবর ২০১৯ আজারবাইজানের বাকুতে অনুষ্ঠিত হয়।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dc63a33540f5624fd5f5b91ebb5912b4'),
(3770, 394, 'পানামা খাল কোন কোন মহাসাগরকে যুক্ত করেছে?', 'আটলান্টিক ও প্রশান্ত মহাসাগর', NULL, 'আটলান্টিক ও ভূমধ্যসাগর', NULL, 'ভারত ও প্রশান্ত মহাসাগর', NULL, 'প্রশান্ত ও ভূমধ্যসাগর', NULL, 'A', '১৯১৪ সালে যুক্তরাষ্ট্র পানামা সরকারের সাথে এক চুক্তি বলে পানামার সংকীর্ণ স্থলভাগ কেটে প্রশান্ত মহাসাগর ও আটলান্টিক মহাসাগরকে সংযুক্ত করে যা পানামা খাল নামে পরিচিত। এ খালের দৈর্ঘ্য ৮১ কিমি। চুক্তি অনুযায়ী যুক্তরাষ্ট্র ১৯৯৯ সালের ১৫ ডিসেম্বর এ খালের নিয়ন্ত্রণ পানামার কাছে হস্তান্তর করে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3f3ef58dd25af94c7006942fecd29892'),
(3771, 391, 'কে লৌহমানবী বলে পরিচিত?', 'ইন্দিরা গান্ধী', NULL, 'বেগম খালেদা জিয়া', NULL, 'অং সান সুচি', NULL, 'মার্গারেট থ্যাচার', NULL, 'D', 'মার্গারেট থ্যাচার কনজারভেটিভ পার্টি থেকে ১৯৭৯ থেকে ১৯৯০ পর্যন্ত একটানা তিন মেয়াদে ব্রিটেনের প্রধানমন্ত্রী ছিলেন। তিনি ইউরোপের প্রথম নারী প্রধানমন্ত্রী এবং ব্রিটেনের সবচেয়ে দীর্ঘমেয়াদি প্রধানমন্ত্রী। পররাষ্ট্র ও অর্থনৈতিক নীতিতে তিনি অত্যন্ত কঠোর উন্নয়নমূলক নীতিমালা প্রয়োগ করেছিলেন, যা Thatcher Revolution নামে খ্যাত। তার এরূপ গঠনমূলক কাজের জন্য বিশ্বে তিনি Iron Lady বা লৌহমানবী বলে পরিচিত।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5656ee6c79ce66cd708ecd8ff67490ee'),
(3772, 393, 'আবু গারিব বলতে কি বোঝায়?', 'একজন বিখ্যাত দার্শনিক', NULL, 'একটি জাদুঘর', NULL, 'একটি জেলখানা', NULL, 'একজন বৈজ্ঞানিক', NULL, 'C', 'আবু গারিব ইরাকের রাজধানী বাগদাদে অবস্থিত একটি কারাগার। মার্কিন বাহিনী ইরাকি যুদ্ধবন্দিদের এই কারাগারে বন্দি করে রাখে ও তাদের ওপর অমানবিক নির্যাতন চালায়।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '18d74a655b5cb3c7a7d06f4413d0f544'),
(3773, 401, 'বিগত ৫০ বছরের সেরা ফুটবলার কে?', 'পেলে', NULL, 'জিদান', NULL, 'বেকেনবাওয়ার', NULL, 'ম্যারাডোনা', NULL, 'B', 'বিশ্বের সর্বকালের সেরা ফুটবলার ব্রাজিলের পেলে। তবে ইউরোপের একটি স্পোর্টস ম্যাগাজিন আয়োজিত এক জরিপে ৫০ বছরের সেরা খেলোয়াড় হিসেবে ফ্রান্সের জিনেদিন জিদানকে স্বীকৃতি দেয়া হয়। এছাড়া ইন্টারনেট জরিপে ম্যারাডোনা সেরা খেলোয়ার।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '348a0e2ea42d8ab6be8a10314dfda5d1'),
(3774, 391, 'ইউনেস্কোর প্রধান কার্যালয় কোথায় অবস্থিত?', 'নিউইয়র্ক', NULL, 'প্যারিস', NULL, 'রোম', NULL, 'জেনেভা', NULL, 'B', 'UNESCO-এর পূর্ণরূপ United Nations Educational, Scientific and Cultural Organization. এটি জাতিসংঘের শিক্ষা, বিজ্ঞান ও সংস্কৃতি বিষয়ক অঙ্গ সংগঠন। এর সনদ স্বাক্ষরিত হয় ১৬ নভেম্বর, ১৯৪৫ সালে এবং সেটি কার্যকর হয় ৪ নভেম্বর, ১৯৪৬ সালে। এর সদর দপ্তর ফ্রান্সের প্যারিসে অবস্থিত।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6a309603b7e3a62db6075be1a1f204ef'),
(3775, 124, 'রাষ্ট্রপ্রধান না হয়েও কোন ব্যক্তি রাষ্ট্রপ্রধানের মর্যাদা ভোগ করেন?', 'ইয়াসির আরাফাত', NULL, 'কফি আনান', NULL, 'ওসামা বিন লাদেন', NULL, 'অ্যারিয়েল শ্যারন', NULL, 'A', 'ইয়াসির আরাফাত ১৯৬৪ সালে পিএলও গঠন করেন। ১৯৮০ সালে জাতিসংঘ পিএলও প্রধান ইয়াসির আরাফাতকে ভবিষ্যৎ ফিলিস্তিন রাষ্ট্রের প্রধান হিসেবে স্বীকৃতি প্রদান করে। তখন থেকে মৃত্যুর (১১ নভেম্বর, ২০০৪) আগ পর্যন্ত ইয়াসির আরাফাত রাষ্ট্রপ্রধানের মর্যাদা ভোগ করেন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0a78b33de4cf49fabacc224d9f8770a0'),
(3776, 391, 'ডিজ আর্মিং ইরাক গ্রন্থটির রচয়িতা কে?', 'সালমান রুশদী', NULL, 'কুলদ্বীপ নায়ার', NULL, 'হ্যান্স ব্লিক্স', NULL, 'হিলারি ক্লিনটন', NULL, 'C', 'সুইডেনের সাবেক পররাষ্ট্রমন্ত্রী হ্যান্স ব্লিক্স ইরাকে তদন্ত কমিশন পরিচালনা এবং এতদসম্পর্কিত আন্তর্জাতিক সংগঠন ও পরাশক্তি রাষ্ট্রের কূটনৈতিক তৎপরতার অভিজ্ঞতার উপর ভিত্তি করে লিখেন ডিজ আর্মিং ইরাক নামক বইটি।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3b412cd0959e6ae8b8a2ebffc0d4f7bb'),
(3777, 391, 'উপমহাদেশ থেকে এ যাবৎ কতজন নোবেল পুরস্কার পেয়েছেন?', 'চারজন', NULL, 'পাঁচজন', NULL, 'ছয়জন', NULL, 'সাতজন', NULL, 'A', 'এ উপমহাদেশ থেকে এ পর্যন্ত ১২ জন ব্যক্তি নোবেল পুরস্কার পেয়েছেন। তারা হলেন- সাহিত্যে রবীন্দ্রনাথ ঠাকুর (১৯১৩), পদার্থবিজ্ঞানে চন্দ্রশেখর ভেঙ্কটরমণ (১৯৩৯), চিকিৎসায় হরগোবিন্দ খোরানা (১৯৬৮), শান্তিতে মাদার তেরেসা (১৯৭৯), পদার্থবিজ্ঞানে আবদুস সালাম (১৯৭৯), পদার্থবিজ্ঞানে সুব্রামানিয়াম চন্দ্রশেখর (১৯৮৩), অর্থনীতিতে অমর্ত্য সেন (১৯৯৮), শান্তিতে ড. মুহাম্মদ ইউনূস (২০০৬), রসায়নে ভেঙ্কটরমণ রামকৃষ্ণ (২০০৯), শান্তিতে মালালা ইউসুফজাঈ ও কৈলাশ সত্যার্থী (২০১৪) এবং অর্থনীতিতে অভিজিৎ ব্যানার্জি (২০১৯)।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6eba54960ca4708817321d4c5fb672ff'),
(3778, 401, 'নেপালের বর্তমান প্রধানমন্ত্রীর নাম কি?', 'মি. কৈরালা', NULL, 'মি. থাপা', NULL, 'মি. রানা', NULL, 'মি. দেউবা', NULL, 'A', 'নেপালের বর্তমান প্রধানমন্ত্রী কে পি শর্মা অলি (১৫ ফেব্রুয়ারি ২০২২-বর্তমান)। উল্লেখ্য, গিরিজা প্রসাদ কৈরালা গণতান্ত্রিকভাবে নির্বাচিত নেপালের প্রথম প্রধানমন্ত্রী ছিলেন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '15591b3d19354108e5a7144de7be26f9'),
(3779, 389, 'ইরাকে কখন মার্কিন-ব্রিটিশ যৌথ সামরিক অভিযান শুরু হয়?', '২০০৩ সালের ১৮ মার্চ', NULL, '২০০৩ সালের ২০ মার্চ', NULL, '২০০৩ সালের ২২ মার্চ', NULL, '২০০৩ সালের ২৪ মার্চ', NULL, 'B', 'ইরাকে ২০০৩ সালের ২০ মার্চ স্থানীয় সময় ভোর সাড়ে পাঁচটায় মার্কিন-ব্রিটিশ বাহিনী কর্তৃক যৌথ সামরিক অভিযান শুরু হয়।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1655f14e713c8020c630af8d3025e1d2'),
(3780, 124, 'বর্তমানে জাতিসংঘের মহাসচিব কোন দেশের নাগরিক?', 'গিনি', NULL, 'ঘানা', NULL, 'সেনেগাল', NULL, 'মরক্কো', NULL, 'B', '১৩ অক্টোবর, ২০১৬ জাতিসংঘের নবম মহাসচিব নির্বাচিত হন পর্তুগালের সাবেক প্রধানমন্ত্রী অ্যান্টনিও গুতেরেস। ৩১ ডিসেম্বর, ২০১৬ অষ্টম মহাসচিব বান কি মুনের মেয়াদ পূর্ণ হলে ১ জানুয়ারি, ২০১৭ জাতিসংঘের মহাসচিব হিসেবে দায়িত্ব গ্রহণ করেন তিনি। ২৬ ফেব্রুয়ারি ২০২১ তিনি পুনরায় নির্বাচিত হন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '01659068ecbbfc30df51d0850c7c66af'),
(3781, 389, 'বিশ্বের নতুনতম রাষ্ট্র কোনটি?', 'লাইবেরিয়া', NULL, 'হংকং', NULL, 'পূর্ব তিমুর', NULL, 'তাইওয়ান', NULL, 'C', 'দীর্ঘ দিনের চলমান সংঘাত অবসানে ২০১১ সালের ১৫ জানুয়ারি অনুষ্ঠিত গণভোটের ভিত্তিতে দক্ষিণ সুদান ৯ জুলাই, ২০১১ থেকে বিশ্বের নবীনতম স্বাধীন দেশ হিসেবে যাত্রা শুরু করে। বিশ্বের নবীনতম প্রজাতন্ত্র বার্বাডোস (২০২২)।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8a638af0b8163bcb995188485bd443b0'),
(3782, 413, 'আরব লীগের প্রতিষ্ঠাতা সদস্য দেশ নয়?', 'সংযুক্ত আরব আমিরাত', NULL, 'মিশর', NULL, 'লেবানন', NULL, 'ইয়েমেন', NULL, 'A', '১৯৪৫ সালের ২২ মার্চ মিশরের রাজধানী কায়রোতে আরব লীগ আনুষ্ঠানিকভাবে প্রতিষ্ঠিত হয়। এর প্রতিষ্ঠাতা সদস্য ৭টি। এগুলো হলো- মিশর, সিরিয়া, লেবানন, ইরাক, জর্ডান, সৌদি আরব এবং ইয়েমেন। পরবর্তীতে ১৯৭১ সালে সংযুক্ত আরব আমিরাত আরব লীগের সদস্যপদ লাভ করে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '478b1045494f533391fe08c3e8b4be28'),
(3783, 394, 'কোন দেশটি ল্যাটিন আমেরিকার অন্তর্ভুক্ত নয়?', 'ব্রাজিল', NULL, 'আর্জেন্টিনা', NULL, 'পেরু', NULL, 'পানামা', NULL, 'A', 'যদি ভৌগোলিকভাবে ল্যাটিন আমেরিকা বলতে পুরো দক্ষিণ আমেরিকা থেকে উত্তর আমেরিকার মেক্সিকোর উত্তর সীমান্ত পর্যন্ত অঞ্চলকে বোঝায়, তবে প্রশ্নে উল্লিখিত চারটি দেশই ল্যাটিন আমেরিকার অন্তর্ভুক্ত। এ অঞ্চলে মোট ২০টি স্বাধীন দেশ রয়েছে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6ec99da6ac86a64337d1c71f57b3c85d'),
(3784, 391, 'ইন্টারপোল সংস্থার সদর দপ্তর কোথায়?', 'প্যারিস', NULL, 'লিঁও', NULL, 'ভার্সাই', NULL, 'মাসাই', NULL, 'B', 'ইন্টারপোলের পূর্ণরূপ International Police Organization। অপরাধীদের শনাক্তকরণ এবং গ্রেফতার করতে বিশ্বের দেশগুলো পরস্পরকে সহযোগিতার লক্ষ্যে প্রতিষ্ঠিত হয়েছে এ আন্তর্জাতিক সংস্থা। ১৯২৩ সালে প্রতিষ্ঠিত এ সংস্থাটির সদর দপ্তর ফ্রান্সের লিঁও শহরে অবস্থিত।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '60d88432da60d62e6ade0cca7a3c2f65'),
(3785, 393, 'মধ্যপ্রাচ্যে কখন প্রথম তেল অস্ত্র ব্যবহার করা হয়েছিল?', '১৯৭৩ সালে', NULL, '১৯৮১ সালে', NULL, '১৯৯১ সালে', NULL, '২০০৩ সালে', NULL, 'A', 'মধ্যপ্রাচ্যের তেলসমৃদ্ধ দেশগুলোর হঠাৎ করে একযোগে তেল রপ্তানি বন্ধ করাকে বলা হয় তেল অস্ত্র ব্যবহার। মধ্যপ্রাচ্যের দেশগুলো ১৯৭৩ সালে সর্বপ্রথম তেল অস্ত্র ব্যবহার করে। তেল অস্ত্র এখন পর্যন্ত তিন বার (১৯৭৩, ১৯৮১, ১৯৮৬ সালে) ব্যবহার করা হয়েছে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dbc34178db0e0aaa8ed9a08e712633bc'),
(3786, 394, 'বান্দুং শহরটি কোন দেশে অবস্থিত?', 'চীন', NULL, 'ইন্দোনেশিয়া', NULL, 'যুগোস্লাভিয়া', NULL, 'মালয়েশিয়া', NULL, 'B', 'বান্দুং শহরটি ইন্দোনেশিয়ার জাভা বারাত প্রদেশের রাজধানী। ইন্দোনেশিয়ার এই বিখ্যাত শহরটি জোট নিরপেক্ষ আন্দোলনের সাথে জড়িত।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0c7489a731ae0a3f998cb62f62354756'),
(3787, 406, 'কার্টাগেনা প্রটোকল হচ্ছে?', 'জাতিসংঘের জৈব নিরাপত্তা বিষয়ক চুক্তি', NULL, 'ইরাক পুনর্গঠন চুক্তি', NULL, 'যুক্তরাষ্ট্র-মেক্সিকো বৈধ চুক্তি', NULL, 'শিশু অধিকার চুক্তি', NULL, 'A', 'জাতিসংঘের জৈব নিরাপত্তা বিষয়ক একটি চুক্তি কার্টাগেনা প্রটোকল। ১৯৯৯ সালের ফেব্রুয়ারিতে কলম্বিয়ার কার্টাগেনা শহরে জৈব নিরাপত্তা বিষয়ক চুক্তিটির ব্যাপারে সিদ্ধান্ত গৃহীত হয়। পরবর্তীতে ২০০০ সালের ২৪ থেকে ২৯ জানুয়ারি চুক্তিটির খসড়া চূড়ান্ত করা হয় এবং ২৯ জানুয়ারিই চুক্তিটি স্বাক্ষরিত হয়।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c8befa90e51a0f71e6a1c286e7aca360'),
(3788, 405, 'এ বছর তামাক নিয়ন্ত্রণে আন্তর্জাতিক জেনেভা সম্মেলনে সভাপতি কোন দেশের নাগরিক?', 'বাংলাদেশ', NULL, 'ভারত', NULL, 'পাকিস্তান', NULL, 'সুইজারল্যান্ড', NULL, 'C', 'প্রশ্নে উল্লিখিত এ বছর বলতে ২০০৪ সালকে বোঝানো হয়েছে। ২০০৪ সালে বিশ্ব স্বাস্থ্য সংস্থার ৫৭তম সম্মেলনে সভাপতিত্ব করেন পাকিস্তানের স্বাস্থ্য মন্ত্রী মোহাম্মদ নাসের খান।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7530abadb0617dd624742a4d2b8af558'),
(3789, 391, 'নাসাউ কোন দেশটির রাজধানী?', 'নিকোবর দ্বীপপুঞ্জ', NULL, 'মাদাগাস্কার দ্বীপপুঞ্জ', NULL, 'বাহামা দ্বীপপুঞ্জ', NULL, 'ফিজি দ্বীপপুঞ্জ', NULL, 'C', 'বাহামা দ্বীপপুঞ্জের রাজধানী নাসাউ। অন্যদিকে, নিকোবর দ্বীপপুঞ্জের রাজধানী পোর্ট ব্লেয়ার, মাদাগাস্কারের রাজধানী আন্টানানারিভো, ফিজির রাজধানী সুভা।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1fa24877a7731ece99fe3873b5eb24b5'),
(3790, 391, 'জাপানের পার্লামেন্টের নাম কি?', 'রাইখস্ট্যাগ', NULL, 'রিকসড্যাগ', NULL, 'ফোকেটিং', NULL, 'ডায়েট', NULL, 'D', 'জাপানের পার্লামেন্টের নাম ডায়েট। অন্যদিকে, রাইখস্ট্যাগ জার্মানির, রিকসড্যাগ সুইডেনের এবং ফোকেটিং ডেনমার্কের পার্লামেন্টের নাম।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bdac6910eca7da87680a1d6f117cc722'),
(3791, 391, 'শান্তির জন্য প্রথম কোন মহিলা নোবেল পুরস্কার পান?', 'আলভা মায়ারডাল', NULL, 'অং সান সুচি', NULL, 'শিরিন এবাদি', NULL, 'মাদার তেরেসা', NULL, 'D', 'শান্তিতে প্রথম মহিলা নোবেল বিজয়ী বার্থা ফন সুটনার (অস্ট্রিয়া, ১৯০৫ সালে)। তবে উল্লিখিত চারজনের মধ্যে প্রথম নোবেল জয়ী মাদার তেরেসা। মাদার তেরেসা (আলবেনীয় বংশোদ্ভূত) ১৯৭৯ সালে, আলভা মায়ারডাল (সুইডেন) ১৯৮২ সালে, অং সান সুচি (মিয়ানমার) ১৯৯০ সালে এবং শিরিন এবাদি (ইরান) ২০০৩ সালে নোবেল বিজয়ী হন।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0f433acaed3a2a59d85d4d019f2c7c38'),
(3792, 389, 'আটলান্টিক সনদে যুক্তরাষ্ট্র এবং ব্রিটেনের পক্ষে স্বাক্ষর করেন কে কে?', 'রোনাল্ড রিগ্যান ও মার্গারেট থ্যাচার', NULL, 'জর্জ ডব্লিউ বুশ ও টনি ব্লেয়ার', NULL, 'জিমি কার্টার ও রানী দ্বিতীয় এলিজাবেথ', NULL, 'ফ্রাঙ্কলিন ডি রুজভেল্ট ও উইনস্টন চার্চিল', NULL, 'D', 'জাতিসংঘ গঠনের দ্বিতীয় পদক্ষেপ আটলান্টিক সনদ। ১৯৪১ সালের ১৪ আগস্ট মার্কিন প্রেসিডেন্ট ফ্রাঙ্কলিন ডি রুজভেল্ট এবং ব্রিটিশ প্রধানমন্ত্রী উইনস্টন চার্চিল ব্রিটিশ নৌ-তরী প্রিন্স অব ওয়েলস-এ মিলিত হয়ে বিশ্বশান্তি ও নিরাপত্তার জন্য আটলান্টিক সনদ স্বাক্ষর করেন।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '20c4eb54d5cbc40b21a0800439e3b178'),
(3793, 406, 'গ্রিনপিস (Green Peace) কোন দেশের পরিবেশবাদী গ্রুপ?', 'হল্যান্ড', NULL, 'পোল্যান্ড', NULL, 'ফিনল্যান্ড', NULL, 'নিউজিল্যান্ড', NULL, 'A', 'গ্রিনপিস হল্যান্ড বা নেদারল্যান্ডসভিত্তিক একটি বেসরকারি পরিবেশবাদী সংস্থা। ১৯৭১ সালে এটি প্রতিষ্ঠিত হয়।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd0cdf8a4a14809cfbd44d841160718b6'),
(3794, 391, 'ব্রিটেনের রানী কোন দেশটির সাংবিধানিক রাষ্ট্রপ্রধান নন?', 'ফিজি', NULL, 'কানাডা', NULL, 'অস্ট্রিয়া', NULL, 'অস্ট্রেলিয়া', NULL, 'C', 'যুক্তরাজ্য সহ সাবেক ব্রিটিশ উপনিবেশভুক্ত ১৫টি দেশ ব্রিটেনের রাজা/রানীকে তাদের প্রতীকী রাষ্ট্রপ্রধান হিসেবে মান্য করে। অস্ট্রিয়া ব্রিটিশ উপনিবেশ ছিল না, তাই ব্রিটেনের রানী অস্ট্রিয়ার সাংবিধানিক রাষ্ট্রপ্রধান নন।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3cb785a66ba1b515553e79734ab988be'),
(3795, 124, 'ফ্রান্সের মহান সম্রাট নেপোলিয়নের জীবনাবসান হয় কোথায়?', 'ওয়াটারলু নামক স্থানে', NULL, 'দ্বীপ এনাবার্তে', NULL, 'ভার্সাই নগরীতে', NULL, 'সেন্ট হেলেনা দ্বীপে', NULL, 'D', 'সম্রাট নেপোলিয়ন ১৮১৫ সালে ওয়াটারলু যুদ্ধে ইংরেজ সেনাপতি লর্ড ওয়েলিংটনের নেতৃত্বে সম্মিলিত বাহিনীর নিকট পরাজিত হয়ে আত্মসমর্পণ করেন। মিত্রবাহিনী তাকে সেন্ট হেলেনা দ্বীপে নির্বাসন দেয় এবং সেখানে তিনি ১৮২১ সালে মারা যান।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f160a55c0dd2e8673d6407b7972f6e12'),
(3796, 391, 'গারুদা কোন দেশের বিমান সংস্থা?', 'গ্রিস', NULL, 'জার্মানি', NULL, 'ইন্দোনেশিয়া', NULL, 'নেদারল্যান্ড', NULL, 'C', 'গারুদা ইন্দোনেশিয়ার বিমান সংস্থা। অন্যদিকে, গ্রিসের বিমান সংস্থা অলিম্পিক এয়ারওয়েজ, জার্মানির বিমান সংস্থার নাম লুফথানসা এবং নেদারল্যান্ডের বিমান সংস্থার নাম রয়েল ডাচ এয়ারলাইন্স (কেএলএম)।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'adce218a936f1101427b409381a75fb3'),
(3797, 394, 'কোনটি ভারতের সেভেন সিস্টার্স রাজ্যসমূহের অন্তর্ভুক্ত নয়?', 'কেরালা', NULL, 'ত্রিপুরা', NULL, 'মণিপুর', NULL, 'মিজোরাম', NULL, 'A', 'সেভেন সিস্টার্স হলো বাংলাদেশের উত্তর-পূর্বে অবস্থিত ভারতের সীমান্ত থেকে প্রায় বিচ্ছিন্ন সাতটি রাজ্য। রাজ্যগুলো হলো আসাম, ত্রিপুরা, মণিপুর, মেঘালয়, মিজোরাম, অরুণাচল ও নাগাল্যান্ড। অন্যদিকে, কেরালা দক্ষিণ ভারতের রাজ্য।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ac1689bea2769bf09b591ee3c665b27c'),
(3798, 393, 'ফিলিস্তিনের প্রেসিডেন্ট ইয়াসির আরাফাত-এর আনুষ্ঠানিক অন্ত্যেষ্টিক্রিয়া অনুষ্ঠানে যোগদানের জন্য বিশ্বের বিভিন্ন দেশের রাষ্ট্রপ্রধান/সরকারপ্রধানগণ কোথায় মিলিত হন?', 'রামাল্লা', NULL, 'প্যারিস', NULL, 'কায়রো', NULL, 'জেরুজালেম', NULL, 'C', 'ফিলিস্তিনের প্রেসিডেন্ট ইয়াসির আরাফাত ১১ নভেম্বর ২০০৪ প্যারিসের পার্সি সামরিক হাসপাতালে ইন্তেকাল করেন। ইসরাইলের নিষেধাজ্ঞার কারণে তার অন্ত্যেষ্টিক্রিয়া অনুষ্ঠিত হয় মিশরের কায়রোতে এবং সেখানে বিশ্বের বিভিন্ন দেশের সরকার ও রাষ্ট্রপ্রধানগণ অন্ত্যেষ্টিক্রিয়া অনুষ্ঠানে যোগদান করেন।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '909d79b90e1747ae5d37c862f2fa4456'),
(3799, 391, 'United Nations Conference on Trade and Development (UNCTAD)-এর সদর দপ্তর কোথায়?', 'হেগে', NULL, 'জেনেভায়', NULL, 'নিউইয়র্কে', NULL, 'ক্যানবেরায়', NULL, 'B', 'জাতিসংঘের সাধারণ পরিষদের অঙ্গসংস্থা UNCTAD প্রতিষ্ঠিত হয় ১৯৬৪ সালে। এর সদর দপ্তর সুইজারল্যান্ডের জেনেভায় অবস্থিত।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3c4408679772731a16fdd692dae9987f'),
(3800, 391, 'যুক্তরাষ্ট্রের প্রেসিডেন্ট নির্বাচিত হতে হলে ন্যূনতম কত ইলেক্টোরাল ভোটের প্রয়োজন?', '২৭২', NULL, '২৭১', NULL, '২৭০', NULL, '২৬৮', NULL, 'C', 'যুক্তরাষ্ট্রের প্রেসিডেন্ট নির্বাচন সরাসরি ভোটের মাধ্যমে না হলেও ৫৩৮ সদস্যের ইলেক্টোরাল কলেজের পছন্দের ওপর প্রেসিডেন্ট প্রার্থীর জয়-পরাজয় নির্ভর করে। কোনো প্রার্থীকে প্রেসিডেন্ট নির্বাচনে জয়ী হওয়ার জন্য ইলেক্টোরাল কলেজের ২৭০টি ভোট পেতে হয়।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2b23dad46be9f8cb5f163a6633c2408a'),
(3801, 391, 'ইন্টারপোলের সদর দপ্তর কোথায় অবস্থিত?', 'লন্ডন', NULL, 'লিঁও', NULL, 'রোম', NULL, 'প্যারিস', NULL, 'B', 'ইন্টারপোলের সাবেক সদর দপ্তর প্যারিসে হলেও বর্তমানে ফ্রান্সের লিঁও শহরে ইন্টারপোলের সদর দপ্তর অবস্থিত।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ef240aa1978681ceb5f66a3dc882af2f'),
(3802, 124, 'ফিলিস্তিনিদের মাতৃভূমিতে কখন ইসরাইল রাষ্ট্র প্রতিষ্ঠিত হয়?', '১৯৪৮', NULL, '১৯৫০', NULL, '১৯৬৭', NULL, '১৯৭০', NULL, 'A', '২৯ নভেম্বর ১৯৪৭ জাতিসংঘের ৮১ নং প্রস্তাব অনুসারে ফিলিস্তিন রাষ্ট্র বিভক্তি ও ইসরাইল রাষ্ট্র প্রতিষ্ঠার প্রস্তাব গৃহীত হয়। কিন্তু শক্তিধর রাষ্ট্রগুলোর প্রত্যক্ষ প্রভাবে জাতিসংঘ প্রস্তাব উপেক্ষা করে ১৪ মে ১৯৪৮ ফিলিস্তিনিদের মাতৃভূমিতে ইসরাইল রাষ্ট্র প্রতিষ্ঠিত হয়।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b388799eff230a07cab6c2e2d1f9f1f1'),
(3803, 393, 'পশ্চিম তিমুর-এর বর্তমান মর্যাদা কি?', 'ইন্দোনেশিয়ার একটি অঙ্গরাজ্য', NULL, 'একটি স্বাধীন দেশ', NULL, 'অস্ট্রেলিয়ার একটি প্রদেশ', NULL, 'কোনোটিই ঠিক নয়', NULL, 'A', 'খ্রিস্টান অধ্যুষিত পূর্ব তিমুর ২০০২ সালের ২০ মে ইন্দোনেশিয়ার নিকট থেকে স্বাধীন হলেও পশ্চিম তিমুর স্বাধীন নয়। পশ্চিম তিমুর ইন্দোনেশিয়ার একটি প্রদেশ বা অঙ্গরাজ্য।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '43096de12ad7da3d58c35b778a8e5575'),
(3804, 391, 'কফি আনান আফ্রিকা মহাদেশ থেকে নিয়োগকৃত জাতিসংঘের কততম মহাসচিব?', 'প্রথম', NULL, 'তৃতীয়', NULL, 'দ্বিতীয়', NULL, 'চতুর্থ', NULL, 'C', 'আফ্রিকা থেকে নিয়োগকৃত জাতিসংঘের প্রথম মহাসচিব ড. বুট্রোস ঘালি (১৯৯১-৯৬)। পরবর্তীতে ১৯৯৭ সালে কফি আনান আফ্রিকা মহাদেশ থেকে নিয়োগকৃত জাতিসংঘের দ্বিতীয় মহাসচিব হিসেবে নিয়োগপ্রাপ্ত হন।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '89aa02479255e097d8771cc8460d47e0'),
(3805, 391, 'TI-এর সদর দপ্তর কোথায়?', 'ম্যানিলা', NULL, 'বার্লিন', NULL, 'ব্যাংকক', NULL, 'সিঙ্গাপুর', NULL, 'B', 'TI-এর পূর্ণ অভিব্যক্তি Transparency International। জার্মানির বার্লিনভিত্তিক এ সংস্থা পৃথিবীর বিভিন্ন দেশের দুর্নীতি সংক্রান্ত তথ্য বিশ্লেষণ করে এবং দুর্নীতির সূচক প্রদান করে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ed25d681eba5c0e345be72e2820cd0f6'),
(3806, 391, '২০০৪ সালে শান্তির জন্য নোবেল পুরস্কার লাভ করেন কোন দেশের নাগরিক?', 'ব্রাজিল', NULL, 'ইরান', NULL, 'সুইডেন', NULL, 'কেনিয়া', NULL, 'D', '২০০৪ সালে শান্তিতে নোবেল পুরস্কার লাভ করেন কেনিয়ার ওয়ানগারি মাথাই। পরিবেশ রক্ষায় Green Belt Movement-এর জন্য প্রথম আফ্রিকান নারী হিসেবে তিনি নোবেল পুরস্কার পান।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a301f16f57ac636d3c5cf4f0c2d11fd2'),
(3807, 391, 'ভারতীয় লোকসভার নির্বাচিত সদস্য সংখ্যা কত?', '৫৪৫', NULL, '৫৪৩', NULL, '৬১০', NULL, '৪১৫', NULL, 'B', 'দ্বি-কক্ষ বিশিষ্ট ভারতীয় কেন্দ্রীয় পার্লামেন্টের নিম্নকক্ষের নাম লোকসভা। ভারতের সংবিধান অনুযায়ী লোকসভার আসন সংখ্যা হতে পারবে সর্বোচ্চ ৫৫২। তবে বর্তমান লোকসভার নির্বাচিত সদস্য সংখ্যা ৫৪৩।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9e9cc0e356e846f5607a954274879579'),
(3808, 394, 'সুয়েজ খাল কোন দুটি সাগরকে সংযোজিত করে?', 'লোহিত সাগর ও ভূমধ্যসাগর', NULL, 'ভূমধ্যসাগর ও আরব সাগর', NULL, 'লোহিত সাগর ও আরব সাগর', NULL, 'ভূমধ্যসাগর ও কাস্পিয়ান সাগর', NULL, 'A', 'লোহিত সাগর ও ভূমধ্যসাগরকে সংযোগকারী জলপথ সুয়েজ খাল খনন করেন ফরাসি ইঞ্জিনিয়ার ফার্ডিনান্ড ডি লিসেপস ১৮৬৯ সালে এবং ১৯৫৬ সালে মিশর এটিকে জাতীয়করণ করে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e709c95df053abf6952b45eb4ed4c340'),
(3809, 406, 'কোন তারিখে আন্তর্জাতিক পরিবেশ দিবস পালিত হয়?', '৫ জুলাই', NULL, '২১ মার্চ', NULL, '৫ জুন', NULL, '২১ জুন', NULL, 'C', '৫ জুন আন্তর্জাতিক পরিবেশ দিবস। অন্যদিকে, ২১ মার্চ বিশ্ব বন দিবস, আন্তর্জাতিক বর্ণবৈষম্য বিলোপ দিবস, বিশ্ব কবিতা দিবস এবং ২১ জুন বিশ্ব সঙ্গীত দিবস, বিশ্ব হাইড্রোগ্রাফিক দিবস।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '38297a758afc17e867471b2b4c896aef'),
(3810, 390, 'লেবানন কোন দেশের কাছ থেকে স্বাধীনতা লাভ করে?', 'ব্রিটেন', NULL, 'ফ্রান্স', NULL, 'তুরস্ক', NULL, 'স্পেন', NULL, 'B', '১৯৪৩ সালের ২২ নভেম্বর লেবানন ফ্রান্সের কাছ থেকে স্বাধীনতা লাভ করে। লীগ অব নেশন্স-এর সিদ্ধান্ত অনুযায়ী প্রথম বিশ্বযুদ্ধের পরাজিত শক্তি জার্মানি ও তুরস্কের উপনিবেশগুলোকে ম্যান্ডেট ব্যবস্থার মাধ্যমে মিত্রশক্তির নিকট হস্তান্তর করা হয়।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '60c63ea91e64f1e60b167940f051e168'),
(3811, 122, 'গ্রিনিচ মান সময়ের সঙ্গে বাংলাদেশের সময়ের পার্থক্য কত ঘণ্টা?', 'ছয় ঘণ্টা', NULL, 'আট ঘণ্টা', NULL, 'দশ ঘণ্টা', NULL, 'পাঁচ ঘণ্টা', NULL, 'A', 'বাংলাদেশের অবস্থান ৯০° দ্রাঘিমা রেখায় এবং গ্রিনিচের অবস্থান ০° দ্রাঘিমায় হওয়ায় উভয়ের মধ্যে ৯০° অর্থাৎ (৪×৯০) ৩৬০ মিনিট বা ৬ ঘণ্টা সময়ের ব্যবধান রয়েছে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '55c3e2e05d2f99feb3f79fd4bd8f2028'),
(3812, 122, 'ভারতের কোন রাজ্যের রাজধানী ইম্ফল?', 'মিজোরাম', NULL, 'অরুণাচল', NULL, 'মণিপুর', NULL, 'মেঘালয়', NULL, 'C', 'ভারতের সেভেন সিস্টার্স খ্যাত সাতটি রাজ্যের মধ্যে মণিপুরের রাজধানী ইম্ফল। অন্যদিকে, মিজোরামের রাজধানী আইজল, মেঘালয়ের রাজধানী শিলং এবং অরুণাচলের রাজধানী ইটানগর।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fde4a742d909987ba69347a88d6f948a'),
(3813, 412, 'ইউরো মুদ্রা কখন চালু হয়?', '১৯৯৭ সালের ১ জানুয়ারি', NULL, '২০০০ সালের ১ মার্চ', NULL, '২০০১ সালের ১ জানুয়ারি', NULL, '১৯৯৮ সালের ১ নভেম্বর', NULL, 'A', 'ইউরো মুদ্রা চালু হয় ১ জানুয়ারি ১৯৯৯, ইউরো ব্যাংক নোটের প্রচলন হয় ১ জানুয়ারি ২০০২। সদস্য দেশগুলোর নিজস্ব ব্যাংক নোট ও মুদ্রা বাতিল হয় ১ জুলাই ২০০২। ইউরো মুদ্রার জনক রবার্ট মুন্ডেল।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1da37820fd9de989d918138d159bc7c4'),
(3814, 391, 'সহস্রাব্দ উন্নয়ন লক্ষ্যসমূহের সময়সীমা নির্ধারণ করা হয়েছে কোন সাল পর্যন্ত?', '২০১০', NULL, '২০১৫', NULL, '২০২০', NULL, '২০২৫', NULL, 'B', '২০০০ সালের সেপ্টেম্বরে জাতিসংঘ আয়োজিত বিশ্ব সম্মেলনে গৃহীত লক্ষ্য ও উদ্দেশ্যগুলোই মূলত মিলেনিয়াম ডেভলপমেন্ট গোল (MDG) নামে পরিচিত। এই লক্ষ্যমাত্রা সঠিকভাবে বাস্তবায়নের জন্য বিশ্ব নেতৃবৃন্দ ২০১৫ সাল পর্যন্ত সময়সীমা নির্ধারণ করে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '991fb2df381d065cba67d3ce38378018'),
(3815, 393, 'আবু সায়েফ গেরিলা গোষ্ঠী কোন দেশে তৎপর?', 'ইরাক', NULL, 'ফিলিপাইন', NULL, 'ইন্দোনেশিয়া', NULL, 'থাইল্যান্ড', NULL, 'B', '১৯৯১ সালে প্রতিষ্ঠিত স্বাধীনতাকামী আবু সায়েফ গ্রুপ (ASG) ফিলিপাইনের মুসলিম অধ্যুষিত মিন্দানাও প্রদেশে তৎপর। তারা দীর্ঘদিন ধরে মুসলিম সংখ্যাগরিষ্ঠ মিন্দানাও প্রদেশে একটি স্বাধীন মুসলিম রাষ্ট্র প্রতিষ্ঠার লড়াইয়ে রত।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5265ffeb77ae89b16e2c63d90cb756fc'),
