(3830, 394, 'কোন দেশটি স্ক্যান্ডিনেভিয়ার অন্তর্ভুক্ত নয়?', 'ডেনমার্ক', NULL, 'ফিনল্যান্ড', NULL, 'নেদারল্যান্ডস', NULL, 'যুক্তরাষ্ট্র', NULL, 'D', 'স্ক্যান্ডিনেভিয়া হচ্ছে ইউরোপ মহাদেশের উত্তরাঞ্চলের একটি এলাকার নাম। স্ক্যান্ডিনেভিয়া বলতে ৫টি দেশকে বোঝায়: ডেনমার্ক, ফিনল্যান্ড, আইসল্যান্ড, নরওয়ে এবং সুইডেন। যুক্তরাষ্ট্র উত্তর আমেরিকার দেশ।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9e697ad57cdfadb0f294ec8044c894cc'),
(3831, 124, 'মুসলমান প্রধান না হয়েও কোন দেশটি ইসলামী সহযোগিতা সংস্থার সদস্য?', 'নাইজেরিয়া', NULL, 'লেবানন', NULL, 'নাইজার', NULL, 'উগান্ডা', NULL, 'D', 'ওআইসি (Organisation of Islamic Cooperation) মূলত মুসলিম সংখ্যাগরিষ্ঠ দেশের সংগঠন। উপরিউক্ত দেশগুলোর মধ্যে মুসলমানদের সংখ্যা নাইজেরিয়ায় ৬৪%, লেবাননে ৫৭%, নাইজারে ৯৭% এবং উগান্ডায় ৩৬%।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4feadb77a8339559dd7b9ed72d0d2e8b'),
(3832, 124, 'কিউবায় ক্ষেপণাস্ত্র সঙ্কটের সময় যুক্তরাষ্ট্রের প্রেসিডেন্ট কে ছিলেন?', 'রিচার্ড এম নিক্সন', NULL, 'জন এফ কেনেডি', NULL, 'লিন্ডন বেইনস জনসন', NULL, 'হ্যারি এস ট্রুম্যান', NULL, 'B', 'জন এফ কেনেডি ডেমোক্র্যাট দল থেকে নির্বাচিত যুক্তরাষ্ট্রের ৩৫তম প্রেসিডেন্ট। তিনি আন্তর্জাতিক ক্ষেত্রে সবচেয়ে বড় সঙ্কট মোকাবিলা করেন ১৯৬২ সালের কিউবার ক্ষেপণাস্ত্র সংকট।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a02b6836b3a3ca83dc8af727257849b4'),
(3833, 124, 'মার্কিন যুক্তরাষ্ট্রের কোন প্রেসিডেন্ট ১২ বছর ক্ষমতায় অধিষ্ঠিত ছিলেন?', 'হ্যারি এস ট্রুম্যান', NULL, 'ফ্রাঙ্কলিন রুজভেল্ট', NULL, 'জেমস মনরো', NULL, 'তথ্যটি সঠিক নয়', NULL, 'B', 'যুক্তরাষ্ট্রে সবচেয়ে বেশি সময় ক্ষমতায় ছিলেন ডেমোক্র্যাট দল থেকে নির্বাচিত ৩২তম প্রেসিডেন্ট ফ্রাঙ্কলিন ডি রুজভেল্ট। তিনি তিন মেয়াদে ১৯৩৩ থেকে ১৯৪৫ পর্যন্ত ১২ বছর ক্ষমতায় ছিলেন।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2d406a5d9f5414660e6cd0ad63354f3c'),
(3834, 391, 'ভারতীয় লোকসভার নির্বাচিত সদস্য সংখ্যা কত?', '৫৪৩', NULL, '৫৪৫', NULL, '৪১৪', NULL, '৫৪০', NULL, 'A', 'দ্বি-কক্ষ বিশিষ্ট ভারতীয় কেন্দ্রীয় পার্লামেন্টের নিম্নকক্ষের নাম লোকসভা। ভারতের সংবিধান অনুযায়ী লোকসভার আসন সংখ্যা হতে পারবে সর্বোচ্চ ৫৫২। তবে বর্তমান লোকসভার নির্বাচিত সদস্য সংখ্যা ৫৪৩।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8dbc875f1e1bbfe2405fa99e1bedf2c7'),
(3835, 124, 'কোন দেশের মহিলারা সর্বপ্রথম ভোটাধিকার লাভ করে?', 'মার্কিন যুক্তরাষ্ট্র', NULL, 'নিউজিল্যান্ড', NULL, 'বাহামা', NULL, 'সুইজারল্যান্ড', NULL, 'B', 'বিশ্বের প্রথম দেশ হিসেবে ১৮৯৩ সালে নিউজিল্যান্ডে নারীর ভোটাধিকার স্বীকৃত হয়। যুক্তরাষ্ট্রে মহিলারা ভোটাধিকার লাভ করে ১৯২০ সালে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'aee2d195e337afa60dace7b96cae2482'),
(3836, 397, 'রাসায়নিক অস্ত্র চুক্তি (Chemical Weapons Convention) কোন সালে স্বাক্ষরিত হয়?', '১৯৯০', NULL, '১৯৯৩', NULL, '১৯৯৬', NULL, '১৯৯৯', NULL, 'B', '১৯৯৩ সালে রাসায়নিক অস্ত্র কনভেনশন (Chemical Weapons Convention) স্বাক্ষরিত হয়। এ চুক্তিতে রাসায়নিক অস্ত্রের উন্নয়ন, উৎপাদন, মজুদ ও ব্যবহার নিষিদ্ধ করা হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '78120b044ccd9fca95afc3b77c19c4c2'),
