(3840, 391, 'অক্সফাম (Oxfam)-এর সদর দপ্তর কোথায়?', 'নিউইয়র্ক', NULL, 'ক্যামেনিক্স', NULL, 'লন্ডন', NULL, 'হেগ', NULL, 'C', 'অক্সফাম (Oxfam) ব্রিটেনের বিখ্যাত আন্তর্জাতিক স্বেচ্ছাসেবী দাতব্য সংস্থা। ১৯৪২ সালে প্রতিষ্ঠিত সংস্থাটির সদর দপ্তর লন্ডনে অবস্থিত।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2d46e2569b3086c4cb63bb23fb3d9c90'),
(3841, 124, 'কোনটি বিংশ শতাব্দীর শেষভাগে উপনিবেশবাদের নিগড় থেকে মুক্ত হয়?', 'হংকং', NULL, 'শ্রীলংকা', NULL, 'ম্যাকাউ', NULL, 'বাংলাদেশ', NULL, 'C', 'বিংশ শতাব্দীর শেষভাগে পর্তুগাল তাঁর উপনিবেশ ম্যাকাউ ১৯৯৯ সালের ১৯ ডিসেম্বর মধ্য রাতে চীনের কাছে হস্তান্তর করে এবং ২০ ডিসেম্বর থেকে ম্যাকাউর ওপর চীনের পূর্ণ কর্তৃত্ব প্রতিষ্ঠিত হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '38f77c8026ebfc07c5cc5cac21902e45'),
