(3843, 124, 'Amnesty International কত সালে নোবেল শান্তি পুরস্কার পেয়েছিল?', '১৯৭৭', NULL, '১৯৭৮', NULL, '১৯৭৯', NULL, '১৯৮১', NULL, 'A', 'আন্তর্জাতিক সেবাধর্মী স্বেচ্ছাসেবী সংগঠন অ্যামনেস্টি ইন্টারন্যাশনাল ২৮ মে, ১৯৬১ সালে ব্রিটিশ আইনজ্ঞ পিটার বেনেনসন প্রতিষ্ঠা করেন। এ সংস্থা ১৯৭৭ সালে শান্তিতে নোবেল পুরস্কার লাভ করে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a3fca876ae5f6482d659f6cbf545f719'),
(3844, 124, 'START-2 কী?', 'টিভিতে সম্প্রচারিত একটি সিরিয়াল', NULL, 'বাণিজ্য সংক্রান্ত একটি চুক্তি', NULL, 'কৌশলগত অস্ত্র হ্রাস সংক্রান্ত চুক্তি', NULL, 'এর কোনোটিই নয়', NULL, 'C', '১৯৯৩ সালের ৩ জানুয়ারি মার্কিন যুক্তরাষ্ট্র ও রাশিয়ার মধ্যে পারমাণবিক অস্ত্র বিশেষত দূর পাল্লার পারমাণবিক ক্ষেপণাস্ত্র আগামী ১০ বছরের মধ্যে দুই-তৃতীয়াংশ হ্রাস করার লক্ষ্যে এই চুক্তি স্বাক্ষরিত হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0e34f23246e5335df92f9b504a6a294d'),
(3845, 395, 'আসিয়ান রিজিওনাল ফোরাম (ARF)-এর সদস্য সংখ্যা কত?', '২১', NULL, '২২', NULL, '২৩', NULL, '২৬', NULL, 'D', 'ARF-এর বর্তমান সদস্য সংখ্যা ২৭। এআরএফের ২৬তম সদস্য দেশ বাংলাদেশ। ২০০৬ সালের ২৮ জুলাই বাংলাদেশ সদস্যপদ লাভ করে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4d12ba0a8c6f32f9cbb96ff9d0fadce2'),
(3846, 401, 'মালয়েশিয়ার সাবেক প্রধানমন্ত্রী ড. মাহাথির মোহাম্মদ কত বছর ক্ষমতায় ছিলেন?', '২১ বছর', NULL, '২২ বছর', NULL, '২৪ বছর', NULL, '২৫ বছর', NULL, 'B', '১৯৮১ থেকে ২০০৩ সাল পর্যন্ত দীর্ঘ ২২ বছর ক্ষমতায় থাকার পর স্বেচ্ছায় পদত্যাগ করেন। ১০ মে, ২০১৮ তিনি পুনরায় দেশটির প্রধানমন্ত্রী নির্বাচিত হন। ২৫ ফেব্রুয়ারি, ২০২০ সালে তিনি পদত্যাগ করেন।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a6aee85261a1fb7ceedb9c3681226ccd'),
(3847, 121, 'বাংলাদেশ কত সালে ইসলামী সম্মেলন সংস্থার সদস্যপদ লাভ করে?', '১৯৭২ সালে', NULL, '১৯৭৩ সালে', NULL, '১৯৭৪ সালে', NULL, '১৯৭৫ সালে', NULL, 'C', '১৯৭৪ সালের ২৩ ফেব্রুয়ারি পাকিস্তানের লাহোরে অনুষ্ঠিত ওআইসির দ্বিতীয় শীর্ষ সম্মেলনে বাংলাদেশ সদস্যপদ লাভ করে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1860f087dc7058ad944c495694717290'),
(3848, 393, 'ইরাকের বর্তমান প্রেসিডেন্ট জালাল তালাবানি কোন সম্প্রদায়ের?', 'সুন্নি', NULL, 'শিয়া', NULL, 'কুর্দি', NULL, 'খ্রিস্টান', NULL, 'C', 'ইরাকের সাবেক প্রেসিডেন্ট জালাল তালাবানি কুর্দি সম্প্রদায়ের ছিলেন। ইরাকের বর্তমান প্রেসিডেন্ট আবদুল লতিফ রশিদ এবং প্রধানমন্ত্রী মোহাম্মদ শিয়া আল সুদানি।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '409e9dbbb793c9c1722d236996fd4436'),
(3849, 391, 'যুক্তরাষ্ট্রের সিনেটের মোট আসন সংখ্যা কতটি?', '৯৯', NULL, '১০০', NULL, '১০১', NULL, '১০২', NULL, 'B', 'মার্কিন যুক্তরাষ্ট্রের দ্বিকক্ষ বিশিষ্ট পার্লামেন্টের নাম কংগ্রেস। এর উচ্চকক্ষের নাম সিনেট (Senate) এবং নিম্নকক্ষের নাম প্রতিনিধি পরিষদ (House of Representatives)। যুক্তরাষ্ট্রের ৫০টি অঙ্গরাজ্যের প্রতিটি হতে ২জন করে মোট ১০০ জন সিনেটর নির্বাচিত হন।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f3ee1e5cfc1494645952664a0226d7f3'),
(3850, 391, 'ফেয়ার ফ্যাক্স কী?', 'সংবাদ সংস্থা', NULL, 'পরিবেশ সংস্থা', NULL, 'গোয়েন্দা সংস্থা', NULL, 'মানবাধিকার সংস্থা', NULL, 'C', 'ফেয়ার ফ্যাক্স (Fairfax) মার্কিন যুক্তরাষ্ট্রের একটি বেসরকারি অর্থনৈতিক গোয়েন্দা সংস্থা। এছাড়া ফেয়ার ফ্যাক্স নামে অস্ট্রেলিয়ায় একটি বহুমুখী মিডিয়া কোম্পানি রয়েছে।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '490a74f2631849813d32307992568643'),
(3851, 391, 'NASA-এর সদর দপ্তর কোথায়?', 'ফ্লোরিডা', NULL, 'হিউস্টন', NULL, 'কেপ কেনেডি', NULL, 'টেকসাস', NULL, 'B', 'NASA-এর সদর দপ্তর ওয়াশিংটন ডি.সি.-তে অবস্থিত। তবে NASA-এর প্রধান মহাকাশ কেন্দ্র হিউস্টন, টেক্সাসে অবস্থিত।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b6a9c201c52084e3c17d4afd49e999ea'),
(3852, 389, 'দক্ষিণ আফ্রিকা কত বছর শ্বেতাঙ্গ শাসনে ছিল?', '৩০০ বছর', NULL, '৩৩৫ বছর', NULL, '৩৪২ বছর', NULL, '৫০০ বছর', NULL, 'C', 'আফ্রিকা মহাদেশের সবচেয়ে সম্পদশালী দেশ দক্ষিণ আফ্রিকা ৩৪২ বছর শ্বেতাঙ্গ শাসনে ছিল। ১৯৯২ সালে দক্ষিণ আফ্রিকার বর্ণবাদ নীতিকে সরকারিভাবে বিলোপ করা হয়।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4a6eb04e7d54b29f38f7aa69b4e06f38'),
(3853, 124, 'বসনিয়ার যুদ্ধবিরতি স্বাক্ষরের মধ্যস্থতাকারী কে?', 'বিল ক্লিনটন', NULL, 'জিমি কার্টার', NULL, 'নিক্সন', NULL, 'রিগান', NULL, 'B', 'বসনিয়া-হার্জেগোভিনায় জাতিগত দ্বন্দ্ব ও গৃহযুদ্ধের প্রেক্ষিতে মার্কিন যুক্তরাষ্ট্রের সাবেক রাষ্ট্রপতি জিমি কার্টারের মধ্যস্থতায় ২৩ ডিসেম্বর ১৯৯৪ বসনিয়ার মুসলিম সরকার ও সার্ববাহিনীর মধ্যে একটি যুদ্ধবিরতি চুক্তি স্বাক্ষরিত হয়।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9355ee71935b4e386194f96bf4cef2e5'),
(3854, 401, 'ফ্রান্সের বর্তমান প্রেসিডেন্টের নাম কী?', 'নিকোলাস সার্কোজি', NULL, 'জ্যাক শিরাক', NULL, 'ফ্রঁসোয়া মিতেরাঁ', NULL, 'জেনারেল দ্য গল', NULL, 'A', 'ফ্রান্সের বর্তমান প্রেসিডেন্ট এমানুয়েল মাখোঁ। তিনি ২০২২ সালে পুনরায় নির্বাচিত হন এবং গত ২০ বছরের মধ্যে ফ্রান্সে প্রথমবারের মতো কোনো প্রেসিডেন্ট হিসেবে দুই মেয়াদে ক্ষমতায় রয়েছেন।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '21a8147ddf1fbcfe1a626b893c5d6c72'),
(3855, 122, 'হোয়াংহো নদীর উৎপত্তিস্থল কোথায়?', 'হিমালয়', NULL, 'কুয়েনলুন পর্বত', NULL, 'ব্ল্যাক ফরেস্ট', NULL, 'আল্পস', NULL, 'B', 'হোয়াংহো নদী চীনে অবস্থিত। এর দৈর্ঘ্য ৫,৪৬৪ কিমি; উৎপত্তিস্থল কুয়েনলুন পর্বত। এটি পতিত হয়েছে পীত সাগরে। হোয়াংহো নদীকে বলা হয় হলদে নদ বা পীত নদী।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f61aca2eb148279d40c4625f5d234066'),
(3856, 122, 'মেক্সিকো ও যুক্তরাষ্ট্র বিভক্তকারী সীমারেখা কোনটি?', 'সনোরা লাইন', NULL, 'ম্যাকনামারা লাইন', NULL, 'ডুরান্ড লাইন', NULL, 'হিন্ডারবার্গ লাইন', NULL, 'B', 'মেক্সিকো ও যুক্তরাষ্ট্রের মধ্যে সীমারেখা হলো রিও গ্রান্ডে নদী। তবে প্রশ্নে উল্লিখিত অপশনগুলোর মধ্যে ম্যাকনামারা লাইন যুক্তরাষ্ট্র-মেক্সিকো সীমান্তের একটি অংশ চিহ্নিত করে।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bf52a4805091da799ba66a6c96737b80'),
(3857, 394, 'ইউরোপের ককপিট বলা হয় কোন দেশকে?', 'বেলজিয়াম', NULL, 'ফ্রান্স', NULL, 'জার্মানি', NULL, 'ফিনল্যান্ড', NULL, 'A', 'প্রায়শ যুদ্ধ সংঘটিত হয়েছে এরূপ স্থানকে ককপিট বলা হয়। বেলজিয়ামকে ইউরোপের ককপিট বা ইউরোপের সমরক্ষেত্র বা রণক্ষেত্র বলা হয়, কারণ এখানে ওয়াটারলুসহ অনেক বিখ্যাত যুদ্ধ সংঘটিত হয়।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cff01b13b0aa5a20012a58c2f6f829ae'),
(3858, 391, 'বিশ্বের কোন দেশের সাক্ষরতার হার ১০০%?', 'পোল্যান্ড', NULL, 'লিথুয়ানিয়া', NULL, 'কাজাখস্তান', NULL, 'স্লোভাকিয়া', NULL, 'B', 'World Population Review-এর তথ্য অনুসারে পৃথিবীর যে সকল দেশের সাক্ষরতার হার ১০০%-এর কাছাকাছি তার মধ্যে লিথুয়ানিয়া অন্যতম।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9cd778e388a18f4a26130816b400604d'),
(3859, 412, 'আইএলও-র সদর দপ্তর কোথায় অবস্থিত?', 'লন্ডন', NULL, 'জেনেভা', NULL, 'নিউইয়র্ক', NULL, 'দিল্লী', NULL, 'B', 'জেনেভা সুইজারল্যান্ডে অবস্থিত একটি বিখ্যাত শহর। ILO ছাড়াও জেনেভায় WHO, WTO, ITU, WMO, WIPO, UNHCR, UNCTAD, ITC, OHCHR, UNITAR, UNRISD, জাতিসংঘ মানবাধিকার কাউন্সিল, রেডক্রস, বিশ্ব স্কাউট সংস্থা, ISO, IAS, IPU-এর সদর দপ্তর অবস্থিত।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '83eee6bc56f6a949114f17e74df95a22'),
(3860, 412, 'এসকাপের সদর দপ্তর কোথায় অবস্থিত?', 'ব্যাংকক', NULL, 'সিঙ্গাপুর', NULL, 'দিল্লী', NULL, 'কলম্বো', NULL, 'A', 'Economic and Social Commission for Asia and the Pacific (ESCAP)-এর সদর দপ্তর ১৯৪৭ সালে থাইল্যান্ডের রাজধানী ব্যাংককে প্রতিষ্ঠা করা হয়।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6074f49120b973ab474232e18fa1badc'),
(3861, 413, 'ইউরোপীয় ইউনিয়নের সদর দপ্তর কোথায় অবস্থিত?', 'লন্ডন', NULL, 'ব্রাসেলস', NULL, 'বন', NULL, 'প্যারিস', NULL, 'B', 'বেলজিয়ামের রাজধানী ব্রাসেলসকে ইউরোপের রাজধানী বলা হয়। এছাড়াও ব্রাসেলসে রয়েছে ইউরোপিয়ান পার্লামেন্ট, কাউন্সিল অব মিনিস্টারস্, ইউরোপিয়ান কমিশনের সদর দপ্তর।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'db20ea2814ee5516e535e81f7d35ca42');
