(3862, 121, 'বাংলাদেশকে প্রথম স্বীকৃতিদানকারী দেশ কোনটি?', 'ভারত', NULL, 'শ্রীলংকা', NULL, 'মায়ানমার', NULL, 'রাশিয়া', NULL, 'A', 'বাংলাদেশকে প্রথম স্বীকৃতিদানকারী দেশ ভুটান (৬ ডিসেম্বর, ১৯৭১)। দ্বিতীয় দেশ ভারত (৬ ডিসেম্বর, ১৯৭১)।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e624e8aaf9caedd313891c7112791ea1'),
(3863, 394, 'East London কোথায় অবস্থিত?', 'ইংল্যান্ডে', NULL, 'জার্মানিতে', NULL, 'আমেরিকায়', NULL, 'দক্ষিণ আফ্রিকায়', NULL, 'D', 'দক্ষিণ আফ্রিকায় অবস্থিত বাফেলো (Buffalo) নদীর তীরবর্তী শহর East London. ইংল্যান্ডের স্যার হ্যারি স্মিথ (Sir Harry Smith) এ নামকরণ করেন।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '40f4381f78cfb6d99932666a8827cef5'),
(3864, 389, 'ব্রিটিশ ভারতের শেষ ভাইসরয় কে ছিলেন?', 'লর্ড কার্জন', NULL, 'লর্ড মাউন্টব্যাটেন', NULL, 'লর্ড বেন্টিঙ্ক', NULL, 'লর্ড ওয়াভেল', NULL, 'B', 'লর্ড মাউন্টব্যাটেন (মেয়াদকাল ১৯৪৫-১৯৪৭) ভারতবর্ষকে ভেঙে ১৪ আগস্ট, ১৯৪৭ পাকিস্তান এবং ১৫ আগস্ট, ১৯৪৭ ভারত নামে দুইটি রাষ্ট্র গঠন করেন। ভারতবর্ষের স্বাধীনতার পর তার ভাইসরয় উপাধি বিলুপ্ত হয়ে গভর্নর জেনারেল উপাধিতে রূপান্তরিত হয়। ফলে তিনি ভারতের শেষ ভাইসরয় ও প্রথম গভর্নর জেনারেলে পরিণত হন।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8ea089c80f14482fba3b0b08ab3bdb38'),
(3865, 401, 'মার্কিন যুক্তরাষ্ট্রের বর্তমান পররাষ্ট্রমন্ত্রীর নাম কি?', 'জর্জ বুশ', NULL, 'হিলারী ক্লিনটন', NULL, 'রবার্ট গেইট', NULL, 'কন্ডালিসা রাইস', NULL, 'B', 'মার্কিন যুক্তরাষ্ট্রের বর্তমান পররাষ্ট্রমন্ত্রী অ্যান্টনি জন ব্লিনকেন। ২০২১ সালের ২৬ জানুয়ারি ৭১তম পররাষ্ট্রমন্ত্রী হিসেবে দায়িত্ব গ্রহণ করেন।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ca138273d03f9662cc1c7587bf4e7417'),
(3866, 401, 'ভারতের বর্তমান প্রধানমন্ত্রীর নাম কি?', 'সোনিয়া গান্ধী', NULL, 'ড. মনমোহন সিং', NULL, 'মমতা ব্যানার্জী', NULL, 'রাহুল গান্ধী', NULL, 'B', 'ভারতের বর্তমান প্রধানমন্ত্রী নরেন্দ্র মোদি। তিনি ২৬ মে, ২০১৪ ভারতের প্রধানমন্ত্রী হিসেবে প্রথমবার শপথ গ্রহণ করেন এবং ৩০ মে, ২০১৯ দ্বিতীয় মেয়াদে প্রধানমন্ত্রী হিসেবে শপথ গ্রহণ করেন।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '32bfb5f3b8eb77dafb52cd189b350924'),
(3867, 391, 'জাতিসংঘের সদর দপ্তর কোথায় অবস্থিত?', 'লন্ডন', NULL, 'নিউইয়র্ক', NULL, 'প্যারিস', NULL, 'মস্কো', NULL, 'B', 'জাতিসংঘের সদর দপ্তর নিউইয়র্কে অবস্থিত। এছাড়াও নিউইয়র্কে ইউনিসেফ (UNICEF), ইউএনডিপি (UNDP), ইউএনএফপিএ (UNFPA), ইউনিফেম (UNIFEM)-এর সদর দপ্তর রয়েছে।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b675d0ad4b34cef468cd128026de54f5'),
(3868, 395, 'সার্কের সচিবালয় কোথায় অবস্থিত?', 'দিল্লী', NULL, 'ইসলামাবাদ', NULL, 'কাঠমান্ডু', NULL, 'ঢাকা', NULL, 'C', '১৬ জানুয়ারি, ১৯৮৭ নেপালের রাজধানী কাঠমান্ডুতে সার্ক সচিবালয় প্রতিষ্ঠা করা হয়। এছাড়া কাঠমান্ডুতে রয়েছে সার্ক যক্ষ্মা কেন্দ্র।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '36b0e4afa0d7407118a2ef9dd4edfafe'),
(3869, 124, 'খাদ্য ও কৃষি সংস্থার প্রধান কার্যালয় কোথায় অবস্থিত?', 'নিউইয়র্কে', NULL, 'রোমে', NULL, 'জেনেভায়', NULL, 'অটোয়ায়', NULL, 'B', 'খাদ্য ও কৃষি সংস্থা (FAO)-এর প্রধান কার্যালয় ইতালির রোমে অবস্থিত। এছাড়া রোমে IFAD ও WFP-এর সদর দপ্তর অবস্থিত। FAO প্রতিষ্ঠিত হয় ১৬ অক্টোবর, ১৯৪৫।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c3fd5229c1e85894ccefa6390be86c32'),
(3870, 401, 'ডেভিস কাপ কোন খেলায় দেয়া হয়?', 'ব্যাডমিন্টন', NULL, 'লন টেনিস', NULL, 'টেবিল টেনিস', NULL, 'ক্রিকেট', NULL, 'B', 'ডেভিস কাপ লন টেনিস খেলার প্রতিযোগিতা। ১৯০০ সালে Dwight Davis এই কাপের প্রচলন করেন। লন টেনিসের অন্যান্য কাপগুলো হলো উইম্বলডন, অস্ট্রেলিয়ান ওপেন, ফ্রেঞ্চ ওপেন, ইউএস ওপেন ইত্যাদি।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1d3e0abd37b59b9830b62acdd8d7ab43'),
(3871, 395, 'ষোড়শ সার্ক সম্মেলন কোথায় অনুষ্ঠিত হয়?', 'ঢাকা', NULL, 'কাঠমাণ্ডু', NULL, 'থিম্পু', NULL, 'মালে', NULL, 'C', 'ষোড়শ সার্ক সম্মেলন ২৮-২৯ এপ্রিল, ২০১০ ভুটানের রাজধানী থিম্পুতে অনুষ্ঠিত হয়। সার্ক প্রতিষ্ঠার পর ২০১০ সালেই প্রথম ভুটানে সার্ক সম্মেলন অনুষ্ঠিত হয়। সম্মেলনের মূল প্রতিপাদ্য ছিল: সবুজ ও সুখী দক্ষিণ এশিয়ার পথে।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a0055729674697dd7279fa54d6074b00'),
(3872, 412, 'বিশ্বের সবচেয়ে বড় অর্থনৈতিক জোট কোনটি?', 'EU', NULL, 'WTO', NULL, 'NATO', NULL, 'FIFA', NULL, 'A', 'ইউরোপীয় ইউনিয়ন (EU) বিশ্বের সবচেয়ে বড় অর্থনৈতিক জোট। WTO একটি বৈশ্বিক বাণিজ্য সংস্থা, NATO সামরিক জোট এবং FIFA ফুটবল সংস্থা।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dfa47fdfe73883871e19c0482f3aa6a7'),
(3873, 391, 'আলফ্রেড নোবেল কি আবিষ্কার করেন?', 'ডিনামাইট', NULL, 'বিদ্যুৎ', NULL, 'পোলিও টিকা', NULL, 'কয়লা', NULL, 'A', 'আলফ্রেড বার্নার্ড নোবেল ১৮৩৩ সালে ২১ অক্টোবর সুইডেনের স্টকহোমে জন্মগ্রহণ করেন। ১৮৬৬ সালে তিনি কিজেলগুর নামে বিশেষ এক ধরনের শৈবালযুক্ত মাটির জৈব মোড়ক আবিষ্কার করতে সক্ষম হন। ১৮৬৭ সালে তার এ উদ্ভাবন ডিনামাইট নামে পেটেন্ট হয়।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3602f273fbf666be67941afbfdf8ae12'),
(3874, 124, 'নিম্নের কোন দেশটি G-8 এর সদস্য নয়?', 'জাপান', NULL, 'যুক্তরাজ্য', NULL, 'ফ্রান্স', NULL, 'সুইডেন', NULL, 'D', 'বিশ্বের শিল্পোন্নত দেশসমূহের সংগঠন G-8 (Group Eight) ১৫ নভেম্বর, ১৯৭৫ সালে প্রতিষ্ঠিত হয়। বর্তমান G-7 সদস্য রাষ্ট্রসমূহ হলো: মার্কিন যুক্তরাষ্ট্র, যুক্তরাজ্য, ফ্রান্স, জার্মানি, ইতালি, জাপান ও কানাডা। সুইডেন G-8-এর সদস্য নয়।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '414c6eddb931118657e4bb1e9041a894'),
(3875, 394, 'হাজার হ্রদের দেশ কোনটি?', 'নরওয়ে', NULL, 'ফিনল্যান্ড', NULL, 'ইন্দোনেশিয়া', NULL, 'জাপান', NULL, 'B', 'নরওয়ের ভৌগোলিক উপনাম নিশীথ সূর্যের দেশ। জাপানের ভৌগোলিক উপনাম সূর্যোদয়ের দেশ ও ভূমিকম্পের দেশ। ফিনল্যান্ডের ভৌগোলিক উপনাম হাজার হ্রদের দেশ।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '399fa986b0b916ee7a6e52698b8eda34'),
(3876, 124, 'কোথায় সেনাবাহিনী নেই?', 'সুদান', NULL, 'সাইপ্রাস', NULL, 'মালদ্বীপ', NULL, 'ভুটান', NULL, 'C', 'এই পরীক্ষা অনুষ্ঠিত হবার সময় মালদ্বীপে সেনাবাহিনী ছিলো না। বর্তমানে মালদ্বীপস ন্যাশনাল ডিফেন্স ফোর্স (Maldives National Defence Force) রয়েছে। তবে মালদ্বীপের কোনো স্থলবাহিনী নেই।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cb57aa7456a5d1a1bfe14bceb3c40a53'),
(3877, 124, 'কবে রেডক্রস প্রতিষ্ঠিত হয়?', '১৮৬৪ সালে', NULL, '১৮৬৮ সালে', NULL, '১৮৬৬ সালে', NULL, '১৮৬১ সালে', NULL, 'A', 'বিশ্বের দুস্থ মানবতার সেবায় নিয়োজিত আন্তর্জাতিক সেবা প্রতিষ্ঠান রেডক্রস ৯ ফেব্রুয়ারি, ১৮৬৩ সালে সুইজারল্যান্ডের নাগরিক হেনরি ডুনান্ট-এর সহযোগিতায় প্রতিষ্ঠিত হয়। মুসলিম বিশ্বে এটি রেড ক্রিসেন্ট নামে পরিচিত।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c74b5362bd03e55ad59d12e6eb6fd351'),
(3878, 391, 'বিশ্ব মানবাধিকার দিবস কবে পালিত হয়?', '২৬ জুন', NULL, '১ আগস্ট', NULL, '১ মে', NULL, '১০ ডিসেম্বর', NULL, 'D', '১৯৪৮ সালের ১০ ডিসেম্বর জাতিসংঘের সাধারণ পরিষদে তৃতীয় অধিবেশনে মানবাধিকার সম্পর্কে সর্বজনীন ঘোষণা অনুমোদিত হয়। সেই থেকে প্রতিবছর ১০ ডিসেম্বর সর্বজনীন মানবাধিকার দিবস হিসেবে পালিত হচ্ছে।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5a9bff63184c75f4e48c8d66bbef1dbb'),
(3879, 124, 'FIFA প্রতিষ্ঠিত হয় কবে?', '১৯০৪', NULL, '১৯২৪', NULL, '১৯১৪', NULL, '১৯০৫', NULL, 'A', 'FIFA বা Federation of International Football Association গঠিত হয় ১৯০৪ সালের ২১ মে ফ্রান্সের রাজধানী প্যারিসে। FIFA-এর সদর দপ্তর সুইজারল্যান্ডের জুরিখে অবস্থিত। বর্তমান সভাপতি জিয়ান্নি ইনফান্তিনো (সুইজারল্যান্ড)।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7e9d3b204ab4924e551fad5c8f152dfe'),
(3880, 391, 'কিরগিজস্তানের রাজধানী কোথায়?', 'বিশকেক', NULL, 'আলমাআতা', NULL, 'আশখাবাদ', NULL, 'উলানবাটো', NULL, 'A', 'মধ্য এশিয়ার দেশ কিরগিজস্তানের রাজধানী বিশকেক। তুর্কমেনিস্তানের রাজধানী আশখাবাদ, কাজাখস্তানের রাজধানী আস্তানা (পূর্বে আলমাআতা) এবং মঙ্গোলিয়ার রাজধানী উলানবাটোর।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '97c1631a6892e16ddb76cbc1b6f2921f'),
(3881, 406, 'বিশ্ব পরিবেশ দিবস কোনটি?', '৫ মে', NULL, '১৫ মে', NULL, '৫ জুন', NULL, '১৫ জুন', NULL, 'C', '৫ মে আন্তর্জাতিক ধাত্রী দিবস, ১৫ মে আন্তর্জাতিক পরিবার দিবস এবং ৫ জুন বিশ্ব পরিবেশ দিবস।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e2a7311f6e2a37beabde8bc0981211d5'),
(3882, 394, 'হাজার হ্রদের দেশ কোনটি?', 'নরওয়ে', NULL, 'ফিনল্যান্ড', NULL, 'ইন্দোনেশিয়া', NULL, 'জাপান', NULL, 'B', 'স্থানীয় অধিবাসীদের কাছে সুমোয় নামে পরিচিত স্ক্যান্ডিনেভিয়ান দেশ ফিনল্যান্ডের ভৌগোলিক উপনাম হাজার হ্রদের দেশ। নরওয়ের ভৌগোলিক উপনাম নিশীথ সূর্যের দেশ। জাপানের ভৌগোলিক উপনাম সূর্যোদয়ের দেশ ও ভূমিকম্পের দেশ।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '399fa986b0b916ee7a6e52698b8eda34'),
(3883, 391, 'পূর্বে কোন দেশটি শ্যামদেশ নামে পরিচিত ছিল?', 'মালয়েশিয়া', NULL, 'ইন্দোনেশিয়া', NULL, 'থাইল্যান্ড', NULL, 'মায়ানমার', NULL, 'C', 'থাইল্যান্ডের পূর্বনাম শ্যামদেশ। পক্ষান্তরে ইন্দোনেশিয়ার পূর্বনাম ডাচ ইস্ট ইন্ডিয়া, মালয়েশিয়ার পূর্বনাম মালয় এবং মিয়ানমারের পূর্বনাম বার্মা।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4fcdb94fdfdb09834b2cdfd718a2def5'),
(3884, 391, 'হারারের পূর্ব নাম কি?', 'সলসব্যারি', NULL, 'রোডেসিয়া', NULL, 'জিবুতি', NULL, 'জায়ারে', NULL, 'A', 'জিম্বাবুয়ের রাজধানী হারারের পূর্বনাম সলসব্যারি। পক্ষান্তরে রোডেসিয়া হলো জিম্বাবুয়ের, জায়ার হলো ডেমোক্রেটিক রিপাবলিক অব দ্য কঙ্গোর পূর্ব নাম।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4b81d17fda4afd7b329405e69bc9cb43'),
(3885, 389, 'কবে ফরাসি বিপ্লব সংঘটিত হয়?', '১৭৮৯', NULL, '১৭৯১', NULL, '১৭৯৫', NULL, '১৮০০', NULL, 'A', '১৭৭৮ থেকে ১৭৮৯ সাল পর্যন্ত ফ্রান্সের নানা উত্তাল ঘটনাধারা ফরাসি বিপ্লব নামে ইতিহাস প্রসিদ্ধ হয়ে আছে। ১৭৮৯ সালের ১৪ জুলাই বাস্তিল দুর্গ আক্রমণ ও দখলের মাধ্যমে জনগণের বিপ্লবী অভ্যুত্থান জয়যুক্ত হয়।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fa590d2163754b3af7d09363b4d7a7ca'),
(3886, 389, 'কার্ল মার্কস কোন দেশে মৃত্যুবরণ করেন?', 'জার্মানি', NULL, 'ফ্রান্স', NULL, 'যুক্তরাজ্য', NULL, 'রাশিয়া', NULL, 'C', 'সমাজতন্ত্রের প্রবর্তক কার্ল মার্কস ১৮৮৩ সালে যুক্তরাজ্যে মৃত্যুবরণ করেন। তিনি ১৮১৮ সালে জার্মানিতে জন্মগ্রহণ করেন। ডাস ক্যাপিটাল তার রচিত কালজয়ী গ্রন্থ।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c9f2a648460e70bcdc9970a4ce40fbe0'),
(3887, 401, 'আফগানিস্তানের শেষ বাদশাহ কে ছিলেন?', 'দাউদ খাঁ', NULL, 'জহির শাহ', NULL, 'নাদির শাহ', NULL, 'নজীবুল্লাহ', NULL, 'B', 'আফগানিস্তানের শেষ বাদশাহ মোহাম্মদ জহির শাহ ১৯৩৩ সালের ৮ নভেম্বর থেকে ১৯৭৩ সালের জুলাই পর্যন্ত ক্ষমতায় ছিলেন। জহির শাহের পর দেশটির প্রথম প্রেসিডেন্ট হন দাউদ খাঁ।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ce1d4fc0f6674a43ba639a0a5940155b'),
(3888, 393, 'স্বাধীন ফিলিস্তিন রাষ্ট্রকে সর্বপ্রথম কোন দেশ স্বীকৃতি দান করে?', 'ইরাক', NULL, 'ইরান', NULL, 'সৌদি আরব', NULL, 'আলজেরিয়া', NULL, 'D', 'ফিলিস্তিনকে স্বীকৃতি দানকারী প্রথম দেশ আলজেরিয়া। ১৯৮৮ সালের ১৫ নভেম্বর PLO আলজেরিয়ার রাজধানী আলজিয়ার্সের এক অধিবেশনে ফিলিস্তিন রাষ্ট্রের ঘোষণা দেয়।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4a479eb67692bcb2ca3887559cc5e22e'),
(3889, 393, 'লাইন অব কন্ট্রোল কোন দুটি রাষ্ট্রের সীমান্তবর্তী রেখা চিহ্নিত করে?', 'ইসরাইল ও জর্ডান', NULL, 'ভারত ও পাকিস্তান', NULL, 'চীন ও তাইওয়ান', NULL, 'দক্ষিণ কোরিয়া ও উত্তর কোরিয়া', NULL, 'B', 'LOC- Line of Control ভারত-পাকিস্তানের সীমান্তবর্তী রেখা। এটি কাশ্মীরের পাকিস্তান ও ভারতের সীমান্ত বরাবর কাশ্মীর নিয়ন্ত্রণ রেখা। LAC (Line of Actual Control) বলতে ভারত ও চীনের সীমান্তবর্তী রেখাকে বোঝায়।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a6b6a97185aa9705b1842fa4b1e6b50b'),
(3890, 124, 'মধ্য আমেরিকার কোন দেশে স্থায়ী সেনাবাহিনী নেই?', 'কলাম্বিয়া', NULL, 'নিকারাগুয়া', NULL, 'কোস্টারিকা', NULL, 'এল সালভাদর', NULL, 'C', 'মধ্য আমেরিকার দেশ কোস্টারিকায় কোনো সেনাবাহিনী নেই। এছাড়া অন্যান্য যেসব দেশে সেনাবাহিনী নেই সেগুলো হলো: এন্ডোরা, ডোমিনিকা, গ্রানাডা, হাইতি, কিরিবাতি, লিচটেনস্টাইন, মার্শাল দ্বীপপুঞ্জ, মরিশাস, মাইক্রোনেশিয়া, নাউরু, পালাউ, সামোয়া, সলোমন দ্বীপপুঞ্জ, টুভ্যালু, ভ্যাটিকান সিটি।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1513ac625f68457fc15f9fa08f7ea2bf'),
(3891, 412, 'পৃথিবীর সর্বাপেক্ষা বেশি গম উৎপাদনকারী দেশ কোনটি?', 'অস্ট্রেলিয়া', NULL, 'কানাডা', NULL, 'যুক্তরাষ্ট্র', NULL, 'চীন', NULL, 'D', 'বিশ্বের গম উৎপাদনে শীর্ষ দেশ চীন। এর পরের অবস্থানে রয়েছে যথাক্রমে ভারত, রাশিয়া, যুক্তরাষ্ট্র, ফ্রান্স ও কানাডা।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1415f8643e1d3132eb075e8d8fd1a45f'),
(3892, 389, 'জনসংখ্যার ভিত্তিতে বৃহত্তম মুসলিম রাষ্ট্র কোনটি?', 'পাকিস্তান', NULL, 'সৌদি আরব', NULL, 'মিশর', NULL, 'ইন্দোনেশিয়া', NULL, 'D', 'জনসংখ্যার ভিত্তিতে বৃহত্তম মুসলিম দেশ ইন্দোনেশিয়া। বিশ্বের মুসলিম জনসংখ্যা নিয়ে গবেষণা করা একটি প্রতিষ্ঠানের তথ্যমতে, ইন্দোনেশিয়ার মোট জনসংখ্যার ২২ কোটি ৯০ লাখ মুসলিম। পাকিস্তান দ্বিতীয়, জনসংখ্যার ২০ কোটি ৪ লাখ মুসলিম, মিশর ৬ষ্ঠ, জনসংখ্যার ৮ কোটি ৭৫ লাখ মুসলিম।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '22ba430906e5b117ea96e18463bca35b'),
(3893, 391, 'রেডক্রসের সদর দপ্তর কোথায় অবস্থিত?', 'প্যারিস', NULL, 'লন্ডন', NULL, 'নিউইয়র্ক', NULL, 'জেনেভা', NULL, 'D', 'বিশ্বের দুস্থ মানবতার সেবায় নিয়োজিত আন্তর্জাতিক সংস্থা রেডক্রস (Red Cross)-এর প্রতিষ্ঠাতা হেনরি ডুনান্ট, এটি ৯ ফেব্রুয়ারি ১৮৬৩ সালে প্রতিষ্ঠিত। এর সদর দপ্তর সুইজারল্যান্ডের জেনেভায় অবস্থিত।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8fa058f537923af377928c9e967efe18'),
(3894, 389, 'জুলিয়াস সিজার কেন বিখ্যাত?', 'রোমান সম্রাট হিসেবে', NULL, 'বর্ণবাদ বিরোধী হিসেবে', NULL, 'ব্রিটেনের রাজা হিসেবে', NULL, 'আমেরিকার প্রেসিডেন্ট হিসেবে', NULL, 'A', 'রোমান সম্রাট ও রোমান প্রজাতন্ত্রের একনায়ক হিসেবে খ্যাত জুলিয়াস সিজার খ্রিস্টপূর্ব ১০০ অব্দে রোমের Subura নামক স্থানে জন্মগ্রহণ করেন। তিনি খ্রিস্টপূর্ব ৪৪ অব্দে মারা যান।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3ba1a9336aa70974777052a3ae3b87c5'),
(3895, 391, 'পূর্ব তিমুরের রাজধানী কোথায়?', 'লাসা', NULL, 'পোর্টো নোভো', NULL, 'দিলি', NULL, 'তিয়েন আন মেন', NULL, 'C', '২০ মে, ২০০২ ইন্দোনেশিয়া থেকে স্বাধীনতা লাভকারী পূর্ব তিমুরের রাজধানী হচ্ছে দিলি। লাসা তিব্বতের রাজধানী, পোর্টো-নোভা বেনিনের রাজধানী।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '37813ff9a90571fc8faed9f2c225e23e'),
(3896, 391, 'নোবেল পুরস্কার বিজয়ী তাওয়াকুল কারমান কোন দেশের নাগরিক?', 'ইরান', NULL, 'ইন্দোনেশিয়া', NULL, 'তুরস্ক', NULL, 'ইয়েমেন', NULL, 'D', 'ইয়েমেন বিপ্লবের জননী তাওয়াকুল কারমান নারীদের নিরাপত্তায় অহিংস আন্দোলন এবং শান্তি প্রতিষ্ঠায় নারীদের পূর্ণ অংশগ্রহণের অধিকার আদায়ের আন্দোলনে বিশেষ ভূমিকার জন্য ২০১১ সালে লাইবেরিয়ার এলেন জনসন সারলিফ ও লেমাহ বোইয়ের সাথে যৌথভাবে শান্তিতে নোবেল পুরস্কার লাভ করেন।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5ff6bf573732f293874de94d640465c7'),
(3897, 397, 'আমেরিকার চালকবিহীন গোয়েন্দা বিমান স্টিলথ ড্রোনটি কি?', 'বোমারু বিমান চালিত', NULL, 'মিগ চালিত', NULL, 'হেলিকপ্টার চালিত', NULL, 'শক্তিশালী রকেট চালিত', NULL, 'A', 'স্টিলথ ড্রোন: আমেরিকার চালকবিহীন গোয়েন্দা বিমান, স্টিলথ ড্রোনটি বোমারু বিমান চালিত। যুক্তরাষ্ট্রের বিমান বাহিনীর একটি পাইলট চালিত বিমানের সঙ্গে পাল্লা দেয়ার জন্য একটি অত্যাধুনিক স্বয়ংক্রিয় বিমান।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '93d0d3065623f7435fbe3f2b3d0023ee'),
(3898, 122, 'আটলান্টিক ও প্রশান্ত মহাসাগরকে যুক্ত করেছে কোনটি?', 'সুয়েজ খাল', NULL, 'মিসিসিপি', NULL, 'ভলগা', NULL, 'পানামা খাল', NULL, 'D', 'বনভূমি কেটে তৈরিকৃত ৮০ কিমি দীর্ঘ ও ৯১ মিটার প্রস্থ বিশিষ্ট পানামা খালটি আটলান্টিক ও প্রশান্ত মহাসাগরকে যুক্ত করেছে। সুয়েজ খাল ভূমধ্যসাগর ও লোহিত সাগরকে যুক্ত করেছে।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '48b64d21980fe8ebc05b638436a50de9'),
(3899, 394, 'গ্রিনল্যান্ড এর মালিকানা কোন দেশের?', 'সুইডেন', NULL, 'নেদারল্যান্ডস', NULL, 'ডেনমার্ক', NULL, 'ইংল্যান্ড', NULL, 'C', 'আর্কটিক ও আটলান্টিক মহাসাগরের মধ্যে অবস্থিত বিশ্বের বৃহত্তম দ্বীপ গ্রিনল্যান্ডের মালিকানা ডেনমার্কের। গ্রিনল্যান্ডের আয়তন ২১,৬৬,০৮৬ বর্গকিমি।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a270ffcc5488db4fc4709d445aa1e34b'),
(3900, 391, 'গ্রেট হল কোথায় অবস্থিত?', 'ব্রিটেন', NULL, 'যুক্তরাষ্ট্র', NULL, 'চীন', NULL, 'রাশিয়া', NULL, 'C', 'চীনের রাজধানী বেইজিংয়ের তিয়েন আনমেন স্কয়ারের পশ্চিম কোণে অবস্থিত চীনের বিখ্যাত গ্রেট হল। এটা মূলত চীনের ন্যাশনাল পিপলস কংগ্রেসের পার্লামেন্ট ভবন।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8c8db542e39a3136f047f732dfa1623f'),
(3901, 391, 'তাস কোন দেশের সংবাদ সংস্থা?', 'রাশিয়া', NULL, 'চীন', NULL, 'ভারত', NULL, 'পাকিস্তান', NULL, 'A', 'ইতার-তাস ১ সেপ্টেম্বর ১৯০৪ সালে প্রতিষ্ঠিত রাশিয়ার একটি বিশ্ববিখ্যাত সংবাদ সংস্থা। এর পূর্ণরূপ হচ্ছে Information Telegraph Agency of Russia (ITAR-TASS)।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ebfd32662bcb7cae291f0f81df8faaf2'),
(3902, 394, 'পৃথিবীর বৃহত্তম বিমান বন্দরটি কোথায় অবস্থিত?', 'নিউইয়র্ক', NULL, 'লন্ডন', NULL, 'বার্লিন', NULL, 'জেদ্দা', NULL, 'D', 'বর্তমানে আয়তনে বৃহত্তম বিমান বন্দর সৌদি আরবের কিং ফাহাদ আন্তর্জাতিক বিমান বন্দর।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9aea3bc006ab53b0bfdabc813c373cd4'),
(3903, 394, 'পৃথিবীর গভীরতম স্থান কোন মহাসাগরে?', 'ভারত', NULL, 'আটলান্টিক', NULL, 'প্রশান্ত', NULL, 'উত্তর', NULL, 'C', 'প্রশান্ত মহাসাগরের ঠিক পশ্চিমে অবস্থিত পৃথিবীর গভীরতম খাদ বা স্থান মারিয়ানা ট্রেঞ্চ। বিভিন্ন সময়ে এর গভীরতা বিভিন্ন রকম মাপা হলেও আধুনিক বিজ্ঞানীদের মতে এর গভীরতা ৩৬,০৭০ ফুট (প্রায় ১১ কিলোমিটার)।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1e5dcc9be0a9b4f19eae2ab66812986d'),
(3904, 394, 'পৃথিবীর গভীরতম হ্রদ কোনটি?', 'কাস্পিয়ান', NULL, 'বৈকাল', NULL, 'মানস সরোবর', NULL, 'ডেড সী (Dead Sea)', NULL, 'B', 'বৈকাল হ্রদ রাশিয়ার সাইবেরিয়ার দক্ষিণভাগে অবস্থিত একটি সুপেয় পানির হ্রদ। এটি বিশ্বের গভীরতম হ্রদ। ১৯৯৬ সালে ইউনেস্কো এটিকে ৭৫৪তম বিশ্ব ঐতিহ্য হিসেবে ঘোষণা করে। বিশ্বের বৃহত্তম হ্রদ কাস্পিয়ান।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '987d5dd936ad9002d3bfb7b399cd5cef'),
(3905, 401, '২০১৪ সালে বিশ্বকাপ ফুটবল কোথায় অনুষ্ঠিত হবে?', 'লন্ডন', NULL, 'বার্লিন', NULL, 'ব্রাজিল', NULL, 'আর্জেন্টিনা', NULL, 'C', '২০১৪ সালের ১২ জুন-১৩ জুলাই ব্রাজিলে অনুষ্ঠিত হয় ২০তম বিশ্বকাপ ফুটবল। উল্লেখ্য, সর্বশেষ বিশ্বকাপ ২০২২ সালে কাতারে অনুষ্ঠিত হয় এবং ২০২৬ সালে যৌথভাবে যুক্তরাষ্ট্র, কানাডা ও মেক্সিকোতে বিশ্বকাপ ফুটবল অনুষ্ঠিত হবে।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1181f40dd82d087befb3344935e9e267'),
(3906, 406, 'World No-Tobacco Day is observed on–', 'May 25', NULL, 'May 28', NULL, 'May 30', NULL, 'May 31', NULL, 'D', '৩১ মে বিশ্ব তামাকমুক্ত দিবস। তামাকের ভয়াবহতা নিয়ন্ত্রণ এবং তামাকমুক্ত বিশ্ব গড়ার লক্ষ্যে বিশ্ব স্বাস্থ্য সংস্থা ১৯৮৭ সাল থেকে প্রতিবছর ৩১ মে বিশ্ব তামাকমুক্ত দিবস পালনের সিদ্ধান্ত নেয়।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '860d4012f47bca6b84cbf4705549711f'),
(3907, 406, 'Which one of the following ecosystems covers the largest area of the earth\'s surface?', 'Desert Ecosystem', NULL, 'Mountain Ecosystem', NULL, 'Fresh water Ecosystem', NULL, 'Marine Ecosystem', NULL, 'D', 'Ecosystem অর্থ বাস্তুতন্ত্র। পৃথিবী পৃষ্ঠের চার ভাগের প্রায় তিন ভাগই পানি। অধিকাংশ পানি সমুদ্রের পানি দ্বারা পরিপূর্ণ। সমুদ্রের Marine বাস্তুতন্ত্রই সবচেয়ে বড়।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bc7edbd1ccffe2d121ede760fdb969df'),
(3908, 124, 'In Cricket game the length of pitch between the two wickets is–', '24 yards', NULL, '23 yards', NULL, '22 yards', NULL, '21 yards', NULL, 'C', 'ক্রিকেট মাঠে পিচের দৈর্ঘ্য ২২ গজ। মাটি থেকে স্টাম্পের উচ্চতা ২৭ ইঞ্চি এবং ক্রিকেট ব্যাটের প্রস্থ সর্বাধিক ৪.৫ ইঞ্চি, দৈর্ঘ্য সর্বাধিক ৩৮ ইঞ্চি।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5fe42ea283209fb256b89eaf4eb975f0'),
(3909, 412, 'IMF (International Monetary Fund) is the result of–', 'Hawana Conference', NULL, 'Geneva Conference', NULL, 'Rome Conference', NULL, 'Brettonwood Conference', NULL, 'D', '১৯৪৪ সালের ১-২২ জুলাই যুক্তরাষ্ট্রের নিউ হ্যাম্পশায়ারের ব্রেটন উডসের মাউন্ট ওয়াশিংটন হোটেলে অনুষ্ঠিত ৪৫টি দেশের প্রতিনিধিদের অংশগ্রহণে গৃহীত চুক্তির মাধ্যমে IMF প্রতিষ্ঠিত হয়।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '48aa904d6a6446cc2cff259bf7170191'),
(3910, 391, 'The International Court of Justice is located in–', 'New York', NULL, 'London', NULL, 'Geneva', NULL, 'Hague', NULL, 'D', 'আন্তর্জাতিক আদালত (ICJ)-এর সদর দপ্তর নেদারল্যান্ডসের দি হেগ-এ অবস্থিত। আন্তর্জাতিক আদালত প্রতিষ্ঠিত হয় ২৪ অক্টোবর ১৯৪৫ (কার্যক্রম শুরু ১৮ এপ্রিল ১৯৪৬)।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '501694aeac62e4c744de1c36e97b99d9'),
(3911, 412, 'EURO is the currency of–', 'Asia', NULL, 'Europe', NULL, 'America', NULL, 'Africa', NULL, 'B', 'ইউরো হলো ইউরোপীয় ইউনিয়নভুক্ত দেশসমূহের একক মুদ্রা। এ মুদ্রার জনক রবার্ট মুন্ডেল। ১৯৯৯ সালের ১ জানুয়ারি ইউরো চালু হয়। বর্তমানে ২০টি ইইউভুক্ত দেশে ইউরো মুদ্রা চালু আছে।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c37609e8cd693d8f3de5624928568d5'),
(3912, 391, 'নিচের কোন সংস্থাটি ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস হিসাবে স্বীকৃতি দিয়েছে?', 'UNDP', NULL, 'UNESCO', NULL, 'UNICEF', NULL, 'UNCTAD', NULL, 'B', '১৯৯৯ সালের ১৭ নভেম্বর ইউনেস্কোর ৩০তম সাধারণ অধিবেশনে ২১ ফেব্রুয়ারিকে আন্তর্জাতিক মাতৃভাষা দিবস হিসেবে ঘোষণা করা হয়। ২০০০ সালের ২১ ফেব্রুয়ারি বিশ্বের ১৮৮টি দেশ প্রথমবারের মতো এই দিবস পালন করে।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '26e0dc7de82cbc7da838f2c5e5a2734d'),
(3913, 393, 'তাহরির স্কয়ার কোথায় অবস্থিত?', 'সিউল', NULL, 'আম্মান', NULL, 'কায়রো', NULL, 'তেহরান', NULL, 'C', 'তাহরির স্কয়ার মিশরের কায়রোতে অবস্থিত। আরবিতে ডাকা হয় ময়দান আল তাহরির, ইংরেজিতে লিবারেশন স্কয়ার। মিশরের সাবেক প্রেসিডেন্ট হোসনি মোবারকের পদত্যাগের দাবিতে যে গণবিক্ষোভ হয় তার মূল কেন্দ্রবিন্দু ছিল তাহরির স্কয়ার।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5e6c97caa23649563a0f33a9a4cafc2f'),
(3914, 124, 'কোনটি D-8 ভুক্ত দেশ নয়?', 'নাইজেরিয়া', NULL, 'ভারত', NULL, 'মালয়েশিয়া', NULL, 'তুরস্ক', NULL, 'B', 'D-8 ভুক্ত দেশ ৮টি: তুরস্ক, ইরান, পাকিস্তান, মিশর, ইন্দোনেশিয়া, বাংলাদেশ, মালয়েশিয়া ও নাইজেরিয়া। ১৯৯৭ সালের ৫ জুন D-8 (Developing-8) গঠিত হয়।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '84adf3ed88447871d97134d381f18797'),
(3915, 391, 'অ্যামনেস্টি ইন্টারন্যাশনাল-এর সদর দপ্তর কোথায় অবস্থিত?', 'লন্ডন', NULL, 'নিউইয়র্ক', NULL, 'প্যারিস', NULL, 'ভিয়েনা', NULL, 'A', '১৯৬১ সালের ২৮ মে অ্যামনেস্টি ইন্টারন্যাশনাল প্রতিষ্ঠা করা হয়। যুক্তরাজ্যের লন্ডনে এর সদর দপ্তর অবস্থিত।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '94ef89c2de716c6207fc3712cf15ae95'),
(3916, 393, 'আরব বসন্ত বলতে কি বুঝায়?', 'আরবের বিভিন্ন দেশে গণজাগরণ', NULL, 'আরব অঞ্চলে বসন্তকাল', NULL, 'আরব রাজতন্ত্র', NULL, 'আরবীয় মহিলাদের ক্ষমতায়ন', NULL, 'A', '২০১০ সালের ১৭ ডিসেম্বর থেকে আরব বিশ্বের বিভিন্ন দেশে যে গণজাগরণ সৃষ্টি হয়েছে তাকে আরব বসন্ত (Arab Spring) বলা হয়। আরব বসন্তের সূতিকাগার হিসেবে খ্যাত দেশ হচ্ছে তিউনিসিয়া।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd33adf7d5ccce311ac39b7cf5606bb99'),
(3917, 394, 'আয়তনে পৃথিবীর সবচেয়ে ছোট দেশ?', 'ফিজি', NULL, 'ভ্যাটিকান', NULL, 'কুয়েত', NULL, 'মালদ্বীপ', NULL, 'B', 'আয়তনে পৃথিবীর সবচেয়ে ছোট দেশ ভ্যাটিকান, যার আয়তন ০.৪৪ বর্গ কিমি।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2c872aaf8c916aac2be3759b6a456595'),
(3918, 391, 'এশিয়ার হিন্দু রাষ্ট্র কোনটি?', 'নেপাল', NULL, 'ভারত', NULL, 'ভূটান', NULL, 'মালদ্বীপ', NULL, 'A', 'নেপালকে সাংবিধানিকভাবে হিন্দু রাষ্ট্র ঘোষণা করা হয় ১৯৬২ সালের সংবিধানের মাধ্যমে। ২০০৬ সালের ১৮ মে আইন পাসের মাধ্যমে নেপালকে ধর্মনিরপেক্ষ রাষ্ট্রে পরিণত করা হয়।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '82935294f04ea6ad320f52caaace4b3a'),
(3919, 391, 'লয়া জিরগা কোন দেশের আইন সভা?', 'ফিজি', NULL, 'সিরিয়া', NULL, 'লেবানন', NULL, 'আফগানিস্তান', NULL, 'D', 'আফগানিস্তানের বিভিন্ন সম্প্রদায়, সম্মানিত উপজাতীয় ও রাজনৈতিক নেতাদের সর্বোচ্চ পরিষদ লয়া জিরগা (Loya Jirga)।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8cde465daec280fa4699f9435ab6e50a'),
(3920, 391, 'কোপেনহেগেন কোন দেশের রাজধানী?', 'ডেনমার্ক', NULL, 'বেলজিয়াম', NULL, 'ভিয়েতনাম', NULL, 'আর্মেনিয়া', NULL, 'A', 'কোপেনহেগেন ডেনমার্কের রাজধানী ও প্রধান শহর। ভিয়েতনামের রাজধানী হ্যানয়, বেলজিয়ামের রাজধানী ব্রাসেলস ও আর্মেনিয়ার রাজধানী ইয়েরেভান।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '22e4fed66c1aa22cd81c643447be7277'),
(3921, 391, 'শ্যামদেশ কোন দেশের পুরাতন নাম?', 'মিসর', NULL, 'ইরাক', NULL, 'ইরান', NULL, 'থাইল্যান্ড', NULL, 'D', 'থাইল্যান্ডের পূর্বনাম শ্যামদেশ (Sayam)। রাজা প্রথম রমা ১৭৮২ সালে শ্যামদেশ নামকরণ করেন।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c56d472ac209c82e3ab8a8aca3730a2f'),
(3922, 401, 'নেপালের সর্বশেষ রাজা ছিলেন–', 'রাজা ধীরেন্দ্র', NULL, 'রাজা জ্ঞানেন্দ্র', NULL, 'রাজা বীরেন্দ্র', NULL, 'রাজা মহেন্দ্র', NULL, 'B', 'নেপালের সর্বশেষ রাজা ছিলেন জ্ঞানেন্দ্র বীর বিক্রম শাহদেব। ২৮ মে, ২০০৮ দেশের সরকার রাজতন্ত্র বিলুপ্ত করলে রাজা জ্ঞানেন্দ্র ক্ষমতাচ্যুত হন।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f4e15054dda09e189265e07e77ff60f4'),
(3923, 389, 'প্রথম বিশ্বযুদ্ধ চলাকালীন বেলফোর ঘোষণা ১৯১৭ এর মূল প্রতিপাদ্য ছিল–', 'জাতিপুঞ্জ সৃষ্টি করা', NULL, 'অটোমানদের জায়গা দখল করা', NULL, 'ইহুদিদের জন্য একটি জাতিরাষ্ট্র গঠন', NULL, 'জার্মানির বিরুদ্ধে মিত্র শক্তির নতুন কৌশল অবলম্বন', NULL, 'C', 'বেলফোর ঘোষণা (২ নভেম্বর ১৯১৭) হলো ব্রিটিশ ইহুদি সম্প্রদায়ের নেতা ব্যারন রথচাইল্ডের কাছে যুক্তরাজ্যের পররাষ্ট্র সচিব আর্থার জেমস বেলফোরের লেখা একটি চিঠি। যার মূল কথা ছিল ফিলিস্তিন ভূমিতে ইহুদিদের জন্য একটি জাতিরাষ্ট্র গঠন।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '217cfe90a1bb2ef4e2f40c2a84ce74ab'),
(3924, 395, 'প্রশান্ত মহাসাগরে যুক্তরাষ্ট্রের সপ্তম নৌবহরের সদর দপ্তর হচ্ছে–', 'ইউকোসুক', NULL, 'হাওয়াই', NULL, 'গোয়াম', NULL, 'সুবিক বে', NULL, 'A', 'প্রশান্ত মহাসাগরে যুক্তরাষ্ট্রের সপ্তম নৌবহরের সদর দপ্তর জাপানের ইউকোসুকে অবস্থিত। এই নৌবহরে ৭০-৮০টি যুদ্ধ জাহাজ, ৩০০টি যুদ্ধ বিমান এবং প্রায় ৪০,০০০ সেনা রয়েছে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e51bc4fd3f83df38e181568936158d97'),
(3925, 393, 'ডমিনো তত্ত্বটি কোন অঞ্চলের জন্য প্রযোজ্য ছিল?', 'নিকট প্রাচ্য', NULL, 'পূর্ব আফ্রিকা', NULL, 'দক্ষিণ-পূর্ব এশিয়া', NULL, 'পূর্ব ইউরোপ', NULL, 'C', 'ডমিনো তত্ত্বটি দক্ষিণ-পূর্ব এশিয়ার জন্য প্রযোজ্য ছিল। ১৯৫০ থেকে ১৯৮০ সাল পর্যন্ত যুক্তরাষ্ট্র এই তত্ত্বটি প্রচার করেছিল। ডমিনো তত্ত্বের মূল কথা হলো একটি রাষ্ট্র যদি সমাজতন্ত্রীদের দখলে চলে যায় তাহলে তার পাশের রাষ্ট্রটিতেও সমাজতন্ত্র প্রতিষ্ঠা পাবে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '46960e4d13dadf7f4ede81818cd170de'),
(3926, 389, 'গ্লাসনস্ত নীতি কোন দেশে চালু হয়েছিল?', 'চীন', NULL, 'সাবেক সোভিয়েত ইউনিয়ন', NULL, 'হাঙ্গেরি', NULL, 'পোল্যান্ড', NULL, 'B', 'রুশ শব্দ গ্লাসনস্ত মানে খোলানীতি। সোভিয়েত নেতা মিখাইল গর্বাচেভ এ নীতির প্রবর্তক। তিনি ১৯৮৭ সালে ঘোষণা করেন যে, সোভিয়েত ইউনিয়নের জনগণ নির্ভয়ে খোলামেলাভাবে তাদের মতামত প্রকাশ করতে পারবেন। অনেকটা এই গ্লাসনস্তের কারণেই সোভিয়েত ইউনিয়ন ভেঙে যায়।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7b8b62ac34809e50097afa41cafd4133'),
(3927, 124, 'ভারতের প্রধানমন্ত্রী নরেন্দ্র মোদির শপথগ্রহণ অনুষ্ঠানে সার্ক অঞ্চলের বাহিরে আমন্ত্রিত রাষ্ট্রের সংখ্যা–', '২', NULL, '৩', NULL, '৪', NULL, '১', NULL, 'D', 'স্বাধীন ভারতে জন্ম নেওয়া ভারতের প্রথম প্রধানমন্ত্রী নরেন্দ্র মোদির শপথ গ্রহণ অনুষ্ঠান হয় ২০১৪ সালের ২৬ মে। সার্কের বাইরের একমাত্র দেশ হিসেবে মরিশাসের সাবেক প্রধানমন্ত্রী নবীন রামগুলাম আমন্ত্রিত অতিথি ছিলেন।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'da2824fd0d35b94109447a0311ce6359'),
(3928, 124, 'বর্তমান বিশ্বের কোন দেশটির সংবিধানকে শান্তি সংবিধান বলা হয়?', 'জাপান', NULL, 'পেরু', NULL, 'কোস্টারিকা', NULL, 'সুইজারল্যান্ড', NULL, 'A', 'শান্তি সংবিধান বলা হয় জাপানের সংবিধানকে। দ্বিতীয় বিশ্বযুদ্ধের পরে ১৯৪৭ সালের ৩ মে জাপান পুরানো সংবিধান রহিত করে নতুন সংবিধান রচনা করে। সংবিধানে উল্লেখ করা হয় জাপানি জনগণ চিরতরে যুদ্ধ পরিহার করছে এবং ভূমি, নৌ ও বিমানবাহিনীসহ অন্যান্য সম্ভাব্য যুদ্ধ সৃষ্টিকারী বাহিনী রাখবে না।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3cdebe6177cc74a0e8a22202512bb814'),
(3929, 124, 'Global Terrorism Index ২০১৪ অনুযায়ী বিশ্বে সর্বাপেক্ষা ঝুঁকিপূর্ণ রাষ্ট্র–', 'সিরিয়া', NULL, 'সুদান', NULL, 'ইরাক', NULL, 'সোমালিয়া', NULL, 'C', 'Global Terrorism Index (GTI) ২০১৪ অনুযায়ী সন্ত্রাসবাদে বিশ্বের শীর্ষ দেশ ইরাক। IEP কর্তৃক প্রকাশিত GTI ২০২২-তে শীর্ষে রয়েছে আফগানিস্তান।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '412fe5568a161a30bc5830cfaa392cc9'),
(3930, 123, 'জলবায়ু পরিবর্তনের হুমকির ব্যাপকতা তুলে ধরার জন্য কোন দেশটি সমুদ্রের গভীরে মন্ত্রীসভার বৈঠক করেছে?', 'ফিজি', NULL, 'পাপুয়া নিউগিনি', NULL, 'গোয়াম', NULL, 'মালদ্বীপ', NULL, 'D', 'জলবায়ু পরিবর্তন মোকাবিলায় বিশ্ববাসীকে সচেতন করতে ২০০৯ সালের ১৭ অক্টোবর মালদ্বীপের তৎকালীন প্রেসিডেন্ট মোহাম্মদ নাশিদের সভাপতিত্বে তার দেশের মন্ত্রীসভার একটি বৈঠক সাগরতলে অনুষ্ঠিত হয়।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '332351a0488d8a2bea9269782b33176f'),
(3931, 124, 'দ্বিতীয় বিশ্বযুদ্ধের পর পূর্ব-পশ্চিম দ্বন্দ্বের ফলে সৃষ্ট পূর্বের অর্থনৈতিক জোটটির নাম ছিল–', 'কমিন্টার্ন', NULL, 'কমিনফর্ম', NULL, 'কমেকন', NULL, 'কোনোটিই নয়', NULL, 'C', 'দ্বিতীয় বিশ্বযুদ্ধের পর মার্শাল প্ল্যানের প্রতিপক্ষ হিসেবে পূর্ব ইউরোপীয় দেশগুলোতে সোভিয়েত আর্থিক সাহায্য প্রদানের উদ্দেশ্যে মস্কোতে পারস্পরিক অর্থনৈতিক সাহায্য পরিষদ বা COMECON (কমেকন) গঠন করা হয়। সংগঠনটি ১৯৪৯ থেকে ১৯৯০ সাল পর্যন্ত টিকে ছিল।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '41cbd35a75f90497fe118467919f696e'),
(3932, 412, 'ব্রিকসের সর্বশেষ শীর্ষ বৈঠক অনুষ্ঠিত হয়–', 'রাশিয়া', NULL, 'ব্রাজিল', NULL, 'ভারত', NULL, 'দক্ষিণ আফ্রিকা', NULL, 'D', 'ব্রিকসের সর্বশেষ সম্মেলন অনুষ্ঠিত হয় ২০২৩ সালে দক্ষিণ আফ্রিকায়। ২০২৪ সালে রাশিয়ায় ব্রিকস সম্মেলন অনুষ্ঠিত হবে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e470e9549894ee78fa07f96f73c2dcc9'),
(3933, 391, 'উইঘুর হলো–', 'চীনের একটি খাবারের নাম', NULL, 'চীনের একটি ধর্মীয় স্থানের নাম', NULL, 'চীনের একটি শহরের নাম', NULL, 'চীনের একটি সম্প্রদায়ের নাম', NULL, 'D', 'চীনের মুসলিম অধ্যুষিত জিনজিয়ান প্রদেশে বসবাসকারী মুসলিম সম্প্রদায়ের নাম হলো উইঘুর। চীন ছাড়াও উইঘুররা কাজাখস্তান, উজবেকিস্তান, কিরঘিজস্তান, তুরস্ক ও রাশিয়াতে বসবাস করে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4a65db7186f33aeeb9470291add43a49'),
(3934, 124, '১৯৮২ সালের সমুদ্র আইন সংক্রান্ত কনভেনশন অনুযায়ী একটি উপকূলীয় রাষ্ট্রের মহীসোপানের (Continental Shelf) সীমা হবে ভিত্তি রেখা হতে–', '২০০ নটিকেল মাইল', NULL, '৩০০ নটিকেল মাইল', NULL, '৩৫০ নটিকেল মাইল', NULL, '৪৫০ নটিকেল মাইল', NULL, 'C', '১৯৮২ সালের সমুদ্র আইন সংক্রান্ত কনভেনশন অনুযায়ী একটি উপকূলীয় রাষ্ট্রের মহীসোপানের সীমা হবে ভিত্তি রেখা হতে ৩৫০ নটিক্যাল মাইল এবং অর্থনৈতিক সীমা হবে ভিত্তি রেখা হতে ২০০ নটিক্যাল মাইল পর্যন্ত।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8ae193191c58f105c739416c410418e4'),
(3935, 394, 'মংডু কোন দুটি দেশের সীমান্ত এলাকা?', 'বাংলাদেশ-মায়ানমার', NULL, 'মায়ানমার-চীন', NULL, 'বাংলাদেশ-ভারত', NULL, 'ভারত-মায়ানমার', NULL, 'A', 'মংডু হলো বাংলাদেশের কক্সবাজার সীমান্তে মিয়ানমারের একটি জেলা শহর। নাফ নদীর মাধ্যমে মংডু ও বাংলাদেশের টেকনাফ শহর আলাদা হয়ে আছে। টেকনাফ-মংডু বাংলাদেশ ও মিয়ানমারের মধ্যকার একটি সীমান্ত বাণিজ্য এলাকা।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8d6c29f4390eeee87c968a929b33858a'),
(3936, 406, 'কার্টাগেনা প্রটোকল হচ্ছে–', 'জাতিসংঘের যুদ্ধ মোকাবেলা সংক্রান্ত চুক্তি', NULL, 'জাতিসংঘের শিশু অধিকার বিষয়ক চুক্তি', NULL, 'জাতিসংঘের নারী অধিকার বিষয়ক প্রটোকল', NULL, 'জাতিসংঘের জৈব নিরাপত্তা বিষয়ক চুক্তি', NULL, 'D', 'জীবপ্রযুক্তির ব্যবহার দ্বারা পরিমার্জিত প্রাণের নিরাপদ ব্যবহার নিশ্চিতকরণ সংক্রান্ত কার্টাগেনা প্রটোকল ২০০০ সালের ২৯ জানুয়ারি কানাডার মন্ট্রিলে গৃহীত হয়। এর পুরো নাম Cartagena Protocol on Biosafety to the Convention on Biological Diversity.', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '11eae855aee71bb722d7f134d6a4cccc'),
(3937, 406, '১৯৮৯ থেকে ওজনস্তর বিষয়ক মন্ট্রিল প্রটোকল কতবার সংশোধন করা হয়?', '৫', NULL, '৮', NULL, '৪', NULL, '৭', NULL, 'A', 'ওজোনস্তরকে রক্ষা করার উদ্দেশ্যে ১৯৮৭ সালের ১৬ সেপ্টেম্বর স্বাক্ষরিত মন্ট্রিল চুক্তি কার্যকর হয় ১ জানুয়ারি ১৯৮৯। এ পর্যন্ত মন্ট্রিল প্রটোকল ৫ বার সংশোধন করা হয়। সর্বশেষ পঞ্চম সংশোধন হয় ১৪ অক্টোবর ২০১৬ রুয়ান্ডার কিগালি শহরে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1c157c56fe6b435cd914d711acfedda1'),
(3938, 391, 'The Art of War গ্রন্থের রচয়িতা–', 'ক্লজউইজ', NULL, 'আলফ্রেড মাহান', NULL, 'সুন জু', NULL, 'কৌটিল্য', NULL, 'C', 'চীনের বিখ্যাত সমরবিদ সুন জু হলো The Art of War-এর রচয়িতা। তিনি সম্রাটের আদেশে যুদ্ধজয়ের বিভিন্ন কৌশল সম্পর্কে তার চিন্তা-ভাবনা তুলে ধরেছেন বইটিতে। কৌটিল্য ছিলেন অর্থশাস্ত্রের রচয়িতা।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f2e0c29e0a600194bd3a632a9a70c5c8'),
(3939, 412, 'বর্তমান বিশ্বে নিউ সিল্ক রোডের প্রবক্তা–', 'জাপান', NULL, 'ভারত', NULL, 'আফগানিস্তান', NULL, 'চীন', NULL, 'D', 'সিল্ক রোড হলো চীনের চালু করা বাণিজ্য পথ। ১৯৩০ সালে যুক্তরাজ্য প্রাচীন সিল্ক রোড চালুর উদ্যোগ নিলেও তা বাস্তবায়ন না হওয়ায় ২০১৪ সালে চীন নিউ সিল্ক রোড চালুর উদ্যোগ গ্রহণ করে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '907157ebd2e0818131101269a9848f6f'),
(3940, 406, 'বিশ্ব প্রাণী দিবস হচ্ছে–', '৪ অক্টোবর', NULL, '২৩ অক্টোবর', NULL, '২৯ জুন', NULL, '১১ ফেব্রুয়ারি', NULL, 'A', '৪ অক্টোবর হলো বিশ্ব প্রাণী দিবস। ১৯৩১ সাল থেকে এ দিবস পালিত হচ্ছে। ১১ ফেব্রুয়ারি নেলসন ম্যান্ডেলার মুক্তি দিবস।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dea6821733e9bd3e80c8441942e61363'),
(3941, 391, 'WIPO-এর সদর দপ্তর–', 'ব্রাসেলস', NULL, 'লন্ডন', NULL, 'জেনেভা', NULL, 'প্যারিস', NULL, 'C', 'WIPO-এর পূর্ণরূপ World Intellectual Property Organization। এটির সদর দপ্তর সুইজারল্যান্ডের জেনেভায় অবস্থিত। এছাড়াও জেনেভাতে ILO, WTO, WHO, ITU-প্রভৃতির সদর দপ্তর রয়েছে।', NULL, 6, '35th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a71cbd9490320f895f1eb219b3a307b4'),
(3942, 391, 'কোন সংকটকে কেন্দ্র করে ১৯৫০ সালে শান্তির জন্য ঐক্য প্রস্তাব জাতিসংঘের মাধ্যমে পেশ করা হয়?', 'ভিয়েতনাম সংকট', NULL, 'সাইপ্রাস সংকট', NULL, 'কোরিয়া সংকট', NULL, 'প্যালেস্টাইন সংকট', NULL, 'C', '১৯৫০ সালে কোরীয় যুদ্ধের সময় সৃষ্ট সংকট মোকাবিলায় একই বছরের ৩ নভেম্বর জাতিসংঘের সাধারণ পরিষদ কর্তৃক গৃহীত একটি প্রস্তাব শান্তির জন্য ঐক্য প্রস্তাব বা The Uniting for Peace Resolution।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '892e4dd0afa4cc0bb2b226fa5f96c8ab'),
(3943, 394, 'সুয়েজ খাল কোন বছর চালু হয়?', '১৯০৩', NULL, '১৮৬৯', NULL, '১৮৮৯', NULL, '১৮৫৪', NULL, 'B', 'সুয়েজ খাল মিশরের সিনাই উপদ্বীপের পশ্চিমে অবস্থিত একটি কৃত্রিম খাল। ১৮৫৯ সালের ২৪ এপ্রিল খনন কাজ শুরু হয়ে ১৮৬৯ সালের ১৭ নভেম্বর প্রথম নৌ চলাচলের জন্য খুলে দেওয়া হয়।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '89981661777b52664e36b8806bd9768b'),
