(3949, 412, 'জাতিসংঘ উন্নয়ন কর্মসূচি (UNDP)-এর শীর্ষ পদটি কি?', 'প্রশাসক', NULL, 'মহাপরিচালক', NULL, 'মহাসচিব', NULL, 'প্রেসিডেন্ট', NULL, 'A', 'জাতিসংঘ উন্নয়ন কর্মসূচির (UNDP) শীর্ষপদ প্রশাসক। এটি জাতিসংঘ সাধারণ পরিষদের একটি সহায়ক সংস্থা। এ সংস্থাটি প্রতিষ্ঠিত হয় ১৯৬৫ সালে।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5bb66f24ce416df44e16eb865efab5f7'),
(3950, 406, 'জলবায়ু পরিবর্তন মোকাবেলায় Green Climate Fund বিশ্বের দরিদ্র দেশগুলোর জন্য কি পরিমাণ অর্থ মঞ্জুর করেছে?', '৮০ বিলিয়ন ডলার', NULL, '১০০ বিলিয়ন ডলার', NULL, '১৫০ বিলিয়ন ডলার', NULL, '২০০ বিলিয়ন ডলার', NULL, 'B', '৭-১৮ ডিসেম্বর ২০০৯ ডেনমার্কের রাজধানী কোপেনহেগেনে অনুষ্ঠিত হয় COP-15 সম্মেলন। উক্ত সম্মেলনে Green Climate Fund বিশ্বের দরিদ্র দেশগুলোকে ১০০ বিলিয়ন ডলার দেয়ার প্রতিশ্রুতি দেয়।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5b0a1ae58dce1db5f6eb9455fff25555'),
(3951, 397, 'যুক্তরাষ্ট্র কবে এককভাবে ABM (Anti-Ballistic Missile) চুক্তি থেকে নিজেকে প্রত্যাহার করে?', 'জুন ২০০১', NULL, 'জুন ২০০০', NULL, 'জুন ২০০২', NULL, 'জুন ২০০৩', NULL, 'C', 'ABM চুক্তি স্বাক্ষরিত হয় ১৬ মে ১৯৭২ সালে। এ চুক্তির দুটি পক্ষ ছিল সোভিয়েত ইউনিয়ন ও যুক্তরাষ্ট্র। ABM চুক্তি থেকে মার্কিন যুক্তরাষ্ট্র নিজেকে প্রত্যাহার করে ১৩ জুন ২০০২।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cca187b3d05f4c8297f3ff30ff913dd3'),
(3952, 413, 'আরব লীগ প্রতিষ্ঠা পায়–', '১৯৪৯', NULL, '১৯৫০', NULL, '১৯৪৫', NULL, '১৯৪০', NULL, 'C', 'আরব লীগ প্রতিষ্ঠিত হয় ১৯৪৫ সালের ২২ মার্চ। এর বর্তমান সদস্য সংখ্যা ২২। এর সদর দপ্তর মিশরের কায়রোতে।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a1cb082f443121e9271494227dc7ccd5'),
