(3954, 395, 'বর্তমানে NAM-এর সদস্য সংখ্যা–', '৩৩', NULL, '১৫', NULL, '৭৭', NULL, '২১', NULL, 'A', 'বর্তমানে NAM-এর সদস্য সংখ্যা ১২০ এবং সর্বশেষ এ সংস্থায় যোগদানকারী রাষ্ট্র আজারবাইজান ও ফিজি। ১৯৬১ সালে বেলগ্রেড সম্মেলনের মধ্য দিয়ে আনুষ্ঠানিকভাবে যাত্রা শুরু করে NAM।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b0908abde210cf56fa9eb2fc33e84cd9'),
