(3962, 393, 'কালাপানি কোন দুই রাষ্ট্রের মধ্যে অমীমাংসিত ভূখণ্ড?', 'ভারত ও নেপাল', NULL, 'পাকিস্তান ও চীন', NULL, 'ভুটান ও ভারত', NULL, 'বাংলাদেশ ও ভারত', NULL, 'A', 'কালাপানি অমীমাংসিত ভূখণ্ডটি ভারত ও নেপালের মধ্যে অবস্থিত। এ ভূখণ্ডটি নেপালের মহাকালি এবং ভারতের উত্তরাখণ্ড সীমানায় অবস্থিত।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c8047901efc5a539e75330c3c084126e'),
(3963, 394, 'সলোমন-দ্বীপপুঞ্জ কোন মহাসাগরে অবস্থিত?', 'ভারত মহাসাগর', NULL, 'প্রশান্ত মহাসাগর', NULL, 'আটলান্টিক মহাসাগর', NULL, 'আর্কটিক মহাসাগর', NULL, 'B', 'সলোমন দ্বীপপুঞ্জ পশ্চিম প্রশান্ত মহাসাগরীয় মেলোনেশিয়া অঞ্চলের একটি স্বাধীন দেশ। প্রশান্ত মহাসাগরের আরো কতগুলো দ্বীপ হলো হাওয়াই, মার্শাল দ্বীপপুঞ্জ, ফিজি, তাহিতি, পালাউ প্রভৃতি।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5440e64bf313b1adf9fa2311d98b2e4e'),
(3964, 124, 'চীনের জিনজিয়াং প্রদেশে বসবাসকারী প্রধান মুসলিম সম্প্রদায়ের নাম কি?', 'তুর্কমেন', NULL, 'উইঘুর', NULL, 'তাজিক', NULL, 'কাজাখ', NULL, 'B', 'চীনের উত্তর-পশ্চিম জিনজিয়াং প্রদেশে বসবাসকারী প্রধান মুসলিম সম্প্রদায় হলো উইঘুর। আর তুর্কমেন, তাজিক ও কাজাখ যথাক্রমে তুর্কমেনিস্তান, তাজিকিস্তান ও কাজাখস্তানে বাস করে।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4083abae4a888c28420085254b2e719a'),
(3965, 124, 'সম্প্রতি ভারত Google-কে নিচের কোন প্রোগ্রামের জন্য ছবি তোলা থেকে বিরত করে?', 'Google Earth', NULL, 'Street View', NULL, 'Road Image', NULL, 'Google Map', NULL, 'B', 'Google Street View-এর কার্যক্রম বিশ্বের পর্যটন গুরুত্ব আছে এমন শহরগুলোর রাস্তার ৩৬০° ছবি ক্যামেরায় ধারণ করে। সম্প্রতি ভারত অভ্যন্তরীণ নিরাপত্তা বিঘ্নিত হওয়ার আশঙ্কায় Street View-এর কার্যক্রম নিষিদ্ধ করে।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4e23a7f0880f382319a6be75ff0bc692'),
(3966, 124, 'সংবিধান অনুযায়ী মিয়ানমারের সংসদে কত শতাংশ আসন অনির্বাচিত সামরিক বাহিনীর সদস্যদের জন্য সংরক্ষিত থাকবে?', '২৫%', NULL, '৩৫%', NULL, '৪৫%', NULL, '৫৫%', NULL, 'A', 'মিয়ানমারের নিম্নকক্ষ বা হাউস অব রিপ্রেজেন্টেটিভসের আসন সংখ্যা ৪৪০টি। যার ২৫% অর্থাৎ ১১০টি আসন অনির্বাচিত সামরিক বাহিনীর সদস্যদের জন্য সংরক্ষিত।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '776b246c098971b52257b0e5c1dc7b00'),
