(4061, 124, 'আধুনিক মেধাভিত্তিক সিভিল সার্ভিস এর উন্মেষ ঘটে কোন দেশ হতে?', 'যুক্তরাজ্য', NULL, 'যুক্তরাষ্ট্র', NULL, 'চীন', NULL, 'ভারত', NULL, 'C', 'আধুনিক মেধাভিত্তিক সিভিল সার্ভিসের উন্মেষ ঘটে প্রাচীন চীন সম্রাজ্যে। তাঁরাই প্রথম পরীক্ষার মাধ্যমে যোগ্য প্রার্থীকে বেছে নেয়ার পদ্ধতি চালু করে। সুই সাম্রাজ্য (৫৮১ থেকে ৬১৮) মেধার ভিত্তিতে আমলাদের নির্বাচিত করার পদ্ধতি চালু করে।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '686c1ea70ca44b0ad44401edbb010e85'),
(4062, 122, 'কোন রাষ্ট্রটি বিরোধপূর্ণ দক্ষিণ চীন সাগরের জলসীমার দাবিদার নয়?', 'মালয়েশিয়া', NULL, 'ফিলিপাইন', NULL, 'ভিয়েতনাম', NULL, 'কম্বোডিয়া', NULL, 'D', 'দক্ষিণ চীন সাগরের তীরবর্তী দেশসমূহ হলো: চীন, তাইওয়ান, ফিলিপাইন, ভিয়েতনাম, মালয়েশিয়া, ব্রুনেই, সিঙ্গাপুর ও ইন্দোনেশিয়া। কম্বোডিয়া দক্ষিণ চীন সাগরের দাবিদার নয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b66117bf49c95e14f684b39fef78d01b'),
(4063, 122, 'নাথু লা পাস কোন দুটি দেশকে সংযুক্ত করেছে?', 'ভারত-নেপাল', NULL, 'ভারত-পাকিস্তান', NULL, 'ভারত-চীন', NULL, 'ভারত-ভুটান', NULL, 'C', 'নাথু লা পাস ভারত ও চীনের মধ্যে একমাত্র স্থল সীমান্ত পথ, যা ভারতের সিকিম থেকে চীনের তিব্বতে যাওয়ার পাহাড়ী পথ। এটি হিমালয়ের ১৪,৪২৫ ফুট উঁচুতে অবস্থিত।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6ecc00a13e6c76f5c9e3088cf4c3ab48'),
(4064, 124, 'জাতিসংঘের টেকসই উন্নয়নের লক্ষ্য কয়টি?', '১১', NULL, '১৫', NULL, '১৭', NULL, '২১', NULL, 'C', '২০-২২ জুন ২০১২ রিও+২০ সম্মেলনে টেকসই উন্নয়নের জন্য কৌশল নির্ধারণ করা হয়। এতে ১৭টি অভীষ্ট, ১৬৯টি সহযোগী লক্ষ্য এবং ২৪১টি সূচক নির্ধারিত হয়। SDG-এর মেয়াদকাল ২০১৬ থেকে ২০৩০ সাল পর্যন্ত।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'eac8e24c71b57b5afa9651c9119e5d9d'),
(4065, 124, 'বিশ্ব মানবাধিকার দিবস–', '৮ ডিসেম্বর', NULL, '১০ ডিসেম্বর', NULL, '১১ ডিসেম্বর', NULL, '১৩ ডিসেম্বর', NULL, 'B', '১৯৪৮ সালের ১০ ডিসেম্বর জাতিসংঘের সাধারণ পরিষদের তৃতীয় অধিবেশনে সার্বজনীন মানবাধিকার ঘোষণাপত্র গৃহীত হয়। প্রতি বছর ১০ ডিসেম্বর বিশ্ব মানবাধিকার দিবস হিসেবে পালিত হয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5b88a831e231e18372dbd2c0b5dc6a1d'),
(4066, 124, 'World Development Report কোন সংস্থার বার্ষিক প্রকাশনা?', 'UNDP', NULL, 'World Bank', NULL, 'IMF', NULL, 'BRICS', NULL, 'B', '১৯৭৮ সাল থেকে বিশ্বব্যাংক বা International Bank for Reconstruction and Development (IBRD) World Development Report প্রকাশ করে। অপরদিকে, Human Development Index প্রকাশ করে UNDP।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '264cf043cc2e2948f402424ac44eece4'),
(4067, 124, 'ব্যাডমিন্টন কোন দেশের জাতীয় খেলা?', 'মালয়েশিয়া', NULL, 'ইন্দোনেশিয়া', NULL, 'চীন', NULL, 'ইংল্যান্ড', NULL, 'B', 'চীনের জাতীয় খেলা টেবিল টেনিস, ইংল্যান্ডের জাতীয় খেলা ক্রিকেট, ইন্দোনেশিয়ার জাতীয় খেলা ব্যাডমিন্টন।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd8cfd295e7586a16ad630a40db5122ab'),
(4068, 121, 'বাংলাদেশ কোনটির সদস্য নয়?', 'BCIM-EC', NULL, 'OAS', NULL, 'OIC', NULL, 'BIMSTEC', NULL, 'B', 'আমেরিকান অঞ্চলের জোট হলো Organization of American States (OAS)। এর সদর দপ্তর ওয়াশিংটন ডিসি। বাংলাদেশ OAS-এর সদস্য নয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd3cde95e659ebf838296cffd8f11c619'),
(4069, 124, 'চীনের জিনজিয়াং প্রদেশের মুসলিম গোষ্ঠীর নাম–', 'তুর্কমেন', NULL, 'উইঘুর', NULL, 'তাজিক', NULL, 'কাজাখ', NULL, 'B', 'চীনের পশ্চিমাঞ্চলীয় শহর জিনজিয়াং-এর প্রধান দুটি জাতি উইঘুর ও হান। উইঘুর জাতিগোষ্ঠী ইসলাম ধর্মাবলম্বী।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '23d8d4780e7e94542e35e052b1196a00'),
(4070, 124, 'The Lady with the Lamp নামে পরিচিত–', 'হেলেন কেলার', NULL, 'ফ্লোরেন্স নাইটিঙ্গেল', NULL, 'মাদার তেরেসা', NULL, 'সরোজিনী নাইডু', NULL, 'B', '১৮৫৩ থেকে ১৮৫৬ সাল পর্যন্ত ক্রিমিয়া যুদ্ধে যোদ্ধাহত সৈন্যদের সেবা প্রদানের জন্য ফ্লোরেন্স নাইটিঙ্গেলকে The Lady with the Lamp উপাধি প্রদান করা হয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ac66d4dec43d5eac739d8d2480f63f08'),
(4071, 124, 'মিয়ানমারের নির্বাসিত সরকারের নাম–', 'এনএলডি সরকার', NULL, 'ন্যাশনাল ইউনিটি সরকার', NULL, 'বার্মিজ গভর্নমেন্ট ইন এক্সাইল', NULL, 'অং সান সু চি সরকার', NULL, 'B', '১ ফেব্রুয়ারি ২০২১ মিয়ানমারের সামরিক জান্তা ক্ষমতা দখল করে। ১৬ এপ্রিল ২০২১ বিরোধীদল ও গোষ্ঠীগুলোর সমন্বয়ে গঠিত হয় জাতীয় ঐক্য সরকার (ন্যাশনাল ইউনিটি গভর্নমেন্ট)।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0c548ee129edde9f162c4c537c6d8d1f'),
(4072, 122, 'আকাবা একটি–', 'সমুদ্র বন্দর', NULL, 'বিমান বন্দর', NULL, 'স্থল বন্দর', NULL, 'নদী বন্দর', NULL, 'A', 'আকাবা হলো জর্ডানের একমাত্র সমুদ্র বন্দর এবং এটি আকাবা পোর্ট কর্পোরেশন পরিচালনা করে।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '12cf04107b774b579b7847af53c1c3f9'),
(4073, 124, 'Trafalgar Square এর অবস্থান–', 'রাশিয়ায়', NULL, 'ইংল্যান্ডে', NULL, 'ফ্রান্সে', NULL, 'চীনে', NULL, 'B', 'Trafalgar Square লন্ডনের কেন্দ্রস্থলে অবস্থিত একটি স্কয়ার। ১৮০৫ সালে সংঘটিত ট্রাফালগারের যুদ্ধে ব্রিটিশ নৌবাহিনীর জয়কে স্মরণীয় রাখতে এ নামকরণ করা হয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a406da5e608c999c8342420ad16804a1'),
(4074, 124, 'নিম্নের কোনটি জাতিসংঘের সংস্থা নয়?', 'আসিয়ান আঞ্চলিক ফোরাম (ARF)', NULL, 'আন্তর্জাতিক শ্রম সংস্থা (ILO)', NULL, 'আন্তর্জাতিক কৃষি উন্নয়ন তহবিল (IFAD)', NULL, 'খাদ্য ও কৃষি সংস্থা (FAO)', NULL, 'A', 'ILO, IFAD ও FAO জাতিসংঘের সহযোগী সংস্থা। অন্যদিকে ARF দক্ষিণ-পূর্ব এশিয়ার একটি আঞ্চলিক সংস্থা, জাতিসংঘের সংস্থা নয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '98db8c89e5bba09642c66c51bdcbd352'),
(4075, 124, 'ইরান-ইরাক যুদ্ধবিরতির তদারকির কাজে নিয়োজিত জাতিসংঘের বাহিনী কোন নামে পরিচিত ছিল?', 'UNIMOG', NULL, 'UNIIMOG', NULL, 'UNGOMAP', NULL, 'UNICEF', NULL, 'B', '১৯৮৮ সালে ইরাক-ইরান যুদ্ধ বন্ধে জাতিসংঘ United Nations Iran-Iraq Military Observer Group (UNIIMOG) প্রেরণ করে। এই মিশনে বাংলাদেশ প্রথমবারের মতো ১৫ জন সদস্য প্রেরণ করে।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'aa3278b25741794766a84614f437aa0d'),
(4076, 124, 'আন্তর্জাতিক গণতন্ত্র দিবস কোন তারিখে পালিত হয়?', '১৫ সেপ্টেম্বর', NULL, '১৫ অক্টোবর', NULL, '১৫ নভেম্বর', NULL, '১৫ ডিসেম্বর', NULL, 'A', 'আন্তর্জাতিক গণতন্ত্র দিবস জাতিসংঘ কর্তৃক ২০০৭ সাল থেকে সদস্যভূক্ত দেশগুলোতে প্রতি বছর ১৫ সেপ্টেম্বর পালিত হয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '787c17cd782b9bc7d4bbeef550793cd0'),
(4077, 124, 'ট্র্যান্সপারেন্সি ইন্টারন্যাশনাল এর প্রধান কার্যালয় কোথায়?', 'ফ্রান্স', NULL, 'জার্মানি', NULL, 'নেদারল্যান্ড', NULL, 'হাঙ্গেরি', NULL, 'B', '১৯৯৩ সালে জার্মানির বার্লিনে প্রতিষ্ঠিত হয় ট্র্যান্সপারেন্সি ইন্টারন্যাশনাল। এর উদ্দেশ্য হলো বিশ্বব্যাপী দুর্নীতি বিরোধী প্রচারণা ও তথ্য প্রদান।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '422ef10e081905dde5aef623779a049b'),
(4078, 124, 'চীন থেকে ক্রয়কৃত বাংলাদেশ নৌবাহিনীর ডুবোজাহাজ দুটি নিম্নোক্ত কোন শ্রেণির?', 'কিলো-ক্লাস', NULL, 'মিং-ক্লাস', NULL, 'ডলফিন-ক্লাস', NULL, 'শ্যাং-ক্লাস', NULL, 'B', '২০১২ সালে চীনের কাছ থেকে ২টি মিং-ক্লাস সাবমেরিন ক্রয় করার চুক্তি করা হয়। ২০১৯ সালে বিএনএস জয়যাত্রা এবং বিএনএস নবযাত্রা নামে দুটি সাবমেরিন বাংলাদেশ নৌবাহিনীতে যুক্ত হয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ef7b0042285a75b951823767b825432d'),
