(4082, 124, 'কোন দেশ থেকে আরব বসন্ত এর সূচনা হয়?', 'মিশর', NULL, 'তিউনিশিয়া', NULL, 'লিবিয়া', NULL, 'সিরিয়া', NULL, 'B', '২০১০ সালের ১৭ ডিসেম্বর তিউনিশিয়ার রাজধানী তিউনিশে মোঃ বুয়াজ্জিজি নামে ২৬ বছরের এক ফল বিক্রেতা প্রশাসনের দুর্নীতি আর বেকারত্বের জীবনে ক্ষুব্ধ হয়ে নিজের গায়ে কেরোসিন ঢেলে আগুন ধরিয়ে দিলে গণবিক্ষোভ শুরু হয়। এর ২৭ দিনের মাথায় স্বৈরশাসক জয়নুল আবেদিন বেন আলীর পতনের মাধ্যমে আরব বসন্তের সূচনা হয়।', NULL, 13, '44th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ad4dd0db090a2ac07d1e8d31ad960920'),
