(4140, 124, 'উত্তর আটলান্টিক চুক্তির কত নম্বর ধারায় যৌথ নিরাপত্তার ধারণাটি ব্যক্ত হয়েছে?', 'আর্টিকেল ২', NULL, 'আর্টিকেল ৩', NULL, 'আর্টিকেল ৪', NULL, 'আর্টিকেল ৫', NULL, 'D', 'আর্টিকেল ৫-এ বলা হয় যে, যদি একটি ন্যাটো মিত্র সশস্ত্র আক্রমণের শিকার হয়, তবে জোটের প্রতিটি সদস্য এই সহিংসতার কাজটিকে সদস্যদের বিরুদ্ধে সশস্ত্র আক্রমণ হিসেবে বিবেচনা করবে এবং প্রয়োজনীয় ব্যবস্থা গ্রহণ করবে।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ad920f9fb64e3ac6f0c62a069d315105'),
(4141, 124, 'আন্তর্জাতিক সম্পর্কের কোন তত্ত্বটি আন্তর্জাতিক প্রতিষ্ঠানের কার্যকরী ভূমিকার বিষয়ে ইতিবাচক ধারণা প্রদান করে?', 'উদারবাদ', NULL, 'বাস্তববাদ', NULL, 'মার্ক্সবাদ', NULL, 'কোনোটিই নয়', NULL, 'A', 'নব্য উদারতাবাদ আঞ্চলিক সংস্থা এবং আন্তর্জাতিক প্রতিষ্ঠানের কার্যকরী ভূমিকার উপর গুরুত্ব প্রদান করে। এ কারণে অনেক স্কলার নব্য উদারতাবাদকে Liberal institutionalism বা উদার প্রতিষ্ঠানবাদও বলে থাকেন।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0b3e26e2f4b9a17affa16954e459a383'),
(4142, 122, 'সম্প্রতি পেরুতে খুঁজে পাওয়া ৩৫০০ বছরের পুরোনো শহরের নাম কী?', 'মাচুপিচু', NULL, 'কোরাল', NULL, 'পেনিকো', NULL, 'কুস্কো', NULL, 'C', 'পেনিকো নগরটি পেরুর রাজধানী লিমার উত্তরে হুয়াওরা প্রদেশে অবস্থিত। এটি ৩৫০০ বছরের বেশি আগে সমৃদ্ধ বাণিজ্যিক কেন্দ্র হিসেবে গড়ে ওঠা একটি প্রাচীন শহর।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2fca5d47b6b0cad5215d36300070ab3d'),
