(4165, 121, 'বাংলাদেশের রাজনীতি সম্পর্কে একজন আমেরিকান ঐতিহাসিক মন্তব্য করেছেন; বাংলাদেশের রাজনীতি ব্যক্তিত্বকে কেন্দ্র করে আবর্তিত হয়, ধারণা বা প্রতিষ্ঠানকে কেন্দ্র করে নয়। এই ঐতিহাসিকের নাম কী?', 'এন্থনি মাসকারেনহাস', NULL, 'লরেঞ্চ জিরিং', NULL, 'লরেঞ্চ লিফশুলজ', NULL, 'হেনরি কিসিঞ্জার', NULL, 'B', 'বাংলাদেশের রাজনীতি ব্যক্তিত্বকে কেন্দ্র করে আবর্তিত হয়, ধারণা বা প্রতিষ্ঠানকে কেন্দ্র করে নয়—মন্তব্যটি আমেরিকান ঐতিহাসিক লরেঞ্চ জিরিং-এর। তিনি তার বই Bangladesh: from Mujib to Ershad: an interpretive study-তে এ মন্তব্য করেন।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '78d6ab8903ab947a44ce8f1511c9e521'),
(4166, 124, 'বিশ্বের প্রথম জাতিসংঘ শান্তিরক্ষী বাহিনী কোনটি?', 'UNOSOM', NULL, 'UNMOGIP', NULL, 'UNTSO', NULL, 'UNEF 1', NULL, 'C', 'জাতিসংঘ ১৯৪৮ সাল থেকে প্রথম শান্তিরক্ষা কার্যক্রম শুরু করে। প্রথম আরব-ইসরাইল যুদ্ধের (১৯৪৮) প্রেক্ষাপটে জাতিসংঘের প্রথম শান্তিরক্ষী বাহিনী United Nations Truce Supervision Organization (UNTSO) গঠিত হয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1a4e772387fa6bc40a0e2abc032b184a'),
(4167, 124, 'প্রথম বিশ্বযুদ্ধ কোন চুক্তির মাধ্যমে সমাপ্ত হয়?', 'প্যারিস চুক্তি', NULL, 'ভার্সাই চুক্তি', NULL, 'জেনেভা চুক্তি', NULL, 'রোম চুক্তি', NULL, 'B', '১৯১৯ সালে জার্মানির সাথে মিত্রশক্তিদের মধ্যে স্বাক্ষরিত ভার্সাই চুক্তির মাধ্যমে প্রথম বিশ্বযুদ্ধের আনুষ্ঠানিক সমাপ্তি হয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '68da9426af24f012f964f478b01af7d3'),
(4168, 124, 'মার্কিন যুক্তরাষ্ট্রের কোন প্রেসিডেন্ট জাপানে পারমাণবিক বোমা নিক্ষেপের অনুমোদন করেছিলেন?', 'হ্যারি এস ট্রুম্যান', NULL, 'ফ্রাঙ্কলিন ডি. রুজভেল্ট', NULL, 'রিচার্ড নিক্সন', NULL, 'জর্জ ডাব্লিও বুশ', NULL, 'A', '১৯৪৫ সালে তৎকালীন মার্কিন প্রেসিডেন্ট হ্যারি এস ট্রুম্যান জাপানে পারমাণবিক বোমা নিক্ষেপের অনুমোদন করেন। ৬ আগস্ট হিরোশিমায় এবং ৯ আগস্ট নাগাসাকিতে বোমা নিক্ষেপ করা হয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'de848f70ab095f3a5d5a4f63163e0efb'),
(4169, 123, 'ODS (Ozone Depleting Substances)-এর ব্যবহার কমানোর জন্য কোন চুক্তি স্বাক্ষরিত হয়?', 'কিয়োটো প্রটোকল', NULL, 'মন্ট্রিল প্রটোকল', NULL, 'প্যারিস চুক্তি', NULL, 'রামসার কনভেনশন', NULL, 'B', 'ODS (Ozone Depleting Substances)-এর ব্যবহার কমানোর জন্য ১৯৮৭ সালে কানাডার মন্ট্রিলে Montreal Protocol on Substances that Deplete the Ozone Layer স্বাক্ষরিত হয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd0a424085580be906921fd1705ae0414'),
(4170, 124, 'আফিম যুদ্ধ কোন দুইটি দেশের মধ্যে সংঘটিত হয়?', 'চীন ও আফগানিস্তান', NULL, 'চীন ও ইংল্যান্ড', NULL, 'চীন ও রাশিয়া', NULL, 'ইংল্যান্ড ও আফগানিস্তান', NULL, 'B', 'চীন আর ব্রিটেনের মধ্যে ১৮৩৯ থেকে ১৮৪২ সাল পর্যন্ত সংঘটিত হয় আফিম যুদ্ধ। যুদ্ধে চীন পরাজিত হয় এবং পাঁচটি গুরুত্বপূর্ণ বন্দর ব্রিটিশদের ছেড়ে দেয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '65c1fd741f7f5a2ec6fd5541c7736fb4'),
(4171, 122, 'কেপ ভার্দে (Cape Verde) দ্বীপ রাষ্ট্রটি কোথায় অবস্থিত?', 'গালফ অফ গিনি', NULL, 'ফ্রেঞ্চ পলিনেশিয়া', NULL, 'দক্ষিণ আফ্রিকা', NULL, 'পশ্চিম আফ্রিকা', NULL, 'D', 'কেপ ভার্দে পশ্চিম আফ্রিকার উপকূলে আটলান্টিক মহাসাগরে অবস্থিত একটি দ্বীপ রাষ্ট্র। এটি ১০টি প্রধান এবং ৮টি ক্ষুদ্র দ্বীপ নিয়ে গঠিত।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '92c21a88658bb97cbd6f4ea75a6c8db4'),
(4172, 124, 'নিম্নোক্ত কোন দেশ বা অঞ্চল জাতিসংঘের সদস্য দেশ নয়?', 'তিমুর লেস্তে', NULL, 'দক্ষিণ সুদান', NULL, 'ওয়েস্টার্ন সাহারা', NULL, 'সেন্ট্রাল আফ্রিকান রিপাবলিক', NULL, 'C', 'আফ্রিকা মহাদেশের উত্তর প্রান্তে অবস্থিত পশ্চিম সাহারা জাতিসংঘের সদস্য নয়। এর অধিকাংশ এলাকা বর্তমানে মরক্কোর নিয়ন্ত্রণে।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2853df248db2a5624acec3dc2da392a9'),
(4173, 124, 'নিম্নোক্ত কোন দেশটি ইউরোপিয়ান ইউনিয়নের (EU) সদস্য নয়?', 'বুলগেরিয়া', NULL, 'হাঙ্গেরি', NULL, 'পোল্যান্ড', NULL, 'সুইজারল্যান্ড', NULL, 'D', 'EU ম্যাসট্রিক্ট চুক্তির মাধ্যমে ১৯৯৩ সালে গঠিত হয়। সুইজারল্যান্ড ইউরোপের দেশ হলেও European Union-এর সদস্য নয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '43f0858d70f54401c104cabde70a4de0'),
(4174, 124, 'নিম্নোক্ত কোন দেশটি Five Eyes-ভুক্ত নয়?', 'অস্ট্রেলিয়া', NULL, 'ফ্রান্স', NULL, 'নিউজিল্যান্ড', NULL, 'কানাডা', NULL, 'B', 'Five Eyes (FVEY) একটি গোয়েন্দা জোট। এর সদস্য ৫টি: যুক্তরাষ্ট্র, যুক্তরাজ্য, অস্ট্রেলিয়া, কানাডা ও নিউজিল্যান্ড। ফ্রান্স এর সদস্য নয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ffbc07a4cb0548d1fc22d6eb0773639b'),
(4175, 124, 'নিম্নোক্ত কোন রাষ্ট্রটি সাংহাই কোঅপারেশন অর্গানাইজেশন বা SCO-এর সদস্য নয়?', 'আজারবাইজান', NULL, 'ভারত', NULL, 'পাকিস্তান', NULL, 'ইরান', NULL, 'A', 'SCO প্রতিষ্ঠা ১৫ জুন, ২০০১ সালে। বর্তমান সদস্য ১০টি: চীন, রাশিয়া, কাজাখস্তান, কিরগিজিস্তান, তাজিকিস্তান, উজবেকিস্তান, ভারত, পাকিস্তান, ইরান ও বেলারুশ। আজারবাইজান SCO-এর সদস্য নয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8cd17aca124d66a5968a57f1d1d79ccd'),
(4176, 122, 'চীন, ভারত ও বাংলাদেশের প্রবাহিত ব্রহ্মপুত্র নদী চীন বা তিব্বতে কী নামে পরিচিত?', 'ইয়াংসি', NULL, 'লিজিয়াং', NULL, 'হোয়াইলি', NULL, 'ইয়ারলাং সাংপো', NULL, 'D', 'ব্রহ্মপুত্র নদী চীন/তিব্বতে ইয়ারলাং সাংপো নামে পরিচিত। ভারতে এটি সিয়াং/দিহেং নামে পরিচিত।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0b32b14c470eeef88ee745269fb5e2f1'),
(4177, 124, 'ভারত-পাকিস্তানের মধ্যে ইন্দাস ওয়াটার ট্রিটি (IWT) কোন সালে স্বাক্ষরিত হয়?', '১৯৪৮', NULL, '১৯৭৪', NULL, '১৯৬৫', NULL, '১৯৮০', NULL, 'C', 'ভারত-পাকিস্তানের মধ্যে ইন্দাস ওয়াটার ট্রিটি (IWT) স্বাক্ষরিত হয় ১৯ সেপ্টেম্বর, ১৯৬০ সালে করাচিতে। বিশ্বব্যাংক এর মধ্যস্থতায় ছিল। একে বাংলায় সিন্ধু পানি চুক্তি বলা হয়।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd27b6b5ecd2c0164744ef524d3459637'),
