(4181, 124, 'প্রাচীন কালে কোন দেশে সিভিল সার্ভিসের ধারণা প্রথম উদ্ভূত হয়?', 'মিশর', NULL, 'গ্রীস', NULL, 'চীন', NULL, 'রোম', NULL, 'C', 'হান রাজবংশের সময়কালে চীনে প্রথম সিভিল সার্ভিসের ধারণার সৃষ্টি হয়। কনফুসিয়াসের দর্শনের ভিত্তিতে রাষ্ট্র পরিচালনায় মেধা ও গুণসম্পন্ন ব্যক্তিদের নিয়োগের জন্য পরীক্ষা পদ্ধতি চালু হয়েছিল।', NULL, 185, '49th BCS Special (Education)', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '690feace51ac96e750c9aee44bc27f10'),
(4182, 124, 'কোন বিষয়টি মুদ্রাপাচারের অন্তর্ভুক্ত নয়?', 'রপ্তানী পণ্যের অবমূল্যায়ন', NULL, 'আমদানী পণ্যের অধিক মূল্য নির্ধারণ', NULL, 'আয়কর ফাঁকি দেয়া', NULL, 'অবৈধ চ্যানেলে বিদেশে টাকা পাঠানো', NULL, 'C', 'মুদ্রাপাচার হলো অবৈধ অর্থকে বৈধ করার প্রক্রিয়া বা অবৈধ পথে অর্থ স্থানান্তর। রপ্তানি পণ্যের অবমূল্যায়ন, আমদানি পণ্যের অধিক মূল্য নির্ধারণ এবং অবৈধ চ্যানেলে বিদেশে টাকা পাঠানো সবই মুদ্রাপাচারের কৌশল। কিন্তু আয়কর ফাঁকি একটি কর সংক্রান্ত অপরাধ, যা মুদ্রাপাচারের অন্তর্ভুক্ত নয়।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '04ef8592d21fcd9318526daa4d8e7547'),
(4183, 124, 'বিশ্ব বাণিজ্য সংস্থা (WTO) প্রতিষ্ঠিত হয়েছিল ____ চুক্তির মাধ্যমে।', 'ব্রেটন উডস', NULL, 'লিসবন', NULL, 'জেনেভা', NULL, 'মারাকেশ', NULL, 'D', 'দীর্ঘ ৮ বছর চলমান উরুগুয়ে রাউন্ডের চূড়ান্ত ফসল হিসেবে ১৫ এপ্রিল, ১৯৯৪ সালে মরোক্কোর মারাকেশে চুক্তি স্বাক্ষরিত হয়। ১ জানুয়ারি, ১৯৯৫ সালে GATT বিশ্ব বাণিজ্য সংস্থায় (WTO) রূপান্তরিত হয়।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9929261095fdba9d0cf96ace1022f134'),
(4184, 124, 'কোন ভূ-রাজনৈতিক তত্ত্ব বিশ্ব আধিপত্যের চাবিকাঠি হিসাবে ইউরেশিয়ার নিয়ন্ত্রণকে সমর্থন করে?', 'হার্টল্যান্ড তত্ত্ব', NULL, 'ডমিনো তত্ত্ব', NULL, 'রিমল্যান্ড তত্ত্ব', NULL, 'কন্টেইনমেন্ট তত্ত্ব', NULL, 'A', '১৯০৪ সালে Sir Halford Mackinder হার্টল্যান্ড তত্ত্ব প্রদান করেন। মূলভাব: যারা পূর্ব ইউরোপ শাসন করবে তারা হার্টল্যান্ড নিয়ন্ত্রণ করবে, যারা হার্টল্যান্ড শাসন করে তারা বিশ্বদ্বীপ নিয়ন্ত্রণ করবে, যারা বিশ্বদ্বীপ নিয়ন্ত্রণ করবে তারা পুরো পৃথিবী নিয়ন্ত্রণ করবে।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-06', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0ecd1e6aa29ea127c412f4832c48e902'),
