(4528, 127, 'I have read the book ___ you lent me.', 'that', NULL, 'whom', NULL, 'whose', NULL, 'what', NULL, 'A', 'এখানে conjunction বসবে যা the book বা বস্তুর পরিবর্তে বসে। That বস্তুর ক্ষেত্রে বসে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '257c37b3f28e57c33bbc64d404721209'),
(4529, 139, 'Water boils ____ you heat it to 100° centigrade.', 'unless', NULL, 'until', NULL, 'if', NULL, 'although', NULL, 'C', 'বাক্যটি একটি বৈজ্ঞানিক শর্ত প্রকাশ করছে বলে if-ই এখানে যথার্থ।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1600bb28e8fe6ecce8850e7cc393f33d'),
(4530, 139, 'Tell me ___ that.', 'whom told you', NULL, 'that told you', NULL, 'who told you', NULL, 'told you', NULL, 'C', 'বাক্যটির শূন্যস্থান পূরণ করলে একটি WH question দাঁড়ায়। Who told you - কে বলল?', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2c98c0e985aba666513efe26ad81ea32'),
(4531, 138, 'I opened the door as soon as I ___ the bell.', 'have heard', NULL, 'was hearing', NULL, 'am heard', NULL, 'heard', NULL, 'D', 'অতীতে কোনো ঘটনা সমসাময়িক সময়ে ঘটলে উভয়ই একই tense-এ হয়। As soon as এর পূর্বে past indefinite থাকায় এর পরেও past indefinite (heard) হবে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e4deebe8757066017a20ee8f50e7d3e0'),
(4532, 128, 'I am looking for someone who ____ play the piano.', 'able to', NULL, 'is able', NULL, 'can be able to', NULL, 'can', NULL, 'D', 'কারো কোনো কিছু করার যোগ্যতা, সামর্থ্য বা সুযোগ রয়েছে বুঝাতে can ব্যবহৃত হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a8ec5672e2de6b87170abc2652c44e2d'),
(4533, 138, 'Don\'t make a noise while your father ____.', 'is being asleep', NULL, 'is sleeping', NULL, 'asleep', NULL, 'has slept', NULL, 'B', 'subordinate clause-এর শুরুতে while থাকায় তা continuous tense হবে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '076e653912a6e82e7b8fc6a710cf2c9a'),
(4534, 138, 'As the sun ____, I decided to go out.', 'shines', NULL, 'has shone', NULL, 'shine', NULL, 'was shining', NULL, 'D', 'main clause যদি past tense-এ থাকে তাহলে subordinate clause অবশ্যই past tense হবে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7d0c96dc035d81f78ebfc098f3ff6f96'),
(4535, 128, 'He gave up ____ football when he got married.', 'to play', NULL, 'playing', NULL, 'play', NULL, 'of playing', NULL, 'B', 'gave up verb টি থাকার ফলে শূন্যস্থানে gerund (playing) বসবে।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bd2fe1b47967d9f9f1e6f92046b8d9da'),
(4536, 131, 'I have ____ interest in the matter.', 'not', NULL, 'any', NULL, 'none', NULL, 'no', NULL, 'D', 'have মূল verb হিসেবে থাকলে negative করার সময় no ব্যবহার করতে হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-10', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b0a1a7a93819ff1dfdbfc02f428be8d5'),
