(5636, 290, 'বাংলাদেশের অর্থনৈতিক সমুদ্রসীমা কত নটিক্যাল মাইল?', '১৫০ নটিক্যাল মাইল', NULL, '২০০ নটিক্যাল মাইল', NULL, '২৫০ নটিক্যাল মাইল', NULL, '৩০০ নটিক্যাল মাইল', NULL, 'B', 'বাংলাদেশের মোট মহীসোপান ৩৫৪ নটিক্যাল মাইল। তার মধ্যে ২০০ নটিক্যাল মাইল অর্থনৈতিক সমুদ্রসীমা যা সমুদ্রসীমা আইন ১৯৮২ দ্বারা নির্ধারিত হয়েছে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '00b8381ea6497843a223f0b15f1d0530'),
(5637, 307, 'নিচের কোনটি বাংলাদেশের সর্ববৃহৎ গ্যাস ক্ষেত্র?', 'বাখরাবাদ', NULL, 'হরিপুর', NULL, 'তিতাস', NULL, 'হবিগঞ্জ', NULL, 'C', 'গ্যাসের মজুদের ভিত্তিতে বাংলাদেশের সবচেয়ে বড় প্রাকৃতিক গ্যাসক্ষেত্র তিতাস। অর্থনৈতিক সমীক্ষা ২০২৩ অনুসারে এটির উৎপাদনরত কূপসংখ্যা ২২টি। উল্লেখ্য যে বাংলাদেশে মোট গ্যাসক্ষেত্রের সংখ্যা ২৯টি।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '96e5ff521234a7a27e3e8e85c0538a39'),
(5638, 328, 'ভূমিকম্প সংঘটন বিন্দুর সরাসরি উপরে ভূপৃষ্ঠস্থ বিন্দুকে বলে–', 'ফোকাস', NULL, 'এপিসেন্টার', NULL, 'ফ্রাকচার', NULL, 'ফল্ট', NULL, 'B', 'ভূমিকম্প উৎপাদনের সম্ভাবনা দুইটি টেকটোনিক প্লেটের মধ্যবর্তী স্থানে সবচেয়ে বেশি যাকে বলে ফল্ট। ভূমিকম্প ভূগর্ভের যেখানে উৎপাদিত হয় তাকে Centre বলে। এই বিন্দু বরাবর সরাসরি উপরে ভূপৃষ্ঠের স্থানকে বলে এপিসেন্টার।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1fa074fdb37ae73eb2991e9262603416'),
(5639, 314, 'বিশ্বব্যাপী নিচের কোন অর্থনৈতিক খাত থেকে সবচাইতে বেশি গ্রিন হাউজ গ্যাস নির্গত হয়?', 'পরিবহন', NULL, 'বিদ্যুৎ ও তাপ উৎপাদন', NULL, 'ভবন নির্মাণ', NULL, 'শিল্প', NULL, 'B', 'IPCC এর রিপোর্ট অনুযায়ী বিদ্যুৎ ও তাপশক্তি উৎপাদনে ২৫%, চাষাবাদ, পশুপালন, বৃক্ষ নিধন মিলে ২৪%, বিভিন্ন কলকারখানা অর্থাৎ শিল্প খাত হতে ২১%, পরিবহন হতে ১৪% এবং অন্যান্য আরো কিছু উৎস থেকে গ্রিন হাউস গ্যাস নির্গত হয়।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '985e2379d7eee0222bbad291a73e106e'),
(5640, 324, 'উত্তর গোলার্ধে ক্রান্তীয় ঘূর্ণিঝড়ের বায়ু প্রবাহিত হয়–', 'ঘড়ির কাটার দিকে', NULL, 'ঘড়ির কাটার বিপরীতে', NULL, 'সোজা', NULL, 'কোনটাই সঠিক নয়', NULL, 'B', 'উত্তর গোলার্ধে ক্রান্তীয় ঘূর্ণিঝড়ের বায়ু প্রবাহিত হয় ঘড়ির কাটার বিপরীত দিকে। দক্ষিণ গোলার্ধে ক্রান্তীয় ঘূর্ণিঝড়ের বায়ু প্রবাহিত হয় ঘড়ির কাটার দিকে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8616d377958b31698ab74f02323fabff'),
(5641, 289, 'হিলি স্থল বন্দরটি বাংলাদেশের কোথায় অবস্থিত?', 'বিরামপুর, দিনাজপুর', NULL, 'ঘোড়াঘাট, দিনাজপুর', NULL, 'হাকিমপুর, দিনাজপুর', NULL, 'পাঁচবিবি, জয়পুর হাট', NULL, 'C', 'হিলি স্থলবন্দরটি বাংলাদেশ–ভারত সীমান্তে দিনাজপুর জেলার হাকিমপুর উপজেলায় অবস্থিত।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '540f0b209326b4d3125e4408aab72983'),
(5642, 312, 'ঢাকা থেকে পূর্বদিকে অবস্থিত একটি স্থানের সাথে দ্রাঘিমার পার্থক্য ৪৫°। ঢাকার সময় মধ্যাহ্ন ১২:০০ টা হলে ঐ স্থানটির স্থানীয় সময় হবে–', 'সকাল ০৯:০০ টা', NULL, 'বিকাল ০৩:০০ টা', NULL, 'সন্ধ্যা ০৬:০০ টা', NULL, 'রাত ০৯:০০ টা', NULL, 'B', 'দ্রাঘিমা (Longitude): গ্রিনিচের মূল মধ্যরেখা থেকে পূর্বে বা পশ্চিমে যে কোন স্থানের কৌণিক দূরত্বকে সেই স্থানের দ্রাঘিমা বলা হয়। যদি গ্রিনিচের সময় এবং অন্য কোনো স্থানের সময় জানা থাকে তাহলে দুটি স্থানের সময়ের পার্থক্য অনুসারে প্রতি ৪ মিনিট সময়ের পার্থক্যে ১° দ্রাঘিমার পার্থক্য ধরে ঐ স্থানের দ্রাঘিমা নির্ণয় করা যায়। কোনো স্থান গ্রিনিচের পূর্বে হলে তার স্থানীয় সময় গ্রিনিচের সময় অপেক্ষা বেশি হবে এবং পশ্চিমে হলে স্থানীয় সময় গ্রিনিচের সময় থেকে কম হবে। ঢাকা থেকে পূর্বদিকে অবস্থিত একটি স্থানের সাথে দ্রাঘিমার পার্থক্য ৪৫°। ৪৫° × ৪ মিনিট = ১৮০ মিনিট = ৩ ঘণ্টা। ঢাকার সময় ১২:০০ টা + ৩ ঘণ্টা = বিকাল ০৩:০০ টা।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f452a14e910b62def703c81d13ff7325'),
(5643, 328, 'কোন দুটি প্লেটের সংযোগস্থল বরাবর মাউন্ট এভারেস্ট অবস্থিত?', 'ইন্ডিয়ান ও ইউরেশিয়ান', NULL, 'ইন্ডিয়ান ও বার্মিজ', NULL, 'ইন্ডিয়ান ও আফ্রিকান', NULL, 'বার্মিজ ও ইউরেশিয়ান', NULL, 'A', 'ভূপৃষ্ঠে বিভিন্ন আয়তনের মোট ২৭টি পাত বা প্লেটের সন্ধান পাওয়া গেছে। এদের মধ্যে ৭টি বৃহৎ এবং ২০টি ক্ষুদ্র আকৃতির প্লেট রয়েছে। ভারতীয় টেকটনিক প্লেটের ইউরেশীয় প্লেটের নিচে অধোগমন দ্বারা উত্থিত হওয়ায়, হিমালয় পর্বতমালা ২,৪০০ কিলোমিটার দীর্ঘ একটি দুর্গম পথ ধরে পশ্চিম-উত্তর-পশ্চিম থেকে পূর্ব-দক্ষিণ-পূর্ব দিকে বিস্তৃত হয়েছে। এর উল্লেখযোগ্য পর্বত শৃঙ্গের মধ্যে একটি হলো মাউন্ট এভারেস্ট, যা পৃথিবীর সর্বোচ্চ চূড়া (৮৮৪৮ মিটার)।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cf8b35ae6efd0f523a415a53fe283bcd'),
(5644, 312, 'উচ্চতা বৃদ্ধির সাথে ট্রপোমন্ডলে বায়ুর ক্রমহ্রাসমান তাপমাত্রা হল–', '৫.৫° সেলসিয়াস/কিলোমিটার', NULL, '৬.৫° সেলসিয়াস/কিলোমিটার', NULL, '৭.৫° সেলসিয়াস/কিলোমিটার', NULL, '৮.৫° সেলসিয়াস/কিলোমিটার', NULL, 'B', 'ভূপৃষ্ঠের কাছাকাছি যে স্তরে উচ্চতা বৃদ্ধির সাথে সাথে তাপমাত্রা হ্রাস পায়, তাকে ট্রপোস্ফিয়ার বলে। এটি বায়ুমন্ডলের সর্বনিম্ন স্তর। ট্রপোস্ফিয়ারে অর্থাৎ নিম্ন বায়ুমন্ডলে প্রতি কিলোমিটারে ৬.৪° সেলসিয়াস বা প্রতি হাজার ফুটে ৩.৫° ফা. হারে বায়ুর তাপমাত্রা হ্রাস পায়। বায়ুর তাপমাত্রা হ্রাসের এ হারকে পরিবেশগত তাপ হ্রাস হার (Environmental lapse rate) বা স্বাভাবিক তাপ হ্রাস হার (Normal lapse rate) বলে।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4b16326016a8107319fbecea9c8f0717'),
(5645, 314, 'দুবাইয়ে অনুষ্ঠিত জাতিসংঘ জলবায়ু বিষয়ক সম্মেলন (কপ-২৮) মূল ফোকাস ছিল–', 'জীবাশ্ম জ্বালানির ব্যবহার পর্যায়ক্রমে হ্রাসকরণ', NULL, 'জীববৈচিত্র সংরক্ষণ বিষয়ক', NULL, 'ওজোনস্তর ক্ষয় নিয়ন্ত্রণ বিষয়ক', NULL, 'মরুকরণ প্রক্রিয়া বিষয়ক', NULL, 'A', 'দুবাইয়ে জাতিসংঘের জলবায়ু বিষয়ক বৈশ্বিক সম্মেলন কনফারেন্স অব পার্টিজ বা কপ-২৮ এ একটি নতুন চুক্তির বিষয়ে সবাই ঐকমত্যে পৌঁছেছে, যাতে প্রথমবারের মতো তেল, গ্যাস ও কয়লার মতো জীবাশ্ম জ্বালানী থেকে সরে আসার জন্য দেশগুলোর প্রতি আহবান জানানো হয়েছে।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c922f7ae9a3a2c9efe153cfa524b9340'),
(5646, 312, 'নিরক্ষীয় তল থেকে উত্তর মেরুর কৌণিক দূরত্ব বা উৎপন্ন কোণ কত?', '১৮০°', NULL, '৩৬০°', NULL, '৯০°', NULL, '০°', NULL, 'C', 'নিরক্ষরেখা থেকে উত্তরে বা দক্ষিণে অবস্থিত কোনো স্থানের কৌণিক দূরত্বকে ঐ স্থানের অক্ষাংশ বলে। নিরক্ষরেখার উত্তর দিকে অবস্থিত কোনো স্থানের উত্তর অক্ষাংশ এবং দক্ষিণ দিকে অবস্থিত কোনো স্থানের অক্ষাংশকে দক্ষিণ অক্ষাংশ বলে। নিরক্ষরেখার অক্ষাংশ ০°; উত্তর মেরু বা সুমেরুর অক্ষাংশ ৯০° উত্তর এবং দক্ষিণ মেরু বা কুমেরুর অক্ষাংশ ৯০° দক্ষিণ।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e7f4771a960e1bb2f4981f109107dda7'),
(5647, 325, 'জাপানিজ শব্দ সুনামি এর অর্থ কী?', 'বিশালাকৃতির ঢেউ', NULL, 'সামুদ্রিক ঢেউ', NULL, 'জলোচ্ছ্বাস', NULL, 'পোতাশ্রয়ের ঢেউ', NULL, 'D', 'জাপানি শব্দ সুনামি অর্থ পোতাশ্রয়ের ঢেউ। সুনামি সমুদ্রের ঢেউ নামে অধিকভাবে পরিচিত। কিন্তু চন্দ্র অথবা সূর্যের আকর্ষণের দ্বারা প্রকৃতপক্ষে এ ঢেউয়ের উৎপত্তি হয় না। মূলত সুনামি হলো ভূমিকম্পের সময় সমুদ্রতলের উলম্ব স্থানচ্যুতির ফলাফল। একটি পুকুরে ঢিল নিক্ষেপের ফলে যে ধরনের মৃদু তরঙ্গের সৃষ্টি হয়, তার সাথে সুনামির তুলনা করা চলে। সুনামির ক্ষেত্রে ঢেউগুলো একের পর এক উঁচু হয়ে আসে। উপকূলে এসে ঢেউয়ের উচ্চতা অনেক বৃদ্ধি পায় এবং উপকূলে আঘাত হেনে জনবসতি ও প্রাণহানির মতো ঘটনা ঘটায়।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '17845f525842354deaf533f47e45d6cb'),
(5648, 314, 'বৈশ্বিক উষ্ণায়নের জন্য ঝুঁকিপূর্ণ নয় কোনটি?', 'মরুকরণ', NULL, 'বন্যা', NULL, 'সমুদ্র পৃষ্ঠের উচ্চতা বৃদ্ধি', NULL, 'ভূমিকম্প', NULL, 'D', 'বৈশ্বিক উষ্ণায়নের কারণে জলবায়ুর যে মারাত্মক পরিবর্তন দেখা দিয়েছে তার প্রভাবে সবচেয়ে ঝুঁকিপূর্ণ দেশ হিসেবে বিবেচিত হচ্ছে বাংলাদেশ। বিশ্বব্যাংক জলবায়ু পরিবর্তনের ফলে ২০০৯ সালে ৫টি ঝুঁকিপূর্ণ দিক (যেমন- মরুকরণ, বন্যা, ঝড়, সমুদ্রপৃষ্ঠের উচ্চতা বৃদ্ধি এবং কৃষিক্ষেত্রে অধিকতর অনিশ্চয়তা) চিহ্নিত করেছে এবং এ ৫টি ভাগের একটিতে শীর্ষ ঝুঁকিপূর্ণ অবস্থানসহ ৩টিতে বাংলাদেশের নাম রয়েছে। অন্যদিকে, বৈশ্বিক উষ্ণায়নের জন্য ঝুঁকিপূর্ণ নয় ভূমিকম্প। ভূমিকম্প: পৃথিবীর অভ্যন্তর ভাগ কোনো কারণে কেঁপে ওঠাকে সাধারণভাবে ভূমিকম্প বলে। মূলত ভূ-অভ্যন্তরে কোনো কারণে (তাপ ও চাপের তারতম্যজনিত) দ্রুত বিপুল শক্তি মুক্ত হওয়ায় ভূপৃষ্ঠে যে প্রবল ঝাঁকুনি বা কম্পনের সৃষ্টি হয়, তাকে ভূমিকম্প বলে।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8562aeca20ddd3786a8d46827876863d'),
(5649, 323, 'বন্যা নিয়ন্ত্রণে সাধারণ ব্যবস্থাপনার অন্তর্ভুক্ত নয় কোনটি?', 'নদী খননের মাধ্যমে পানি পরিবহন সক্ষমতা বৃদ্ধি করা', NULL, 'নদী শাসন ব্যবস্থা সুনিশ্চিত করা', NULL, 'নদীর দুই তীরে বনাঞ্চল সৃষ্টি করা', NULL, 'বন্যার পূর্বাভাস ও সতর্কীকরণ ব্যবস্থার উন্নয়ন সাধন করা', NULL, 'C', 'বন্যা নিয়ন্ত্রণে সাধারণ ব্যবস্থাপনার মধ্যে নদী খননের মাধ্যমে পানি পরিবহন সক্ষমতা বৃদ্ধি করা, নদী শাসন ব্যবস্থা সুনিশ্চিত করা এবং বন্যার পূর্বাভাস ও সতর্কীকরণ ব্যবস্থার উন্নয়ন সাধন করা অন্তর্ভুক্ত। নদীর দুই তীরে বনাঞ্চল সৃষ্টি করা বন্যা নিয়ন্ত্রণের সাধারণ ব্যবস্থাপনার অন্তর্ভুক্ত নয়।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b0aa9d17ca0c859233f52fc52b47cfc8'),
(5650, 327, 'নিচের কোনটি কৃষি আবহাওয়াজনিত আপদ (Hazard)?', 'ভূমিকম্প', NULL, 'ভূমিধস', NULL, 'সুনামি', NULL, 'খরা', NULL, 'D', 'কৃষি আবহাওয়াজনিত আপদের মধ্যে খরা অন্যতম। খরা সরাসরি কৃষি উৎপাদনকে ক্ষতিগ্রস্ত করে। ভূমিকম্প, ভূমিধস ও সুনামি প্রাকৃতিক দুর্যোগ হলেও এগুলো কৃষি আবহাওয়াজনিত আপদ নয়।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9176e7129d13af1a4f8d02df890251d1'),
(5651, 290, 'বাংলাদেশের দীর্ঘতম স্থলসীমান্ত ভারতের কোন রাজ্যের সাথে?', 'মেঘালয়', NULL, 'আসাম', NULL, 'পশ্চিমবঙ্গ', NULL, 'ত্রিপুরা', NULL, 'C', 'বিজিবির তথ্য অনুযায়ী ভারতের ৫টি রাজ্যের সাথে বাংলাদেশের মোট ৪১৫৬ কি.মি. সীমান্ত বিদ্যমান। যার মধ্যে বাংলাদেশের সাথে পশ্চিমবঙ্গের ২২১৬.৭ কি.মি. সীমান্ত বিদ্যমান।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1a2314601278637903c0b89dbb5047e4'),
(5652, 312, 'প্রতি ৩০° দ্রাঘিমার স্থানান্তরে সময়ের ব্যবধান কত মিনিট হয়?', '১৫ মিনিট', NULL, '৩০ মিনিট', NULL, '৬০ মিনিট', NULL, '১২০ মিনিট', NULL, 'D', 'পৃথিবী ২৪ ঘণ্টায় ৩৬০° ঘোরে, অর্থাৎ প্রতি ১ ঘণ্টা বা ৬০ মিনিটে পৃথিবী ১৫° দ্রাঘিমাংশ ঘোরে। প্রতি ১° দ্রাঘিমাংশের জন্য সময়ের পার্থক্য হয় ৬০/১৫ = ৪ মিনিট। সুতরাং, ৩০° দ্রাঘিমা স্থানান্তরে সময়ের ব্যবধান হবে ৩০ × ৪ = ১২০ মিনিট।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5e84236a0e0c35d731cdf64f37ecb9e6'),
(5653, 292, 'বাংলাদেশের ভৌগোলিক অবস্থান কোন দুটি গুরুত্বপূর্ণ সামুদ্রিক করিডরের মাঝখানে?', 'মালাক্কা ও হরমুজ প্রাণালী', NULL, 'হরমুজ ও পক প্রাণালী', NULL, 'সুয়েজ খাল ও জিব্রাল্টার প্রণালী', NULL, 'জিব্রাল্টার ও বসফরাস প্রণালী', NULL, 'A', 'মালাক্কা ও হরমুজ এই প্রণালী দুটির মধ্যবর্তী অংশে অবস্থিত দেশগুলো হচ্ছে ইন্দোনেশিয়া, মালয়েশিয়া, সিঙ্গাপুর, থাইল্যান্ড, মিয়ানমার, ভারত, বাংলাদেশ, শ্রীলঙ্কা, পাকিস্তান, ওমান ও ইরান।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd88d4b5c8fb835b19d93755c51be342a'),
(5654, 328, 'হিমালয় পর্বতমালার উদ্ভব কোন দুটি টেকটোনিক প্লেটের সংঘর্ষে হয়েছে?', 'ইউরেশিয়ান ও আফ্রিকান', NULL, 'ইন্দোঅস্ট্রেলিয়ান ও ইউরেশিয়ান', NULL, 'আমেরিকান ও ইউরেশিয়ান', NULL, 'প্যাসিফিক ও ইন্দোঅস্ট্রেলিয়ান', NULL, 'B', 'ভূতাত্ত্বিক গবেষণা অনুসারে প্রায় ৫ কোটি বছর আগে ভারত মহাসাগরের তলদেশসহ ভারতীয় উপমহাদেশ ছিল ইন্দো-অস্ট্রেলিয়ান প্লেটের অংশ। পরবর্তীতে ইন্দো-অস্ট্রেলিয়ান প্লেট হতে ইন্ডিয়ান প্লেট ও অস্ট্রেলিয়ান প্লেটের সৃষ্টি হয় এবং ইন্ডিয়ান প্লেট ও ইউরেশিয়ান প্লেটের সংঘর্ষে হিমালয় পর্বতের সৃষ্টি হয়।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4b2ea1d1366513d8af1e6e4fbee72e2f'),
(5655, 312, 'বায়ুমণ্ডলের কোন স্তরে ওজোন গ্যাসের স্তর অবস্থান করে?', 'ট্রপোমণ্ডল', NULL, 'থার্মোমণ্ডল', NULL, 'স্ট্র্যাটোমণ্ডল', NULL, 'মেসোমণ্ডল', NULL, 'C', 'ট্রপোবিরতির উপরের দিকে প্রায় ৫০ কি.মি. পর্যন্ত স্ট্র্যাটোমণ্ডল অবস্থিত। ওজোন গ্যাসের প্রায় ৯০% এই স্ট্র্যাটোমণ্ডলে অবস্থিত।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4bcc00de0ff0efbb1863de101373fa11'),
(5656, 300, 'ভূতাত্বিক গঠন অনুযায়ী বাংলাদেশের কোন অঞ্চলে সবচেয়ে পুরাতন শিলা গঠন পাওয়া যায়?', 'সিলেট', NULL, 'দিনাজপুর', NULL, 'পার্বত্য চট্টগ্রাম', NULL, 'মধ্যভাগের উচ্চভূমি', NULL, 'B', 'বাংলাদেশের সবচেয়ে পুরাতন শিলা গঠন পাওয়া যায় দিনাজপুর, নওগাঁ ও রাজশাহী জেলায় যা প্রাক্-ক্যাম্ব্রিয়ান যুগের গ্রানাইট ও গনাইস জাতীয় শিলা দিয়ে গঠিত; যেগুলোর আনুমানিক বয়স প্রায় ১০০০ মিলিয়ন বছর।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8b5ae7cb00baaa868dc58e13943667bf'),
(5657, 300, 'কনরাড বিযুক্তি ভূ-অভ্যন্তরের কোন স্তরসমূহের মাঝে অবস্থান করে?', 'সিয়াল ও সিমা', NULL, 'অশ্বমণ্ডল ও গুরুমণ্ডল', NULL, 'গুরুমণ্ডল ও কেন্দ্রমণ্ডল', NULL, 'সিমা ও অশ্বমণ্ডল', NULL, 'A', 'ভূপৃষ্ঠ থেকে কেন্দ্র পর্যন্ত যেখানে যেখানে ভূমিকম্প তরঙ্গের গতিবেগ পরিবর্তিত হয়, সে স্থানগুলোকে বিযুক্তি রেখা বলে। সিয়াল গঠিত হয় সিলিকা ও অ্যালুমিনিয়াম দ্বারা এবং সিমা গঠিত হয় সিলিকা ও ম্যাগনেশিয়াম দ্বারা। যে সীমান্তে সিয়াল ও সিমা এর ঘনত্বের পরিবর্তন ঘটে, সেটিই কনরাড বিযুক্তি রেখা।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a8ca21684e16725ff2d1dac4892b0582'),
(5658, 307, 'বাংলাদেশের উত্তর পশ্চিমাঞ্চলের প্রধান খনিজ সম্পদ কোনটি?', 'চুনাপাথর', NULL, 'কাঁচবালি', NULL, 'কয়লা', NULL, 'খনিজ লবণ', NULL, 'C', 'বাংলাদেশে এখন পর্যন্ত আবিষ্কৃত কয়লা ক্ষেত্র হচ্ছে ৫টি। এগুলো হলো জামালগঞ্জ, খালাসপীর, ফুলবাড়ী, দীঘিপাড়া ও বড়পুকুরিয়া। এই ক্ষেত্রগুলোতে প্রাপ্ত কয়লার মজুদ প্রায় ৭,৮২৩ মিলিয়ন টন। সবকটি কয়লা ক্ষেত্রই বাংলাদেশের উত্তর-পশ্চিমাঞ্চলের রংপুর, দিনাজপুর ও জয়পুরহাট জেলায় অবস্থিত।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9526ced7fc9b507bf3844139458d47a5'),
(5659, 314, 'এল নিনো বাংলাদেশ ও দক্ষিণ পূর্ব এশিয়ার আঞ্চলিক আবহাওয়ায় কীভাবে প্রভাব ফেলে?', 'শীতকালীন তাপমাত্রা বৃদ্ধি', NULL, 'বর্ষার বৃষ্টিপাতের ধরনে অনিয়ম সৃষ্টি করে', NULL, 'গ্রীষ্মকালীন তাপমাত্রা কমায়', NULL, 'ঘূর্ণিঝড় বৃদ্ধি পায়', NULL, 'B', 'শক্তিশালী এল নিনোর প্রভাবে বিশ্বের অনেক অঞ্চলের তাপমাত্রা ৪২° সেলসিয়াসের উপরে উঠে গেছে এবং বাংলাদেশে ইতিমধ্যে ৪০° সেলসিয়াস ছাড়িয়েছে, যা গ্রীষ্মকালীন তাপমাত্রা বৃদ্ধিকে নির্দেশ করে। এল নিনোর বছরগুলোতে গঙ্গা-মেঘনা-ব্রহ্মপুত্র অববাহিকায় অনিয়মিত বৃষ্টিপাত ঘটে, ফলে খরা দেখা দেয়। উদাহরণ ১৯৮২-৮৩ ও ১৯৯৭ সালের খরা। এল নিনোর বছরগুলোতে অনিয়মিত বৃষ্টিপাতের কারণে বাংলাদেশে মারাত্মক পানি সংকট দেখা দেয়।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1bbf764272ae9e7c98bc3edd07be91d4'),
(5660, 332, 'বাংলাদেশের দুর্যোগ ব্যবস্থাপনা আইন কবে প্রণীত হয়?', '২০০৫', NULL, '২০০৮', NULL, '২০১২', NULL, '২০১৫', NULL, 'C', 'বাংলাদেশের দূর্যোগ ব্যবস্থাপনা আইন প্রণীত হয় ২৪ সেপ্টেম্বর, ২০১২ সালে।', NULL, 16, '47th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '63e724f9d3d6c09445e0fa54c5c41e8f'),
(5661, 324, 'ঘূর্ণিঝড় সিডর ও আইলা বাংলাদেশে আঘাত হানে ___ এবং ____ সালে।', '২০০৭, ২০০৮', NULL, '২০০৮, ২০০৯', NULL, '২০০৭, ২০০৯', NULL, '২০০৭, ২০০৬', NULL, 'C', 'ঘূর্ণিঝড় সিডর ও আইলা দুটিই বাংলাদেশে সংঘটিত প্রাকৃতিক দুর্যোগ। সিডর বাংলাদেশে আঘাত হানে ১৫ নভেম্বর, ২০০৭ এবং আইলা আঘাত হানে ২৫ মে, ২০০৯ তারিখে। দুটিই ছিল অত্যন্ত বিধ্বংসী ও প্রলয়ংকরী ঘূর্ণিঝড়।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'acfffefb9a200958bcb3df20e53d66bd'),
(5662, 328, 'এভারেস্ট শৃঙ্গের তিব্বতী ও চীনা নাম কী কী?', 'দালাইলামা এবং চিংলু', NULL, 'চোমোলাংমা এবং কোমোলাংমা', NULL, 'কোমোলাংমা এবং চিংলু', NULL, 'চোমোলাংমা এবং এলবার্গ', NULL, 'B', 'এভারেস্ট শৃঙ্গের তিব্বতী ও চীনা নাম যথাক্রমে চোমোলাংমা এবং কোমোলাংমা। তিব্বতী নাম: এভারেস্টের তিব্বতী নাম হলো মোলাংমা। এর অর্থ হলো বিশ্বের জননী বা তুষারের দেবী। চীনা নাম: চীনারা তিব্বতী নামের অনুকরণেই এভারেস্ট শৃঙ্গকে ঝুয়ুলাংমা ফেং বা সংক্ষেপে কোমোলাংমা বলে ডাকে।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fab268e4e0870aac683c437fe6c018e7'),
(5663, 333, 'দুর্যোগ ব্যবস্থাপনার প্রথম ধাপ কোনটি?', 'উদ্ধার', NULL, 'পুনর্বাসন', NULL, 'পুনর্গঠন', NULL, 'প্রস্তুতি', NULL, 'D', 'দুর্যোগ ব্যবস্থাপনার প্রথম ও প্রধান ধাপ হলো দুর্যোগ প্রস্তুতি। এই পর্যায়ে দুর্যোগ আসার আগেই ঝুঁকির ম্যাপিং, সতর্কবার্তা ব্যবস্থা, সচেতনতা বৃদ্ধি এবং উদ্ধার তৎপরতার জন্য প্রয়োজনীয় পূর্ব-পরিকল্পনা ও প্রস্তুতি গ্রহণ করা হয়। এটি দুর্যোগের ক্ষয়ক্ষতি কমিয়ে আনতে মূল ভূমিকা পালন করে।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3badcd09cd34d0a62f45c012cbeac93a'),
(5664, 295, 'ভঙ্গিল পর্বত, আগ্নেয় পর্বত ও স্তূপ পর্বতের উদাহরণ যথাক্রমে–', 'রকি, ভিসুভিয়াস, ব্ল্যাক ফরেস্ট', NULL, 'হিমালয়, আল্পস, রকি', NULL, 'হিমালয়, রকি, বিন্দা', NULL, 'আল্পস, হেনরি, ফুজিয়ামা', NULL, 'A', 'ভঙ্গিল পর্বত, আগ্নেয় পর্বত ও স্তূপ পর্বতের উদাহরণ যথাক্রমে রকি, ভিসুভিয়াস, ব্ল্যাক ফরেস্ট। ভঙ্গিল পর্বত (Fold Mountain): উত্তর আমেরিকার রকি পর্বতমালা একটি প্রধান ভঙ্গিল পর্বত। এছাড়া হিমালয় এবং আল্পসও এই শ্রেণির অন্তর্গত। আগ্নেয় পর্বত (Volcanic Mountain): ইতালির ভিসুভিয়াস একটি সুপরিচিত আগ্নেয় পর্বত, যা আগ্নেয়গিরির অগ্নুৎপাতের ফলে সঞ্চিত লাভা ও ছাই থেকে তৈরি হয়েছে। স্তূপ পর্বত (Block Mountain): জার্মানির ব্ল্যাক ফরেস্ট হলো স্তূপ পর্বতের একটি আদর্শ উদাহরণ।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9b42578a57d7fe9e7940a6d5e8d7bd0f'),
(5665, 312, 'বায়ুমণ্ডল ও মহাশূন্যের মধ্যবর্তী রেখাটির নাম কী?', 'বিষুবরেখা', NULL, 'ট্রপোপজ', NULL, 'কারমান লাইন', NULL, 'কলোরাডো লাইন', NULL, 'C', 'বায়ুমণ্ডল ও মহাশূন্যের মধ্যবর্তী রেখাটির নাম কারমান লাইন (Kármán line)। এটি পৃথিবীর সমুদ্রপৃষ্ঠ থেকে ১০০ কিলোমিটার (প্রায় ৬২ মাইল) উচ্চতায় অবস্থিত একটি কাল্পনিক সীমানা।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ba89aab1cbca4c92b7641aa5ba85062f'),
(5666, 387, 'নবায়নযোগ্য শক্তি উৎসের একটি উদাহরণ হলো–', 'পারমাণবিক জ্বালানি', NULL, 'পীট কয়লা', NULL, 'ফুয়েল সেল', NULL, 'সূর্য', NULL, 'D', 'যেসব শক্তি উৎস অফুরন্ত এবং বারবার করা যায় তাদেরকে নবায়নযোগ্য শক্তি উৎস বলা হয়। সূর্য, পানি, বায়ু নবায়নযোগ্য শক্তির উৎস। অন্যদিকে যে শক্তির উৎস অফুরন্ত নয় এবং বারবার ব্যবহারের ফলে এক সময় নিঃশেষিত হয়ে যায় সেগুলোকে অনবায়নযোগ্য শক্তি বলে। কয়লা, গ্যাস, তেল, পারমাণবিক জ্বালানি ইত্যাদি অনবায়নযোগ্য শক্তির উৎস।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '47b1fa6bf4b79e5e7554c4d375eca5f0'),
(5667, 343, 'প্রেসার কুকারে রান্না তাড়াতাড়ি হয় কারণ–', 'রান্নার জন্য তাপ নয় চাপও কাজে লাগে', NULL, 'বদ্ধ পাত্রে তাপ সংরক্ষিত হয়', NULL, 'উচ্চচাপে তরলের স্ফুটনাংক বৃদ্ধি পায়', NULL, 'সঞ্চিত বাষ্পের তাপ রান্নায় সহায়ক', NULL, 'C', 'বায়ুর চাপ যতো বৃদ্ধি পায় পানি বা তরলের স্ফুটনাঙ্ক ততো বৃদ্ধি পায়। প্রেসার কুকারে বাষ্পের বহির্গমন নিয়ন্ত্রণ করার মাধ্যমে অভ্যন্তরীণ চাপ বৃদ্ধির ফলে পানির স্ফুটনাঙ্ক বৃদ্ধি পায়। এ কারণে প্রেসার কুকারে রান্না তাড়াতাড়ি হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a676b12a87a65ec6eacccb4736678afe'),
(5668, 344, 'যে তিনটি মুখ্য বর্ণের সমন্বয়ে অন্যান্য বর্ণ সৃষ্টি করা যায় সেগুলো হলো–', 'লাল, হলুদ, নীল', NULL, 'লাল, কমলা, বেগুনী', NULL, 'হলুদ, সবুজ, নীল', NULL, 'লাল, নীল, সবুজ', NULL, 'D', 'তিনটি মৌলিক রং হচ্ছে লাল, নীল (আসমানী) ও সবুজ। এই রংগুলোর সমন্বয়ে গঠিত হয় অন্যান্য রং।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6905ea825c966f73d37dc61237f6dda7'),
(5669, 371, 'ভৌগলিকভাবে গুরুত্বপূর্ণ যে কাল্পনিক রেখাটি বাংলাদেশের উপর দিয়ে গিয়েছে তা হলো–', 'মূল মধ্যরেখা', NULL, 'কর্কটক্রান্তি রেখা', NULL, 'মকরক্রান্তি রেখা', NULL, 'আন্তর্জাতিক তারিখ রেখা', NULL, 'B', 'নিরক্ষরেখার ২৩.৫° উত্তর অক্ষাংশকে কর্কটক্রান্তি এবং ২৩.৫° দক্ষিণ অক্ষাংশকে মকরক্রান্তি রেখা বলে। বাংলাদেশের প্রায় মধ্যভাগ দিয়ে কর্কটক্রান্তি রেখা গেছে। লন্ডনের গ্রিনিচ মান মন্দিরের ওপর দিয়ে উত্তরমেরু ও দক্ষিণ মেরু পর্যন্ত যে মধ্যরেখা অতিক্রম করেছে তাকে মূল মধ্যরেখা বলা হয়। ১৮০° দ্রাঘিমাংশ বরাবর এক কাল্পনিক রেখাকে আন্তর্জাতিক তারিখ রেখা বলা হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6ad4ed26c535a1cb4b0c1a5ba37604a3'),
(5670, 359, 'মাছ অক্সিজেন নেয়–', 'মাঝে মাঝে পানির উপর নাক তুলে', NULL, 'পানিতে অক্সিজেন ও হাইড্রোজেন বিশ্লিষ্ট করে', NULL, 'পটকার মধ্যে জমানো বাতাস হতে', NULL, 'পানির মধ্যে দ্রবীভূত বাতাস হতে', NULL, 'D', 'সাধারণত মাছ ফুলকার সাহায্যে পানিতে দ্রবীভূত অক্সিজেনের মাধ্যমে শ্বাসকার্য চালায়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c9716de0fe60d48900f1d961174801ff'),
(5671, 360, 'কচুশাক বিশেষভাবে মূল্যবান যে উপাদানের জন্য তা হলো–', 'ভিটামিন-\'এ\'', NULL, 'ভিটামিন-\'সি\'', NULL, 'লৌহ', NULL, 'ক্যালসিয়াম', NULL, 'C', 'কচুশাকের উল্লেখযোগ্য উপাদান লৌহ। তাছাড়া একে ভিটামিন-এ, ক্যালসিয়াম অক্সালেট এবং অন্যান্য ভিটামিন ও খনিজ পদার্থ রয়েছে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a3c42472e960f393f62ad1647ca3014a'),
(5672, 346, 'সাধারণ ড্রাইসেলে ইলেকট্রোড হিসাবে থাকে–', 'তামার দণ্ড ও দস্তার দণ্ড', NULL, 'তামার পাত ও দস্তার পাত', NULL, 'কার্বন দণ্ড ও দস্তার কৌটা', NULL, 'তামার দণ্ড ও দস্তার কৌটা', NULL, 'C', 'ড্রাইসেলে উপাদান হিসেবে থাকে অ্যামোনিয়াম ক্লোরাইডের পেষ্ট, কার্বন দণ্ড, দস্তার তৈরি চোঙাকৃতির পাত্র, ম্যাঙ্গানিজ ডাই অক্সাইড, কয়লার গুড়ো, পিতলের টুপি এবং শক্ত কাগজ। এতে ইলেকট্রোড হিসেবে কার্বন দণ্ড ও দস্তার তৈরি চোঙাকৃতি পাত্র ব্যবহৃত হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c0b2b685d8d61edb654ad667b6923321'),
(5673, 346, 'দূরের বিদ্যুৎ উৎপাদন কেন্দ্র হতে বিদ্যুৎ নিয়ে আসতে হলে হাইভোল্টেজ ব্যবহার করার কারণ–', 'এতে বিদ্যুতের অপচয় কম হয়', NULL, 'এতে কমে গিয়েও প্রয়োজনীয় ভোল্টেজ বজায় থাকে', NULL, 'অধিক বিদ্যুৎ প্রবাহ পাওয়া যায়', NULL, 'প্রয়োজনমতো ভোল্টজ কমিয়ে ব্যবহার করা যায়', NULL, 'A', 'বৈদ্যুতিক তারের রোধের জন্য উচ্চ ভোল্টেজ ব্যবহার করে দূরবর্তী স্থানে বিদ্যুৎ নিয়ে আসা হয়। এতে বিদ্যুতের অপচয় কম হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7f4e3f1c8aee16b857d994ac63be7eaa'),
(5674, 337, 'সংকর ধাতু পিতলের উপাদান হলো–', 'তামা ও টিন', NULL, 'তামা ও দস্তা', NULL, 'তামা ও নিকেল', NULL, 'তামা ও সীসা', NULL, 'B', 'সংকর ধাতু পিতলে ৬৫% তামা এবং ৩৫% দস্তা থাকে। তামা ও টিনের সংকর ধাতু হলো ব্রোঞ্জ।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2c81537f7ca0c4e037f0e46c28371a1c'),
(5675, 358, 'আমাদের দেহকোষ রক্ত হতে গ্রহণ করে–', 'অক্সিজেন ও গ্লুকোজ', NULL, 'অক্সিজেন ও রক্তের আমিষ', NULL, 'ইউরিয়া ও গ্লুকোজ', NULL, 'এমাইনো এসিড ও কার্বন ডাইঅক্সাইড', NULL, 'A', 'রক্তের মাধ্যমে অক্সিজেন, গ্লুকোজ এবং অন্যান্য পুষ্টি উপাদান দেহের সকল কোষে স্থানান্তরিত হয়। লোহিত রক্ত কণিকার হিমোগ্লোবিন অক্সিজেন ও কার্বন-ডাই-অক্সাইড পরিবহন করে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '48586c8725c235851cf4eb882f529acc'),
(5676, 341, 'পৃথিবীর ঘূর্ণনের ফলে আমরা ছিটকিয়ে পড়ি না–', 'মহাকর্ষ বলের জন্য', NULL, 'মাধ্যাকর্ষণ বলের জন্য', NULL, 'আমরা স্থির থাকার জন্য', NULL, 'পৃথিবীর সঙ্গে আমাদের আবর্তনের জন্য', NULL, 'B', 'যে বল দ্বারা পৃথিবী সবকিছুকেই তার কেন্দ্রের দিকে টানে, তাকে মাধ্যাকর্ষণ বল বলে। এই মাধ্যাকর্ষণের জন্যে সবকিছু পৃথিবীর সঙ্গে লেগে থাকে এবং ছিটকে মহাশূন্যে যায় না।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd15aa871a723b922a1845b85a601ae70'),
(5677, 387, 'নিচের কোনটি জীবাশ্ম জ্বালানি নয়?', 'পেট্রোলিয়াম', NULL, 'কয়লা', NULL, 'প্রাকৃতিক গ্যাস', NULL, 'বায়োগ্যাস', NULL, 'D', 'কোটি কোটি বছর পূর্বে গাছ-গাছড়া, জীবজন্তু প্রভৃতি ভূমিকম্পসহ নানা প্রাকৃতিক বিপর্যয়ের ফলে ভূ-অভ্যন্তরে চাপা পড়ে যায়। ভূ-অভ্যন্তরের প্রচণ্ড চাপ ও তাপে এসব পদার্থের জৈব বিধ্বংসী পাতন ঘটে এবং পেট্রোলিয়াম, কয়লা ও প্রাকৃতিক গ্যাস আকারে ভূ-অভ্যন্তরে অবস্থান করে। এগুলোকে জীবাশ্ম জ্বালানী বলে। বায়োগ্যাস জীবাশ্ম জ্বালানি নয় কারণ এটি গাজন প্রক্রিয়ায় তৈরি করা হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd2ebcd5fa5e84aaf0c5fe647dc7bfcc1'),
(5678, 346, 'বৈদ্যুতিক মটর এমন একটি যন্ত্রকৌশল, যা–', 'তাপ শক্তিকে যান্ত্রিক শক্তিতে রূপান্তরিত করে', NULL, 'তাপ শক্তিকে তড়িৎ শক্তিতে রূপান্তরিত করে', NULL, 'যান্ত্রিক শক্তিকে তড়িৎ শক্তিতে রূপান্তরিত করে', NULL, 'তড়িৎ শক্তিকে যান্ত্রিক শক্তিতে রূপান্তরিত করে', NULL, 'D', 'যে যন্ত্র তড়িৎ শক্তিকে যান্ত্রিক শক্তিতে রূপান্তরিত করে তাকে বৈদ্যুতিক মটর বলে এবং যান্ত্রিক শক্তিকে তড়িৎ শক্তিতে রূপান্তর কারী যন্ত্রকে জেনারেটর বলে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '148fc56f8e534998cbe1213e741fb6d3'),
(5679, 342, 'যে বায়ু সর্বদাই উচ্চচাপ অঞ্চল হতে নিম্নচাপ অঞ্চলের দিকে প্রবাহিত হয়, তাকে বলা হয়–', 'আয়ন বায়ু', NULL, 'প্রত্যয়ন বায়ু', NULL, 'মৌসুমী বায়ু', NULL, 'নিয়ত বায়ু', NULL, 'D', 'পৃথিবীর চাপ বলয় দ্বারা নিয়ন্ত্রিত হয়ে বায়ু উচ্চচাপ অঞ্চল হতে নিম্নচাপ অঞ্চলে প্রবাহিত হওয়ার সময় উত্তর গোলার্ধে ডানদিকে এবং দক্ষিণ গোলার্ধে বামদিকে বেঁকে যায়। এভাবে সারা বছর একই দিকে নিয়মিতভাবে যে বায়ু প্রবাহিত হয় তাকে নিয়ত বায়ু বলে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1a81002b2bbaecd76fe3b6126ad42c1a'),
(5680, 353, 'জলজ উদ্ভিদ সহজে ভাসতে পারে, কারণ–', 'এরা অনেক ছোট হয়', NULL, 'এদের কাণ্ডে অনেক বায়ু কুঠুরী থাকে', NULL, 'এরা পানিতে জন্মে', NULL, 'এদের পাতা অনেক কম থাকে', NULL, 'B', 'জলজ উদ্ভিদের কাণ্ডে প্রচুর পরিমাণে বায়ু কুঠুরী রয়েছে, যেগুলোতে বায়ু থাকায় জলজ উদ্ভিদ সহজেই পানির উপর ভেসে থাকতে পারে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f6f6c02d429e7644e9a43b3f9e4eaad9'),
(5681, 355, 'ধানের ফুলে পরাগ সংযোগ ঘটে–', 'বাতাসের সাহায্যে ঝরে পড়ে', NULL, 'পাতা দ্বারা স্থানান্তরিত হয়ে', NULL, 'কীটপতঙ্গের সাহায্যে', NULL, 'ফুলে ফুলে সংস্পর্শে', NULL, 'A', 'ধান বায়ুপরাগী উদ্ভিদ। দিনের প্রথম ভাগে ধানের স্পাইকলেট উন্মুক্ত হয়। এ অবস্থায় পরাগরেণু গর্ভমুণ্ডের উপর ঝরে পড়ে এবং প্রকৃতিগতভাবেই পরাগায়ন ঘটে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '096a1125c63ad0521f5c51c2c024749d'),
(5682, 342, 'সমুদ্রপৃষ্ঠে বায়ুর চাপ প্রতি বর্গ সেন্টিমিটারে–', '১০ কি. মি.', NULL, '১০ নিউটন', NULL, '২৭ কি. মি.', NULL, '৫ কি. মি.', NULL, 'B', 'যে কোনো পদার্থের মত বায়ুর নিজস্ব ওজন আছে। বায়ুর এই ওজনজনিত কারণে যে চাপের সৃষ্টি হয় তাই বায়ুর চাপ। সমুদ্রপৃষ্ঠে বায়ুর চাপ প্রতি বর্গ সেন্টিমিটারে ১০ নিউটন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c5ebde3a5273d4c16d61fb77d7241a9d'),
(5683, 353, 'সর্বপ্রথমে যে উফশি ধান এ দেশে চালু হয়ে এখনো বর্তমান রয়েছে তা হলো–', 'ইরি-৮', NULL, 'ইরি-১', NULL, 'ইরি-২০', NULL, 'ইরি-৩', NULL, 'A', 'ইরি-৮ নামক \'উফশি\' অর্থাৎ উচ্চ ফলনশীল ধান বাংলাদেশে প্রথম চালু হয়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5ee58edc229c0d7136a9926d27fd2dee'),
(5684, 337, 'ইস্পাত সাধারণ লোহা থেকে ভিন্ন। কারণ এতে–', 'বিশেষ ধরনের আকরিক ব্যবহার করা হয়েছে', NULL, 'সুনিয়ন্ত্রিত পরিমাণ কার্বন রয়েছে', NULL, 'সুনিয়ন্ত্রিত পরিমাণ কার্বন রয়েছে', NULL, 'সব বিজাতীয় দ্রব্য বের করে দেয়া হয়েছে', NULL, 'B', 'লোহার সঙ্গে সুনিয়ন্ত্রিত মাত্রার কার্বন মিশিয়ে ইস্পাত তৈরি হয়। এতে ০.১৫%-১.৫% কার্বন থাকে। ফলে এর স্থিতিস্থাপকতা বৃদ্ধি পায়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd742f49a601e22e0bf43d775d2ee7d3f'),
(5685, 337, 'প্রাকৃতিক গ্যাসের প্রধান উপাদান হলো–', 'নাইট্রোজেন গ্যাস', NULL, 'মিথেন', NULL, 'হাইড্রোজেন গ্যাস', NULL, 'কার্বন মনোক্সাইড', NULL, 'B', 'প্রাকৃতিক গ্যাসের উপাদান হলো: মিথেন ৮০% –৯০%, ইথেন ১৩%, প্রোপেন ৩%। এছাড়া বিউটেন, ইথিলিন ও নাইট্রোজেন কিছু পরিমাণ থাকে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '981a41799475a81adae15542cd4deb06'),
(5686, 336, 'মৌলিক পদার্থের ক্ষুদ্রতম কণা যা রাসায়নিক প্রক্রিয়ায় অংশগ্রহণ করে তাকে বলা হয়–', 'পরমাণু', NULL, 'ইলেকট্রন', NULL, 'অণু', NULL, 'প্রোটন', NULL, 'A', 'মৌলিক পদার্থের ক্ষুদ্রতম কণা যা রাসায়নিক বিক্রিয়ায় অংশগ্রহণ করে তাকে পরমাণু বলে। পরমাণুকে ভাঙ্গলে ইলেকট্রন, প্রোটন ও নিউট্রন পাওয়া যায়। \'অণু\' রাসায়নিক প্রক্রিয়ায় অংশগ্রহণ করে না। অণুকে ভাঙ্গলে পরমাণু পাওয়া যায়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0cddb243fe398f4ce057da94ac53ad8f'),
(5687, 342, 'সমুদ্র স্রোতের অন্যতম কারণ–', 'বায়ু প্রবাহের প্রভাব', NULL, 'সমুদ্রের পানিতে তাপ পরিচালনা', NULL, 'সমুদ্রের পানিতে ঘনত্বের তারতম্য', NULL, 'সমুদ্রের ঘূর্ণিঝড়', NULL, 'A', 'সমুদ্র স্রোতের কারণগুলো হচ্ছে বায়ু প্রবাহ, উষ্ণতার তারতম্য, লবণাক্ততার তারতম্য, বাষ্পীভবনের তারতম্য, গভীরতার তারতম্য, পৃথিবীর আবর্তন এবং মূলভাগের অবস্থান।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1cfa9340ac7ef8c89bd6c6e068fc05d9'),
(5688, 340, 'কাজ করার সামর্থ্যকে বলে–', 'ক্ষমতা', NULL, 'কাজ', NULL, 'শক্তি', NULL, 'বল', NULL, 'C', 'শক্তির এস.আই. একক জুল। কাজ করার হারকে ক্ষমতা বলে। এর এস. আই. একক ওয়াট। কোন বস্তুর উপর প্রযুক্ত বল ও তার অভিমুখে সরণের গুণফলকে কাজ বলে। এর এস. আই. একক জুল। যা কোনো স্থির বস্তুর উপর ক্রিয়া করে তাকে গতিশীল করে বা করতে চায় কিংবা গতিশীল বস্তুর উপর ক্রিয়া করে তার গতির পরিবর্তন করে বা করতে চায় তাকে বল বলে। এর এস. আই. একক নিউটন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c7bebf2ae3d5f26857dcee3f3f2573b7'),
(5689, 344, 'রংধনু সৃষ্টির বেলায় পানির কণাগুলো–', 'দর্পণের কাজ করে', NULL, 'আতষীকাচের কাজ করে', NULL, 'লেন্সের কাজ করে', NULL, 'প্রিজমের কাজ করে', NULL, 'D', 'সাদা রশ্মি প্রিজমের ভেতর দিয়ে বেরিয়ে আসার সময় বিভিন্ন বর্ণের রশ্মিতে ভেঙে যায় ও বর্ণালি সৃষ্টি হয়। পানির কণাগুলো রংধনু সৃষ্টির সময় প্রিজমের কাজ করে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f6170b50ca77a62ad19744cea7aba5ea'),
(5690, 337, 'কাচ তৈরির প্রধান কাঁচামাল হলো–', 'জিপসাম', NULL, 'বালি', NULL, 'সাজি মাটি', NULL, 'চুনাপাথর', NULL, 'B', 'সাধারণ কাচ বালি, সোডিয়াম কার্বনেট, চুনাপাথর প্রভৃতি গলিয়ে কাচ তৈরি করা হয়। বিশেষ গুণসম্পন্ন কাচে সোডিয়ামের পরিবর্তে থাকে সিসা, পটাসিয়াম, বেরিয়াম, কিংবা অন্য ধাতু। তবে কাচ তৈরির প্রধান উপাদান বালি।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e4de44a9fd431869a72144b9ecd18d95'),
(5691, 352, 'মানুষের ক্রোমোজোমের সংখ্যা কত?', '২৪ জোড়া', NULL, '২৬ জোড়া', NULL, '২৩ জোড়া', NULL, '২৫ জোড়া', NULL, 'C', 'মানুষের ক্রোমোজোম ২৩ জোড়া। এর মধ্যে ২২ জোড়া অটোজোম এবং ১ জোড়া সেক্স ক্রোমোজোম (পুরুষের ক্ষেত্রে XY এবং মহিলাদের ক্ষেত্রে XX)।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'def7635f97fc7811a1ea45ed2d40f693'),
(5692, 387, 'সৌরকোষের বিদ্যুৎ রাতেও ব্যবহার করা সম্ভব যদি এর সঙ্গে থাকে–', 'ট্রান্সফরমার', NULL, 'জেনারেটর', NULL, 'স্টোরেজ ব্যাটারি', NULL, 'ক্যাপাসিটার', NULL, 'C', 'স্টোরেজ ব্যাটারির সাহায্যে দিনের সৌরশক্তিকে সঞ্চিত করে রাতে ব্যবহার করা যায়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '63b90cc9027cf5196b42e10f73e098df'),
(5693, 346, 'বৈদ্যুতিক পাখা ধীরে ধীরে ঘুরলে বিদ্যুৎ খরচ–', 'একই হয়', NULL, 'বেশি হয়', NULL, 'কম হয়', NULL, 'খুব কম হয়', NULL, 'A', 'রেগুলেটরের মাধ্যমে বৈদ্যুতিক পাখার বিদ্যুৎ সরবরাহ নিয়ন্ত্রণ করা হয়। যখন বৈদ্যুতিক পাখা ধীরে ঘুরানোর জন্য বিদ্যুৎ প্রবাহ কমানো হয় তখন অতিরিক্ত বিদ্যুৎ রেগুলেটরে তাপ সৃষ্টি করে। যার ফলে বৈদ্যুতিক পাখা ঘুরলেও বিদ্যুৎ খরচ একই হয় কারণ সবসময় বিদ্যুৎ প্রবাহ একই থাকে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c2adf4dfd9a54cf6f5e9a44eda700392'),
(5694, 344, 'শহরের রাস্তায় ট্রাফিক পুলিশ সাধারণত সাদা ছাতা ও সাদা জামা ব্যবহার করে থাকে কারণ–', 'সরকারি নির্দেশ', NULL, 'দূর থেকে চোখে পড়বে বলে', NULL, 'তাপ বিকিরণ থেকে বাঁচার জন্য', NULL, 'দেখতে সুন্দর লাগে', NULL, 'C', 'সাদা রঙ অন্যান্য রঙের চেয়ে তাপের বিকিরণ বেশি করে তাই সাদা ছাতা ও সাদা জামা ব্যবহৃত হয়। দূর থেকে চোখে পড়ার জন্য হলুদ বা লাল রঙ ব্যবহৃত হয়।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b64bea80391b060f7a03d2258730d21b');
