(5750, 335, 'পানির ছোট ফোঁটা পানির যে গুণের জন্য গোলাকৃতি হয়–', 'সান্দ্রতা', NULL, 'স্থিতিস্থাপকতা', NULL, 'প্লবতা', NULL, 'পৃষ্ঠটান', NULL, 'D', 'তরলের পৃষ্ঠটানের জন্য পানির ছোট ফোঁটা গোলাকৃতি হয়ে থাকে।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3cca34a0f8961db9a90e8f91d8334248'),
(5751, 368, 'মুক্তা হলো ঝিনুকের–', 'খোলসের টুকরা', NULL, 'চোখের মণি', NULL, 'প্রদাহের ফল', NULL, 'জমাট হরমোন', NULL, 'C', 'ঝিনুকের খোলসের অভ্যন্তরে কোনো শক্ত বস্তু প্রবেশ করলে ঐ স্থানে প্রদাহের সৃষ্টি হয় এবং ঐ বস্তুকে জড়িয়ে ঝিনুকের শরীর থেকে এক ধরনের পদার্থ নির্গত হয়, যা মুক্তায় রূপ নেয়।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cfcf7f9a8b64fbbf991246d2d6ac1d61'),
(5752, 368, 'বাংলাদেশের গবাদিপশুতে প্রথম ভ্রূণ বদল করা হয়–', '৫ মে, ১৯৯৪', NULL, '৬ এপ্রিল, ১৯৯৪', NULL, '৫ মে, ১৯৯৫', NULL, '৭ মে, ১৯৯৫', NULL, 'A', 'বাংলাদেশের গবাদিপশুতে প্রথম ভ্রূণ বদল করা হয় ৫ মে, ১৯৯৪ তারিখে।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4bc5a1f214375a114ffe0bea7ca7e099'),
(5753, 368, 'বাংলাদেশের একটি জীবন্ত জীবাশ্মের নাম–', 'রাজ কাঁকড়া', NULL, 'গন্ডার', NULL, 'পিপীলিকাভুক্ত ম্যানিস', NULL, 'স্নো লোরিস', NULL, 'A', 'জীবন্ত ফসিল হলো এমন কতগুলো জীব, দূর অতীতে জন্ম হলেও যাদের বংশধরেরা আজও পৃথিবীতে বেঁচে আছে। অথচ এদের সমসাময়িক ও সমগোত্রীয় সকল প্রাণীই বহু পূর্বে পৃথিবী থেকে বিলুপ্ত হয়েছে। বিবর্তনের ইতিহাসে এদের অঙ্গপ্রত্যঙ্গের কোনো পরিবর্তন হয়নি। যেমন- প্লাটিপাস, মাছের মধ্যে সিলাকান্থ, সরীসৃপেদের মধ্যে স্কেনোডন, উদ্ভিদ শ্রেণির মধ্যে ডিঙ্গো বাইলোবা ইত্যাদি। বাংলাদেশের জীবন্ত ফসিলের উদাহরণ হচ্ছে রাজ কাঁকড়া।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '05996bf60400ba88f0ca2955302da89b'),
(5754, 350, 'Natural protein-এর কোড নাম–', 'protein-P 53', NULL, 'protein-P 51', NULL, 'protein-P 49', NULL, 'protein-P 54', NULL, 'A', 'কার্বন, হাইড্রোজেন, নাইট্রোজেন ও অক্সিজেন দ্বারা গঠিত জটিল জৈব পদার্থ হচ্ছে প্রোটিন। এটি দেহকোষ গঠনসহ এনজাইম ও হরমোন তৈরিতে অংশগ্রহণ করে। Natural protein-এর কোড নাম হলো protein-P 53।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ba7675bb407af07b564e77681aec6f8'),
(5755, 387, 'বাংলাদেশে বিদ্যুৎ শক্তির উৎস–', 'খনিজ তেল', NULL, 'প্রাকৃতিক গ্যাস', NULL, 'পাহাড়ি নদী', NULL, 'উপরের সবগুলোই', NULL, 'D', 'দেশের বিভিন্ন বিদ্যুৎ উৎপাদন কেন্দ্রে প্রাকৃতিক গ্যাস ব্যবহার করে বিদ্যুৎ উৎপাদন করা হচ্ছে। তবে বেসরকারি ক্ষুদ্র বিদ্যুৎকেন্দ্রে খনিজ তেল ব্যবহার করা হয়। এছাড়া পাহাড়ি নদী থেকেও বিদ্যুৎ উৎপাদন সম্ভব।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5a50ec3ea4a378b460ae1fb7cbde5035'),
(5756, 380, 'Adult Cell ক্লোন করে যে ভেড়ার জন্ম হয়েছে তার নাম দেয়া হয়েছে–', 'শেলী', NULL, 'ডলি', NULL, 'মলি', NULL, 'নেলী', NULL, 'B', 'যুক্তরাজ্য বা গ্রেট ব্রিটেনের আওতাধীন স্কটল্যান্ডের এডিনবরার রোসলিন ইনস্টিটিউটের বিজ্ঞানীরা ১৯৯৬ সালের ৫ জুলাই ক্লোন ভেড়া ডলির জন্ম দেন। রোসলিন ইনস্টিটিউটের ভ্রূতত্ত্ববিদ ড. আয়ান উইলমুট ভেড়াটিকে ক্লোন করেন। ১৯৯৭ সালে ডলির জন্মের বিষয়টি ঘোষণা করা হয়।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b0443c11b5e487a089cdf228a468e7da'),
(5757, 380, 'Adult Cell ক্লোন করে কোন দেশে একটি ভেড়ার জন্ম হয়েছে?', 'যুক্তরাজ্যে', NULL, 'যুক্তরাষ্ট্রে', NULL, 'অস্ট্রেলিয়ায়', NULL, 'ফ্রান্সে', NULL, 'A', 'যুক্তরাজ্য বা গ্রেট ব্রিটেনের আওতাধীন স্কটল্যান্ডের এডিনবরার রোসলিন ইনস্টিটিউটের বিজ্ঞানীরা ১৯৯৬ সালের ৫ জুলাই ক্লোন ভেড়া ডলির জন্ম দেন। রোসলিন ইনস্টিটিউটের ভ্রূতত্ত্ববিদ ড. আয়ান উইলমুট ভেড়াটিকে ক্লোন করেন। ১৯৯৭ সালে ডলির জন্মের বিষয়টি ঘোষণা করা হয়।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5c871652acfa78664350f40502c5edd2'),
(5758, 337, 'সবচেয়ে শক্ত বস্তু কোনটি?', 'হীরা', NULL, 'গ্রানাইট পাথর', NULL, 'পিতল', NULL, 'ইস্পাত', NULL, 'A', 'হীরা হলো পৃথিবীর সবচেয়ে শক্ত প্রাকৃতিক বস্তু। এটি কার্বনের একটি রূপভেদ (অ্যালোট্রপ) যা অত্যন্ত শক্তিশালী সমযোজী বন্ধনের জন্য পরিচিত। মোহস স্কেলে হীরার কঠিনতা ১০, যা সর্বোচ্চ।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '060daf5e5ee8b9cfb07ea2dec9fdb2a4'),
(5759, 356, 'কোনটি স্তন্যপায়ী প্রাণী নয়?', 'হাতি', NULL, 'কুমির', NULL, 'তিমি', NULL, 'বাদুর', NULL, 'B', 'যে সকল প্রাণী বাচ্চা প্রসব করে এবং বাচ্চা মায়ের দুধ পান করে বড় হয় তাকে স্তন্যপায়ী প্রাণী বলে। হাতি, তিমি, বাদুর স্তন্যপায়ী প্রাণী। কুমির ডিম দেয় এবং এটি সরীসৃপ (Reptile) শ্রেণির প্রাণী।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '543a02e4622aebd9dbfe2060f726f60b'),
(5760, 346, 'বিদ্যুৎকে সাধারণ মানুষের কাজে লাগানোর জন্য কোন বৈজ্ঞানিকের অবদান সবচেয়ে বেশি?', 'বেঞ্জামিন ফ্রাঙ্কলিন', NULL, 'আইজ্যাক নিউটন', NULL, 'টমাস এডিসন', NULL, 'ভোল্টা', NULL, 'C', 'মার্কিন বিজ্ঞানী টমাস আলভা এডিসন বিজ্ঞানকে সাধারণ মানুষের কাজে লাগানোর জন্য বিভিন্ন ব্যবহারিক যন্ত্র আবিষ্কার করেন। যেমন- বৈদ্যুতিক বাল্ব, সিনেমাস্কোপ, ফনোগ্রাফ ইত্যাদি।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '38d084bed9d47349a0b94a0e21dd0482'),
(5761, 363, 'বহুমূত্র রোগে কোন হরমোনের দরকার?', 'ইনসুলিন', NULL, 'থাইরক্সিন', NULL, 'এন্ড্রোজেন', NULL, 'এস্ট্রোজেন', NULL, 'A', 'অগ্ন্যাশয়ের বিটা কোষ থেকে নিঃসৃত ইনসুলিন হরমোন রক্তে গ্লুকোজের পরিমাণ কমায়। রক্তে এই ইনসুলিন হরমোন কমে গেলে গ্লুকোজের পরিমাণ বেড়ে যায় যাকে হাইপারগ্লাইসেমিয়া বলে। এর ফলে ঘন ঘন ক্ষুধা, পিপাসা ও প্রস্রাবের চাপ লাগে যাকে ডায়াবেটিস বা বহুমূত্র রোগ বলে। এই রোগের জন্য ইনসুলিন হরমোন চামড়ার নিচে দেওয়া হয়।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1eec593e65cc93e57e23b15c191da66f'),
(5762, 387, 'গ্রিন হাউজ ইফেক্টের পরিণতিতে বাংলাদেশের সবচেয়ে গুরুতর ক্ষতি কি হবে?', 'উত্তাপ অনেক বেড়ে যাবে', NULL, 'বৃষ্টিপাত কমে যাবে', NULL, 'নিম্নভূমি নিমজ্জিত হবে', NULL, 'সাইক্লোনের প্রবণতা বাড়বে', NULL, 'C', 'গ্রিন হাউজের প্রভাবে পৃথিবীর তাপমাত্রা বৃদ্ধি পাচ্ছে। এর প্রভাবে আগামী ২০৩০ সাল নাগাদ বায়ুমণ্ডলে তাপমাত্রা বৃদ্ধিকারী গ্যাসের পরিমাণ দ্বিগুণ বৃদ্ধি পাবে। এর ফলে মেরু অঞ্চলের বরফ গলে যাবে এবং সমুদ্রপৃষ্ঠের উচ্চতা বৃদ্ধি পাবে। ফলে বাংলাদেশের সমুদ্র উপকূলবর্তী অঞ্চলের অধিকাংশ নিমজ্জিত হবে।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '14f62b415892f0d8caf58f9b9a1ff750'),
(5763, 387, 'ওজোন স্তরের ফাটলের জন্য মুখ্যত দায়ী কোন গ্যাস?', 'ক্লোরোফ্লোরো কার্বন', NULL, 'কার্বন মনোক্সাইড', NULL, 'কার্বন ডাইঅক্সাইড', NULL, 'মিথেন', NULL, 'A', 'ক্লোরোফ্লোরো কার্বন বায়ুমণ্ডলের ওজোনস্তরে পৌঁছে ওজোনের সঙ্গে বিক্রিয়া করে অক্সিজেনে পরিণত করে। এর ফলে ওজোনস্তর হালকা বা ফুটো হয়ে যায়। এ ফাটল দিয়ে মহাজাগতিক বিভিন্ন রশ্মি পৃথিবীতে এসে জীবজগতের ক্ষতিসাধন করে।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '50e5d6d34186d010930c245cebaddce4'),
(5764, 352, 'মানুষের ক্রোমোজোমের সংখ্যা কত?', '২০ জোড়া', NULL, '২২ জোড়া', NULL, '২৩ জোড়া', NULL, '২৫ জোড়া', NULL, 'C', 'মানুষের ক্রোমোজোমের সংখ্যা ২৩ জোড়া। এর মধ্যে ২২ জোড়া অটোজোম এবং ১ জোড়া সেক্স ক্রোমোজোম। সেক্স ক্রোমোজোম সন্তান-সন্ততির লিঙ্গ নির্ধারণ করে। মহিলাদের সেক্স ক্রোমোজোম XX এবং পুরুষের XY।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '75c366926c5f03efb0f2205d31d19923'),
(5765, 360, 'কোন জারক রস পাকস্থলীতে দুগ্ধ জমাট বাঁধায়?', 'পেপসিন', NULL, 'এমাইলেজ', NULL, 'রেনিন', NULL, 'ট্রিপসিন', NULL, 'C', 'পাকস্থলীতে বিদ্যমান রেনিন এনজাইম দুগ্ধ প্রোটিন কেসিনকে প্যারাকেসিনে পরিণত করে। এর ফলে দুধ জমাট বাঁধে। ট্রিপসিন এবং পেপসিন নামক এনজাইম প্রোটিন পরিপাকে এবং এমাইলেজ কার্বোহাইড্রেট পরিপাকে সহায়তা করে।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd2c461971c53522c39554502bd5227a2'),
(5766, 368, 'বিশ্ব খাদ্য ও কৃষি সংস্থার সদর দপ্তর কোথায় অবস্থিত?', 'জেনেভা', NULL, 'প্যারিস', NULL, 'লন্ডন', NULL, 'রোম', NULL, 'D', '১৯৪৫ সালের ১৬ অক্টোবর কুইবেকে অনুষ্ঠিত এক সম্মেলনে জাতিসংঘ খাদ্য ও কৃষি সংস্থা (FAO) প্রতিষ্ঠিত হয়। এর সদর দপ্তর ইতালির রোমে এবং সদস্য রাষ্ট্র ১৯৪টি।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0bb0dce9cff80698f6880ec6eb179c2e'),
(5767, 386, 'ভায়াগ্রা কি?', 'একটি জলপ্রপাত', NULL, 'নতুন একটি ঔষধ', NULL, 'সাড়া জাগানো চলচ্চিত্রের নাম', NULL, 'নতুন জাহাজের নাম', NULL, 'B', 'সিলডেনাফিল সাইট্রেট যা ভায়াগ্রা এবং অন্যান্য বাণিজ্যিক নামে বিক্রি হয়ে থাকে এমন একটি ঔষধ যা পুরুষের ধ্বজভঙ্গের (ইরেকটাইল ডিসফাংশন) ক্ষেত্রে ব্যবহার করা হয়। এছাড়াও হৃদপিণ্ডের ধমনীর উচ্চ রক্তচাপের চিকিৎসায় ও ব্যবহৃত হয়ে থাকে। এটি ফাইজার কোম্পানির বিজ্ঞানী এন্ড্রু বেল, ডেভিড ব্রাউন এবং নিকোলাস টেরেট ১৯৯৮ সালে আবিষ্কার করেন।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5bc4a59c82d8d125dd9bf42769adcc6f'),
(5768, 380, 'ক্লোনিং পদ্ধতিতে জন্মগ্রহণকারী ভেড়ার নাম কি?', 'নেনী', NULL, 'টমি', NULL, 'শেলী', NULL, 'ডলি', NULL, 'D', 'স্কটল্যান্ডের এডিনবরার রোসলিন ইনস্টিটিউটের বিজ্ঞানীরা ১৯৯৬ সালের ৫ জুলাই ক্লোন ভেড়া ডলির জন্ম দেন। রোসলিন ইনস্টিটিউটের ভ্রূণতত্ত্ববিদ ড. আয়ান উইলমুট ভেড়াটিকে ক্লোন করেন। ১৯৯৭ সালে ডলির জন্মের বিষয়টি ঘোষণা করা হয়।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b0725b134503113d7145cde9d09d8b34'),
(5769, 337, 'প্রাণীর মলমূত্র থেকে ব্যাকটেরিয়ার সাহায্যে ফারমেন্টেশন প্রক্রিয়ায় উৎপন্ন হয়–', 'ইথেন', NULL, 'অ্যামোনিয়া', NULL, 'মিথেন', NULL, 'বিউটেন', NULL, 'C', 'স্তন্যপায়ী প্রাণীর মূত্রে ইউরিয়া নামক জৈব পদার্থ থাকে। ব্যাকটেরিয়ার মাধ্যমে ফারমেন্টেশন প্রক্রিয়ায় মিথেন উৎপন্ন হয়। ঈস্ট, ব্যাকটেরিয়া প্রভৃতি এনজাইমের প্রভাবে জৈব পদার্থের রাসায়নিক পরিবর্তনের নাম ফারমেন্টেশন বা গাঁজন।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c00ce8aa8340398290bef878d7c1340e'),
(5770, 381, 'কোনটি তেজস্ক্রিয় পদার্থ নয়?', 'লৌহ', NULL, 'ইউরেনিয়াম', NULL, 'প্লুটোনিয়াম', NULL, 'নেপচুনিয়াম', NULL, 'A', 'ভারী মৌলিক পদার্থের নিউক্লিয়াস থেকে স্বতঃস্ফূর্তভাবে অবিরত আলফা, বিটা ও গামা রশ্মি নির্গমনের প্রক্রিয়াকে তেজস্ক্রিয়তা বলে। প্রকৃতপক্ষে যে সব মৌলের পারমাণবিক সংখ্যা ৮২-এর চেয়ে বেশি তাদেরকে তেজস্ক্রিয় পদার্থ বলা হয়। উপরিউক্ত মৌলগুলোর মধ্যে লৌহের পারমাণবিক সংখ্যা ২৬, অন্যগুলোর ৮২ বা তার বেশি, যার ফলে শুধু লৌহই তেজস্ক্রিয় পদার্থ নয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ca74bd613c57493135790eb5de3ee26e'),
(5771, 339, 'কোন বস্তুটির স্থিতিস্থাপকতা বেশি?', 'রবার', NULL, 'এলুমিনিয়াম', NULL, 'লৌহ', NULL, 'তামা', NULL, 'C', 'বাইরে থেকে প্রযুক্ত বল অপসারিত হলে বিকৃত বস্তু যে ধর্মের ফলে তার পূর্বের অবস্থায় ফিরে আসে, তাকে স্থিতিস্থাপকতা বলে। যেসব বস্তুর ক্ষেত্রে পীড়ন এবং বিকৃতির অনুপাত বেশি অর্থাৎ স্থিতিস্থাপক গুণাঙ্কের মান বেশি সেসব বস্তু বেশি স্থিতিস্থাপক। লৌহের ক্ষেত্রে অধিক পীড়ন দেয়া সত্ত্বেও বিকৃতির মান যৎসামান্য হয়। কিন্তু রবার, এলুমিনিয়াম ও তামার ক্ষেত্রে অল্প পীড়ন দিলেই বিকৃতির মান অনেক বেশি হয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e15ae9bd20105922b95919c4a45fcc83'),
(5772, 347, 'কোন পদার্থটি চৌম্বক পদার্থ নয়?', 'কাঁচা লোহা', NULL, 'ইস্পাত', NULL, 'এলুমিনিয়াম', NULL, 'কোবাল্ট', NULL, 'C', 'যে পদার্থকে চুম্বক আকর্ষণ করতে পারে না তাকে অচৌম্বক পদার্থ বলা হয়। উপরিউক্ত পদার্থগুলোর মধ্যে শুধু এলুমিনিয়ামকেই চুম্বক আকর্ষণ করে না।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6570fb23c2ac39a1677eef3f8825415e'),
(5773, 344, 'যে মসৃণতলে আলোর নিয়মিত প্রতিফলন ঘটে তাকে কি বলে?', 'দর্পণ', NULL, 'লেন্স', NULL, 'প্রিজম', NULL, 'বিম্ব', NULL, 'A', 'কোনো মসৃণতলে আলো আপতিত হয়ে নির্দিষ্ট নিয়ম অনুযায়ী কোনো দিকে চললে ঐ আপতন তলকে বলা হয় দর্পণ। বক্রপৃষ্ঠ স্বচ্ছ মাধ্যমের সাধারণ নাম লেন্স।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5b0e6a4dba35dc2e4c8f5b642c444de2'),
(5774, 385, 'রাডারে যে তড়িৎ চৌম্বক ব্যবহার করা হয় তার নাম কি?', 'গামা রশ্মি', NULL, 'মাইক্রোওয়েভ', NULL, 'অবলোহিত বিকিরণ', NULL, 'আলোক তরঙ্গ', NULL, 'B', 'রাডারের মূলনীতি হলো ক্ষুদ্র তরঙ্গ দৈর্ঘ্যের পালস ছড়িয়ে দেয়া হয় যেন বস্তু থেকে প্রতিফলিত হয়ে রাডারের গ্রাহক যন্ত্রে আসে। এ জন্য গামা রশ্মি বা মাইক্রোওয়েভ উভয়ের তরঙ্গ দৈর্ঘ্য ক্ষুদ্র হলেও কম ভেদন ক্ষমতাসম্পন্ন মাইক্রোওয়েভই ব্যবহার করা হয়। অপরপক্ষে অবলোহিত বিকিরণ ও আলোক তরঙ্গের তরঙ্গদৈর্ঘ্য বেশ বড়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '01c1113da6a021f125ee2854e29dc7cb'),
(5775, 381, 'মহাজাগতিক রশ্মি আবিষ্কার করে কোন বিজ্ঞানী নোবেল পুরস্কার পান?', 'হেস', NULL, 'গোল্ডস্টাইন', NULL, 'রাদারফোর্ড', NULL, 'আইনস্টাইন', NULL, 'A', 'আইনস্টাইন আপেক্ষিক তথ্য ও রাদারফোর্ড আণবিক নিউক্লিয়াসের মতবাদ আবিষ্কার করেন। ভিক্টর ফ্রান্সিস হেস মহাজাগতিক রশ্মি আবিষ্কারের জন্য ১৯৩৬ সালে পদার্থ বিজ্ঞানে নোবেল পুরস্কার পান।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3acd0deeb3545acb7d8b8562659a556a'),
(5776, 346, 'তড়িৎশক্তি শব্দশক্তিতে রূপান্তরিত হয় কোন যন্ত্রের মাধ্যমে?', 'এমপ্লিফায়ার', NULL, 'জেনারেটর', NULL, 'লাউড স্পিকার', NULL, 'মাইক্রোফোন', NULL, 'C', 'এমপ্লিফায়ার বিবর্ধক শব্দশক্তিকে জোরালো করে। জেনারেটর যান্ত্রিকশক্তিকে বৈদ্যুতিক শক্তিতে রূপান্তরিত করে। লাউড স্পিকার তড়িৎশক্তিকে শব্দশক্তিতে রূপান্তরিত করে এবং মাইক্রোফোন শব্দতরঙ্গকে বিদ্যুৎ প্রবাহে পরিণত করে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd9e521b4618ed294b54f766434a558cc'),
(5777, 345, 'সমুদ্রের গভীরতা মাপা হয় কোন যন্ত্র দিয়ে?', 'ফ্যাদোমিটার', NULL, 'জাইরো কম্পাস', NULL, 'সাবমেরিন', NULL, 'এনিওমিটার', NULL, 'A', 'পানির গভীরতা মাপার যান্ত্রিক সরঞ্জাম ফ্যাদোমিটার। এ যন্ত্রের কার্যকারিতা শব্দের প্রতিধ্বনির ওপর নির্ভরশীল। ধ্বনির উৎপত্তি থেকে ফিরে আসা প্রতিধ্বনির সময়ের পার্থক্য থেকে গভীরতা নির্ণয় করা হয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '662edecabf878f10dbb30ff5727702eb'),
(5778, 385, 'কম্পিউটার কে আবিষ্কার করেন?', 'উইলিয়াম অটরেড', NULL, 'ব্লেইস প্যাসকেল', NULL, 'হাওয়ার্ড এইকিন', NULL, 'অ্যাবাকাস', NULL, 'C', 'হাওয়ার্ড এইকিন প্রথম স্বয়ংক্রিয় গণনা যন্ত্র আবিষ্কার করেন এবং অ্যাবাকাস খ্রিষ্টপূর্ব ৪৫০-৫০০ অব্দে চীন/মিশরে ব্যবহৃত এক ধরনের গণনা যন্ত্র।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '25c5859de4d03165534cf5ae1e561019'),
(5779, 363, 'কোন হরমোনের অভাবে ডায়াবেটিস রোগ হয়?', 'থাইরোক্সিন', NULL, 'গ্লুকাগন', NULL, 'এড্রিনালিন', NULL, 'ইনসুলিন', NULL, 'D', 'হরমোন হচ্ছে একশ্রেণীর রাসায়নিক বস্তু, যা দেহের কোষ বা অঙ্গসমূহের বিপাক ক্রিয়া নিয়ন্ত্রণ করে। অগ্ন্যাশয় থেকে নিঃসৃত ইনসুলিন হচ্ছে এমন এক ধরনের হরমোন, যা রক্তে গ্লুকোজের বিপাক ক্রিয়া নিয়ন্ত্রণ করে। কোনো কারণে রক্তে ইনসুলিন সরবরাহ কমে গেলে গ্লুকোজের বিপাক ক্রিয়া বিঘ্নিত হয়, যার ফলে ডায়াবেটিস রোগ হয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd4934f1109f046c37b5fd6ab6afcf0cf'),
(5780, 387, 'বায়ুমণ্ডলের ওজোনস্তর অবক্ষয়ে কোন গ্যাসটির ভূমিকা সর্বোচ্চ?', 'কার্বন-ডাই-অক্সাইড', NULL, 'জলীয় বাষ্প', NULL, 'CFC বা ক্লোরোফ্লোরো কার্বন', NULL, 'নাইট্রিক অক্সাইড', NULL, 'C', 'সিএফসি হলো ক্লোরোফ্লোরো কার্বনের সংক্ষিপ্ত রূপ। এটি বায়ুমণ্ডলের ওজোনস্তরে পৌঁছে ওজোনের সঙ্গে বিক্রিয়া করে অক্সিজেনে পরিণত করে। এর ফলে ওজোনস্তর হালকা বা ফুটো হয়ে যায়। এই ফাটল দিয়ে মহাজাগতিক বিভিন্ন রশ্মি পৃথিবীতে এসে জীবজগতের ক্ষতিসাধন করে।', NULL, 170, '21st BCS', '100-100', '100', 'N', NULL, NULL, '2026-08-12', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2ca05b9e5c0e9c595c8322a87ad36069');
