(6357, 418, 'উদ্দীপক: কম্পিউটার শিক্ষক জনাব শফিক স্যার বোর্ডে একটি (77)₈ সংখ্যা লিখলেন। [য.বো.\'১৭]\r\nউদ্দীপকে উল্লেখিত সংখ্যাটির দশমিক সংখ্যা হলো – ', '56', NULL, '63', NULL, '64', NULL, '77', NULL, 'B', '(77)₈ = (৭ × ৮) + ৭ = ৬৩।', NULL, 220, 'য.বো.১৭', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', '2026-09-21', 'admin', NULL, NULL, '1', 2017, '0000-00-00', 'ICT', '', NULL, 'e6018cdd6e5310a2019d436a90513478'),
(6358, 418, 'উদ্দীপক: কম্পিউটার শিক্ষক জনাব শফিক স্যার বোর্ডে একটি (77)₈ সংখ্যা লিখলেন। [য.বো.\'১৭]\r\nউদ্দীপকের সংখ্যাটির পরবর্তী সংখ্যা কোনটি?', '(78)₈', NULL, '(100)₈', NULL, '(200)₈', NULL, '(777)₈', NULL, 'B', '৭৭ + ১ = (১০০)₈।', NULL, 220, 'য.বো.১৭', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', '2026-09-21', 'admin', NULL, NULL, '1', 2017, '0000-00-00', 'ICT', '', NULL, '9516279e28e14d9510e375baf5e98317'),
(6359, 418, 'উদ্দীপক: মি. আতিক কামালকে বলল, \'তোমার বয়স কত?\' কামাল বলল যে তার বয়স (101101)₂। [দি.বো.\'১৭]\r\nকামালের বয়সের সমকক্ষ সংখ্যা হলো – (উদ্দীপক: (101101)₂)', '(25)₈', NULL, '(35)₈', NULL, '(55)₈', NULL, '(65)₈', NULL, 'C', '(101101)₂ = (55)₈ = ৪৫ বছর।', NULL, 264, 'দি.বো.১৭', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', '2026-09-21', 'admin', NULL, NULL, '1', 2017, '0000-00-00', 'ICT', '', NULL, '9d68519cef7cafed336ae0192b53d6d4'),
(6360, 418, 'উদ্দীপক: মি. আতিক কামালকে বলল, \'তোমার বয়স কত?\' কামাল বলল যে তার বয়স (101101)₂। [দি.বো.\'১৭]\r\nদশ বছর পর কামালের বয়স বাইনারিতে কত হবে?', '(101011)₂', NULL, '(101110)₂', NULL, '(101111)₂', NULL, '(110111)₂', NULL, 'D', '৪৫ + ১০ = ৫৫ = (110111)₂।', NULL, 264, 'দি.বো.১৭', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', '2026-09-21', 'admin', NULL, NULL, '1', 2017, '0000-00-00', 'ICT', '', NULL, '307ddf989f4b46f915be8f2af8bf90e5'),
(6361, 421, 'বাংলা বর্ণমালা কোন কোডভুক্ত?', 'BCD', NULL, 'ASCII', NULL, 'EBCDIC', NULL, 'UNICODE', NULL, 'D', 'বিশ্বের ছোট-বড় সকল ভাষার বর্ণ ও চিহ্নকে কম্পিউটারে কোডভুক্ত করার জন্য ব্যবহৃত ১৬-বিটের সার্বজনীন কোড হলো ইউনিকোড (UNICODE)।', NULL, 194, 'ঢা.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'eeb32f44f3c12d4b747a50d8b84b26c6'),
(6362, 418, '11001.0100₂ এর সমতুল্য অক্টাল সংখ্যা কত?', '25.25₈', NULL, '52.52₈', NULL, '31.20₈', NULL, '62.20₈', NULL, 'C', 'পূর্ণাংশ (11001)₂ = (011 001)₂ = (3 1)₈। ভগ্নাংশ (.0100)₂ = (.010 000)₂ = (.2 0)₈। অতএব, সমতুল্য অক্টাল = 31.20₈।', NULL, 194, 'ঢা.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'c7940f1a3dd9d54ded13ec6b2145de57'),
(6363, 418, 'FF₁₆ এর পূর্বের সংখ্যা কোনটি?', 'EE', NULL, 'EF', NULL, 'FE', NULL, 'FO', NULL, 'C', 'হেক্সাডেসিমেল FF₁₆ এর আগের সংখ্যা = FF₁₆ - 1₁₆ = FE₁₆ (যেহেতু F এর আগের অঙ্ক E)।', NULL, 194, 'ঢা.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '726d38e31d883843b1127526cd632199'),
(6364, 417, '10 ভিত্তিক সংখ্যা পদ্ধতি হলো — i. ভারতীয়  ii. মায়ান  iii. চীন', 'i ও ii', NULL, 'i ও iii', NULL, 'ii ও iii', NULL, 'i, ii ও iii', NULL, 'B', 'ভারতীয় ও প্রাচীন চীনা সংখ্যা পদ্ধতি ১০ ভিত্তিক (Decimal) ছিল। মায়ান ছিল ২০ ভিত্তিক (Vigesimal)।', NULL, 216, 'রা.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '8a9e8930933e56a6e3bf41de950cc90b'),
(6365, 419, '1101.10010₂ - 111.11011₂ = ?', '100.10111₂', NULL, '101.00111₂', NULL, '100.10101₂', NULL, '101.10111₂', NULL, 'D', '(1101.10010)₂ = (13.5625)₁₀, (111.11011)₂ = (7.84375)₁₀। বিয়োগফল = 5.71875₁₀ = 101.10111₂।', NULL, 216, 'রা.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '92a5da936618d6c1b350d319104db54a'),
(6366, 421, '4 বিটবিশিষ্ট কোড কোনটি?', 'Octal code', NULL, 'BCD code', NULL, 'ASCII code', NULL, 'Unicode', NULL, 'B', 'BCD (Binary Coded Decimal) কোডে দশমিক সংখ্যার প্রতিটি অঙ্ককে (০-৯) প্রকাশের জন্য ৪ বিট বাইনারি ব্যবহার করা হয়।', NULL, 216, 'রা.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'd85f28375486f36b82ef18be5e43832b'),
(6367, 420, '31₁₀ সংখ্যাটির 2\'s complement কত?', '11000111', NULL, '11100000', NULL, '11000010', NULL, '11100001', NULL, 'D', '+31 এর ৮-বিট বাইনারি = 00011111। ১-এর পরিপূরক = 11100000। +১ যোগ করলে = 11100001।', NULL, 205, 'চ.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '9f0b3adc07467b42219b966651ba1200');
