(6369, 418, '5, D, 15 ----- ধারাটির পরবর্তী সংখ্যা কোনটি?', '20', NULL, '29', NULL, '1C', NULL, '1D', NULL, 'D', 'ধারাটি হেক্সাডেসিমেলে: 5=5, D=13, 15=21। পার্থক্য ৮। পরবর্তী = 21+8 = 29₁₀ = (1D)₁₆।', NULL, 227, 'য.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '96191020bcb62861349790f4e6bf5368'),
(6370, 421, 'UTF-8 নিম্নের কোন কোড?', 'BCD', NULL, 'EBCDIC', NULL, 'ASCII-8', NULL, 'Uni', NULL, 'D', 'UTF-8 হলো ইউনিকোড (Unicode / Uni) পরিবারের একটি বহুল ব্যবহৃত ৮-বিট ক্যারেক্টার এনকোডিং মানক।', NULL, 227, 'য.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'f1eb31966889ab6c0bbcf4729c27a5d3'),
(6371, 417, '321 সংখ্যাটি হতে পারে — i. অক্টাল  ii. ডেসিমাল  iii. হেক্সাডেসিমাল', 'i ও ii', NULL, 'i ও iii', NULL, 'ii ও iii', NULL, 'i, ii ও iii', NULL, 'D', '৩, ২, ১ অঙ্কগুলো অক্টাল (৮), ডেসিমাল (১০) এবং হেক্সাডেসিমাল (১৬)—তিনটি পদ্ধতিতেই গ্রহণযোগ্য।', NULL, 227, 'য.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'e903d45598b69e7d5a29be2322fb1eb6'),
(6372, 418, '101110₂ এর সমকক্ষ মান — i. 56₈  ii. 46₁₀  iii. 2E₁₆', 'i ও ii', NULL, 'i ও iii', NULL, 'ii ও iii', NULL, 'i, ii ও iii', NULL, 'A', '(101110)₂ = 56₈ = 46₁₀ = 2E₁₆। সোর্সের অপশনে 2F থাকায় i ও ii সঠিক।', NULL, 282, 'ম.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '00c1c42a122cb437ca6abb6f7e7025e2'),
(6373, 418, '(1A.48)₁₆ এর সমতুল্য বাইনারি মান —', '10110.01001', NULL, '11001.01001', NULL, '11010.00101', NULL, '11010.01001', NULL, 'D', '1 = 0001, A = 1010, 4 = 0100, 8 = 1000। সম্পূর্ণ = 0001 1010.0100 1000₂ = 11010.01001₂।', NULL, 271, 'দি.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '22fd30520ccddab2678276d973790e07'),
(6374, 418, 'x₅ হলে x=14 এর পরবর্তী মান কোনটি?', '15', NULL, '18', NULL, '20', NULL, '22', NULL, 'C', 'বেস-৫ এর প্রতীক 0-4। 14₅ + 1 = 20₅ (৪+১=১০, ০ বসে ক্যারি ১; ১+১=২)।', NULL, 249, 'ব.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, '4a0146a2e66f37fc539b0029a9c4908b'),
(6375, 418, 'উদ্দীপকের রোলের (রোল = 63₁₀) সমতুল্য মান — i. 63₁₀  ii. 111111₂  iii. 3F₁₆', 'i ও ii', NULL, 'i ও iii', NULL, 'ii ও iii', NULL, 'i, ii ও iii', NULL, 'D', '63₁₀ = 111111₂ = 3F₁₆। তিনটি মানই সমান।', NULL, 249, 'ব.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'fcf053ea8e20a2126c7a39ed1f57af0a'),
(6376, 419, 'ক্লাসে ICT শিক্ষক (1011.11)₂ ও (1101.10)₂ এর যোগফল নির্ণয় করতে বললেন। আরিফ (11011.11)₂ লিখল। সে কত বেশি লিখল?', '101.10', NULL, '11.11', NULL, '11.10', NULL, '10.10', NULL, 'D', 'প্রকৃত যোগফল = (11001.01)₂ = 25.25₁₀। আরিফের মান = (11011.11)₂ = 27.75₁₀। পার্থক্য = 2.5₁₀ = (10.10)₂।', NULL, 260, 'সি.বো.২৪', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2024, NULL, 'ICT', NULL, NULL, 'ea5c35ac753a8dda43660239d3a65ecc'),
