(6384, 111, 'HTML এর বৈশিষ্ট্য হলো—', 'এটি ইউজার ফ্রেন্ডলি ওপেন টেকনোলজি', NULL, 'নিরাপত্তা ব্যবস্থা উন্নত', NULL, 'এটি নিজেকে বর্ধিত করার ক্ষমতা রাখে', NULL, 'কোড লিখতে সিনট্যাক্স মনে রাখতে হয়', NULL, 'A', 'HTML একটি অত্যন্ত সহজ, মুক্ত বা ওপেন টেকনোলজি যা সব ধরনের ব্রাউজারে বিনামূল্যে সাপোর্ট করে।', NULL, NULL, 'মা.বো.১৭', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2017, NULL, 'ICT', NULL, NULL, '07c29dcafec34bb67113aad58761a5a5'),
(6385, 109, 'HTML ডকুমেন্ট এর অংশ নয় তবে লেখা জরুরি কোনটি?', '<!DOCTYPE html>', NULL, '<html>', NULL, '<head>', NULL, '<body>', NULL, 'A', 'DOCTYPE প্রদেয় ডকুমেন্টটি HTML5 স্ট্যান্ডার্ড নির্দেশ করে। এটি ডকুমেন্টের এলিমেন্ট বা অংশ নয়, কিন্তু ব্রাউজারের সঠিক রেন্ডারিংয়ের জন্য লেখা জরুরি।', NULL, 237, 'কু.বো.২৩', '100-100', '100', 'N', NULL, NULL, '2026-09-21', 'softadmin', NULL, NULL, NULL, NULL, '1', 2023, NULL, 'ICT', NULL, NULL, 'b623aab373c8b383946408adb1c21813'),
