(6513, 678, '‘‘অর্ধচন্দ্র’’-এর অর্থ-', 'গলাধাক্কা দেয়া', NULL, 'অমাবস্যা', NULL, 'দ্বিতীয়ত', NULL, 'কাস্তে', NULL, 'C', 'অর্ধচন্দ্র অর্থ অর্ধেক চন্দ্র বা দ্বিতীয়া চাঁদ (দ্বিতীয়তিথির চাঁদ)। কাস্তে হলো অর্ধচন্দ্রাকৃতি অস্ত্র।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f2aa3c6cc4de0c952183c48869b6936d'),
(6514, 677, 'কোনটি শুদ্ধ?', 'সৌজন্নতা', NULL, 'সৌজন্যতা', NULL, 'সৌজনতা', NULL, 'সৌজন্য', NULL, 'D', 'শুদ্ধ বানান হলো \"সৌজন্য\" (সৎ+ঔজন্য-এর সন্ধি) যা ভদ্রতা, শিষ্টাচার অর্থে ব্যবহৃত হয়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '678cdbb940e684982a4c80af015ef345'),
(6515, 645, 'বেগম রোকেয়ার রচনা কোনটি?', 'ভাষা ও সাহিত্য', NULL, 'আয়না', NULL, 'লালসালু', NULL, 'অবরোধবাসিনী', NULL, 'D', 'বেগম রোকেয়া সাখাওয়াত হোসেন রচিত প্রবন্ধ \"অবরোধবাসিনী\"। এ প্রবন্ধে নারীর দুঃখ দুর্দশার চিত্র ফুটিয়ে তোলা হয়েছে। তাঁর অন্যান্য রচনা: মতিচূর ও পদ্মরাগ।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '68ccabdea877babc84b24a5b1cae3f50'),
(6516, 495, 'বাংলা গীতি কবিতায় ভোরের পাখি কে?', 'বিহারীলাল চক্রবর্তী', NULL, 'প্যারীচাঁদ মিত্র', NULL, 'ঈশ্বরচন্দ্র বিদ্যাসাগর', NULL, 'শরৎচন্দ্র চট্রোপাধ্যায়', NULL, 'A', 'বিহারীলাল চক্রবর্তী বাংলা গীতিকবিতার জনক। বাংলা সাহিত্যের আধুনিক যুগের প্রথম দিকে সফল গীতিকবিতা রচনার জন্য বিশ্বকবি রবীন্দ্রনাথ ঠাকুর বিহারীলাল চক্রবর্তীকে ভোরের পাখি উপাধি দেন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ac244a40d036b31eddcc58e796e2f7cb'),
(6517, 673, 'কোনটি শুদ্ধ বাক্য?', 'একটা গোপনীয় কথা বলি', NULL, 'একটি গোপন কথা বলি', NULL, 'একটা গোপন কথা বলি', NULL, 'একটি গুপ্ত কথা বলি', NULL, 'B', 'শুদ্ধ বাক্য: \"একটি গোপন কথা বলি\" - \"গোপন\" অর্থ লুকানো, গুপ্ত। \"গোপনীয়\" অর্থ গোপন রাখার যোগ্য। বাক্যে সঠিক শব্দ \"গোপন\" এবং \"একটি\" শুদ্ধ রূপ।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '151e358b790e7e4265489a7e14a17855'),
(6518, 678, '‘‘শিষ্টাচার’’-এর সমার্থক শব্দ কোনটি?', 'নিষ্ঠা', NULL, 'সদাচার', NULL, 'সততা', NULL, 'সংযম', NULL, 'B', '‘নিষ্ঠা’ অর্থ একাগ্রতা, অনন্যচিত্ততা। ‘সততা’ অর্থ সত্যপরায়ণতা, সত্যনিষ্ঠা। ‘সংযম’ অর্থ নিয়ন্ত্রণ, দমন। ‘শিষ্টাচার’ অর্থ ভদ্রতা, সৌজন্য, সদাচার।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '41162cfab458192d83d2a00718f99986'),
(6519, 678, '‘‘সংশয়’’-এর বিপরীতার্থক শব্দ কোনটি?', 'নির্ভয়', NULL, 'বিস্ময়', NULL, 'প্রত্যয়', NULL, 'দ্বিধা', NULL, 'C', 'ভয়-নির্ভয়; প্রত্যয়-সংশয়; দ্বিধা-নির্দ্বিধা; বিস্ময়-প্রত্যয়। \"সংশয়\" অর্থ সন্দেহ, দ্বিধা; এর বিপরীত \"প্রত্যয়\" অর্থ বিশ্বাস, আস্থা।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '97a1e7841ad3082ad80d85307c947e79'),
(6520, 678, '‘‘ক্ষমার যোগ্য’’-এর বাক্য সংকোচন-', 'ক্ষমার্হ', NULL, 'ক্ষমাপ্রার্থী', NULL, 'ক্ষমা', NULL, 'ক্ষমাপ্রদ', NULL, 'A', 'ক্ষমার যোগ্য = ক্ষমার্হ। \"ক্ষমাপ্রার্থী\" অর্থ ক্ষমা প্রার্থনা করে এমন, \"ক্ষমাপ্রদ\" অর্থ ক্ষমা দেয় এমন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dcb9ed87d77bfb620f0086283b0c8fb4'),
(6521, 680, '_____ সেপ্টেম্বর বিশ্ব নিরক্ষরতা দিবস। শূন্যস্থান পূরণ করুন।', '৮', NULL, '৬', NULL, '১০', NULL, '৫', NULL, 'A', '৮ সেপ্টেম্বর বিশ্ব সাক্ষরতা দিবস (বিশ্ব নিরক্ষরতা দিবস)। ইউনেস্কো ১৯৬৫ সালে ৮ সেপ্টেম্বরকে বিশ্ব সাক্ষরতা দিবস ঘোষণা করে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'eabee4419f3f6e40f525e08939193f15'),
(6522, 545, '‘‘মোস্তফা চরিত’’ গ্রন্থের রচয়িতা-', 'মুহম্মদ আব্দুল হাই', NULL, 'মোঃ বরকতুল্লাহ', NULL, 'ড. মুহম্মদ শহীদুল্লাহ', NULL, 'মওলানা আকরম খাঁ', NULL, 'D', 'মওলানা আকরম খাঁর (১৮৬৮-১৯৬৮) শ্রেষ্ঠ রচনা ‘মোস্তফা চরিত’ (১৯২৩)। এটি হযরত মুহম্মদ (স)-এর জীবনীমূলক রচনা।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '07fd23c94380aab8474b67669d2001ce'),
(6523, 655, '‘‘আমার দেখা রাজনীতির পঞ্চাশ বছর’’ গ্রন্থটির রচয়িতা-', 'মুহম্মদ আব্দুল হাই', NULL, 'ড. মুহম্মদ শহীদুল্লাহ', NULL, 'আবুল মনসুর আহমেদ', NULL, 'আতাউর রহমান', NULL, 'C', '‘‘আমার দেখা রাজনীতির পঞ্চাশ বছর’’ গ্রন্থটির রচয়িতা আবুল মনসুর আহমেদ। এটি তার আত্মজীবনীমূলক রচনা।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c9535f7c33a175e81c30a7da8e82776f'),
(6524, 480, 'পুঁথি সাহিত্যের প্রাচীনতম লেখক-', 'ভারতচন্দ্র রায়', NULL, 'দৌলত কাজী', NULL, 'সৈয়দ হামজা', NULL, 'আব্দুল হাকিম', NULL, 'C', 'উপরিউক্ত কবিদের মধ্যে সৈয়দ হামজা পুঁথি সাহিত্য রচনা করেন। তবে তিনি প্রথম আদি রচয়িতা নন। পুঁথি সাহিত্যের প্রথম সার্থক ও জনপ্রিয় লেখক ফকির গরীবুল্লাহ।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9c6bf6f990e36d362700f3de70184f99'),
(6525, 655, '‘‘চাচা কাহিনীর’’ লেখক –', 'সৈয়দ শামসুল হক', NULL, 'সৈয়দ মুজতবা আলী', NULL, 'শওকত ওসমান', NULL, 'ফররুখ আহমেদ', NULL, 'B', '‘‘চাচা কাহিনী’’ সৈয়দ মুজতবা আলী রচিত একটি জনপ্রিয় গ্রন্থ। তিনি বিংশ শতাব্দীর প্রখ্যাত বাঙালি সাহিত্যিক।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '91e2bf35d0128bdcace5a68f9016a9ab'),
(6526, 667, 'বিভক্তিযুক্ত শব্দ ও ধাতুকে বলে–', 'শব্দ', NULL, 'কারক', NULL, 'পদ', NULL, 'ক্রিয়াপদ', NULL, 'C', 'বিভক্তিযুক্ত শব্দ ও ধাতুকে পদ বলে। বাক্যের অন্তর্গত প্রত্যেকটি শব্দকেও পদ বলে। বাক্যস্থিত ক্রিয়াপদের সাথে নাম পদের যে সম্পর্ক তাকে কারক বলে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6065ec2449174267d5e297e910522347'),
(6527, 562, '‘‘রাজলক্ষ্মী’’ চরিত্রের স্রষ্টা ঔপন্যাসিক-', 'বঙ্কিমচন্দ্র', NULL, 'শরৎচন্দ্র', NULL, 'তারাশংকর', NULL, 'নজরুল ইসলাম', NULL, 'B', 'শরৎচন্দ্র চট্টোপাধ্যায়ের আত্মজীবনীমূলক উপন্যাস ‘শ্রীকান্ত’ ৪ খণ্ডে প্রকাশিত হয়। এর বিখ্যাত চরিত্রসমূহ হলো- শ্রীকান্ত, ইন্দ্রনাথ, অন্নদাদিদি, অভয়া, রাজলক্ষ্মী।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ca964fe3f47cc0f13bc43fbb5a8a43a1'),
(6528, 669, 'ক্রিয়া পদের মূল অংশকে বলা হয়?', 'বিভক্তি', NULL, 'ধাতু', NULL, 'প্রত্যয়', NULL, 'কৃৎ', NULL, 'B', 'ক্রিয়াপদের মূল অংশকে বলা হয় ধাতু বা ক্রিয়ামূল। ক্রিয়াপদকে বিশ্লেষণ করলে দুটি অংশ পাওয়া যায়: ধাতু বা ক্রিয়ামূল এবং ক্রিয়া বিভক্তি। ধাতু তিন প্রকারের: মৌলিক ধাতু, সাধিত ধাতু এবং যৌগিক বা সংযোগমূলক ধাতু।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'aee6f4995e0c482453dc9388e5914162'),
(6529, 497, 'স্বাধীনতা হীনতায় কে বাঁচিতে চায় চরণটি কার রচনা?', 'ঈশ্বরচন্দ্র গুপ্ত', NULL, 'মধুসূদন দত্ত', NULL, 'হেমচন্দ্র বন্দ্যোপাধ্যায়', NULL, 'রঙ্গলাল বন্দ্যোপাধ্যায়', NULL, 'D', 'রঙ্গলাল বন্দ্যোপাধ্যায় এর সর্বাধিক জনপ্রিয় কাব্য পদ্মিনী উপাখ্যান থেকে চরণটি সংগৃহীত। তার অন্যান্য উল্লেখযোগ্য কাব্যগ্রন্হ হলো- কর্মদেবী, শূরসুন্দরী, নীতি কুসুমাঞ্জলি ও কাঞ্চী কাবেরী।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '698f057895114aaf1ade9351e9de71bc'),
(6530, 673, 'শুদ্ধ বাক্যটি চিহ্নিত করুন-', 'বিদ্যান ব্যক্তিগণ দরিদ্রের শিকার হন', NULL, 'বিদ্যান ব্যক্তিগণ দারিদ্রতার শিকার হন', NULL, 'বিদ্বান ব্যক্তিগণ দারিদ্র্যের শিকার হন', NULL, 'বিদ্যান ব্যক্তিগণ দরিদ্রতার স্বীকার হন', NULL, 'C', 'বিদ্যান, দারিদ্র, দারিদ্রতা শব্দগুলোর শুদ্ধরূপ হলো: বিদ্বান, দারিদ্র্য, দরিদ্রতা। শুদ্ধ বাক্য: বিদ্বান ব্যক্তিগণ দারিদ্র্যের শিকার হন।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '45df156a887f67323b0a1a4221337825'),
(6531, 664, 'কোন শব্দে বিদেশি উপসর্গ ব্যবহৃত হয়েছে?', 'নিখুঁত', NULL, 'আনমনা', NULL, 'অবহেলা', NULL, 'নিমরাজী', NULL, 'D', 'নিম ফারসি উপসর্গ। বাংলা ভাষায় মোট ১০ টি ফারসি উপসর্গ ব্যবহৃত হয়- কার, দর, না, নিম, ফি, বদ, বে, বর, ব, কম। \"নিমরাজী\" - নিম (ফারসি উপসর্গ) + রাজী।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a179605e75deb18c5402af33aec86ac7'),
(6532, 677, 'কোন বানানটি শুদ্ধ?', 'পাষাণ', NULL, 'পাষান', NULL, 'পাসান', NULL, 'পাশান', NULL, 'A', 'ণ-ত্ব বিধানের নিয়মানুযায়ী ঋ, র, ষ এর পরে ণ হয়। যেমন- তৃণ, ঋণ, রেণু, বিশেষণ, পাষাণ, দূষণ, ভীষণ প্রভৃতি।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e858ff5f0de051afe65e48e7c7cb2c56'),
