(6537, 668, 'নিম্নরেখ কোন শব্দে করণ কারকে শূন্য বিভক্তি ব্যবহৃত হয়েছে?', 'ঘোড়াকে চাবুক মার', NULL, 'ডাক্তার ডাক', NULL, 'গাড়ি স্টেশন ছেড়েছে', NULL, 'মুষলধারে বৃষ্টি পড়ছে', NULL, 'A', 'ক্রিয়া সম্পাদনের যন্ত্র, উপকরণ বা সহায়ককেই করণ কারক বলা হয়। ঘোড়াকে চাবুক মার (করণে শূন্য)।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4c80ad20996a54c6caf681b9a1dcf668'),
(6538, 549, 'রূপসী বাংলার কবি-', 'জসীমউদ্দীন', NULL, 'জীবনানন্দ দাশ', NULL, 'কালিদাস রায়', NULL, 'সত্যেন্দ্রনাথ দত্ত', NULL, 'B', 'জীবনানন্দ দাশ রূপসী বাংলা কাব্যগ্রন্থের রচয়িতা। তিনি বাংলা সাহিত্যের আধুনিক কবিতার অন্যতম পথিকৃৎ।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6cdbb7d7827c5e500eea7e3b19777c35'),
(6539, 480, 'বটতলার পুঁথি বলতে বুঝায়-', 'মধ্যযুগীয় কাব্যের হস্তলিখিত পাণ্ডুলিপি', NULL, 'বটতলা নামক স্থানে রচিত কাব্য', NULL, 'দোভাষী বাংলায় রচিত পুঁথি সাহিত্য', NULL, 'অবিমিশ্র দেশজ বাংলায় রচিত লোকসাহিত্য', NULL, 'C', 'মধ্যযুগে অষ্টাদশ শতকের দ্বিতীয়ার্ধে মুসলমান সাহিত্যিকদের রচিত দোভাষী পুঁথি ছিল আরবি, ফারসি, হিন্দি, বাংলা ও ইংরেজি শব্দের মিশ্রণে রচিত এক ধরনের পুঁথি।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a9b5c99b09fa6cca70a198f4b4cd5c3a'),
(6540, 678, 'এক কথায় প্রকাশ করুন- যা বলা হয়নি-', 'অউক্ত', NULL, 'অব্যক্ত', NULL, 'অনুক্ত', NULL, 'অব্যাক্ত', NULL, 'C', 'যা প্রকাশ করা হয়নি- অব্যক্ত। যা বলা হয়নি- অনুক্ত।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '794e6665dd24c1cb402cbd31d5f07558'),
(6541, 479, 'কবি গান রচয়িতা এবং গায়ক হিসেবে এরা উভয়েই পরিচিত-', 'রাম বসু এবং ভোলা ময়রা', NULL, 'এন্টনি ফিরিঙ্গি এবং রামপ্রসাদ রায়', NULL, 'সাবিরিদ খান এবং দশরথী রায়', NULL, 'আলাওল এবং ভারতচন্দ্র', NULL, 'B', 'গোজলা গুঁই, হরু ঠাকুর, কেষ্টা মুচি, ভবানী বেনে, নিতাই বৈরাগী, ভোলা ময়রা, এন্টনি ফিরিঙ্গি, রামপ্রসাদ রায় ছিলেন বিখ্যাত কবিওয়ালা। এন্টনি ফিরিঙ্গি এবং রামপ্রসাদ রায় উভয়েই কবি গান রচয়িতা এবং গায়ক হিসেবে পরিচিত।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5284838af68d0d5750eba6644a39cf8f'),
(6542, 665, 'কোন শব্দে ধাতুর সঙ্গে প্রত্যয় যুক্ত হয়েছে?', 'ঠগী', NULL, 'পানাস', NULL, 'পাঠক', NULL, 'সেলামী', NULL, 'C', 'ঠগী = ঠক + ঈ, সেলামী = সেলাম + ঈ, পাঠক = পঠ্ + অক। পাঠক শব্দে ধাতু (পঠ্) + প্রত্যয় (অক) যুক্ত হয়েছে।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e2f2e940bea2b809185a7065d9b2603f'),
(6543, 678, 'বাগধারা যুগলদের মধ্যে কোন জোড়া সর্বাধিক সমার্থবাচক?', 'অমাবস্যার চাঁদ; আকাশ কুসুম', NULL, 'বক ধার্মিক; বিড়াল তপস্বী', NULL, 'রুই-কাতলা; কেউ কেটা', NULL, 'বক ধার্মিক; ভিজে বেড়াল', NULL, 'B', 'বক ধার্মিক (ভণ্ড), বিড়াল তপস্বী (ভণ্ড)। অর্থাৎ বক ধার্মিক ও বিড়াল তপস্বী শব্দযুগল সর্বাধিক সমার্থবাচক।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd05af990ba46afd720057978504ed6f8'),
(6544, 637, 'বাংলা সাহিত্যের সর্বাধিক সমৃদ্ধ ধারা-', 'নাটক', NULL, 'ছোট গল্প', NULL, 'প্রবন্ধ', NULL, 'গীতি কবিতা', NULL, 'D', 'বাংলা সাহিত্যের জীবনচক্রে একটি বিশাল সময়জুড়ে গীতি কবিতা সৃষ্টি ও সমৃদ্ধ হয়েছে। অন্যান্য বিষয়াদি এতো ব্যাপক সময়ব্যাপী বিকাশ লাভ করেনি।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '72cacb9662fe6bfda2844401dfe6a0b9'),
