(6546, 663, 'বাংলা ভাষা এই শব্দ দুটি গ্রহণ করেছে চীনা ভাষা হতে-', 'চাকু, চাকর', NULL, 'খদ্দর, হরতাল', NULL, 'চা, চিনি', NULL, 'রিকশা, রেস্তোঁরা', NULL, 'C', 'বাংলা ভাষা চীনা ভাষা থেকে চা ও চিনি শব্দ দুটি গ্রহণ করেছে।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '990253636057dc9e918095302cf6a587'),
(6547, 545, 'ড. মুহম্মদ শহীদুল্লাহ ছিলেন প্রধানত-', 'ভাষাতত্ত্ববিদ', NULL, 'সাহিত্যের ইতিহাস রচয়িতা', NULL, 'ইসলাম প্রচারক', NULL, 'সমাজ সংস্কারক', NULL, 'A', 'ড. মুহম্মদ শহীদুল্লাহ ছিলেন প্রধানত ভাষাতত্ত্ববিদ। তিনি ছিলেন অধ্যাপক, গবেষক, বহুভাষাবিদ, লেখক ও সম্পাদক।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5ff1923cba22581cac3646b3c5772d8e'),
(6548, 678, '‘গোঁফ- খেজুরে’ – এই বাগধারাটির অর্থ কি?', 'আরামপ্রিয়া', NULL, 'উদাসীন', NULL, 'নিতান্ত অলস', NULL, 'পরমুখাপেক্ষী', NULL, 'C', 'গোঁফ-খেজুরে বাগধারাটি একটি সমাসবদ্ধ শব্দ। এর ব্যাসবাক্য- গোঁফে খেজুর পড়ে থাকলেও খায় না যে। এটি মধ্যপদলোপী বহুব্রীহি সমাস। অত্যন্ত অলস ব্যক্তি বোঝাতে এটি ব্যবহৃত হয়।', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '33f2e42f5de3a63031b45c4e27d59331'),
(6549, 661, 'কোন দুটি অঘোষ ধ্বনি?', 'চ ছ', NULL, 'ড ঢ', NULL, 'ব ভ', NULL, 'দ ধ', NULL, 'A', 'অঘোষ ধ্বনি হলো যে ধ্বনি উচ্চারণে স্বরযন্ত্রের অনুনাসিক কোমলমণ্ডলের সংযোগ থাকে না। চ, ছ, ক, খ, ত, থ, প, ফ, শ, ষ, স অঘোষ ধ্বনি। ড, ঢ, ব, ভ, দ, ধ ঘোষ ধ্বনি।', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-23', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9eb8de8a83fed1f1157a4717403608a4'),
