(7462, 690, 'বাংলাদেশ গণপ্রজাতন্ত্রীর ঘোষণা ছিলো–', '১৭ এপ্রিল, ১৯৭১', NULL, '২৬ মার্চ, ১৯৭১', NULL, '১১ এপ্রিল, ১৯৭১', NULL, '১০ জানুয়ারি, ১৯৭২', NULL, 'B', 'মেহেরপুর জেলার মুজিবনগরে ১৯৭১ সালের ১০ এপ্রিল গণপ্রজাতন্ত্রী বাংলাদেশের অস্থায়ী সরকার গঠিত হয় এবং ১৭ এপ্রিল শপথ গ্রহণ করে। ১৭ এপ্রিল অধ্যাপক এম. ইউসুফ আলী স্বাধীনতার ঘোষণাপত্র পাঠ করেন। তবে বাংলাদেশের স্বাধীনতা ঘোষণা করা হয় ২৬ মার্চ ১৯৭১ তারিখে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a505223ebd777ca379a7a6341aa8a524'),
(7463, 721, 'গণপ্রজাতন্ত্রী বাংলাদেশের সংবিধান প্রবর্তিত হয়–', '১৭ এপ্রিল, ১৯৯১', NULL, '১৬ ডিসেম্বর, ১৯৭২', NULL, '৭ মার্চ, ১৯৭২', NULL, '২৬ মার্চ, ১৯৭৩', NULL, 'B', '১৯৭২ সালের ১১ জানুয়ারি অস্থায়ী সংবিধান আদেশ জারির পর ২৩ জুন রাষ্ট্রপতি গণপরিষদ আদেশ জারি করেন। ১০ এপ্রিল গণপরিষদের প্রথম অধিবেশন বসে। এ অধিবেশনে খসড়া সংবিধান প্রণয়নের জন্য ৩৪ সদস্যবিশিষ্ট একটি কমিটি গঠন করা হয়। এ কমিটির সভাপতি ছিলেন ড. কামাল হোসেন। এ কমিটি গণপরিষদে খসড়া সংবিধান পেশ করে ১৯৭২ সালের ১২ অক্টোবর, যা ৪ নভেম্বর গণপরিষদ কর্তৃক গৃহীত হয় এবং ১৯৭২ সালের ১৬ ডিসেম্বর থেকে কার্যকর হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '74b81d81ad12bbd8fbe6420ace8e2300'),
(7464, 682, 'বিখ্যাত সাধক শাহ্ সুলতান বলখীর মাজার কোথায়?', 'মহাস্থানগড়ে', NULL, 'শাহজাদপুরে', NULL, 'নেত্রকোনায়', NULL, 'রামপালে', NULL, 'A', 'বিখ্যাত \"শাহ্ সুলতান বলখী মহীসওয়ার\" এর মাজারটি বগুড়া শহর থেকে ১০ কি.মি. দূরে মহাস্থানের দক্ষিণ-পূর্ব কোণে অবস্থিত। মহাস্থানগড়ের প্রধান নিদর্শনগুলো হলো বৈরাগী ভিটা, গোবিন্দ ভিটা, খোদাই পাথর ভিটা, সভাবাটি, শীলা দেবীর ঘাট, পরশুরামের প্রাসাদ ইত্যাদি।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e8b359f37a386f78187dc3f7f7dc5592'),
(7465, 750, 'বাংলাদেশের লোক শিল্প জাদুঘর কোথায় অবস্থিত?', 'চট্টগ্রামে', NULL, 'বগুড়ায়', NULL, 'সোনারগাঁওয়ে', NULL, 'রামপালে', NULL, 'C', 'বাংলাদেশের লোকশিল্পের অতীত কীর্তিসমূহ (নক্‌শী কাঁথা, মাটির পাত্র, বেত, কাঁসা, মসলিন বস্ত্র, তৈজসপত্র ইত্যাদি) সংরক্ষণের জন্য নারায়ণগঞ্জ জেলার সোনারগাঁওয়ে লোকশিল্প জাদুঘর স্থাপন করা হয়েছে। ১৯৯৬ সালের ৬ অক্টোবর সোনারগাঁও লোক ও কারুশিল্প ফাউন্ডেশনের নাম পরিবর্তন করে \"শিল্পাচার্য জয়নুল আবেদিন\" জাদুঘর করা হয়েছে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2672ad8d04bce8a9c52be5b6a256cced'),
(7466, 681, 'বাংলায় ইউরোপীয় বণিকদের মধ্যে বাণিজ্যের উদ্দেশ্যে প্রথম এসেছিল-', 'ইংরেজরা', NULL, 'ওলন্দাজরা', NULL, 'ফরাসিরা', NULL, 'পর্তুগিজরা', NULL, 'D', 'পঞ্চদশ শতকের শেষভাগে পর্তুগিজ নাবিক ভাস্কো-দা-গামা আফ্রিকার পশ্চিম-পূর্ব উপকূলে ঘুরে বরাবর সমুদ্রপথে ভারতবর্ষে আসার পথ আবিষ্কার করেন। ১৫১৪ খ্রিষ্টাব্দে পর্তুগিজ বণিকগণ উড়িষ্যার অন্তর্গত পিপলি নামক স্থানে সর্বপ্রথম বাণিজ্য কুঠি স্থাপন করে। ১৫৩৬ খ্রিষ্টাব্দে বাংলার সুলতান মাহমুদ শাহ শের শাহের বিরুদ্ধে পর্তুগিজদের সাহায্যের আশায় চট্টগ্রাম ও সপ্তগ্রামে (হুগলি) বাণিজ্য কুঠি নির্মাণের অনুমতি দেন। এভাবে বাংলায় পর্তুগিজদের প্রতিষ্ঠা হয়। উল্লেখ্য, ১৬০২ সালে ওলন্দাজরা, ১৬০০ সালে ইংরেজরা এবং ১৬৬৪ সালে ফরাসিরা বাংলায় আগমন করেন।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ae555b25b61216da16c84d3690cdaa68'),
(7467, 681, 'বাংলা নববর্ষ পহেলা বৈশাখ চালু করেছিলেন-', 'লক্ষ্মণ সেন', NULL, 'ইলিয়াস শাহ', NULL, 'আকবর', NULL, 'বিজয় সেন', NULL, 'C', 'কৃষিকাজের সুবিধার্থে মোগল সম্রাট আকবর ১৫৮৪ খ্রিষ্টাব্দের ১০/১১ মার্চ বাংলা সন প্রবর্তন করেন এবং তা ১৫৫৬ সালের ৫ নভেম্বর তার সিংহাসনে আরোহণের সময় থেকে কার্যকর হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dfbba01410f7e4bfdfdf64e840d4a883'),
(7468, 682, 'পাহাড়পুরের বৌদ্ধ বিহারটি কি নামে পরিচিত ছিল?', 'সোমপুর বিহার', NULL, 'ধর্মপাল বিহার', NULL, 'জগদ্দল বিহার', NULL, 'শ্রী বিহার', NULL, 'A', 'নওগাঁ জেলার বদলগাছি উপজেলার পাহাড়পুরে অবস্থিত বৌদ্ধ বিহারের নাম পাহাড়পুর বা সোমপুর বিহার। এর নির্মাতা ধর্মপাল ছিলেন পাল বংশের শ্রেষ্ঠ রাজা। এটি মধ্যযুগীয় সবচেয়ে বড় বিহার।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cdb6484c52e8458ad5cd77f157664de5'),
(7469, 696, 'বাংলাদেশে চীনামাটির সন্ধান পাওয়া গেছে–', 'বিজয়পুরে', NULL, 'রানীগঞ্জে', NULL, 'টেকেরহাটে', NULL, 'বিয়ানী বাজারে', NULL, 'A', 'পাকিস্তান ভূতাত্ত্বিক জরিপ অধিদপ্তর (বর্তমান বাংলাদেশ ভূতাত্ত্বিক জরিপ অধিদপ্তর) ১৯৫৭ সালে নেত্রকোণা জেলার দুর্গাপুর উপজেলার ভেদিকুরা নামক স্থানে প্রথম চীনামাটির সন্ধান লাভ করে। এ চীনামাটিকে বিজয়পুর চীনামাটি নামকরণ করা হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fecccff3c0b26fcfcf30b8e9f0b7b0a4'),
(7470, 750, 'ঢাকা বিশ্ববিদ্যালয় প্রতিষ্ঠিত হয়–', '১৮৯৭ সালে', NULL, '১৯০২ সালে', NULL, '১৯২১ সালে', NULL, '১৯০৫ সালে', NULL, 'C', 'বঙ্গভঙ্গ রদ হলে ব্রিটিশরা পূর্ববঙ্গে একটি বিশ্ববিদ্যালয় প্রতিষ্ঠার ঘোষণা দেয় এবং এজন্য ১৯১২ সালে ১৩ সদস্য বিশিষ্ট নাথান কমিশন গঠিত হয়। ঢাকার নবাব সলিমুল্লাহ ঢাকা বিশ্ববিদ্যালয়ের জন্য জমি দান করেন। কলকাতার হিন্দুদের ব্যাপক বিরোধিতা সত্ত্বেও ১৯২১ সালে ঢাকা বিশ্ববিদ্যালয় চালু হয়। পরবর্তীতে এটি প্রাচ্যের অক্সফোর্ড নামে খ্যাতি অর্জন করে।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '79a5aa41bc566136ee651713f629a2f8'),
(7471, 750, 'ঢাকার বিখ্যাত তারা মসজিদ তৈরী করনে–', 'শায়েস্তা খান', NULL, 'নওয়াব সলিমুল্লাহ', NULL, 'মির্জা আহমেদ জান', NULL, 'খান সাহেব আবুল হাসনাত', NULL, 'C', 'পুরানো ঢাকার আরমানিটোলা এলাকায় তারা মসজিদ অবস্থিত। মসজিদটি নির্মাণ করেন মির্জা আহমেদ জান বা মির্জা গোলাম পীর। পরবর্তী ১৯২৬ সালে আলীজান বেপারী নামক একজন ব্যবসায়ী মসজিদটির সংস্কার করেন। আলীজান বেপারী বহু অর্থ ব্যয়ে মসজিদটিকে অলঙ্কৃত করেন, বিশেষ করে সমস্ত মসজিদটি তারকাখঁচিত করেন। এ কারণে এর বর্তমান নাম তারা মসজিদ।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd195c549616ed8dd41cab7da651bd796'),
(7472, 696, 'পাখি ছাড়া \"বলাকা\" ও \"দোয়েল\" নামে পরিচিত হচ্ছে-', 'দু\'টি উন্নত জাতের গমশস্য', NULL, 'দু\'টি উন্নত জাতের ধানশস্য', NULL, 'দু\'টি উন্নত জাতের ভুট্টাশস্য', NULL, 'দু\'টি উন্নতজাতের ইক্ষু', NULL, 'B', 'বলাকা ও দোয়েল ছাড়াও উন্নতজাতের আরো কিছু গম শস্য হলো সোনালিকা, আকবর, আনন্দ, কাঞ্চন, বরকত, অগ্রণী, ইনিয়া ৬৬, জোপাটিকা। (দ্রষ্টব্য: প্রশ্নপত্রে \"ধান\" উল্লেখ থাকলেও প্রকৃতপক্ষে এগুলো গমের জাত। তবে প্রশ্নের উত্তরে প্রদত্ত অপশন অনুযায়ী B)', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '705f47b0f2295e0626d65d0fc93f3390'),
(7473, 697, '\"অগ্নিশ্বর\", \"কানাইবাঁসি\", \"মোহনবাঁশী\" ও \"বীটজবা\" কি জাতীয় ফলের নাম?', 'পেয়ারা', NULL, 'কলা', NULL, 'পেঁপে', NULL, 'জামরুল', NULL, 'B', 'অগ্নিশ্বর, কানাইবাঁশি, মোহনবাঁশি ও বীটজবা উন্নত জাতের কলার নাম। এছাড়াও বাংলাদেশে আরো কিছু জাতের কলার চাষ হয়, যেমন- অমৃতসাগর, মেহেরসাগর, সবরি, সিঙ্গাপুরী, চাঁপা ইত্যাদি।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ec97f61eba69226e7de1c046d960e83a'),
(7474, 681, 'বাংলায় চিরস্থায়ী বন্দোবস্ত প্রথা প্রবর্তন করা কোন সালে?', '১৭০০ সালে', NULL, '১৭৭২ সালে', NULL, '১৭৬৫ সালে', NULL, '১৭৯৩ সালে', NULL, 'D', 'লর্ড কর্নওয়ালিস ১৭৮৬ সালের ১২ সেপ্টেম্বর থেকে ১৭৯৩ সালের ১০ অক্টোবর পর্যন্ত বাংলায় ফোর্ট উইলিয়ামের গভর্নর জেনারেল ছিলেন। তিনি ছিলেন চিরস্থায়ী বন্দোবস্ত ও বাংলায় ইস্ট ইন্ডিয়া কোম্পানির প্রশাসনিক ও বিচার ব্যবস্থার রূপকার। ১৭৯৩ সালের ২২ মার্চ তিনি \"চিরস্থায়ী বন্দোবস্ত\" প্রথা চালুর মাধ্যমে সূর্যাস্ত আইন বলবৎ করেন।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a6d900eae8e778e76aa7eb667d1621e3'),
(7475, 681, 'কোন মুঘল সম্রাট বাংলার নাম দেন \"জান্নাতাবাদ\"?', 'বাবর', NULL, 'হুমায়ুন', NULL, 'আকবর', NULL, 'জাহাঙ্গীর', NULL, 'B', 'মুঘল সম্রাট হুমায়ূন বাংলার নাম দেন \"জান্নাতাবাদ\"। বাবরের মৃত্যুর পর জ্যেষ্ঠপুত্র হুমায়ূন সিংহাসনে আরোহণ করেন।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e8b5c7a151a8d467cf49146759851e53'),
(7476, 749, 'উপমহাদেশীয়দের মধ্যে ঢাকা বিশ্ববিদ্যালয়ের প্রথম ভাইস চ্যান্সেলর-', 'ড. রমেশচন্দ্র মজুমদার', NULL, 'ড. মাহমুদ হাসান', NULL, 'ড. সৈয়দ মোয়াজ্জেম হোসেন', NULL, 'স্যার এ. এফ. রহমান', NULL, 'D', 'ঢাকা বিশ্ববিদ্যালয়ের প্রথম ভাইস চ্যান্সেলর বা উপাচার্য ছিলেন স্যার ফিলিপ জোসেফ হার্টগ। স্যার এ. এফ. রহমান ছিলেন প্রথম ভারতীয় এবং মুসলমান উপাচার্য। ঢাকা বিশ্ববিদ্যালয়ের ছাত্রদের মধ্যে প্রথম উপাচার্য ছিলেন ড. সৈয়দ মোয়াজ্জেম হোসেন।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9a306f794d5381e8561d8b6f0ea32a88'),
(7477, 752, '১৯৮৮ সালের সিউল অলিম্পিকে বাংলাদেশের কোন ভাস্করের শিল্পকর্ম প্রদর্শনীতে স্থান পায়?', 'শামীম সিকদার', NULL, 'সৈয়দ আব্দুল্লাহ খালেদ', NULL, 'হামিদুজ্জামান খান', NULL, 'আবদুস সুলতান', NULL, 'C', '১৯৮৮ সালের সিউল অলিম্পিকের পার্কে হামিদুজ্জামান খানের \"স্টেপস্\" ভাস্কর্যটি স্থান পেয়েছিল। হামিদুজ্জামান খানের উল্লেখযোগ্য স্থাপত্য হলো \"সংশপ্তক\" (জাহাঙ্গীরনগর বিশ্ববিদ্যালয়), \"স্বাধীনতা\" (কাজী নজরুল ইসলাম এভিনিউ, ঢাকা) এবং \"ক্যাম্পাস\" (ঢাকা বিশ্ববিদ্যালয়)।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7ad187c61d5778e5776ee40520c5211d'),
(7478, 681, 'ঢাকায় সর্বপ্রথম কবে বাংলার রাজধানী স্থাপিত হয়?', '১২০৬ খ্রিঃ', NULL, '১৩১০ খ্রিঃ', NULL, '১৫২৬ খ্রিঃ', NULL, '১৬১০ খ্রিঃ', NULL, 'D', 'সম্রাট জাহাঙ্গীর সিংহাসনে আরোহণ করে ইসলাম খান চিশতীকে বাংলা অধিকারে প্রেরণ করেন। ইসলাম খান ১৬১০ সালে মুসা খানকে পরাজিত করে বাংলা অধিকার করেন এবং ঢাকার নামকরণ করেন \"জাহাঙ্গীরনগর\"। তিনি এ সময় রাজমহল থেকে ঢাকায় রাজধানী স্থানান্তর করেন। উল্লেখ্য, ঢাকাকে ১৬১০ সালের পর ১৯০৫ সালে দ্বিতীয় বার, ১৯৪৭ সালে তৃতীয় বার ও ১৯৭১ সালে চতুর্থ বার রাজধানী করা হয়।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f827361a2606b56a2dd6ed4d5684b018'),
(7479, 681, '\"পূর্বাশা\" দ্বীপের অপর নাম–', 'নিঝুম দ্বীপ', NULL, 'সেন্টমার্টিন দ্বীপ', NULL, 'দক্ষিণ তালপট্টি দ্বীপ', NULL, 'দিয়া দ্বীপ', NULL, 'C', 'দক্ষিণ তালপট্টি দ্বীপটি সাতক্ষীরা জেলার দক্ষিণে সীমান্ত নদী হাড়িয়াভাঙ্গা ও রায়মঙ্গল নদীর মোহনায় অবস্থিত। এ দ্বীপটি বাংলাদেশের সীমানায় অবস্থিত হলেও ভারত এ দ্বীপের মালিকানা দাবি করে। ভারত এ দ্বীপের নাম দিয়েছে \"পূর্বাশা\" বা \"নিউমুর\"। বর্তমানে এ দ্বীপটির অস্তিত্ব নেই।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '89082e891c214df857321caac1c544d1'),
(7480, 750, '\"_____ সেপ্টেম্বর বিশ্ব নিরক্ষরতা দিবস।\" শূন্যস্থান পূরণ করুন।', '৮', NULL, '৬', NULL, '১০', NULL, '৫', NULL, 'A', 'বিশ্ব নিরক্ষরতা দিবস পালিত হয় ৮ সেপ্টেম্বর। (দ্রষ্টব্য: প্রশ্নে \"নিরক্ষরতা\" এর স্থলে \"সাক্ষরতা\" হবে)', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ce84405a81dc0a8febad4e88f90ceaa2'),
(7481, 682, 'বাংলাদেশের জাতীয় পতাকার মাপের অনুপাত কত?', '৯ : ৫', NULL, '৯ : ৫', NULL, '১০ : ৬', NULL, '৮ : ৬', NULL, 'C', 'বাংলাদেশের বর্তমান জাতীয় পতাকার রূপকার প্রখ্যাত চিত্রশিল্পী কামরুল হাসান। জাতীয় পতাকার প্রথম নকশা করেছিলেন শিব নারায়ণ দাস এবং ইউসুফ সালাউদ্দিনকে নিয়ে হাসানুল হক ইনু; প্রকৌশল বিশ্ববিদ্যালয়ের শেরে বাংলা হলের ৪০১ নং কক্ষে। বাংলাদেশের জাতীয় পতাকা প্রথম উত্তোলন হয় ঢাকা বিশ্ববিদ্যালয়ের বটতলায় এক ছাত্রসভায় ২ মার্চ ১৯৭১। বাংলাদেশের জাতীয় পতাকার মাপের অনুপাত ১০ : ৬।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '372d106c9dbdf51c55e6614f5fca974a'),
(7482, 681, 'বাংলাদেশের বৃহত্তম নদী কোনটি?', 'মেঘনা', NULL, 'পদ্মা', NULL, 'ব্রহ্মপুত্র', NULL, 'যমুনা', NULL, 'A', 'দৈর্ঘ্য, প্রস্থ ও গভীরতায় দেশের বৃহত্তম নদী মেঘনা।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd6eec26566204f7434cd5fe0a0c72f3b'),
(7483, 696, 'কোন জেলা তুলা চাষের জন্য সবচেয়ে বেশি উপযোগী?', 'রাজশাহী', NULL, 'ফরিদপুর', NULL, 'রংপুর', NULL, 'যশোর', NULL, 'D', 'কৃষি পরিসংখ্যান বর্ষগ্রন্থ ২০১৯ অনুসারে বর্তমানে তুলা উৎপাদনে শীর্ষ জেলা ঝিনাইদহ। পাট উৎপাদনে শীর্ষ জেলা ফরিদপুর। আম উৎপাদনে শীর্ষ জেলা রাজশাহী। তামাক উৎপাদনে শীর্ষ জেলা কুষ্টিয়া।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '403e705f3a47e3fbebce605ef5e2f000'),
