(7486, 682, 'বাংলাদেশে শহীদ বুদ্ধিজীবী দিবস পালিত হয়-', '২৬ মার্চ', NULL, '১৬ ডিসেম্বর', NULL, '২১ ফেব্রুয়ারি', NULL, '১৪ ডিসেম্বর', NULL, 'D', 'বাংলাদেশের মুক্তিযুদ্ধে বাঙালিদের বিজয় নিশ্চিত দেখে পাকবাহিনী ১৯৭১ সালের ১৪ ডিসেম্বর নির্বিচারে বহু বুদ্ধিজীবী হত্যা করে। তাই তাদের স্মরণে ১৪ ডিসেম্বরকে \"শহীদ বুদ্ধিজীবী দিবস\" হিসেবে পালন করা হয়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '986a33af21e597832854a27f232ffd9c'),
(7487, 681, 'বাংলাদেশের কোন বনভূমি শালবৃক্ষের জন্য বিখ্যাত?', 'সিলেটের বনভূমি', NULL, 'পার্বত্য চট্টগ্রামের বনভূমি', NULL, 'ভাওয়াল ও মধুপুরের বনভূমি', NULL, 'খুলনা, বরিশাল ও পটুয়াখালীর বনভূমি', NULL, 'C', 'ভাওয়াল ও মধুপুরের বনভূমি গাজীপুর, টাঙ্গাইল ও ময়মনসিংহ জেলায় অবস্থিত। এ বনে প্রচুর শালগাছ রয়েছে। উল্লেখ্য, অঞ্চল হিসেবে বাংলাদেশের বৃহত্তম বনভূমি চট্টগ্রাম-রাঙামাটি বনভূমি এবং একক হিসেবে বৃহত্তম সুন্দরবন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bb44de927df74c3d2c19d6ef00f17183'),
(7488, 750, 'চীন-বাংলাদেশ মৈত্রী সেতু-১ নির্মাণের প্রধান উদ্দেশ্য–', 'ঢাকা শহরকে নদীর ওপারে বিস্তৃত করা', NULL, 'বাংলাদেশ ও চীনের মধ্যে সুসম্পর্কের স্থায়ী বন্ধন সৃষ্টি করা', NULL, 'ঢাকা-আরিচা রোড যানবাহন চলাচলের চাপ কমানো', NULL, 'দেশের দক্ষিণ অঞ্চলের সাথে ঢাকার পরিবহন ব্যবস্থা উন্নত করা', NULL, 'C', 'এটি বুড়িগঙ্গা নদীর উপর ঢাকার পোস্তগোলা নামক স্থানে নির্মিত হয়েছে। এটিই প্রথম বুড়িগঙ্গা সেতু। সেতুর দৈর্ঘ্য ৭৮০ মিটার। তবে দ্বিতীয় বুড়িগঙ্গা সেতু নির্মিত হয় ঢাকার বাবুবাজারে এবং এ সেতুর মাধ্যমে কেরানীগঞ্জের সাথে সড়ক যোগাযোগ প্রতিষ্ঠিত হয়েছে। এ সেতুর দৈর্ঘ্য ৭২৫ মিটার।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '94b066b53d9ba8e3e1044c86baa80497'),
(7489, 696, 'হরিপুরে তেল আবিষ্কৃত হয়–', '১৯৪৭ সালে', NULL, '১৯৮৬ সালে', NULL, '১৯৮৫ সালে', NULL, '১৯৮৪ সালে', NULL, 'B', 'বাংলাদেশের পূর্বাঞ্চলের সিলেট শহর থেকে ২৪ কিলোমিটার দূরে গোয়াইনঘাট উপজেলার হরিপুরে বাংলাদেশের প্রধান তেলক্ষেত্রটি অবস্থিত। ১৯৮৬ সালের ২২ ডিসেম্বর হরিপুর গ্যাসক্ষেত্রে খননকৃত সপ্তম কূপে তেল পাওয়া যায়। উল্লেখ্য, হরিপুরে বাংলাদেশের প্রথম গ্যাসক্ষেত্র আবিষ্কৃত হয় ১৯৫৫ সালে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f7c59df4daecbc10d5178f1020a0ef76'),
(7490, 749, 'মিশুকের স্থপতি কে?', 'মুস্তফা মনোয়ার', NULL, 'হামিদুর রহমান', NULL, 'শামীম শিকদার', NULL, 'হামিদুজ্জামান খান', NULL, 'A', 'এটি ঢাকার শাহবাগে শিশু পার্কের সামনে অবস্থিত। সাফ গেমসের মাসকট হিসেবে শিল্পী মুস্তফা মনোয়ার মিশুক তৈরি করেন। এটি মূলত হরিণ শাবকের ভাস্কর্য।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e6a5588bf2989187931a0b57169d4a00'),
(7491, 696, 'বাংলাদেশের কোন জেলায় সবচেয়ে বেশি পাট উৎপন্ন হয়?', 'রংপুর', NULL, 'ময়মনসিংহ', NULL, 'টাঙ্গাইল', NULL, 'ফরিদপুর', NULL, 'D', 'বর্তমানে পাট উৎপাদনে শীর্ষ জেলা ফরিদপুর। ধান, কাঁঠাল ও মাছ উৎপাদনে শীর্ষ জেলা ময়মনসিংহ।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cd74dfeea05e40f10da40a1c69632336'),
(7492, 696, 'বাংলাদেশের মোট আবাদযোগ্য জমির পরিমাণ প্রায় কত?', '২ কোটি ৪০ লক্ষ একর', NULL, '২ কোটি ৫০ লক্ষ একর', NULL, '২ কোটি একর', NULL, '২ কোটি ২৫ লক্ষ একর', NULL, 'A', 'কৃষি পরিসংখ্যানের ধান গবেষণা ইনস্টিটিউটের সর্বশেষ তথ্য অনুযায়ী বাংলাদেশের মোট আবাদযোগ্য জমির পরিমাণ ৮৮.২৯ লক্ষ হেক্টর (প্রায় ২ কোটি ৪০ লক্ষ একর)।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3c5f0ef9606a02231c675b6b6805e27b'),
(7493, 681, 'উপকূল হতে বাংলাদেশের অর্থনৈতিক সমুদ্রসীমা কত?', '২৫০ নটিক্যাল মাইল', NULL, '২০০ নটিক্যাল মাইল', NULL, '২২৫ নটিক্যাল মাইল', NULL, '১০ নটিক্যাল মাইল', NULL, 'B', 'বাংলাদেশের মোট সীমান্ত দৈর্ঘ্য ৫১৩৮ কি.মি.। এর মধ্যে ভারত সংলগ্ন স্থল ও নৌ সীমান্ত এলাকার দৈর্ঘ্য ৪১৫৬ কিলোমিটার এবং মিয়ানমারের সাথে রয়েছে ২৭১ কিলোমিটার দীর্ঘ সীমান্ত। অন্যদিকে মোট জলসীমার পরিমাণ ৭১১ কিলোমিটার। সেই সাথে বঙ্গোপসাগর তীরবর্তী দেশ হওয়ায় এ দেশের ভূখণ্ডগত (রাজনৈতিক) সমুদ্রসীমা ১২ নটিক্যাল মাইল (২২.২২ কি.মি.) এবং অর্থনৈতিক সমুদ্রসীমা উপকূল থেকে ২০০ নটিক্যাল মাইল (৩৭০.৪০ কি.মি.) পর্যন্ত বিস্তৃত।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '40d3e19c96f81b83b7f5afd9ab68fa44'),
(7494, 681, 'মহাস্থানগড় কোন নদীর তীরে অবস্থিত?', 'করতোয়া', NULL, 'গঙ্গা', NULL, 'ব্রহ্মপুত্র', NULL, 'মহানন্দা', NULL, 'A', 'বাংলার প্রাচীনতম জনপদ হলো বগুড়া জেলায় অবস্থিত মহাস্থানগড়, যা একসময় মৌর্য ও গুপ্ত বংশের রাজাদের রাজধানী ছিল। তখন এর নাম ছিল পুণ্ড্রনগর। মহাস্থানগড় করতোয়া নদীর তীরে অবস্থিত।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9cbf2bd904f7df7538db8a66a51f0a27'),
(7495, 711, 'ঔষধ নীতির প্রধান উদ্দেশ্য হলো–', 'অপ্রয়োজনীয় এবং ক্ষতিকর ঔষধ প্রস্তুত বন্ধ করা', NULL, 'ঔষধ শিল্পে দেশীয় কাঁচামালের ব্যবহার নিশ্চিত করা', NULL, 'ঔষধ শিল্পে দেশীয় শিল্পপতিদের অগ্রাধিকার দেয়া', NULL, 'বিদেশী শিল্পপতিদের দেশীয় কাঁচামাল ব্যবহারে বাধ্য করা', NULL, 'A', '১৯৮২ সালে প্রথমবারের মতো জাতীয় ঔষুধ নীতি প্রণয়ন করা হয়। কারণ এর আগে ঔষুধ উৎপাদন ও ব্যবহারের বিষয়ে কোনো ধরনের নীতিমালা ছিলো না। ২০০৫ সালে এই নীতি নবায়ন করা হয় এবং ২০১৬ সালে আবার এই জাতীয় ঔষুধ নীতি জন সাধারণের কাছে পৌঁছে দেওয়া জাতীয় ঔষুধ নীতির লক্ষ্য।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '81ca5f4612c862a38ba153a3731a02ad'),
(7496, 752, 'বিকেএসপি হলো–', 'একটি ক্রীড়া শিক্ষা সংস্থার নাম', NULL, 'একটি সংবাদ সংস্থার নাম', NULL, 'একটি কিশোর ফুটবল টিমের নাম', NULL, 'একটি সঙ্গীত শিক্ষা প্রতিষ্ঠানের নাম', NULL, 'A', 'বাংলাদেশ ক্রীড়া শিক্ষা প্রতিষ্ঠান (বিকেএসপি) ঢাকা শহর থেকে ৪০ কিলোমিটার দূরে সাভারের জিরানীতে অবস্থিত। ১৯৮৬ সালের ১৪ এপ্রিল আনুষ্ঠানিকভাবে এর উদ্বোধন করা হয় ও নাম পরিবর্তন করে \"বাংলাদেশ ক্রীড়া শিক্ষা প্রতিষ্ঠান\" রাখা হয়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '69cd9134f79bfcc199d14295f7a90186'),
(7497, 752, 'মা ও মনি হলো–', 'একটি উপন্যাসের নাম', NULL, 'একটি প্রসাধনী শিল্পের নাম', NULL, 'একটি ক্রীড়া প্রতিযোগিতার নাম', NULL, 'একটি গরিব মা ও মেয়ের গল্প কাহিনী', NULL, 'C', 'মা ও মনি গোল্ডকাপ (১৪ বছরের নিচে) টুর্নামেন্ট ১৯৯২ সালের ২৬ আগস্ট থেকে ৩ সেপ্টেম্বর পর্যন্ত ঢাকার জাতীয় স্টেডিয়ামে অনুষ্ঠিত হয়। জেলাভিত্তিক এ ফুটবল টুর্নামেন্টে ফাইনালে খেলে টাঙ্গাইল জেলা দল ২-১ গোলে ফেনী জেলা দলকে হারায়।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '72519364c3ce1f7c0414b6a52fbe0332'),
(7498, 681, 'প্রাচীন \"চন্দ্রদ্বীপ\"- এর বর্তমান নাম–', 'মালদ্বীপ', NULL, 'সন্দ্বীপ', NULL, 'বরিশাল', NULL, 'হাতিয়া', NULL, 'C', 'রামপাল তাম্রশাসনে ত্রৈলোক্য চন্দ্রের শাসনাধীন ভূখণ্ড রূপে চন্দ্রদ্বীপের উল্লেখ রয়েছে। মধ্যযুগে চন্দ্রদ্বীপ ছিল বর্তমান বরিশাল জেলার অংশবিশেষের মাঝে সীমাবদ্ধ একটি উল্লেখযোগ্য স্থান। প্রাচীনকালে বরিশাল চন্দ্রদ্বীপ ও বাকলা ছাড়াও ইসমাইলপুর এবং পোর্টগ্রান্ডে নামেও পরিচিত ছিল।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6d84f5a15cb22bddc57c3709402d3a9e'),
(7499, 750, 'ঢাকা থেকে সরাসরি নোয়াখালী যাওয়ার আন্তঃমহানগরীয় ট্রেনটির নাম-', 'এগার সিন্দুর এক্সপ্রেস', NULL, 'পারাবত এক্সপ্রেস', NULL, 'উপকূল এক্সপ্রেস', NULL, 'সৈকত এক্সপ্রেস', NULL, 'C', 'এগার সিন্দুর এক্সপ্রেস ঢাকা-কিশোরগঞ্জ, পারাবত এক্সপ্রেস ঢাকা-সিলেট, উপকূল এক্সপ্রেস ঢাকা-নোয়াখালী যাওয়ার আন্তঃমহানগরীয় ট্রেনের নাম।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd51f831a5468190512e0632889a54ab1'),
(7500, 681, 'বাংলাদেশের বৃহত্তম হাওর-', 'পাথরচাওলি', NULL, 'হাইল', NULL, 'চলনবিল', NULL, 'হাকালুকি', NULL, 'D', 'বাংলাদেশের সবচেয়ে বড় হাওর হাকালুকি। সিলেট জেলার গোলাপগঞ্জ, বিয়ানিবাজার, ফেঞ্চুগঞ্জ, বালাগঞ্জ এবং মৌলভীবাজার জেলার বড়লেখা, কুলাউড়া প্রভৃতি উপজেলা নিয়ে এ হাওরের বিস্তৃতি।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '92b5a9c93dbc32000a6517513b3b6fdc'),
(7501, 681, 'কিওক্রাডং-এর উচ্চতা প্রায়-', '১০১০ মিটার', NULL, '১৫৩০ মিটার', NULL, '১২৩২ মিটার', NULL, '১৩৬৪ মিটার', NULL, 'C', 'টেক্সট বুক বোর্ড প্রকাশিত মাধ্যমিক ভূগোল বইয়ের তথ্য মতে, কিওক্রাডং-এর উচ্চতা ১২৩০ মিটার বা ৪০৫৩.৪৩ ফুট। অন্যদিকে, বান্দরবান জেলা প্রশাসকের ওয়েবসাইট www.dcbandarban.gov.bd-এর তথ্য মতে, কিওক্রাডং-এর উচ্চতা ৮৮৩ মিটার। এটি বাংলাদেশের দ্বিতীয় সর্বোচ্চ পর্বতশৃঙ্গ।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '12923f2c26a65ead042c14bc9a6c8bad'),
(7502, 696, 'বাংলাদেশে বার্ষিক চা উৎপাদনের পরিমাণ হচ্ছে প্রায়-', '১৪ কোটি পাউন্ড', NULL, '১৩ কোটি পাউন্ড', NULL, '১০.৫ কোটি পাউন্ড', NULL, '৯.৫ কোটি পাউন্ড', NULL, 'C', 'বাংলাদেশ চা বোর্ডের তথ্যমতে, বার্ষিক চা উৎপাদন ১০.৪২ কোটি কেজি (প্রায় ১০.৫ কোটি পাউন্ড)।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ee8b77073e3352f3a9de51df2925a369'),
(7503, 681, 'ঢাকা মেট্রোপলিটন এলাকার আয়তন প্রায়-', '১০০ বর্গমাইল', NULL, '৯০ বর্গমাইল', NULL, '১৬০ বর্গমাইল', NULL, '৮০ বর্গমাইল', NULL, 'C', '২৯ নভেম্বর ২০১১ জাতীয় সংসদে স্থানীয় সরকার (সিটি কর্পোরেশন) (সংশোধন) বিল ২০১১ পাশ হওয়ায় বর্তমানে ঢাকায় সিটি কর্পোরেশন দুটি। উত্তর ও দক্ষিণ সিটি কর্পোরেশন-এর আয়তন যথাক্রমে ৮২.৬৪ বর্গ কি.মি. এবং ৪৭.২১ বর্গ কি.মি.। ঢাকা মেট্রোপলিটন সিটির আয়তন ১৫৩০ বর্গ কি.মি. (প্রায় ১৬০ বর্গমাইল)।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '59770f81d9af6ffde902bb1631335cb4'),
(7504, 696, 'একটি কাঁচা পাটের গাইটের ওজন-', '৩.৫ মণ', NULL, '৫ মণ', NULL, '৪.৫ মণ', NULL, '৫ মণ', NULL, 'B', 'একটি কাঁচা পাটের গাইটের ওজন ৫ মণ।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bd38f2418a1e94cd7f71d8322fbe5e38');
