(7544, 681, 'যমুনা নদী কোথায় পতিত হয়েছে?', 'পদ্মায়', NULL, 'বঙ্গোপসাগরে', NULL, 'ব্রহ্মপুত্রে', NULL, 'মেঘনায়', NULL, 'A', 'হিমালয়ের কৈলাশ শৃঙ্গের মানস সরোবর থেকে উৎপত্তি লাভ করে যমুনা নদী বাংলাদেশের উত্তর অংশ দিয়ে প্রবেশ করে রাজবাড়ী জেলার গোয়ালন্দ নামক স্থানে পদ্মার সাথে মিলিত হয়েছে। পদ্মা পরে চাঁদপুরের নিকট মেঘনার সাথে মিলিত হয়ে মেঘনা নামে বঙ্গোপসাগরে পতিত হয়েছে।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '05213ed19f57133fbaaf9d458796b89f'),
(7545, 681, 'বাংলাদেশের সবচেয়ে উত্তরের জেলা কোনটি?', 'পঞ্চগড়', NULL, 'ঠাকুরগাঁও', NULL, 'দিনাজপুর', NULL, 'লালমনিরহাট', NULL, 'A', 'বাংলাদেশের সবচেয়ে উত্তরের জেলা হলো পঞ্চগড়। এটি রংপুর বিভাগের অন্তর্গত একটি জেলা।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0590f6191102dec7cf330c85bc11979d'),
(7546, 721, 'বাংলাদেশের সংবিধান সর্বপ্রথম কোন তারিখে গণপরিষদে উত্থাপিত হয়?', '১২ অক্টোবর, ১৯৭২', NULL, '১৬ ডিসেম্বর, ১৯৭২', NULL, '২৬ মার্চ, ১৯৭৩', NULL, '১৬ ডিসেম্বর, ১৯৭৩', NULL, 'A', '১৯৭২ সালের ১১ জানুয়ারি অস্থায়ী সংবিধান আদেশ জারির পর ২৩ জুন রাষ্ট্রপতি গণপরিষদ আদেশ জারি করেন। ১০ এপ্রিল গণপরিষদের প্রথম অধিবেশন বসে। এ অধিবেশনে খসড়া সংবিধান প্রণয়নের জন্য ৩৪ সদস্যবিশিষ্ট একটি কমিটি গঠন করা হয়। এ কমিটির সভাপতি ছিলেন ড. কামাল হোসেন। এ কমিটি গণপরিষদে খসড়া সংবিধান পেশ করে ১৯৭২ সালের ১২ অক্টোবর যা ৪ নভেম্বর গণপরিষদ কর্তৃক গৃহীত হয় এবং ১৯৭২ সালের ১৬ ডিসেম্বর থেকে কার্যকর হয়।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '290a68fce909e52cd97eb53c7f8388f3'),
(7547, 683, '১৯৫২ সালে তৎকালীন ভাষা আন্দোলন কিসের জন্ম দিয়েছিল?', 'এক রাজনৈতিক মতবাদের', NULL, 'এক সাংস্কৃতিক আন্দোলনের', NULL, 'এক নতুন জাতীয় চেতনার', NULL, 'এক নতুন সমাজ ব্যবস্থার', NULL, 'C', 'ভাষা আন্দোলন নিখিল পাকিস্তানের শতকরা ৫৬ ভাগ জনগণের মুখের ভাষা বাংলাকে রাষ্ট্রভাষা হিসেবে স্বীকৃতি আদায়ের আন্দোলন। ভাষা আন্দোলনে এক নতুন জাতীয় চেতনার উন্মেষ ঘটে এবং এ চেতনাই ক্রমে ক্রমে বাঙালি জাতীয়তাবাদের জন্ম দেয়।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c269fb942847fd0e48088cc4d676758c'),
(7548, 696, 'ঘোড়াশাল সার কারখানায় উৎপাদিত সারের নাম কি?', 'টিএসপি', NULL, 'ইউরিয়া', NULL, 'পটাশ', NULL, 'অ্যামোনিয়াম সালফেট', NULL, 'B', 'ঘোড়াশাল সার কারখানা নরসিংদীতে অবস্থিত। এ সার কারখানায় প্রাকৃতিক গ্যাস ব্যবহার করে ইউরিয়া সার উৎপন্ন করা হয়।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd139035d50a9957ef3cdcd20d6061386'),
(7549, 696, 'বাংলাদেশের মৎস্য আইনে কত সেন্টিমিটারের কম দৈর্ঘ্যের রুই জাতীয় মাছের পোনা মারা নিষেধ?', '১৮ সেন্টিমিটার', NULL, '২০ সেন্টিমিটার', NULL, '২৩ সেন্টিমিটার', NULL, '২৫ সেন্টিমিটার', NULL, 'C', 'বাংলাদেশের জাতীয় অর্থনীতিতে মৎস সম্পদের অবদান অনস্বীকার্য। তাই দেশের মৎস সম্পদ সংরক্ষণে সরকার মৎস্য আইনে ২৩ সেন্টিমিটারের (প্রায় ৯ ইঞ্চি) কম দৈর্ঘ্যের রুই (কার্প) জাতীয় মাছ ধরা নিষিদ্ধ করে।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7152aa0c895ce6920ada9fb3ee7d312c'),
(7550, 711, 'বাংলাদেশের প্রধান জাহাজ নির্মাণ কারখানা কোথায় অবস্থিত?', 'নারায়ণগঞ্জ', NULL, 'কক্সবাজার', NULL, 'চট্টগ্রাম', NULL, 'খুলনা', NULL, 'D', 'বাংলাদেশে জাহাজ নির্মাণ ও মেরামত কারখানা ৩টি। এগুলো হলো খুলনা শিপইয়ার্ড, চট্টগ্রাম ডকইয়ার্ড এবং নারায়ণগঞ্জ ডকইয়ার্ড।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1b0c55512bd3bab786b837a61fbd13ac'),
(7551, 704, 'নিচের কোন বাংলাদেশীয় উপজাতির পারিবারিক কাঠামো পিতৃতান্ত্রিক?', 'গারো', NULL, 'সাঁওতাল', NULL, 'খাসিয়া', NULL, 'মারমা', NULL, 'D', 'বাংলাদেশে বসবাসকারী ৫০টি ক্ষুদ্র নৃ-গোষ্ঠীর মধ্যে খাসিয়া ও গারো এ দুটি ক্ষুদ্র নৃ-গোষ্ঠীর পারিবারিক কাঠামো মাতৃতান্ত্রিক। বাকি সব ক্ষুদ্র নৃ-গোষ্ঠীর পারিবারিক কাঠামো পিতৃতান্ত্রিক। মারমা উপজাতির পারিবারিক কাঠামো পিতৃতান্ত্রিক।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2026988ae31e02e2fe4b5ecbc38cbb9b'),
(7552, 719, 'কোন ব্যাংক বাংলাদেশের দরিদ্রতম জনগোষ্ঠীকে ঋণ দিয়ে দেশে ও বিদেশে সুনাম কুড়িয়েছে?', 'কৃষি ব্যাংক', NULL, 'গ্রামীণ ব্যাংক', NULL, 'সমবায় ব্যাংক', NULL, 'ইসলামী ব্যাংক', NULL, 'B', 'গ্রামীণ ব্যাংক ১৯৭৬ সালের প্রকল্প হিসেবে যাত্রা শুরু করে এবং ১৯৮৩ সালের ২ অক্টোবর ব্যাংক হিসেবে চালু হয়। গ্রামীণ ব্যাংকের প্রতিষ্ঠাতা ড. মুহাম্মদ ইউনুস।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '39ae5d9c3f4b3f7ac4efb206951fdebe'),
(7553, 711, 'চন্দ্রঘোনা কাগজ কলের প্রধান কাঁচামাল কি?', 'আখের ছোবড়া', NULL, 'বাঁশ', NULL, 'জারুল গাছ', NULL, 'নল-খাগড়া', NULL, 'B', 'রাঙামাটির চন্দ্রঘোনা কাগজ কলের নাম কর্ণফুলী পেপার মিলস। ১৯৫৩ সালে প্রতিষ্ঠিত এ কাগজ কলটি বাংলাদেশের অন্যতম বৃহত্তম কাগজ কল। পার্বত্য চট্টগ্রামের পাহাড়ি অঞ্চলে প্রচুর বাঁশ জন্মে এবং বাঁশ ব্যবহার করে কর্ণফুলী পেপার মিলে কাগজ তৈরি হয়।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fb88e3d9b431d6b551f61f3891497987'),
(7554, 749, 'বাংলাদেশের জাতীয় পতাকার ডিজাইনার কে?', 'কামরুল হাসান', NULL, 'জয়নুল আবেদিন', NULL, 'হাশেম খান', NULL, 'হামিদুর রহমান', NULL, 'A', 'মানচিত্রখচিত প্রথম জাতীয় পতাকার নকশা তৈরি করেন শিবনারায়ণ দাস। বর্তমান জাতীয় পতাকার ডিজাইন করেন বাংলাদেশের প্রখ্যাত চিত্রশিল্পী কামরুল হাসান। কামরুল হাসান বাংলাদেশের জাতীয় প্রতীকেরও ডিজাইন করেন।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2cb0745ff401d372a586cd6a486a28ac'),
(7555, 690, 'মুজিবনগরে কোন তারিখে স্বাধীনতা ঘোষণা করা হয়েছিল?', '২৬ মার্চ, ১৯৭১', NULL, '১০ এপ্রিল, ১৯৭১', NULL, '৬ সেপ্টেম্বর, ১৯৭১', NULL, '১০ নভেম্বর, ১৯৭১', NULL, 'B', 'মেহেরপুর জেলার মুজিবনগরে ১৯৭১ সালের ১০ এপ্রিল গণপ্রজাতন্ত্রী বাংলাদেশের অস্থায়ী সরকার গঠিত হয় এবং ১৭ এপ্রিল স্বাধীনতার ঘোষণাপত্র গৃহীত হয় এবং শপথ গ্রহণ করে। ১৭ এপ্রিল অধ্যাপক এম ইউসুফ আলী স্বাধীনতার ঘোষণাপত্র পাঠ করেন।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '579dac0fc31255ef16f4937a5691cafa'),
(7556, 692, 'স্বাধীনতা যুদ্ধকালে বাংলাদেশকে কয়টি সেক্টরে ভাগ করা হয়েছিল?', '৯টি', NULL, '১০টি', NULL, '১১টি', NULL, '১২টি', NULL, 'C', 'মুক্তিযুদ্ধ চলাকালীন ৪ এপ্রিল সিলেটে মুক্তিফৌজ গঠিত হয় এবং ৯ এপ্রিল এর নামকরণ করা হয় মুক্তিবাহিনী। পরবর্তীতে ১১ এপ্রিল যুদ্ধ পরিচালনার সুবিধার্থে সমগ্র বাংলাদেশকে ১১টি সেক্টরে বিভক্ত করা হয়।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4b39ac0ff0e1c1094d40046d4c1bc0e5'),
(7557, 750, 'নিম্নের কোন আন্তর্জাতিক সংস্থার সদর দপ্তর বাংলাদেশে অবস্থিত?', 'IJO', NULL, 'APEC', NULL, 'SAARC', NULL, 'ADB', NULL, 'A', 'IJO-এর সদর দপ্তর বাংলাদেশে অবস্থিত ছিল। বর্তমানে এ সংস্থাটি বিলুপ্ত। এর পরিবর্তে আইজেএসজি (IJSG- International Jute Study Group) নামক সংস্থা প্রতিষ্ঠিত হয়েছে এবং এর সদর দপ্তর ঢাকায়। উল্লেখ্য, সিরডাপ (CIRDAP)-এর সদর দপ্তরও বাংলাদেশে অবস্থিত।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd25abf48fba64f50f888fdf64c454689'),
(7558, 681, 'বাংলাদেশে সারা বছর নাব্য নদীপথের দৈর্ঘ্য কত?', '৮,০০০ কিমি.', NULL, '৫,২০০ কিমি.', NULL, '১১,০০০ কিমি.', NULL, '৮,৫০০ কিমি.', NULL, 'B', 'বর্ষাকালে বাংলাদেশের নদীপথের দৈর্ঘ্য ৬,০০০ কিমি.। তবে দেশের নদীগুলোতে পলি পড়ে যাওয়ায় শুকনো মৌসুমে নদীপথ কমে আসছে। উল্লেখ্য, উপনদী ও শাখানদীসহ বাংলাদেশে নদীর মোট দৈর্ঘ্য ২৪,১৪০ কি.মি.। নাব্য নদীপথের দৈর্ঘ্য ৫,২০০ কি.মি.।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e4c6f6c0b8717a512c1ace176f7e7e62'),
(7559, 706, 'বাংলাদেশের GDP-তে কৃষিখাতের অবদান কত শতাংশ?', '৮০', NULL, '৭৫', NULL, '৩২', NULL, '১০', NULL, 'D', 'বাংলাদেশ অর্থনৈতিক সমীক্ষা ২০২২ অনুসারে, বাংলাদেশের GDP-তে কৃষিখাতের অবদান ১১.৫০% (প্রায় ১০%)।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '64b5e038b0bf856293c0d27e477a1f2f'),
