(7561, 681, 'কোন নেতা ফরায়েজী আন্দোলনের নেতৃত্ব দেন?', 'তিতুমীর', NULL, 'সৈয়দ আহমদ বেরেলভি', NULL, 'দুদু মিয়া', NULL, 'হাজী শরীয়তউল্লাহ', NULL, 'D', 'হাজী শরীয়তউল্লাহর নেতৃত্বে মুসলমানদের ফরজ কাজসমূহ পালনে উদ্বুদ্ধ করার আন্দোলন হলো ফরায়েজি আন্দোলন। তার মৃত্যুর পর ফরায়েজি আন্দোলনের নেতৃত্ব দেন তার একমাত্র পুত্র দুদু মিয়া।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6e3d2485ee51786f76bdc59762cb9aad'),
(7562, 681, 'তেঁতুলিয়া কোন জেলায় অবস্থিত?', 'দিনাজপুর', NULL, 'পঞ্চগড়', NULL, 'জয়পুরহাট', NULL, 'লালমনিরহাট', NULL, 'B', 'পঞ্চগড় জেলায় অবস্থিত তেঁতুলিয়া বাংলাদেশের সর্বউত্তরের উপজেলা। বাংলাদেশের সর্বউত্তরের ইউনিয়ন বাংলাবান্ধা ও স্থান জায়গীরজোত।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '95da37e346954f02a9d539c0800dadaa'),
(7563, 681, 'কে বাংলার রাজধানী ঢাকা থেকে মুর্শিদাবাদে স্থানান্তরিত করেন?', 'নবাব সিরাজউদ্দৌলা', NULL, 'নবাব মুর্শিদকুলি খাঁ', NULL, 'সুবাদার ইসলাম খান', NULL, 'নবাব শায়েস্তা খান', NULL, 'B', 'আওরঙ্গজেব দিল্লির সম্রাট হওয়ার পর ১৭০০ খ্রিষ্টাব্দে মুর্শিদকুলী খাঁকে ঢাকার দেওয়ান করে পাঠান। ১৭০১ সালে মুর্শিদকুলী খাঁ তার দপ্তর ঢাকা থেকে পশ্চিমবঙ্গের মকসুদাবাদে স্থানান্তর করেন। তার নাম অনুসারে মকসুদাবাদের নাম হয় মুর্শিদাবাদ।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '03f1a6195c18baf38bad9c924499a8f9'),
(7564, 681, '১৯০৫ সালে নবগঠিত প্রদেশের প্রথম লেফটেন্যান্ট গভর্নর ছিলেন-', 'ব্যামফিল্ড ফুলার', NULL, 'লর্ড মিন্টো', NULL, 'লর্ড কার্জন', NULL, 'ওয়ারেন হেস্টিংস', NULL, 'A', 'লর্ড কার্জন ১৯০৫ সালে বেঙ্গল প্রেসিডেন্সিকে বিভক্ত করলে নবগঠিত পূর্ববাংলা ও আসাম প্রদেশের প্রথম লেফটেন্যান্ট গভর্নর নিযুক্ত হন মি. ব্রামফিল্ড ফুলার।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b059a1e54613be8a43451266e19fdfd3'),
(7565, 681, 'হিমছড়ি কোন শহরের নিকট অবস্থিত?', 'চট্টগ্রাম', NULL, 'খুলনা', NULL, 'কক্সবাজার', NULL, 'রাজশাহী', NULL, 'C', 'কক্সবাজার জেলায় অবস্থিত হিমছড়ি হচ্ছে বাংলাদেশের নৈসর্গিক সৌন্দর্যের অন্যতম লীলাভূমি। হিমছড়ি পর্যটকদের জন্য একটি আকর্ষণীয় স্থান হিসেবে পরিচিত।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7f247acb93b214c6b6b268d6a3e41456'),
(7566, 682, 'বাংলাদেশের কোন অঞ্চলকে \"৩৬০ আউলিয়ার দেশ\" বলা হয়?', 'চট্টগ্রাম', NULL, 'সিলেট', NULL, 'ঢাকা', NULL, 'রাজশাহী', NULL, 'B', 'বাংলাদেশের সিলেট অঞ্চলকে ৩৬০ আউলিয়ার দেশ বলা হয়। শাহজালাল ও তার সফরসঙ্গী ৩৬০ জন আউলিয়ার সিলেট আগমন ইতিহাসের একটি উল্লেখযোগ্য ঘটনা।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '546fd038ff9c0da114085ca0af561113'),
(7567, 696, 'বাংলাদেশের পানি সম্পদের চাহিদা সবচেয়ে বেশি কোন খাতে?', 'আবাসিক', NULL, 'কৃষি', NULL, 'পরিবহন', NULL, 'শিল্প', NULL, 'B', 'বাংলাদেশ কৃষিপ্রধান দেশ। আর কৃষিকার্যের জন্য পানির ব্যবহার অপরিহার্য। তাই বাংলাদেশের পানি সম্পদের চাহিদা সবচেয়ে বেশি কৃষিখাতে।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5d6e5db017fc3ca111334d890f3b2786'),
(7568, 750, 'বাংলাদেশ নিচে উল্লিখিত কোন সময়ের জন্য জাতিসংঘ নিরাপত্তা পরিষদে অস্থায়ী সদস্য নির্বাচিত হয়েছিল?', '১৯৭৮-৭৯', NULL, '১৯৭৯-৮০', NULL, '১৯৮০-৮১', NULL, '১৯৮২-৮৩', NULL, 'B', 'বাংলাদেশ এ পর্যন্ত দুবার জাতিসংঘ নিরাপত্তা পরিষদের অস্থায়ী সদস্য নির্বাচিত হয়। প্রথমবার নির্বাচিত হয় ১০ নভেম্বর, ১৯৭৮ (মেয়াদকাল ১৯৭৯-৮০) এবং দ্বিতীয়বার নির্বাচিত হয় ১৪ অক্টোবর, ১৯৯৯ (মেয়াদকাল ২০০০-২০০১)।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cd33c90deceded41e3d042c9d192a887'),
(7569, 714, 'বাংলাদেশের মোট রপ্তানি আয়ে রেডিমেড গার্মেন্টস-এর অংশ কত?', '৭৫%', NULL, '৫৬%', NULL, '৩৫%', NULL, '৬০%', NULL, 'A', 'ইপিবি এর বার্ষিক প্রতিবেদন ২০২২-২৩ অনুসারে, তৈরি পোশাক খাতে বৈদেশিক মুদ্রা আয়ের পরিমাণ ৪৬,৯৯১.৬১ মিলিয়ন মার্কিন ডলার, যা মোট রপ্তানির ৮৪.৫৭% (প্রায় ৭৫% এর বেশি)।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c9ea913be80aacc6b60c69947eb499b7'),
(7570, 726, 'বাংলাদেশ জাতীয় সংসদের নির্ধারিত আসনে মহিলা সদস্যের সংখ্যা কত?', '৩০', NULL, '৩২', NULL, '৩৫', NULL, '৪০', NULL, 'D', 'বাংলাদেশের প্রথম জাতীয় সংসদ থেকেই মহিলাদের জন্য আসন সংরক্ষণ করে রাখা হয়। সংবিধানের দশম সংশোধনীর মাধ্যমে ৩০, চতুর্দশ সংশোধনীর মাধ্যমে ৪৫ এবং পঞ্চদশ সংশোধনীর মাধ্যমে বর্তমানে নারীদের সংরক্ষিত আসন সংখ্যা ৫০ করা হয়েছে। (দ্রষ্টব্য: পুরাতন প্রশ্নে ৪০ ছিল) বর্তমানে এটি ৫০।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd5131bfb2fba1ecca7980685b8913a78'),
(7571, 750, 'বাংলাদেশের সরকারি মেডিকেল কলেজের সংখ্যা কত?', '৮', NULL, '১০', NULL, '১২', NULL, '১৩', NULL, 'C', 'পুরাতন প্রশ্নে সরকারি মেডিকেল কলেজের সংখ্যা ছিল ১২টি। বর্তমানে দেশে সরকারি মেডিকেল কলেজের সংখ্যা ৩৮টি।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4d384634441952757445c29f3d897736'),
