(7575, 681, 'বাংলায় ইউরোপীয় বণিকদের মধ্যে কারা প্রথম এসেছিল?', 'ইংরেজরা', NULL, 'ফরাসিরা', NULL, 'ওলন্দাজরা', NULL, 'পর্তুগিজরা', NULL, 'D', 'পঞ্চদশ শতকের শেষভাগে পর্তুগিজ নাবিক ভাস্কো-দা-গামা আফ্রিকার পশ্চিম-পূর্ব উপকূল ঘুরে সমুদ্রপথে ভারতবর্ষে আসার পথ আবিষ্কার করেন। ১৫১৪ খ্রিষ্টাব্দে পর্তুগিজ বণিকগণ উড়িষ্যার অন্তর্গত পিপলি নামক স্থানে সর্বপ্রথম বাণিজ্য কুঠি স্থাপন করে। উল্লেখ্য, ১৬০২ সালে ওলন্দাজরা, ১৬০০ সালে ইংরেজরা এবং ১৬৬৪ সালে ফরাসিরা বাংলায় আগমন করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'df9c331cb1f29c9b3250233d17b9787f'),
(7576, 696, 'জিয়া সার কারখানায় উৎপাদিত সারের নাম কি?', 'অ্যামোনিয়া', NULL, 'সুপার ফসফেট', NULL, 'টিএসপি', NULL, 'ইউরিয়া', NULL, 'D', 'জিয়া সার কারখানা (বর্তমান নাম আশুগঞ্জ ফার্টিলাইজার অ্যান্ড কেমিক্যাল ইন্ডাস্ট্রিজ লি.) ব্রাহ্মণবাড়িয়া জেলার আশুগঞ্জে অবস্থিত। তিতাস গ্যাস ব্যবহার করে পরিচালিত এ কারখানাতে ইউরিয়াসহ প্যাকিং-এর লাইনিং এবং পলিথিন পেপার উৎপাদন করা হয়।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '24d4af0371b50b67f6b32b758d337ba8'),
(7577, 749, 'বাংলাদেশের জাতীয় পতাকার ডিজাইনার কে?', 'জয়নুল আবেদিন', NULL, 'কামরুল হাসান', NULL, 'হাসেম খান', NULL, 'হামিদুর রহমান', NULL, 'B', 'মানচিত্রখচিত প্রথম জাতীয় পতাকার নকশা তৈরি করেন শিবনারায়ণ দাস। বর্তমান জাতীয় পতাকার ডিজাইন করেন বাংলাদেশের প্রখ্যাত চিত্রশিল্পী কামরুল হাসান। কামরুল হাসান বাংলাদেশের জাতীয় প্রতীকেরও ডিজাইন করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a2b12fd7c39a302a8e251a60637bbabc'),
(7578, 730, 'বাংলাদেশের রাষ্ট্রপতি শাসিত সরকারের পরিবর্তে সংসদীয় শাসনব্যবস্থা চালু হয় সংবিধানের কত নম্বর সংশোধনীর মাধ্যমে?', '১০', NULL, '১১', NULL, '১২', NULL, '১৩', NULL, 'C', 'বঙ্গবন্ধু শেখ মুজিবুর রহমানের শাসনামলে ১৯৭৫ সালে বাংলাদেশের সংবিধানের চতুর্থ সংশোধনীর মাধ্যমে সংসদীয় শাসন ব্যবস্থার পরিবর্তে রাষ্ট্রপতি শাসিত শাসন ব্যবস্থা প্রবর্তন করা হয়। ১৯৯১ সালের ১৮ সেপ্টেম্বর রাষ্ট্রপতির অনুমোদন লাভের মাধ্যমে দ্বাদশ সংশোধনীর মাধ্যমে সংসদীয় শাসন ব্যবস্থা পুনঃপ্রবর্তিত হয়।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2bbde573157decc3dd687471cd7dae3b'),
(7579, 681, 'কোন নগরীতে মুঘল আমলে সুবা বাংলার রাজধানী ছিল?', 'গৌড়', NULL, 'সোনারগাঁও', NULL, 'ঢাকা', NULL, 'হুগলী', NULL, 'C', 'সম্রাট জাহাঙ্গীর সিংহাসনে আরোহণ করে ইসলাম খান চিশতীকে বাংলা অধিকারে প্রেরণ করেন। ইসলাম খান ১৬১০ সালে মুসা খানকে পরাজিত করে বাংলা অধিকার করেন এবং ঢাকার নামকরণ করেন \"জাহাঙ্গীরনগর\"। তিনি এ সময় রাজমহল থেকে ঢাকায় রাজধানী স্থানান্তর করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2bb2d667b4176723bd8c8f0d5bb0ba59'),
(7580, 719, 'স্বাধীন বাংলাদেশে ১০০ টাকার নোট কবে প্রথম চালু করা হয়?', '২৬ মার্চ, ১৯৭২', NULL, '১৬ ডিসেম্বর, ১৯৭২', NULL, '৪ মার্চ, ১৯৭২', NULL, '৪ জানুয়ারী, ১৯৭৩', NULL, 'C', 'বাংলাদেশে প্রথম নোট চালু হয় ৪ মার্চ, ১৯৭২। এ সময় প্রথম ১ টাকা ও ১০০ টাকার নোট বাজারে ছাড়া হয়।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '212c724c07f2f91615a1a5080f59ad53'),
(7581, 695, 'স্বাধীন বাংলাদেশকে কখন মার্কিন যুক্তরাষ্ট্র স্বীকৃতি দান করে?', '৪ ফেব্রুয়ারি, ১৯৭২', NULL, '২৪ জানুয়ারি, ১৯৭২', NULL, '১৬ ডিসেম্বর, ১৯৭২', NULL, '৪ এপ্রিল, ১৯৭২', NULL, 'D', 'বাংলাদেশকে প্রথম স্বীকৃতিদানকারী দেশ ভুটান। ভুটান এবং ভারত ৬ ডিসেম্বর, ১৯৭১ সালে বাংলাদেশকে স্বীকৃতি দেয়। মার্কিন যুক্তরাষ্ট্র বাংলাদেশকে ৪ এপ্রিল, ১৯৭২ সালে স্বীকৃতি দেয়।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ac66e57ad076fb9a7a5834a02bc4a0c9'),
(7582, 748, 'বাংলাদেশ জাতীয় সংসদে \"উপজেলা বাতিল\" বিলটি কখন পাস হয়েছিল?', '১৯৯২ সালে', NULL, '১৯৯৩ সালে', NULL, '১৯৯১ সালে', NULL, '১৯৯০ সালে', NULL, 'A', '১৯৯১ সালে বিএনপি সরকার ক্ষমতায় এসে ১৯৯২ সালে উপজেলা ব্যবস্থার বিলুপ্তি ঘোষণা করে। ৩০ জুন, ২০০৮ রাষ্ট্রপতি স্থানীয় সরকার (উপজেলা পরিষদ) অধ্যাদেশ জারি করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'afe9bb54dc8ca82cdb1d843f2ab73f8c'),
(7583, 748, 'ঢাকা পৌরসভা কোন সালে প্রতিষ্ঠিত হয়েছিল?', '১৯০৬ সালে', NULL, '১৮৬৪ সালে', NULL, '১৯১৯ সালে', NULL, '১৯৪০ সালে', NULL, 'B', 'মুঘল আমলে কোতোয়ালের এবং ব্রিটিশ আমলে পৌরসভার ওপর ঢাকা শহর পরিচালনা ও ব্যবস্থাপনার ভার ন্যস্ত হয়। এ লক্ষ্যে ১ আগস্ট, ১৮৬৪ সালে ঢাকা পৌরসভা প্রতিষ্ঠিত হয়।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ebae2c170b25249736d0db8de4a56eff'),
(7584, 750, 'লালবাগের কেল্লা স্থাপন করেন কে?', 'শায়েস্তা খান', NULL, 'শাহ সুজা', NULL, 'টিপু সুলতান', NULL, 'ইসলাম খান', NULL, 'A', 'ঢাকার ঐতিহ্যবাহী দর্শনীয় স্থানগুলোর অন্যতম হলো লালবাগ দুর্গ। এর পূর্বনাম ছিল আওরঙ্গবাদ দুর্গ। সম্রাট আওরঙ্গজেবের পুত্র সুবাদার শাহাজাদা আজম ১৬৭৮ খ্রিষ্টাব্দে এ দুর্গের নির্মাণ কাজ শুরু করেন এবং সুবাদার শায়েস্তা খান ১৬৮২ সালে তা সম্পন্ন করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e9c607a60de779a02243131e1194a4c5'),
(7585, 681, 'বাংলাদেশের লাগা উত্তরে অবস্থিত-', 'নেপাল ও ভুটান', NULL, 'পশ্চিমবঙ্গ, মেঘালয় ও আসাম', NULL, 'পশ্চিমবঙ্গ ও কুচবিহার', NULL, 'পশ্চিমবঙ্গ ও আসাম', NULL, 'B', 'বাংলাদেশের লাগা উত্তরে পশ্চিমবঙ্গ, মেঘালয় ও আসাম অবস্থিত। এছাড়াও দক্ষিণে বঙ্গোপসাগর; পূর্বে আসাম, ত্রিপুরা, মিজোরাম; এবং পশ্চিমে পশ্চিমবঙ্গ অবস্থিত।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b4f607182a8cba45cea89150030af515'),
(7586, 681, 'উপমহাদেশের সর্বশেষ গভর্নর জেনারেল কে ছিলেন?', 'লর্ড মিন্টো', NULL, 'লর্ড কার্জন', NULL, 'লর্ড মাউন্টব্যাটেন', NULL, 'লর্ড ওয়াভেল', NULL, 'C', 'উপমহাদেশের সর্বশেষ গভর্নর জেনারেল লর্ড মাউন্টব্যাটেন। তিনি ২১ ফেব্রুয়ারি, ১৯৪৭ সাল থেকে ১৫ আগস্ট, ১৯৪৭ সাল পর্যন্ত শেষ ব্রিটিশ \"ভাইসরয়\" এবং ১৫ আগস্ট, ১৯৪৭ থেকে ২১ জুন, ১৯৪৮ পর্যন্ত বিভাগোত্তর ভারত ডোমিনিয়নের প্রথম \"গভর্নর জেনারেল\" পদে দায়িত্ব পালন করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '344de02c284855e61d33c552d04093cc'),
(7587, 711, 'অভ্যন্তরীন কন্টেইনার ডিপো কোথায় অবস্থিত?', 'চট্টগ্রাম', NULL, 'ঢাকা', NULL, 'মংলা', NULL, 'খুলনা', NULL, 'A', 'বাংলাদেশের প্রথম ও বৃহত্তম অভ্যন্তরীণ কন্টেইনার ডিপো (Inland Container Depot) চট্টগ্রামে অবস্থিত। ১৯৮৭ সালে ঢাকার কমলাপুরে দ্বিতীয় ICD প্রতিষ্ঠা করা হয়।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1a1f8a5226ee80a271a8e4ac7ee100eb'),
(7588, 681, 'কর্কটক্রান্তি রেখা–', 'বাংলাদেশের উত্তর সীমান্ত দিয়ে গিয়েছে', NULL, 'বাংলাদেশের দক্ষিণ সীমান্ত দিয়ে গিয়েছে', NULL, 'বাংলাদেশের মধ্যখান দিয়ে গিয়েছে', NULL, 'বাংলাদেশ থেকে অনেক দূরে অবস্থিত', NULL, 'C', 'বাংলাদেশের মানচিত্র অনুযায়ী ঝিনাইদহ, ঢাকা, কুমিল্লার উপর দিয়ে কর্কটক্রান্তি রেখা চলে গিয়েছে যা দেশের মোটামুটি মধ্যভাগে অবস্থিত। কর্কটক্রান্তি রেখার অবস্থান ২৩.৫° উত্তর অক্ষাংশে।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1e677a5189a0057c0da6625a83a4cf06'),
(7589, 681, '১৯৯৩ সালের ডিসেম্বরে অনুষ্ঠিত রাশিয়ার পার্লামেন্টের নির্বাচনে কোন রাজনৈতিক দলটি সংখ্যাগরিষ্ঠ দল হিসেবে আত্মপ্রকাশ করে?', 'রাশিয়া\'স চয়েস', NULL, 'লিবারেল ডেমোক্রেটিক পার্টি', NULL, 'স্যোশ্যাল ডেমোক্রেটিক পার্টি', NULL, 'দ্য কমিউনিস্ট পার্টি', NULL, 'A', '১৯৯৩ সালের ডিসেম্বরে অনুষ্ঠিত রাশিয়ার পার্লামেন্ট নির্বাচনে \"রাশিয়াস চয়েস\" দলটি সংখ্যাগরিষ্ঠ দল হিসেবে আত্মপ্রকাশ করে।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a6ba1ac8caa528f1cc432bc7bceb30f4'),
(7590, 682, '১৪ ডিসেম্বর, ১৯৯৩ তারিখে শহীদ বুদ্ধিজীবীদের স্মৃতিকে স্মরণীয় করে রাখার জন্য ঢাকার মোট কতগুলো সড়কের নামকরণ করা হয়?', '৪টি', NULL, '৫টি', NULL, '৬টি', NULL, '৭টি', NULL, 'B', 'শহীদ বুদ্ধিজীবীদের স্মৃতিকে সরণীয় করে রাখার জন্য ১৯৯৩ সালের ১৪ ডিসেম্বর ঢাকার ৫টি সড়কের নতুন নামকরণ করা হয়। শহীদ বুদ্ধিজীবী স্মৃতিসৌধ নির্মিত হয়েছে ঢাকার মিরপুরে।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '760496e6375e303f4fdeacff014def29'),
(7591, 709, 'বাংলাদেশের ১৯৯৪-৯৫ সালের বাজেটে শিক্ষা খাতে বরাদ্দের পরিমাণ কত?', '১,৮২৪ কোটি টাকা', NULL, '১,৮৪২ কোটি টাকা', NULL, '১,৮৭৬ কোটি টাকা', NULL, '১,৮৬৭ কোটি টাকা', NULL, 'A', '২০২২-২৩ অর্থবছরে শিক্ষা ও প্রযুক্তি খাতে বরাদ্দ দেয়া হয় ৮১,৪৪৯ কোটি টাকা। (দ্রষ্টব্য: ১৯৯৪-৯৫ সালের প্রশ্নের উত্তর ছিল ১,৮২৪ কোটি টাকা)', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd1b780954ec1b09eaed783a0a2f0eaea'),
(7592, 750, 'বাংলাদেশের দীর্ঘতম রেলসেতু কোনটি?', 'ভৈরব সেতু', NULL, 'হার্ডিঞ্জ সেতু', NULL, 'ব্রহ্মপুত্র সেতু', NULL, 'তিস্তা সেতু', NULL, 'B', '১৯৯৮ সালের ২৩ জুন যমুনা বহুমুখী সেতুর উদ্বোধনের পর থেকে এটি বাংলাদেশের সড়কসহ দীর্ঘতম রেল সেতুর মর্যাদা লাভ করে। তবে একক দীর্ঘতম রেলসেতু হলো হার্ডিঞ্জ ব্রিজ। পাবনা জেলায় অবস্থিত হার্ডিঞ্জ সেতুর দৈর্ঘ্য ৫৮৯৪ ফুট (১৭৯৮.৩২ মিটার)।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '15169eb912ad4c9834db93fac90a6d0e'),
(7593, 704, 'চাকমা শরণার্থীদের দ্বিতীয় দফায় ১ম দিন অর্থাৎ ২১ জুলাই, ১৯৯৪ তারিখে কতজন বাংলাদেশে প্রত্যাবর্তন করেন?', '৩৮৭ জন', NULL, '৩৭৫ জন', NULL, '৩৫৭ জন', NULL, '৩৭৮ জন', NULL, 'A', 'চাকমা শরণার্থীদের দ্বিতীয় দফায় ২১ জুলাই, ১৯৯৪ তারিখে ৩৮৭ জন বাংলাদেশে প্রত্যাবর্তন করেন।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8c7c65296073172e7bea049a8e6f6ef2'),
(7594, 749, 'জীবনানন্দ দাশের জন্মস্থান কোন জেলায়?', 'বরিশাল জেলা', NULL, 'ফরিদপুর জেলা', NULL, 'ঢাকা জেলা', NULL, 'রাজশাহী জেলা', NULL, 'A', 'রবীন্দ্র-উত্তর আধুনিক বাংলা কবিতায় পঞ্চপাণ্ডবের একজন ছিলেন জীবনানন্দ দাশ। তাঁর জন্ম ১৮৯৯ সালের ১৭ ফেব্রুয়ারি বরিশাল জেলার ধানসিঁড়ি নদীর তীরে এক ব্রাহ্ম পরিবারে।', NULL, 166, '16th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dfd383da91b18e7c784fe65708899e93'),
(7595, 681, 'ব্রিটিশ বণিকদের বিরুদ্ধে একজন চাকমা জুমিয়া নেতা বিদ্রোহের পতাকা উড়িয়েছিলেন, তার নাম-', 'রাজা ত্রিদিব রায়', NULL, 'রাজা ত্রিভুবন চাকমা', NULL, 'জুম্মা খান', NULL, 'জান বখশ খাঁ', NULL, 'D', 'চাকমা জুমিয়া নেতা জান বখশ খাঁ ব্রিটিশ বণিকদের বিরুদ্ধে বিদ্রোহের পতাকা উড়িয়েছিলেন।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7b22ddcafed3799f51a62e83282ba294');
