(7596, 681, 'বাংলাদেশে ঢোকার পর গঙ্গা নদী, ব্রহ্মপুত্র-যমুনার সাথে নিম্নোক্ত একটা জায়গায় মেশে-', 'গোয়ালন্দ', NULL, 'বাহাদুরাবাদ', NULL, 'ভৈরববাজার', NULL, 'নারায়ণগঞ্জ', NULL, 'A', 'বাংলাদেশের রাজশাহী সীমান্ত দিয়ে প্রবেশ করে পদ্মা নদী (ভারতীয় নাম \"গঙ্গা\")। ব্রহ্মপুত্র-যমুনার সাথে রাজবাড়ী জেলার গোয়ালন্দে মিশেছে। মিলিত প্রবাহ পদ্মা নামে চাঁদপুরে মেঘনা নদীর সাথে মিলিত হয়েছে এবং এরপর মেঘনা নামে বঙ্গোপসাগরে পতিত হয়েছে।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '93493d908aca501ab9080db56e8289d5'),
(7597, 750, '১৮৭৪ সালে ঢাকা শহরে পানি সরবরাহ করার জন্য প্রথম পানি সরবরাহ কার্যক্রম স্থাপিত হয়-', 'সদরঘাটে', NULL, 'চাঁদনীঘাটে', NULL, 'পোস্তগোলায়', NULL, 'শ্যামবাজারে', NULL, 'B', '১৮৭৪ সালে চাঁদনীঘাটে পরিচালিত পানি সরবরাহ প্রকল্পের অর্থ যোগান দেয় ঢাকার নবাব পরিবার। সর্বশেষ ২০০২ সালে পানি সরবরাহ কার্যক্রম স্থাপিত হয় ঢাকার সায়েদাবাদে, যা দেশের সর্ববৃহৎ পানি সরবরাহ কার্যক্রম।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fa235aaac1c600be2b2019d833b6a874'),
(7598, 750, 'ঢাকার বড় কাটরা ও ছোট কাটরা শহরের নিম্নোক্ত একটি এলাকায় অবস্থিত?', 'চকবাজার', NULL, 'সদরঘাট', NULL, 'লালবাগ', NULL, 'ইসলামপুর', NULL, 'A', '১৬৬৪ সালে বাংলার সুবাদার শাহ মুহাম্মদ সুজা বড় কাটরা নামে ঐতিহাসিক অট্টালিকা নির্মাণ করেন ঢাকার চকবাজারে। সুবাদার শায়েস্তা খান ১৬৬৩-৬৪ সালে নিজের বসবাস ও সুবাদারি কার্যক্রম পরিচালনার জন্য ঢাকার চকবাজারে ছোট কাটরা নির্মাণ করেন।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f102a797eebce1c4dc4151da15aa5892'),
(7599, 695, 'বাংলাদেশকে স্বাধীন দেশ হিসেবে স্বীকৃতি দানকারী দ্বিতীয় দেশের নাম-', 'ভারত', NULL, 'রাশিয়া', NULL, 'ভুটান', NULL, 'নেপাল', NULL, 'A', 'ভুটান প্রথম দেশ হিসেবে বাংলাদেশকে আনুষ্ঠানিক স্বীকৃতি দেয় ৬ ডিসেম্বর, ১৯৭১ সালে। একই দিনে ভারত বাংলাদেশকে দ্বিতীয় হিসেবে স্বীকৃতি দেয়। এছাড়া রাশিয়া (তৎকালীন সোভিয়েত ইউনিয়ন) স্বীকৃতি দেয় ২৪ জানুয়ারি, ১৯৭২ এবং নেপাল স্বীকৃতি দেয় ১৬ জানুয়ারি, ১৯৭২।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9c65d54788cb0b0ab679ce8e4fa17df0'),
(7600, 704, 'বাংলাদেশে বাস নেই এমন উপজাতির নাম-', 'সাঁওতাল', NULL, 'মাওরি', NULL, 'মুরং', NULL, 'গারো', NULL, 'B', 'মাওরি উপজাতিরা বসবাস করে নিউজিল্যান্ডে। ২৩ মার্চ, ২০১৯ বাংলাদেশ সরকার কর্তৃক প্রকাশিত গেজেটে বাংলাদেশে ৫০টি ক্ষুদ্র নৃগোষ্ঠীর কথা উল্লেখ করে। এর মধ্যে বৃহত্তম ক্ষুদ্র নৃগোষ্ঠী চাকমা, দ্বিতীয় বৃহত্তম সাঁওতাল।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8d088427786920f2ca59cf5beb9df553'),
(7601, 682, 'লালবাগ দুর্গের অভ্যন্তরে সমাধিতে সমাহিত শায়েস্তা খানের এক কন্যার আসল নাম-', 'পরীবিবি', NULL, 'ইরান দুখ্ত', NULL, 'জাহানারা', NULL, 'মরিয়ম', NULL, 'B', 'শায়েস্তা খানের কন্যা পরীবিবির আসল নাম ইরান দুখ্‌ত। পরী বিবির মাজার লালবাগ কেল্লার ভিতরে দরবারগৃহ থেকে ২৭৫ ফুট পশ্চিমে অবস্থিত। ইরান দুখ্‌ত শাহজাদা আযমের বাগদত্তা ছিলেন, কিন্তু বিয়ের পূর্বে তিনি মৃত্যুমুখে পতিত হন।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '75c5222170c78968a113c755e336456d'),
(7602, 696, 'বাংলাদেশে প্রথম চায়ের চাষ আরম্ভ হয়-', 'সিলেটের মালনীছড়ায়', NULL, 'সিলেটের তামাবিলে', NULL, 'পার্বত্য চট্টগ্রামের খাগড়াছড়িতে', NULL, 'সিলেটের জাফলং এ', NULL, 'A', 'বাংলাদেশে প্রথম চা চাষ আরম্ভ হয় ১৮৪০ সালে চট্টগ্রাম জেলা শহরের ক্লাব সংলগ্ন এলাকায়। ১৮৫৪ সালে সিলেটের মালনীছড়ায় বাণিজ্যিক ভিত্তিতে প্রথম চা চাষ শুরু হয়।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b618efc9b94c4be72b0a009003a82472'),
(7603, 750, 'মুক্তিযুদ্ধ জাদুঘর ঢাকার কোন এলাকায় অবস্থিত?', 'সেগুনবাগিচা', NULL, 'ধানমণ্ডি', NULL, 'মগবাজার', NULL, 'বনানী', NULL, 'A', 'মুক্তিযুদ্ধ জাদুঘর প্রতিষ্ঠিত হয় ২২ মার্চ, ১৯৯৬। প্রতিষ্ঠাকালীন এটির অবস্থান ছিল ঢাকার সেগুনবাগিচায়। সরকার ২০০৮ সালে পশ্চিম আগারগাঁওয়ের শেরে বাংলা নগরে জাদুঘরটি স্থানান্তরের জন্য ২.৫ বিঘা জমি মুক্তিযুদ্ধ জাদুঘর ট্রাস্টি বোর্ডের কাছে হস্তান্তর করে। ১৬ এপ্রিল, ২০১৭ আনুষ্ঠানিকভাবে দ্বার উন্মোচন করা হয় আগারগাঁওয়ে অবস্থিত মুক্তিযুদ্ধ জাদুঘরের নিজস্ব ভবনের।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '920846226151516fa75c748df124e0f2'),
