(7625, 750, 'উত্তরা গণভবন কোথায় অবস্থিত?', 'রাজশাহী', NULL, 'নওগাঁ', NULL, 'বগুড়া', NULL, 'নাটোর', NULL, 'D', 'নাটোর জেলা শহর থেকে ২.৪ কিলোমিটার দূরে অবস্থিত দিঘাপতিয়া মহারাজাদের বাসস্থান দিঘাপতিয়া রাজবাড়ি আঠারো শতকে নির্মিত হয়। বাংলাদেশ স্বাধীনতার পর ১৯৭২ সালের ৯ ফেব্রুয়ারি আনুষ্ঠানিকভাবে এর নাম পরিবর্তন করে রাখেন \"উত্তরা গণভবন\"।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6a55645ea7355d681dad22dbb03f020f'),
(7626, 682, '\"আমার ভাইয়ের রক্তে রাঙ্গানো ২১শে ফেব্রুয়ারি\" গানের রচয়িতা কে?', 'আব্দুল গাফ্ফার চৌধুরী', NULL, 'আলতাফ মাহমুদ', NULL, 'আব্দুল লতিফ', NULL, 'আব্দুল আলীম', NULL, 'A', '\"আমার ভাইয়ের রক্তে রাঙানো একুশে ফেব্রুয়ারি\" বিখ্যাত এ গানটি প্রথম প্রকাশিত হয় হাসান হাফিজুর রহমান সম্পাদিত \"একুশে ফেব্রুয়ারি\" (১৯৫৩) গ্রন্থে। গানটির রচয়িতা আব্দুল গাফ্ফার চৌধুরী।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '570f8b318f2c3a285cdd618c0022bcd6'),
(7627, 750, 'বাগেরহাটে খান জাহান আলীর প্রতিষ্ঠিত মসজিদটি কত গম্বুজ বিশিষ্ট?', 'আশি', NULL, 'একাশি', NULL, 'ষাট', NULL, 'চৌষট্টি', NULL, 'B', 'বাগেরহাটের ষাটগম্বুজ মসজিদটি সুলতানি আমলে নির্মিত। খান জাহান আলী কর্তৃক মসজিদটি নির্মিত হয়। \"ষাটগম্বুজ\" নাম হলেও এ মসজিদের গম্বুজসংখ্যা ৮১টি। ওপরে ৭৭টি এবং চারকোণে ৪টি।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '72935d52b1c4498f2cbb34d7461c3d3a'),
(7628, 692, 'স্বাধীনতা যুদ্ধের সময় বাংলাদেশ কতগুলো সেক্টরে বিভক্ত ছিল?', '১৯টি', NULL, '৯টি', NULL, '৮টি', NULL, '১১টি', NULL, 'D', 'মুক্তিযুদ্ধ চলাকালীন ৪ এপ্রিল সিলেটে মুক্তিফৌজ গঠিত হয় এবং ৯ এপ্রিল এর নামকরণ করা হয় মুক্তিবাহিনী। পরবর্তীতে জুলাই মাসে সেনাপতি এম.এ.জি ওসমানী প্রধানমন্ত্রী তাজউদ্দিন আহমদের পরামর্শে সমগ্র বাংলাদেশকে ১১টি সেক্টর ও ৩টি ব্রিগেডে ভাগ করেন।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c8b9952abc97e878d2962cc42c0a91a7'),
(7629, 682, 'বাংলাদেশের জাতীয় পাখি-', 'ময়না', NULL, 'কাক', NULL, 'শালিক', NULL, 'দোয়েল', NULL, 'D', 'বাংলাদেশের জাতীয় পাখি দোয়েল। দোয়েল পাখি বাংলার ঐতিহ্য ও সংস্কৃতির একটি গুরুত্বপূর্ণ প্রতীক।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7d39a164d2dc5e6955687f0a7b1e8e19'),
(7630, 750, 'বঙ্গবন্ধু সেতুর দৈর্ঘ্য–', '৪.৮ কি.মি.', NULL, '৭.২ কি.মি.', NULL, '৬ কি.মি.', NULL, '৬.২ কি.মি.', NULL, 'A', 'নির্মাণাধীন দীর্ঘতম পদ্মা সেতুর পর বাংলাদেশের দীর্ঘতম সেতু বঙ্গবন্ধু সেতু। যমুনা নদীর উপর নির্মিত এই সেতুর দৈর্ঘ্য ৪.৮ কি.মি. ও প্রস্থ ১৮.৫ মি.। সড়ক ও রেলপথ দুটোর সমন্বয়ে নির্মিত এ সেতুর স্প্যান সংখ্যা ৪৯টি এবং পিলার ৫০টি।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dbd7f1b8c587d8fade210d5bf5331cc4'),
(7631, 682, 'বাংলাদেশের নৌ-বাহিনীর প্রতীক কি?', 'বলাকা', NULL, 'শাপলা', NULL, 'নৌকা', NULL, 'রনতরী', NULL, 'B', 'বাংলাদেশ নৌবাহিনীর প্রতীক কাছিবেষ্টিত নোঙর ও এর উপর শাপলা। শাপলা বাংলাদেশের জাতীয় ফুল। বিমান বাংলাদেশ এয়ারলাইন্সের প্রতীক উদীয়মান সূর্যের মধ্যে উড়ন্ত বলাকা।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8d644dd1572bdbbf33a55b1db490587c'),
(7632, 750, 'বাংলাদেশের লোকশিল্প জাদুঘর কোথায় অবস্থিত?', 'ময়মনসিংহে', NULL, 'বগুড়ায়', NULL, 'সোনারগাঁওয়ে', NULL, 'রাঙামাটিতে', NULL, 'C', 'বাংলাদেশের লোকশিল্পের অতীত কীর্তিসমূহ- নক্শী কাঁথা, মাটির পাত্র, বেত, কাঁসা, মসলিন বস্ত্র, তৈজসপত্র ইত্যাদি সংরক্ষণের জন্য নারায়ণগঞ্জ জেলার সোনারগাঁওয়ে লোকশিল্প জাদুঘর স্থাপন করা হয়েছে।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '868785801ed019c453be7f0d5995a08c'),
(7633, 706, 'বাংলাদেশে জিডিপিতে প্রাণিসম্পদে অবদান কত?', '২%', NULL, '১০%', NULL, '৬.৫%', NULL, '১৫%', NULL, 'A', 'অর্থনৈতিক সমীক্ষা ২০২৩ অনুযায়ী জিডিপিতে প্রানি সম্পদের অবদান ১.৮৫% (প্রায় ২%)।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '78c6bb4e3cca8e9fbf922899b1b12bc8'),
(7634, 712, 'বর্তমানে বিদেশ থেকে কত টাকার গুড়োদুধ আমদানি করা হয়?', '৫০০ কোটি টাকা', NULL, '৪০০ কোটি টাকা', NULL, '৩০০ কোটি টাকা', NULL, '১২৫ কোটি টাকা', NULL, 'A', 'বাংলাদেশ দুগ্ধ উৎপাদনকারী সমবায় প্রতিষ্ঠান মিল্ক ভিটার দেয়া তথ্য মতে, বাংলাদেশ প্রতি বছর ২৫০০ কোটি টাকার গুড়ো দুধ আমদানি করে। (দ্রষ্টব্য: পুরাতন প্রশ্নে ৫০০ কোটি টাকা ছিল)', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fb2d64a27b922a0c630171b7241dd3bb'),
(7635, 696, 'বাংলাদেশের কেন্দ্রীয় গো-প্রজনন খামার কোথায় অবস্থিত?', 'রাজশাহী', NULL, 'চট্টগ্রাম', NULL, 'সিলেট', NULL, 'সাভার', NULL, 'D', 'কেন্দ্রীয় গো-প্রজনন ও দুগ্ধ খামার মূলত একটি গবেষণা ও সেবামূলক প্রতিষ্ঠান। প্রতিষ্ঠানটি ঢাকা বিভাগের ঢাকা জেলার অন্তর্গত সাভার উপজেলাধীন আশুলিয়া থানায় ঢাকা-আরিচা মহাসড়ক সংলগ্ন জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের বিপরীত পাশে অবস্থিত।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '614beef204c72eb59f468d90f8d1f7c5'),
(7636, 682, 'বাংলাদেশের জাতীয় পশু কোনটি?', 'গরু', NULL, 'ছাগল', NULL, 'গয়াল', NULL, 'রয়েল বেঙ্গল টাইগার', NULL, 'D', 'বাংলাদেশের জাতীয় পশু রয়েল বেঙ্গল টাইগার। এটি প্রধানত বাংলাদেশ ও ভারতের অন্তর্গত বিশ্বের বৃহত্তম ম্যানগ্রোভ বন সুন্দরবনে পাওয়া যায়।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd1d37d8e0c9e6182a713ad92bff4df46'),
(7637, 713, 'রপ্তানি আয়ে বর্তমানে প্রাণিসম্পদের অবদান কত?', '৮ ভাগ', NULL, '১০ ভাগ', NULL, '১২ ভাগ', NULL, '১৩ ভাগ', NULL, 'A', 'ইপিবির সর্বশেষ রিপোর্ট অনুসারে, রপ্তানি আয়ে বর্তমানে প্রাণিসম্পদের তথা চামড়া ও চামড়াজাত দ্রব্যের এবং জুতা শিল্পের অবদান ২.৩৯% (প্রায় ৮% এর কম)।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7a597c28fe6dce30e6dfd351f485b7d6'),
(7638, 713, 'দেশের রপ্তানি আয়ের মধ্যে চামড়ার অবস্থান কত?', '১ম', NULL, '২য়', NULL, '৩য়', NULL, '৪র্থ', NULL, 'B', 'চামড়া ও চামড়াজাত পণ্য রপ্তানি হয়েছে ৫২ কোটি ৩০ লাখ। রপ্তানিতে চামড়া খাতের অবস্থান দ্বিতীয় (২০২৩-২৪ অর্থবছর)।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6feeb342fc9ec678a3aa0a6eeafa216d'),
(7639, 749, 'কৃষি বিশ্ববিদ্যালয়ের প্রথম উপাচার্য কে ছিলেন?', 'ড. এস ডি চৌধুরী', NULL, 'ড. কাজী ফজলুর রহিম', NULL, 'ড. ওসমান গণি', NULL, 'অধ্যাপক মোসলেহ উদ্দিন আহমেদ', NULL, 'C', 'বাংলাদেশ কৃষি বিশ্ববিদ্যালয় ১৮ আগস্ট, ১৯৬১ সালে ময়মনসিংহে প্রতিষ্ঠিত হয়। ড. ওসমান গণি ছিলেন এ বিশ্ববিদ্যালয়ের প্রথম উপাচার্য।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a1b34539e397ecd2856dcc2e52ead66b'),
(7640, 749, 'সাম্প্রতিককালে নোবেল পুরস্কারপ্রাপ্ত কোন কৃষিবিজ্ঞানী বাংলাদেশ সফর করেন?', 'প্রফেসর ড. আব্দুল সালাম', NULL, 'প্রফেসর নরম্যান বোরলগ', NULL, 'ড. আব্দুল কাদের', NULL, 'ড. স্বামিনাথন', NULL, 'B', 'প্রফেসর নরম্যান বোরলগ একজন কৃষিবিজ্ঞানী হলেও তিনি ১৯৭০ সালে শান্তিতে নোবেল পুরস্কার লাভ করেন। গমের ওপর গবেষণায় তিনি কিছুদিন ভারত ও পাকিস্তানে কাটান এবং বাংলাদেশ সফর করেন।', NULL, 169, '19th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '503bb5fa53382df884ddf9090d2fb6b8'),
(7641, 721, 'গণপ্রজাতন্ত্রী বাংলাদেশের সংবিধান কার্যকর হয় কোন তারিখ থেকে?', 'জানুয়ারি ১০, ১৯৭৩', NULL, 'ডিসেম্বর ১৬, ১৯৭২', NULL, 'নভেম্বর ৪, ১৯৭২', NULL, 'অক্টোবর ১১, ১৯৭২', NULL, 'B', '১৯৭২ সালের ১১ জানুয়ারি অস্থায়ী সংবিধান আদেশ জারির পর ২৩ জুন রাষ্ট্রপতি গণপরিষদ আদেশ জারি করেন। ১০ এপ্রিল গণপরিষদের প্রথম অধিবেশন বসে। এ কমিটি গণপরিষদে খসড়া সংবিধান পেশ করে ১৯৭২ সালের ১২ অক্টোবর, যা ৪ নভেম্বর গণপরিষদ কর্তৃক গৃহীত হয় এবং ১৯৭২ সালের ১৬ ডিসেম্বর থেকে কার্যকর হয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f4b86c64583e86dea3dc84e3b3f035c5'),
(7642, 744, 'বাংলাদেশের জেলা সংখ্যা কত?', '৩৬ টি', NULL, '৫৪ টি', NULL, '৬৪ টি', NULL, '৪৪ টি', NULL, 'C', 'স্বাধীনতা পরবর্তী সময়ে প্রায় এক দশক বাংলাদেশের জেলার সংখ্যা ছিল ২০টি। সামরিক শাসক লে.জে. হুসেইন মোহাম্মদ এরশাদ ক্ষমতায় আসার পর প্রশাসনিক কাজে গতিশীলতা আনতে ১৯৮৪ সালে জেলার সংখ্যা ৬৪টিতে উন্নীত করে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0802f470994a74656e348d96a9a66d34'),
(7643, 730, 'বাংলাদেশের সংসদীয় ব্যবস্থা সংবিধানের কোন সংশোধনীর মাধ্যমে পুনঃপরিবর্তিত হয়?', 'অষ্টম', NULL, 'নবম', NULL, 'একাদশ', NULL, 'দ্বাদশ', NULL, 'D', 'বঙ্গবন্ধু শেখ মুজিবুর রহমানের শাসনামলে ১৯৭৫ সালে বাংলাদেশের সংবিধানের চতুর্থ সংশোধনীর মাধ্যমে সংসদীয় শাসন ব্যবস্থার পরিবর্তে রাষ্ট্রপতি শাসিত শাসন ব্যবস্থা প্রবর্তন করা হয়। ১৯৯১ সালের ৬ আগস্ট দ্বাদশ সংশোধনীর মাধ্যমে সংসদীয় শাসন ব্যবস্থা পুনঃপরিবর্তিত হয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '677da6a047db9ef64a203f106bfdb206'),
(7644, 681, 'বাংলার ফরায়েজী আন্দোলনের সূচনাকারী কে?', 'তিতুমীর', NULL, 'হাজী মোহাম্মদ মহসীন', NULL, 'হাজী শরীয়তুল্লাহ', NULL, 'হাজী মোহাম্মদ দানেশ', NULL, 'C', 'হাজী শরীয়তুল্লাহর নেতৃত্বে মুসলমানদের ফরজ কাজসমূহ পালনে উদ্বুদ্ধ করার আন্দোলন হলো ফরায়েজি আন্দোলন। তার মৃত্যুর পর ফরায়েজি আন্দোলনের নেতৃত্ব দেন তার একমাত্র পুত্র দুদু মিয়া।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8a615983da0e954c7a1b78a2f12f35d3'),
(7645, 681, 'বাংলার প্রাচীনতম জায়গা কোনটি?', 'সোনারগাঁও', NULL, 'বিক্রমপুর', NULL, 'পুণ্ড্র', NULL, 'গোপালগঞ্জ', NULL, 'C', 'প্রাচীন যুগে বাংলায় অখণ্ড কোনো রাজ্য ছিল না। ভিন্ন ভিন্ন নামে খণ্ডে খণ্ডে বিভিন্ন জনপদে বিভক্ত ছিল সমগ্র বাংলা। বাংলার প্রাচীনতম জনপদ বগুড়া জেলায় অবস্থিত, যার নাম মহাস্থানগড় (পুণ্ড্রনগর)।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '16661a95a8970a39663049cc8bf1f5bf'),
(7646, 691, 'মুজিবনগর কোথায় অবস্থিত?', 'সাতক্ষীরায়', NULL, 'মেহেরপুরে', NULL, 'চুয়াডাঙ্গায়', NULL, 'নবাবগঞ্জে', NULL, 'B', 'মুজিবনগর, খুলনা বিভাগের মেহেরপুর জেলায় অবস্থিত। এখানেই ১৯৭১ সালের ১৭ এপ্রিল আনুষ্ঠানিকভাবে \"গণপ্রজাতন্ত্রী বাংলাদেশ সরকার\" শপথ গ্রহণ করে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1de8ab2841a8ebe070e3d9bab1a59470'),
(7647, 694, '১৯৭১ সালের ১৬ ডিসেম্বর পাকিস্তানি বাহিনী ঢাকার কোথায় আত্মসমর্পন করে?', 'রমনা পার্কে', NULL, 'পল্টন ময়দানে', NULL, 'তৎকালীন রেসকোর্স ময়দানে', NULL, 'ঢাকা ক্যান্টনমেন্টে', NULL, 'C', '১৯৭১ সালের ১৬ ডিসেম্বর পাক বাহিনী ঢাকার তৎকালীন রেসকোর্স ময়দানে (বর্তমান সোহরাওয়ার্দী উদ্যান) ভারতীয় মিত্র বাহিনীর পূর্বাঞ্চলীয় কমান্ডের অধিনায়ক লেফটেন্যান্ট জেনারেল জগজিৎ সিং অরোরার কাছে আত্মসমর্পন করে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2afc71e965f0563f65ec38ced30a5dd6'),
(7648, 728, 'বাংলাদেশে কোনো ব্যক্তির ভোটাধিকার প্রাপ্তির ন্যূনতম বয়স কত?', '১৬ বছর', NULL, '১৮ বছর', NULL, '২০ বছর', NULL, '২১ বছর', NULL, 'B', 'বাংলাদেশের সংবিধানের ১২২(২) অনুচ্ছেদের (খ)-তে বলা হয়েছে \"কোন ব্যক্তি সংসদের নির্বাচনের জন্য নির্ধারিত কোন নির্বাচনী এলাকায় ভোটার তালিকাভুক্ত হইবার অধিকারী হইবেন, যদি তাহার বয়স আঠার বৎসরের কম না হয়\"।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b40f32e753ba57e19412f4fd04369660'),
(7649, 726, 'বাংলাদেশের জাতীয় সংসদে সংরক্ষিত মহিলা আসনের সংখ্যা কত?', '২০', NULL, '২৫', NULL, '৩০', NULL, '৪০', NULL, 'D', 'বাংলাদেশের প্রথম জাতীয় সংসদ থেকেই মহিলাদের জন্য আসন সংরক্ষণ করে রাখা হয়। সংবিধানের চতুর্দশ সংশোধনীর মাধ্যমে ৪৫ এবং পঞ্চদশ সংশোধনীর মাধ্যমে বর্তমানে নারীদের সংরক্ষিত আসন সংখ্যা ৫০ করা হয়েছে। (দ্রষ্টব্য: ২০তম বিসিএসের সময় ছিল ৩০/৪০)', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e32832979fc0b2c0c8c232ce477d5060'),
(7650, 750, 'বঙ্গবন্ধু সেতুর দৈর্ঘ্য কত?', '৪.৫ কি.মি.', NULL, '৪.৮ কি.মি.', NULL, '৫.২ কি.মি.', NULL, '৬.২ কি.মি.', NULL, 'B', 'যমুনা বঙ্গবন্ধু সেতু বাংলাদেশের সর্ববৃহৎ এবং দক্ষিণ এশিয়ার দ্বিতীয় বৃহত্তম সেতু। এ সেতুর দৈর্ঘ্য ৪.৮ কি.মি. ও প্রস্থ ১৮.৫ মি.। এ সেতুর স্প্যানের সংখ্যা ৪৯টি এবং পিলার ৫০টি।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '89948a06e0ef182909032e972cb19a8d'),
(7651, 711, 'বাংলাদেশের প্রথম \"ইপিজেড\" কোথায় স্থাপিত হয়?', 'সাভারে', NULL, 'চট্টগ্রামে', NULL, 'মংলায়', NULL, 'ঈশ্বরদীতে', NULL, 'B', 'বাংলাদেশের প্রথম ইপিজেড \"চট্টগ্রাম ইপিজেড\" ১৯৮৩ সালে চট্টগ্রামের পতেঙ্গায় প্রতিষ্ঠিত হয়। বাংলাদেশের দ্বিতীয় ইপিজেড \"ঢাকা ইপিজেড\" ঢাকার সাভারে ১৯৯৩ সালে প্রতিষ্ঠিত হয়।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ea94deaa9d0b1afc6fb8804689caaafd'),
(7652, 682, 'বাংলার ১৯৪৩ সালের দুর্ভিক্ষের ওপর ছবি এঁকে বিখ্যাত হন কোন শিল্পী?', 'এস এম সুলতান', NULL, 'জয়নুল আবেদিন', NULL, 'কামরুল হাসান', NULL, 'শফিউল আলম', NULL, 'B', '১৯৪৩ সালের দুর্ভিক্ষের ওপর জয়নুলের আঁকা ছবির নাম \"ম্যডোনা ৪৩\"। তিনি বাংলাদেশের শ্রেষ্ঠ চিত্রশিল্পী এবং চারুকলা ইনস্টিটিউটের প্রতিষ্ঠাতা।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f2663874b9c590ea997a1adcf709679c'),
(7653, 695, 'পার্বত্য চট্টগ্রামে শান্তিচুক্তি কবে সম্পাদিত হয়?', 'নভেম্বর ১২, ১৯৯৭', NULL, 'ডিসেম্বর ২, ১৯৯৭', NULL, 'ডিসেম্বর ১৬, ১৯৯৭', NULL, 'ডিসেম্বর ২৫, ১৯৯৭', NULL, 'B', 'পাহাড়িদের স্বতন্ত্র জনগোষ্ঠী হিসেবে চিহ্নিত করে সংরক্ষণশীল নীতিভিত্তিক কিছু সুবিধা নিশ্চিত করা হয় ১৯৯৭ সালের ২ ডিসেম্বর সম্পাদিত এ শান্তিচুক্তির মাধ্যমে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '78507c2ff4e2cfb7b8e72a3dc84740ed'),
(7654, 692, '১৯৭১ সালে মুক্তিযুদ্ধকালে বাংলাদেশকে কয়টি সামরিক সেক্টরে বিভক্ত করা হয়েছিল?', '৯টি', NULL, '১১টি', NULL, '১৫টি', NULL, '১৭টি', NULL, 'B', 'মুক্তিযুদ্ধ চলাকালীন ৪ এপ্রিল সিলেটে মুক্তিফৌজ গঠিত হয় এবং ৯ এপ্রিল এর নামকরণ করা হয় মুক্তিবাহিনী। পরবর্তী জুলাই মাসে সেনাপতি এম.এ.জি ওসমানী সমগ্র বাংলাদেশকে ১১টি সেক্টর ও ৩টি ব্রিগেডে ভাগ করেন।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ff097bb71272793a3d183b054240c719'),
(7655, 681, 'বাংলাদেশের অন্তর্গত সুন্দরবনের আয়তন কত?', '২৪০০ বর্গমাইল', NULL, '১৯৫০ বর্গমাইল', NULL, '৯২৫ বর্গমাইল', NULL, '২০০ বর্গমাইল', NULL, 'A', 'পৃথিবীর সবচেয়ে বড় ম্যানগ্রোভ বনভূমি হলো সুন্দরবন। পশ্চিমবঙ্গ ও বাংলাদেশের এলাকা মিলিয়ে এর আয়তন ১০ হাজার বর্গকিলোমিটার। তবে বাংলাদেশ অংশের আয়তন ৬,০১৭ বর্গ কিলোমিটার বা ২৪০০ বর্গমাইল।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd92fc78cd52d7028442e792a150ee755'),
