(7675, 692, 'মুক্তিযুদ্ধকালে বাংলাদেশকে কয়টি সেক্টরে ভাগ করা হয়?', 'আট', NULL, 'দশ', NULL, 'এগারো', NULL, 'পনের', NULL, 'C', 'মুক্তিযুদ্ধ চলাকালীন সময়ে ৪ এপ্রিল মুক্তিফৌজ নামে মুক্তিবাহিনী গঠিত হয় এবং ৯ এপ্রিল এর নামকরণ করা হয় মুক্তিবাহিনী। পরবর্তীতে জেনারেল এম. এ. জি. ওসমানীকে মুক্তিবাহিনীর প্রধান সেনাপতি হিসেবে নিয়োগ দেয়া হলে তিনি এবং প্রধানমন্ত্রী তাজউদ্দিন আহমদ বাংলাদেশকে যুদ্ধ পরিচালনার সুবিধার্থে ১১টি সেক্টরে বিভক্ত করেন।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5ddf9aa73e8d4a41719da0833b29047b'),
(7676, 695, 'বাংলাদেশ কত সালে ইসলামী সম্মেলন সংস্থার সদস্যপদ লাভ করে?', '১৯৭২ সালে', NULL, '১৯৭৩ সালে', NULL, '১৯৭৪ সালে', NULL, '১৯৭৫ সালে', NULL, 'C', 'ইসলামী সম্মেলন সংস্থা (Organization of Islamic Cooperation) এর প্রতিষ্ঠা কাল ২৫ সেপ্টেম্বর, ১৯৬৯। বাংলাদেশ যোগদান করে ২৩ ফেব্রুয়ারি ১৯৭৪ সালে, লাহোর সম্মেলনে।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1860f087dc7058ad944c495694717290'),
(7677, 750, 'বাংলাদেশ কতবার নিরাপত্তা পরিষদের সদস্যপদ লাভ করে?', '২ বার', NULL, '৩ বার', NULL, '১ বার', NULL, '৪ বার', NULL, 'A', 'নিরাপত্তা পরিষদে বাংলাদেশ এ পর্যন্ত দুবার সদস্যপদ লাভ করে। প্রথমবার সদস্যপদ লাভ করে ১০ নভেম্বর, ১৯৭৮ (১৯৭৯-৮০ মেয়াদে) এবং দ্বিতীয়বার ১৪ অক্টোবর, ১৯৯৯ সালে (২০০০-২০০১ মেয়াদে)।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '112abb20a57aebd6b3c69033f174c89f'),
(7678, 725, 'বাংলাদেশ সরকারি কর্মকমিশন সংবিধানের কত নং অনুচ্ছেদ অনুযায়ী গঠিত?', '১৩৬', NULL, '১৩৭', NULL, '১৩৮', NULL, '১৪০ (২)', NULL, 'B', 'বাংলাদেশের সংবিধানের ১৩৭-১৪১ নং অনুচ্ছেদে সরকারি কর্ম কমিশন সম্পর্কে আলোচনা করা হয়েছে। সংবিধানের ১৩৭ নং ধারায় বলা হয়েছে, \"আইনের দ্বারা বাংলাদেশের জন্য এক বা একাধিক সরকারী কর্মকমিশন প্রতিষ্ঠার বিধান করা যাইবে।\"', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9dc0d648e638c89358526d639abd0089'),
(7679, 749, 'জাতির জনক বঙ্গবন্ধু জাতিসংঘের কোথায় বাংলা ভাষায় বক্তৃতা প্রদান করেন?', 'নিরাপত্তা পরিষদে', NULL, 'সাধারণ পরিষদের অধিবেশনে', NULL, 'ইকোসোকে (ECOSOC)', NULL, 'ইউনেসকোতে (UNESCO)', NULL, 'B', '১৯৭৪ সালের ২৫ সেপ্টেম্বর বঙ্গবন্ধু শেখ মুজিবুর রহমান প্রথম বাংলাদেশী রাষ্ট্রপ্রধান হিসেবে জাতিসংঘের সাধারণ পরিষদের ২৯তম অধিবেশনে বাংলা ভাষায় বক্তৃতা প্রদান করেন।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '878ed03a8f05b0d8f4abd1cb0d391db5'),
(7680, 694, 'মুক্তিযুদ্ধের বিজয়ের দিন আত্মসমর্পণ অনুষ্ঠানে বাংলাদেশের পক্ষে প্রতিনিধিত্ব করেন কে?', 'জেনারেল মোহাম্মদ আতাউল গণি ওসমানী', NULL, 'গ্রুপ ক্যাপ্টেন এ কে খন্দকার', NULL, 'ফ্লাইট লেফটেন্যান্ট মতিউর রহমান', NULL, 'ক্যাপ্টেন মহিউদ্দিন জাহাঙ্গীর', NULL, 'B', '১৯৭১ সালের ১৬ ডিসেম্বর বাংলাদেশের স্বাধীনতা যুদ্ধের বিজয়ের দিন আত্মসমর্পণ অনুষ্ঠানে বাংলাদেশের পক্ষে প্রতিনিধিত্ব করেন গ্রুপ ক্যাপ্টেন এ কে খন্দকার।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '54816f409ec99495c96e15902b557eb0'),
