(7685, 750, 'ঢাকা বিশ্ববিদ্যালয় প্রতিষ্ঠিত হয় কোন সালে?', '১৯০৫ সালে', NULL, '১৯৯১ সালে', NULL, '১৯৩৫ সালে', NULL, '১৯২১ সালে', NULL, 'D', 'বঙ্গভঙ্গ রদ হলে ব্রিটিশ সরকার পূর্ববঙ্গে একটি বিশ্ববিদ্যালয় প্রতিষ্ঠার ঘোষণা দেয় এবং এজন্য ১৯১২ সালে ১৩ সদস্য বিশিষ্ট নাথান কমিশন গঠিত হয়। ঢাকার নবাব সলিমুল্লাহ ঢাকা বিশ্ববিদ্যালয়ের জন্য জমি দান করেন। ১৯২১ সালে ঢাকা বিশ্ববিদ্যালয় চালু হয়।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9ab16305e69d54a091161f7d80109ca6'),
(7686, 681, 'দহগ্রাম ছিটমহল কোন জেলায় অবস্থিত?', 'নীলফামারী', NULL, 'কুড়িগ্রাম', NULL, 'লালমনিরহাট', NULL, 'দিনাজপুর', NULL, 'C', '১৯৭২ সালে ইন্দিরা-মুজিব চুক্তি অনুযায়ী দহগ্রাম আঙ্গরপোতা বাংলাদেশের লালমনিরহাট জেলার একটি ছিটমহলে পরিণত হয়। এটি ২০১৫ সালের ছিটমহল বিনিময়ের আওতা বহির্ভূত।', NULL, 171, '22nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '442211c0cf7dbfca50fa2cfbe4c66a9c'),
(7687, 744, 'বাংলাদেশ সিভিল সার্ভিসের (BCS) ক্যাডার কতটি?', '২৯টি', NULL, '২২টি', NULL, '২১টি', NULL, '৫টি', NULL, 'A', 'বর্তমানে বাংলাদেশ সিভিল সার্ভিসের (BCS) ক্যাডার সংখ্যা ২৬টি। ২০১৮ সালের ১৩ নভেম্বর বাংলাদেশ সিভিল সার্ভিসের ইকনমিক ক্যাডার বিলুপ্ত করায় বর্তমানে বিসিএস ক্যাডার সংখ্যা হয় ২৬টি। (দ্রষ্টব্য: ২৩তম বিসিএসের সময় ২৯টি ছিল)', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2dc33ccb71dcd627ebd3e4899bfe25c7'),
(7688, 713, 'বাংলাদেশে সবচেয়ে বেশি বৈদেশিক মুদ্রা অর্জিত হয় কোন খাত থেকে?', 'চা', NULL, 'পাট ও পাট জাত দ্রব্য', NULL, 'তৈরি পোশাক', NULL, 'চিংড়ি মাছ', NULL, 'C', 'তৈরি পোশাক খাতে ২০২১-২২ অর্থবছরে রপ্তানি আয় হয়েছে ৫ হাজার ২০৮ কোটি ৭ লাখ মার্কিন ডলার।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2d0c0cf577a8747499ef0ccdf29b8393'),
(7689, 692, 'মুক্তিযুদ্ধকালে বাংলাদেশকে কয়টি সেক্টরে ভাগ করা হয়?', 'আট', NULL, 'দশ', NULL, 'এগারো', NULL, 'পনের', NULL, 'C', 'মুক্তিযুদ্ধ চলাকালীন সময়ে ৪ এপ্রিল মুক্তিফৌজ নামে মুক্তিবাহিনী গঠিত হয় এবং ৯ এপ্রিল এর নামকরণ করা হয় মুক্তিবাহিনী। পরবর্তীতে জেনারেল এম.এ.জি. ওসমানীকে মুক্তিবাহিনীর প্রধান সেনাপতি হিসেবে নিয়োগ দেয়া হলে তিনি এবং প্রধানমন্ত্রী তাজউদ্দিন আহমদ বাংলাদেশকে যুদ্ধ পরিচালনার সুবিধার্থে ১১টি সেক্টরে বিভক্ত করেন।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5ddf9aa73e8d4a41719da0833b29047b'),
(7690, 749, '১৯৭৫ সালের ১৫ আগস্ট ভোর রাত পর্যন্ত বাংলাদেশের সেনাবাহিনীর প্রধান কে ছিলেন?', 'মেজর জেনারেল জিয়াউর রহমান', NULL, 'মেজর জেনারেল মঞ্জুর', NULL, 'মেজর জেনারেল কে এম শফিউল্লাহ', NULL, 'মেজর জেনারেল এইচ এম এরশাদ', NULL, 'C', 'মেজর জেনারেল কে এম শফিউল্লাহ ১৯৭২ সালের এপ্রিল থেকে ১৯৭৫ সালের ১৫ আগস্ট পর্যন্ত বাংলাদেশ সেনাবাহিনীর প্রধান ছিলেন।', NULL, 172, '23rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '70aae7763a90d7cd6059c0c394d0015e'),
(7691, 681, 'বর্তমান বৃহত্তর ঢাকা জেলা প্রাচীনকালে কোন জনপদের অন্তর্ভুক্ত ছিল?', 'সমতট', NULL, 'পুণ্ড্র', NULL, 'বঙ্গ', NULL, 'হরিকেল', NULL, 'C', 'বঙ্গ খুবই প্রাচীন জনপদ। \"ঐতরেয় আরণ্যক\" গ্রন্থে সর্বপ্রথম বঙ্গ-এর উল্লেখ পাওয়া যায়। প্রাচীনকালে বঙ্গ জনপদের অন্তর্ভুক্ত জেলাগুলো কুষ্টিয়া, যশোর, নদীয়া, শান্তিপুর, ঢাকা, ফরিদপুর এবং বৃহত্তর ময়মনসিংহ।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '866f2a87a613baaf685b3615f9606bb9');
