(7692, 681, 'বাংলায় মুসলিম আধিপত্য বিস্তারের সূচনা কে করেন?', 'আলী মর্দান খলজী', NULL, 'তুঘরিল খান', NULL, 'শামসুদ্দিন ফিরোজ শাহ', NULL, 'ইখতিয়ারউদ্দিন মুহাম্মদ বিন বখতিয়ার খলজি', NULL, 'D', '১২০৪ সালে বখতিয়ার খলজি অশ্ব বিক্রেতার বেশে অতর্কিতে লক্ষ্মণ সেনের রাজধানী নদীয়া আক্রমণ করলে লক্ষ্মণ সেন পূর্বদিকে পলায়ন করে এবং বখতিয়ার খলজি বাংলায় মুসলিম শাসনের সূত্রপাত ঘটান।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a7b72fb26d3701af5a673da9d1cb76ef'),
(7693, 681, 'ঢাকায় সুবা-বাংলার রাজধানী কখন স্থাপিত হয়?', '১৬১০ সালে', NULL, '১৫৭৬ সালে', NULL, '১৯০৫ সালে', NULL, '১৯৪৭ সালে', NULL, 'A', '১৬১০ সালে সুবাদার ইসলাম খান কর্তৃক বাংলার রাজধানী বিহারের রাজমহল থেকে ঢাকায় স্থানান্তরিত হয় এবং নামকরণ করা হয় জাহাঙ্গীরনগর। স্বাধীনতার পূর্বে ঢাকা চারবার (১৬১০, ১৬৬০, ১৯০৫ ও ১৯৪৭ সালে) বাংলার রাজধানীর মর্যাদা লাভ করে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '673d76f8ee63787fdc51164878b430a0'),
(7694, 681, 'কোন মুঘল সুবাদার চট্টগ্রাম দখল করে এর নাম রাখেন ইসলামাবাদ?', 'ইসলাম খান', NULL, 'রাজা মানসিংহ', NULL, 'মীর জুমলা', NULL, 'শায়েস্তা খান', NULL, 'D', 'শায়েস্তা খান মগ জলদস্যুদের তাড়িয়ে চট্টগ্রাম দখল করেন এবং এর নাম রাখেন \"ইসলামাবাদ\"। পরে তিনি ছোট কাটরা এবং মোহাম্মদপুরের সাত গম্বুজ মসজিদ (১৬৮০ সালে) নির্মাণ করেন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9d74e01bef2042632d682723e027d1bb'),
(7695, 681, 'ইংরেজ ইস্ট ইন্ডিয়া কোম্পানি কখন বাংলা, বিহার ও উড়িষ্যার দেওয়ানী লাভ করে?', '১৬৯০ সালে', NULL, '১৭৬৫ সালে', NULL, '১৭৯৩ সালে', NULL, '১৮২৯ সালে', NULL, 'B', 'বক্সারের যুদ্ধে (১৭৬৪ সাল) নবাব বাহিনী পরাজিত হলে লর্ড ক্লাইভ মীরজাফরের নাবালক পুত্রকে বাংলার সিংহাসনে বসান। ১৭৬৫ সালে দিল্লির সম্রাট শাহ আলমের নিকট থেকে বার্ষিক ২৬ লাখ টাকার বিনিময়ে ইস্ট ইন্ডিয়া কোম্পানি বাংলা, বিহার ও উড়িষ্যার দেওয়ানি লাভ করে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3639ed8366717468972e3ffa7d9d95db'),
(7696, 681, 'বাংলায় ফরায়েজী আন্দোলনের উদ্যোক্তা কে ছিলেন?', 'মাওলানা কেরামত আলী', NULL, 'শাহ ওলিউল্লাহ', NULL, 'হাজী শরীয়তুল্লাহ', NULL, 'পীর মুহসীনুদ্দীন', NULL, 'C', 'মুসলমানদের ফরজ কাজসমূহ পালনে উদ্বুদ্ধ করার আন্দোলনই ফরায়েজী আন্দোলন, যার নেতৃত্ব দেন হাজী শরীয়তুল্লাহ এবং তার মৃত্যুর পর ফরায়েজী আন্দোলনের নেতৃত্ব দেন তার একমাত্র পুত্র দুদু মিয়া।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6e6923f71db71afb2d695c547abfd36a'),
(7697, 749, 'বাংলায় মুসলমানদের মধ্যে আধুনিক শিক্ষা প্রচলনের জন্য কে অগ্রণী ভূমিকা পালন করেন?', 'সৈয়দ আমীর আলী', NULL, 'নওয়াব আবদুল লতিফ', NULL, 'নওয়াব স্যার সলিমুল্লাহ', NULL, 'স্যার সৈয়দ আহমেদ খান', NULL, 'B', 'নওয়াব আবদুল লতিফ বাংলার মুসলমানদের মাঝে ইংরেজি শিক্ষা প্রবর্তনে অগ্রণী ভূমিকা পালন করেন। তার প্রচেষ্টায় রামমোহন রায় প্রতিষ্ঠিত হিন্দু কলেজ ১৮৫৪ সালে প্রেসিডেন্সি কলেজে রূপান্তরিত হয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '45410fe125517423384e8df9cc66f0d1'),
(7698, 681, 'বঙ্গভঙ্গ রদ হয় কোন সালে?', '১৯০৫ সালে', NULL, '১৯১৬ সালে', NULL, '১৯২৩ সালে', NULL, '১৯১১ সালে', NULL, 'D', 'হিন্দুদের তীব্র আন্দোলনের ফলে ভারতবর্ষে ব্রিটিশ বাণিজ্যে অচলাবস্থার সৃষ্টি হলে ১২ ডিসেম্বর, ১৯১১ রাজা পঞ্চম জর্জ দিল্লি দরবারে বঙ্গবিভাগ রদের ঘোষণা দেন এবং ১৯১২ সালের ২০ জানুয়ারি তা কার্যকর হয়।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '982deb6a34752b928ec10d7376137037'),
(7699, 681, 'অবিভক্ত বাংলার শেষ মুখ্যমন্ত্রী কে ছিলেন?', 'হোসেন শহীদ সোহরাওয়ার্দী', NULL, 'এ কে ফজলুল হক', NULL, 'খাজা নাজিমউদ্দিন', NULL, 'আবুল হাশেম', NULL, 'A', 'হোসেন শহীদ সোহরাওয়ার্দী ১৯২১ সালে বঙ্গীয় ব্যবস্থাপক পরিষদের সদস্য নির্বাচিত হন। ১৯৩৭ সালে নির্বাচনের পর তিনি মন্ত্রিসভার সদস্য হন। ১৯৪৬ সালে অবিভক্ত বাংলার মুখ্যমন্ত্রী হন। ১৯৫৪ সালে পাকিস্তানের কেন্দ্রীয় মন্ত্রিসভায় যোগ দেন এবং ১৯৫৬ সালে তিনি পাকিস্তানের প্রধানমন্ত্রী হন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '775a5f8448672fb9b34a471993f977bd'),
(7700, 683, 'পাকিস্তান শাসনতান্ত্রিক পরিষদের (Constituent Assembly) ধারা বিবরণীতে বাংলা ভাষা ব্যবহারের দাবি কে প্রথম করেছিলেন?', 'আবুল হাশেম', NULL, 'শেখ মুজিবুর রহমান', NULL, 'ড. মুহাম্মদ শহীদুল্লাহ', NULL, 'ধীরেন্দ্রনাথ দত্ত', NULL, 'D', '২৩ ফেব্রুয়ারি, ১৯৪৮ পাকিস্তান গণপরিষদের প্রথম অধিবেশনের শুরুতে গণপরিষদ সদস্য কুমিল্লার ধীরেন্দ্রনাথ দত্ত (১৮৮৬-১৯৭১) উর্দুর পাশাপাশি বাংলাকে রাষ্ট্রভাষা করার প্রস্তাব উত্থাপন করেন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e47638f60415583f38c8153c175d852f'),
(7701, 681, 'বাংলাদেশের নদীগুলোর মধ্যে সবচেয়ে দীর্ঘ পথ অতিক্রম করেছে কোনটি?', 'ব্রহ্মপুত্র', NULL, 'পদ্মা', NULL, 'মেঘনা', NULL, 'যমুনা', NULL, 'A', 'ব্রহ্মপুত্র হিমালয় পর্বতের কৈলাস শৃঙ্গের মানস সরোবরে উৎপত্তি হয়ে তিব্বতে সানপো এবং আসামে ডিহি নাম ধারণ করে। অবশেষে ব্রহ্মপুত্র নামে বাংলাদেশে প্রবেশ করেছে। সানপো, ডিহি ও ব্রহ্মপুত্রের মোট দৈর্ঘ্য ২৮৫০ কিমি, যা বিশ্বের ২২তম দীর্ঘ নদী।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ed59189b7e91db406c790abc7f82a6b5'),
(7702, 681, 'বাংলাদেশের প্রাচীনতম নগরকেন্দ্র কোনটি?', 'ময়নামতি', NULL, 'পাহাড়পুর', NULL, 'মহাস্থানগড়', NULL, 'সোনারগাঁও', NULL, 'C', 'বগুড়া জেলার করতোয়া নদীর তীরে অবস্থিত মহাস্থানগড়ের পূর্ব নাম পুণ্ড্রবর্ধন। এটি মৌর্য ও গুপ্ত বংশের রাজাদের রাজধানী ছিল। মহাস্থানগড়ে মৌর্য যুগের শিলালিপি পাওয়া গেছে।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '78803f94516e57cb9e7079be7c4de55c'),
(7703, 750, 'বাংলাদেশের সবচেয়ে বড় মধ্যযুগীয় মসজিদ কোনটি?', 'কুসুম্বা মসজিদ', NULL, 'বড় সোনা মসজিদ', NULL, 'ষাট গম্বুজ মসজিদ', NULL, 'সাত গম্বুজ মসজিদ', NULL, 'C', 'সুলতানী আমলে উলুঘ খান জাহান আলী বাগেরহাট জেলায় ষাটগম্বুজ মসজিদ নির্মাণ করেন। ষাট গম্বুজ মসজিদের মোট গম্বুজ সংখ্যা ৮১টি, চার কোণায় ৪টি এবং মাঝে ৭৭টি।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b181326fa99702c105fb12fd6d768ad7'),
(7704, 681, 'ইরানের কবি হাফিজের সাথে পত্রালাপ হয়েছিল বাংলার কোন সুলতানের?', 'গিয়াসউদ্দীন আযম শাহ', NULL, 'আলাউদ্দীন হুসেন শাহ', NULL, 'ফখরুদ্দীন মোবারক শাহ', NULL, 'ইলিয়াস শাহ', NULL, 'A', 'ইলিয়াস শাহী বংশের শেষ সুলতান গিয়াসউদ্দীন আযম শাহ ফারসি ভাষায় কবিতা লিখতেন। তিনি একটি অসমাপ্ত কবিতা লিখে পারস্য কবি হাফিজের কাছে পাঠান। হাফিজ উক্ত কবিতা সম্পূর্ণ করে সোনারগাঁওয়ে প্রেরণ করেন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6b1379978e298aecc67b67f29b20a4fd'),
(7705, 682, 'বাংলাদেশের জাতীয় দিবস কোনটি?', '১৬ ডিসেম্বর', NULL, '২৬ মার্চ', NULL, '২১ ফেব্রুয়ারি', NULL, '৭ মার্চ', NULL, 'B', '২৬ মার্চ হলো বাংলাদেশের স্বাধীনতা ও জাতীয় দিবস। অন্যদিকে ১৬ ডিসেম্বর বাংলাদেশের বিজয় দিবস, ২১ ফেব্রুয়ারি শহীদ দিবস ও আন্তর্জাতিক মাতৃভাষা দিবস এবং ৭ মার্চ রেসকোর্স ময়দানে বঙ্গবন্ধুর ভাষণ দিবস।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9ae15fb42855e47be2c9d43f1289a377'),
(7706, 726, 'বাংলাদেশে জাতীয় সংসদের অধিবেশন কে আহ্বান করেন?', 'প্রধানমন্ত্রী', NULL, 'রাষ্ট্রপতি', NULL, 'স্পিকার', NULL, 'প্রধান বিচারপতি', NULL, 'B', 'সংবিধানের ৭২ (১) অনুচ্ছেদ অনুযায়ী রাষ্ট্রপতি সংসদের অধিবেশন আহ্বান করেন। উল্লেখ্য, উক্ত ধারা অনুসারে সরকারি বিজ্ঞপ্তি দ্বারা রাষ্ট্রপতি সংসদ স্থগিত ও ভঙ্গ করতে পারেন এবং প্রথম বৈঠকের সময় ও স্থান নির্ধারণ করতে পারেন।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7fe201153f612674423e9192fa459519'),
(7707, 749, 'বাংলাদেশের কোন স্থপতি সবচেয়ে বেশি আন্তর্জাতিক পুরস্কার ও সম্মাননা পেয়েছেন?', 'হামিদুর রহমান', NULL, 'ফজলুর রহমান খান', NULL, 'নভেরা আহমদ', NULL, 'জুলফিকার আলী খান', NULL, 'B', 'ফজলুর রহমান খান স্ট্রাকচারাল ইঞ্জিনিয়ারিংয়ের অন্যতম পথিকৃৎ। তিনি আমেরিকার শিকাগো শহরে অবস্থিত বিখ্যাত সিয়ার্স টাওয়ারের স্থপতি। তিনি তার স্বতন্ত্র নির্মাণ কৌশলের স্বীকৃতিস্বরূপ লাভ করেছিলেন নানা আন্তর্জাতিক পুরস্কার ও সম্মাননা।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '80d300aaa8b1cb71f9257af2a70160fd'),
