(7710, 681, 'বাংলাদেশের সবচেয়ে দক্ষিণের জেলা কোনটি?', 'চট্টগ্রাম', NULL, 'ভোলা', NULL, 'কক্সবাজার', NULL, 'পটুয়াখালী', NULL, 'C', 'বাংলাদেশের সবচেয়ে দক্ষিণের জেলা কক্সবাজার। কক্সবাজার জেলার টেকনাফ উপজেলা বাংলাদেশের সর্বদক্ষিণের উপজেলা।', NULL, 173, '24th BCS (Cancelled)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd527ff5eab63b661e8e4d2fbc04fd2db'),
(7711, 682, 'বাংলাদেশের স্বাধীনতা যুদ্ধে বীরত্বপূর্ণ অবদানের জন্য কতজনকে বীর উত্তম উপাধিতে ভূষিত করা হয়?', '২৫৭ জন', NULL, '১৬৩ জন', NULL, '৪৪ জন', NULL, '৬৮ জন', NULL, 'D', 'মুক্তিযুদ্ধে অবদানের জন্য ৪টি রাষ্ট্রীয় খেতাব প্রদান করা হয় ৬৭৬ জনকে। তার মধ্যে বীরশ্রেষ্ঠ ৭ জন, বীর উত্তম ৬৮ জন, বীর বিক্রম ১৭৫ জন, বীর প্রতীক ৪২৬ জন।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9729cd90dd5201a303054ad4f1b1c6a5'),
(7712, 696, 'জিয়া সার কারখানায় উৎপাদিত সারের নাম কি?', 'অ্যামোনিয়া', NULL, 'টিএসপি', NULL, 'ইউরিয়া', NULL, 'সুপার ফসফেট', NULL, 'C', 'জিয়া সার কারখানার বর্তমান নাম \"আশুগঞ্জ ফার্টিলাইজার অ্যান্ড কেমিক্যাল কোম্পানি লি.\"। কারখানাটি ব্রাহ্মণবাড়িয়া জেলার আশুগঞ্জে অবস্থিত। এ সার কারখানায় ইউরিয়া সার উৎপাদিত হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2a28637fdc6247f92166d5a476f72588'),
(7713, 749, 'বাংলাদেশের জাতীয় পতাকার ডিজাইনার কে?', 'জয়নুল আবেদিন', NULL, 'কামরুল হাসান', NULL, 'হামিদুর রহমান', NULL, 'হাশেম খান', NULL, 'B', 'মানচিত্রখচিত প্রথম জাতীয় পতাকার নকশা তৈরি করেন শিবনারায়ণ দাশ। পরবর্তীতে ১৯৭২ সালে বর্তমান জাতীয় পতাকার (মানচিত্রবিহীন) ডিজাইন করেন বাংলাদেশের প্রখ্যাত চিত্রশিল্পী কামরুল হাসান।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'af4e52ad920b2d25dde625923fa6d58c'),
(7714, 708, 'কোন উৎস থেকে বাংলাদেশ সরকারের সর্বোচ্চ রাজস্ব আয় হয়?', 'আয়কর', NULL, 'আমদানি ও রপ্তানি শুল্ক', NULL, 'ভূমি রাজস্ব', NULL, 'মূল্য সংযোজন কর', NULL, 'D', 'বাংলাদেশ সরকারের সর্বোচ্চ রাজস্ব আয় হয় মূল্য সংযোজন কর (VAT) থেকে। অর্থনৈতিক সমীক্ষা ২০২১-২২ অনুযায়ী ভ্যাট থেকে সর্বোচ্চ রাজস্ব আয় হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ed2824ec576b1b9e7d1ea347575d75c'),
(7715, 681, 'বাংলাদেশের একমাত্র প্রবাল দ্বীপের নাম কি?', 'সেন্টমার্টিন', NULL, 'মহেশখালী', NULL, 'হাতিয়া', NULL, 'সন্দ্বীপ', NULL, 'A', 'কক্সবাজার জেলায় টেকনাফের সমুদ্র উপকূল থেকে ৪৮ কিমি দক্ষিণে সেন্টমার্টিন দ্বীপ অবস্থিত। এর আয়তন প্রায় ৮ বর্গকিমি। এটি বাংলাদেশের একমাত্র প্রবাল দ্বীপ।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bb33fdc90975e5393bb6a5a89d8d228c'),
