(7728, 742, 'আইন-শৃঙ্খলা বিঘ্নকারী অপরাধ (দ্রুত বিচার) আইন জাতীয় সংসদে পাস হয় কোন সালের কত তারিখে?', '১৭ এপ্রিল, ২০০২', NULL, '৯ এপ্রিল, ২০০২', NULL, '১৮ মার্চ, ২০০২', NULL, '৩ এপ্রিল, ২০০২', NULL, 'B', 'আইন-শৃঙ্খলা বিঘ্নকারী অপরাধের দ্রুত বিচার সম্পন্ন করার জন্য জাতীয় সংসদে ২০০২ সালের ৯ এপ্রিল \"আইন-শৃঙ্খলা বিঘ্নকারী অপরাধ (দ্রুত বিচার) বিল ২০০২\" পাস হয়।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ff12e87142593f209003ada4f88b8cbf'),
(7729, 681, 'দক্ষিণ তালপট্টি দ্বীপের অপর নাম কি?', 'কুতুবদিয়া', NULL, 'সোনাদিয়া', NULL, 'সন্দ্বীপ', NULL, 'পূর্বাশা', NULL, 'D', 'সাতক্ষীরা জেলার হাড়িয়াভাঙ্গা নদীর মোহনায় দক্ষিণ তালপট্টি দ্বীপ অবস্থিত। ভারতের নিকট এটি পূর্বাশা বা নিউমুর নামে পরিচিত।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '82fbf93aefd4a2804414542e13a9aa29'),
(7730, 681, 'হালদা ভ্যালি কোথায় অবস্থিত?', 'রাঙ্গামাটি', NULL, 'খাগড়াছড়ি', NULL, 'বান্দরবান', NULL, 'সন্দ্বীপ', NULL, 'B', 'হালদা ভ্যালি খাগড়াছড়ি জেলায় অবস্থিত একটি উপত্যকা।', NULL, 174, '24th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bed952eea603dc1ad2c4bcf16e066a59'),
(7731, 681, 'পুনর্ভবা, নাগর ও ট্যাঙ্গন কোন নদীর উপনদী?', 'মহানন্দা', NULL, 'ভৈরব', NULL, 'কুমার', NULL, 'বড়াল', NULL, 'A', 'পুনর্ভবা, নাগর ও ট্যাঙ্গন নদী মহানন্দার উপনদী। অন্যদিকে ভৈরব, কুমার ও বড়াল নদী পদ্মার শাখা নদী।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0bbaf6914fd5305d741feb69448893ce'),
(7732, 681, 'প্রাচীন \"পুণ্ড্রনগর\" কোথায় অবস্থিত?', 'ময়নামতি', NULL, 'বিক্রমপুর', NULL, 'মহাস্থানগড়', NULL, 'পাহাড়পুর', NULL, 'C', 'বগুড়ার মহাস্থানগড়ে বাংলাদেশের সর্বপ্রাচীন বৃহৎ নগর পুণ্ড্রনগরের ধ্বংসাবশেষ বিদ্যমান। ১৮৭৯ সালে প্রত্নতত্ত্ববিদ স্যার আলেকজান্ডার কানিংহাম এ নগর সভ্যতার ধ্বংসাবশেষ শনাক্ত করেন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '06a98c0dec440eab8d0e29a53bd46f6f'),
(7733, 749, 'উপমহাদেশীয়দের মধ্যে ঢাকা বিশ্ববিদ্যালয়ের প্রথম ভাইস চ্যান্সেলর–', 'ড. রমেশচন্দ্র মজুমদার', NULL, 'ড. মাহমুদ হাসান', NULL, 'ড. সৈয়দ মোয়াজ্জেম হোসেন', NULL, 'স্যার এ এফ রহমান', NULL, 'D', 'উপমহাদেশীয়দের মধ্যে ঢাকা বিশ্ববিদ্যালয়ের প্রথম ভাইস চ্যান্সেলর ছিলেন স্যার আহমদ ফজলুর (এ. এফ রহমান, ১৮৮৯-১৯৪৫)। ১৯৩৪ থেকে ১৯৩৬ সাল পর্যন্ত তিনি ঢাকা বিশ্ববিদ্যালয়ের উপাচার্য ছিলেন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '324988f589fd587e347cd5d719f3469b'),
(7734, 728, 'প্রধান নির্বাচন কমিশনারের মেয়াদকাল কত?', '৪ বছর', NULL, '৫ বছর', NULL, '৩ বছর', NULL, '৭ বছর', NULL, 'B', 'প্রধান নির্বাচন কমিশনার একটি সাংবিধানিক পদ। সংবিধানের ১১৮(৩) অনুচ্ছেদে বলা হয়েছে, \"এই সংবিধানের বিধানাবলী সাপেক্ষে কোনো নির্বাচন কমিশনারের পদের মেয়াদ তাঁহার কার্যভার গ্রহণের তারিখ হইতে পাঁচ বৎসরকাল হইবে।\"', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0f5e7d18bdcc6a74d0bc1adcabbc14e3'),
(7735, 750, 'সার্কভুক্ত কোন দেশের দূতাবাস বাংলাদেশে নেই?', 'মালদ্বীপ', NULL, 'শ্রীলংকা', NULL, 'নেপাল', NULL, 'ভুটান', NULL, 'A', 'সার্কভুক্ত সকল দেশের দূতাবাস বাংলাদেশে রয়েছে। ১ এপ্রিল ২০০৮ মালদ্বীপের দূতাবাস বাংলাদেশে চালু হলে ও পরবর্তীতে ২০১৪ সালের ৩১ মার্চ আবার বন্ধ করে দেয়া হয়। পুনরায় ১ জানুয়ারি ২০১৫ মালদ্বীপ তাদের দূতাবাস বাংলাদেশে চালু করে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '74670742a69820da5568e05061977f16'),
(7736, 704, 'কোন বাংলাদেশী উপজাতির পারিবারিক কাঠামো পিতৃতান্ত্রিক?', 'মারমা', NULL, 'খাসিয়া', NULL, 'সাঁওতাল', NULL, 'গারো', NULL, 'C', 'অপশনে প্রদত্ত চারটি উপজাতির মধ্যে সাঁওতাল পিতৃতান্ত্রিক। খাসিয়া ও গারো উপজাতির পারিবারিক কাঠামো মাতৃতান্ত্রিক। বাংলাদেশে বসবাসরত ৫০টি উপজাতির মধ্যে গারো ও খাসিয়া ব্যতীত সকল উপজাতির পারিবারিক কাঠামো পিতৃতান্ত্রিক।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2631ba6e3076061a9597fa4a1d39bc89'),
(7737, 681, 'নিচের কোন পর্যটক সোনারগাঁও এসেছিলেন?', 'ফা-হিয়েন', NULL, 'ইবনে বতুতা', NULL, 'মার্কো পোলো', NULL, 'হিউয়েন সাং', NULL, 'B', 'জগদ্বিখ্যাত পর্যটক ইবনে বতুতা (১৩০৪-১৩৭৮ খ্রি) ছিলেন মরক্কোর অধিবাসী। ইবনে বতুতা সোনারগাঁওয়ে আসেন ১৩৪৬ সালে। মধ্যযুগের আর যেসব বিখ্যাত পরিব্রাজক সোনারগাঁও পরিভ্রমণ করেন, তারা হচ্ছেন চীনের মা হুয়ান ১৪০৬ সালে এবং হৌ হিয়েন ১৪১৫ সালে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '874ee78e9ba2da088a21760211352272'),
(7738, 748, 'বাংলাদেশে বর্তমানে কয় স্তরবিশিষ্ট স্থানীয় সরকার ব্যবস্থা চালু আছে?', '৩', NULL, '৪', NULL, '৫', NULL, '৬', NULL, 'A', 'বাংলাদেশে বর্তমানে গ্রামাঞ্চলে তিন স্তরবিশিষ্ট স্থানীয় সরকার ব্যবস্থা চালু আছে- প্রথম স্তর: ইউনিয়ন পরিষদ, দ্বিতীয় স্তর: উপজেলা পরিষদ ও তৃতীয় স্তর: জেলা পরিষদ। আর শহরাঞ্চলে রয়েছে দুই স্তরবিশিষ্ট স্থানীয় সরকার ব্যবস্থা।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0d7f1ae107641992987f1b9450a575af'),
(7739, 726, 'বাংলাদেশের অষ্টম জাতীয় সংসদে কোন সদস্য নিজেই নিজের কাছে সংসদ সদস্য হিসেবে শপথ নেন?', 'বেগম খালেদা জিয়া', NULL, 'শেখ হাসিনা', NULL, 'জমির উদ্দীন সরককার', NULL, 'আবদুল হামিদ', NULL, 'D', 'বাংলাদেশ জাতীয় সংসদ সদস্যদের শপথনামা সংবিধানের \"তৃতীয় তফসিল\"-এ লিপিবদ্ধ রয়েছে। অষ্টম সংসদে নির্বাচিত সংসদ সদস্য আবদুল হামিদ এডভোকেট নিজেই নিজের কাছে শপথ গ্রহণ করেন, যেহেতু তিনি নিজেই বিদায়ী স্পিকার ছিলেন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0a813c6a7febfd76c70cacfcf1b55231'),
(7740, 750, 'বাংলাদেশ কোন সনে CTBT অনুমোদন করে?', '১৯৯৯', NULL, '২০০০', NULL, '২০০১', NULL, '২০০২', NULL, 'B', 'CTBT- Comprehensive Test Ban Treaty বা পারমাণবিক অস্ত্র পরীক্ষা নিষিদ্ধকরণ চুক্তি। বাংলাদেশ ১৯৯৬ সালের ২৪ অক্টোবর ১২৯তম দেশ হিসেবে সিটিবিটিতে স্বাক্ষর করে। বাংলাদেশ ২০০০ সালের ৮ মার্চ ২৮তম ও দক্ষিণ এশিয়ার প্রথম দেশ হিসেবে এটি অনুমোদন করে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5eec246644d577a0da2928292755116a'),
(7741, 744, 'সদ্য ঘোষিত তিতাস উপজেলা কোন জেলায় অবস্থিত?', 'নোয়াখালী', NULL, 'কুমিল্লা', NULL, 'রংপুর', NULL, 'সিলেট', NULL, 'B', 'তিতাস দেশের ৪৭০তম উপজেলা। এটি কুমিল্লা জেলার অন্তর্ভুক্ত। বর্তমানে দেশে মোট উপজেলার সংখ্যা ৪৯৫টি।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '642c3baaccdc7cc0deeba4304de8c937'),
(7742, 726, 'বাংলাদেশ জাতীয় সংসদে কোরাম হয় কত সদস্যের উপস্থিতিতে?', '৫৭ জন', NULL, '৬০ জন', NULL, '৬২ জন', NULL, '৬৫ জন', NULL, 'B', 'সংবিধানের ৭৫(২) অনুচ্ছেদে বলা হয়েছে, \"সংসদের বৈঠক চলাকালে কোনো সময়ে উপস্থিত সদস্য সংখ্যা ষাটের কম বলিয়া যদি সভাপতির দৃষ্টি আকর্ষণ করা হয়, তাহা হইলে তিনি অন্যূন ষাট জন সদস্য উপস্থিত না হওয়া পর্যন্ত বৈঠক স্থগিত রাখিবেন কিংবা মুলতবী করিবেন।\"', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '58df7ccf6e99360f5fc754fd6c5aa1d9'),
(7743, 750, 'বাংলাদেশের একমাত্র কিশোরী সংশোধন প্রতিষ্ঠানটি কোথায় অবস্থিত?', 'টঙ্গি', NULL, 'কোনাবাড়ি', NULL, 'যশোর', NULL, 'গাজীপুর', NULL, 'B', '১০ ডিসেম্বর, ২০০২ তৎকালীন প্রধানমন্ত্রী বেগম খালেদা জিয়া গাজীপুরের কোনাবাড়িতে কিশোরী সংশোধন কেন্দ্রের উদ্বোধন করেন। বাংলাদেশে কিশোর ও কিশোরী উন্নয়ন কেন্দ্র রয়েছে ৩টি।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '672ff11237ca7fabf029a339b9baa8cf'),
(7744, 681, 'বাঙ্গালী ও যমুনা নদীর সংযোগ কোথায়?', 'রাজশাহী', NULL, 'পাবনা', NULL, 'বগুড়া', NULL, 'সিরাজগঞ্জ', NULL, 'C', 'রংপুর জেলার ঘাঘট নদীর অব্যাহত প্রবাহটি বগুড়ায় এসে বাঙ্গালী নাম ধারণ করেছে। এরপর নদীটি দক্ষিণে প্রবাহিত হওয়ার সময় যমুনার শাখানদী বাউলাই নদীকে উপনদী হিসেবে গ্রহণ করার মাধ্যমে যমুনার সাথে মিলিত হয়েছে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0fb21f7b3126fedc543e32e62631908d'),
(7745, 719, '\"সাবমেরিন কেবল\" প্রকল্পটি কোন মন্ত্রণালয়ের কার্যক্রম?', 'অর্থ', NULL, 'ডাক ও টেলিযোগাযোগ', NULL, 'বিজ্ঞান ও প্রযুক্তি', NULL, 'পররাষ্ট্র', NULL, 'B', '২০০৫ সালে প্রকল্প বাস্তবায়িত হয় এবং ৩৫ মিলিয়ন মার্কিন ডলার ব্যয়ে মধ্যপ্রাচ্যের সাথে ইউরোপভুক্ত ১৪টি দেশ এবং ১৬টি সংস্থা SEA-ME-WE-4 নামের ২২ হাজার কিলোমিটার বিস্তৃত অপটিক্যাল ফাইবার নেটওয়ার্কের সাথে যুক্ত হয় বাংলাদেশ। ২০০৮ সালে গঠিত হয় বাংলাদেশ সাবমেরিন ক্যাবল কোম্পানি লি. (BSCCL)।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '678f61e462c290ab91713a3d77edba52'),
(7746, 681, '২০০৪ সালে সর্বপ্রথম কোন দেশের রাষ্ট্রপ্রধান বাংলাদেশ সফর করেন?', 'থাইল্যান্ড', NULL, 'মিয়ানমার', NULL, 'ভিয়েতনাম', NULL, 'ভুটান', NULL, 'C', 'ভিয়েতনামের তৎকালীন রাষ্ট্রপ্রধান ট্রান দুক লুয়ং ২০০৪ সালে প্রথম (২২-২৪ মার্চ) বাংলাদেশ সফর করেন।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '36838635e539ae0859a844e3f3f1575a'),
(7747, 708, 'মূল্য সংযোজন কর বাংলাদেশে কখন থেকে চালু করা হয়?', '১ জুলাই, ১৯৯১', NULL, '১ জুলাই, ১৯৯৩', NULL, '১ জুলাই, ১৯৯৫', NULL, '১ জানুয়ারি, ১৯৯৬', NULL, 'A', 'ভ্যাট বা Value Added Tax-এর বাংলারূপ হলো মূল্য সংযোজন কর। ১৯৯১ সালের অর্থ আইন দ্বারা বাংলাদেশে মূল্য সংযোজন কর ব্যবস্থা প্রবর্তন করা হয়। ১ জুলাই, ১৯৯১ থেকে এ কর ব্যবস্থা কার্যকর হয়।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a886636b7681dea115a701c2d69092a0'),
(7748, 750, 'বাংলাদেশ উন্নয়ন ফোরামের সমন্বয়কারী কোন সংস্থা?', 'জাইকা', NULL, 'ইউএনডিপি', NULL, 'বিশ্বব্যাংক', NULL, 'আইএমএফ', NULL, 'C', '২০১৮ সালের ১৭-১৮ জানুয়ারি বাংলাদেশ উন্নয়ন ফোরামের সর্বশেষ বৈঠক অনুষ্ঠিত হয় ঢাকায়। এ সম্মেলনে বিশ্বব্যাংক, জাইকা, ইউএনডিপি ও আইএমএফসহ কতিপয় উন্নয়ন সহযোগী সংস্থা অংশগ্রহণ করে। তবে প্রধান সমন্বয়কারী বিশ্বব্যাংক।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5325b05d384f74a1c325435422e3f8a9'),
(7749, 681, 'কর্ণফুলী নদীর উৎস ভারতে কোন রাজ্যে?', 'ত্রিপুরা', NULL, 'মিজোরাম', NULL, 'মনিপুর', NULL, 'মেঘালয়', NULL, 'B', 'কর্ণফুলী নদীর উৎপত্তিস্থল ভারতের মিজোরাম রাজ্যের লুসাই পাহাড়ের লংলেহতে। এটি রাঙ্গামাটি এবং বন্দরনগরী চট্টগ্রামের মধ্য দিয়ে প্রবাহিত হয়ে পতেঙ্গার সন্নিকটে বঙ্গোপসাগরে পতিত হয়েছে।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '669ec1821f3a3f7b2d20eb7939062479'),
(7750, 752, 'ক্রিকেটে বাংলাদেশ কোন সালে টেস্ট মর্যাদা লাভ করে?', '২০০০', NULL, '২০০১', NULL, '১৯৯৯', NULL, '১৯৯৮', NULL, 'A', '২০০০ সালের জুন মাসে অনুষ্ঠিত আইসিসির সভায় বাংলাদেশকে টেস্ট সদস্যপদ প্রদানের ব্যাপারে আলোচনা করা হয় এবং ২৬ জুন ইংল্যান্ডের লর্ডসে অনুষ্ঠিত সভায় সর্বসম্মতিক্রমে বাংলাদেশকে পূর্ণ সদস্যপদ প্রদান করা হয়।', NULL, 175, '25th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '606ff013c7ccf728750c89ac9578f9ea'),
(7751, 683, 'আন্তর্জাতিক মাতৃভাষা দিবস কোন সালে স্বীকৃত হয়?', '১৯৯৮', NULL, '১৯৯৯', NULL, '২০০০', NULL, '২০০১', NULL, 'B', 'বাঙালি জাতির ১৯৫২ সালের আত্মত্যাগের দীর্ঘ ৪৭ বছর পর ১৯৯৯ সালের ১৭ নভেম্বর UNESCO ২১ ফেব্রুয়ারিকে \"আন্তর্জাতিক মাতৃভাষা দিবস\" হিসেবে স্বীকৃতি প্রদান করে। ২০০০ সালের ২১ ফেব্রুয়ারি UNESCO-র ১৮৮টি সদস্য রাষ্ট্রে এটি প্রথমবারের মতো পালিত হয়।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7ad090aa108ee9b9734ddbea5c77d489'),
(7752, 681, 'ঢাকায় বাংলার রাজধানী স্থাপনের সময় মোগল সুবেদার কে ছিলেন?', 'ইসলাম খান', NULL, 'ইব্রাহীম খান', NULL, 'শায়েস্তা খান', NULL, 'মীর জুমলা', NULL, 'A', 'মুঘল সম্রাট জাহাঙ্গীর ক্ষমতা গ্রহণ করে শেখ আলাউদ্দিন ইসলাম খান চিশতি বাংলার সুবেদার নিয়োগ করেন। ইসলাম খান ১৬১০ সালে রাজমহল থেকে স্থানান্তরিত করে ঢাকায় বাংলার রাজধানী স্থাপন করেন এবং সম্রাট জাহাঙ্গীরের নামানুসারে ঢাকার নামকরণ করেন জাহাঙ্গীরনগর।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8f278f9eecf8979a31adb6f1d59df161'),
(7753, 744, 'শিক্ষা বিভাগের ট্রেনিংয়ের শীর্ষ প্রতিষ্ঠান কোনটি?', 'বিয়াম', NULL, 'নায়েম', NULL, 'টিটিসি', NULL, 'ইউজিসি', NULL, 'B', 'নায়েম (NIEAM) -এর পূর্ণরূপ ন্যাশনাল ইনস্টিটিউট অব এডুকেশনাল অ্যাডমিনিস্ট্রেশন অ্যান্ড ম্যানেজমেন্ট। এটি শিক্ষা ক্যাডারের কর্মকর্তাদের বুনিয়াদি প্রশিক্ষণ এবং শিক্ষা প্রশাসন ও ব্যবস্থাপনা বিষয়ে ট্রেনিং প্রদান করে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e64d6279fdda26d81de6f7636f88a5be'),
(7754, 682, '\"সাবাশ বাংলাদেশ\" ভাস্কর্যটির শিল্পী কে?', 'হামিদুজ্জামান', NULL, 'নিতুন কুণ্ডু', NULL, 'মৃণাল হক', NULL, 'শামিম শিকদার', NULL, 'B', 'রাজশাহী বিশ্ববিদ্যালয়ের মতিহার সবুজ চত্বরে মুক্তাঙ্গনের উত্তর পার্শ্বে \"সাবাশ বাংলাদেশ\" ভাস্কর্যটি অবস্থিত। এর স্থপতি নিতুন কুণ্ডু।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c6bf99cf12dbd9b356720a691cdadd2'),
(7755, 753, '\"সূর্য দীঘল বাড়ি\" চলচ্চিত্রের পরিচালক কে?', 'শেখ নিয়ামত শাকের', NULL, 'জহির রায়হান', NULL, 'সুভাষ দত্ত', NULL, 'খান আতা', NULL, 'A', '\"সূর্য দীঘল বাড়ি\" উপন্যাস অবলম্বনে চলচ্চিত্র নির্মিত হয় শেখ নিয়ামত আলী এবং মসিহউদ্দিন শাকেরের পরিচালনায়। আর মূল উপন্যাসটির রচয়িতা আবু ইসহাক।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6d325a4e91bd12c9bc015a9acd14fd18'),
(7756, 711, 'স্টক শেয়ারে প্রবর্তিত নতুন পদ্ধতি কোনটি?', 'ডিভিডেন্ড', NULL, 'ডিভ্যালু', NULL, 'ডিম্যাট', NULL, 'ডিসকাউন্ট', NULL, 'C', 'সিকিউরিটি ও এক্সচেঞ্জ কমিশন স্টক শেয়ারের ক্ষেত্রে ডিম্যাট (demat) ব্যবস্থার শেয়ার লেনদেনে ডিপজিটরি পদ্ধতি চালু, আন্তর্জাতিক মান ও পদ্ধতি প্রবর্তন, প্রয়োজনীয় অবকাঠামো গড়ে তোলা ইত্যাদি পদক্ষেপ গ্রহণ করে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1dcbf0e97ec4b3e405cd897d5526e4d5'),
