(7787, 681, 'গ্রিন হাউজ ইফেক্টের জন্য বাংলাদেশে কোন ধরনের ক্ষতি হতে পারে?', 'নিম্নভূমি নিমজ্জিত হবে', NULL, 'ক্রমশ উত্তাপ বেড়ে যাবে', NULL, 'বৃষ্টিপাত কমে যাবে', NULL, 'বৃষ্টিপাতের পরিমাণ বাড়বে', NULL, 'A', 'গ্রিন হাউজ ইফেক্টের ফলে বায়ুমণ্ডল উত্তপ্ত হচ্ছে। ফলে মেরু অঞ্চলের বরফ ক্রমে গলে যাচ্ছে। এর ফলে পৃথিবীর নিম্নভূমি ক্রমশ নিমজ্জিত হবে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5a732c79685096e1d87cf183ab815952'),
(7788, 742, 'বেসরকারি বিল কাকে বলে?', 'স্পিকার যে বিলকে বেসরকারি বলে ঘোষণা দেন', NULL, 'সংসদ সদস্যদের উত্থাপিত বিল', NULL, 'বিরোধী দলের সদস্যদের উত্থাপিত বিল', NULL, 'রাষ্ট্রপতি কর্তৃক ঘোষিত বিল', NULL, 'B', 'মন্ত্রী ছাড়া অন্য সংসদ সদস্য কর্তৃক উত্থাপিত বিলকে বেসরকারি বিল বলে। সংসদের ৭২(১) বিধি অনুসারে মন্ত্রী ব্যতীত সকল সংসদ সদস্য সংসদে বেসরকারি বিল উত্থাপনের নোটিশ দিতে পারে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5554df1d895b8b8393d8e5bc6ce051e7'),
(7789, 696, 'বাংলাদেশে কৃষিক্ষেত্রে \"বলাকা\" ও \"দোয়েল\" নাম দুটি কিসের?', 'দুটি কৃষি যন্ত্রপাতির নাম', NULL, 'দুটি কৃষি সংস্থার নাম', NULL, 'উন্নতজাতের গম শস্য', NULL, 'কৃষি খামারের নাম', NULL, 'C', 'বলাকা ও দোয়েল ছাড়াও উন্নতজাতের আরো কিছু গম শস্য হলো সোনালিকা, আকবর, আনন্দ, কাঞ্চন, বরকত, অগ্রণী, ইনিয়া ৬৬, জোপাটিকা।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b6b90bd8766faa25d82e8db577b11c2b');
