(7790, 752, 'প্রথম আইসিসি ট্রফিতে বাংলাদেশ দলের অধিনায়ক কে ছিলেন?', 'গাজী আশরাফ হোসেন লীপু', NULL, 'আকরাম খান', NULL, 'আমিনুল ইসলাম বুলবুল', NULL, 'শফিকুল হক হীরা', NULL, 'D', '১৯৯১ সালে ইংল্যান্ডে অনুষ্ঠিত প্রথম আইসিসি ট্রফিতে বাংলাদেশ অংশগ্রহণ করে। বাংলাদেশ দলের অধিনায়কত্ব করেন শফিকুল হক হীরা।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3e8267f8f589f259516571f90d644f5c'),
(7791, 681, 'বাংলাদেশের কোথায় সুরমা ও কুশিয়ারা নদী মিলিত হয়ে মেঘনা নাম ধারণ করেছে?', 'ভৈরব', NULL, 'চাঁদপুর', NULL, 'দেওয়ানগঞ্জ', NULL, 'আজমিরীগঞ্জ', NULL, 'A', 'সুরমা ও কুশিয়ারা হবিগঞ্জের আজমিরীগঞ্জে মিলিত হয়ে কালনি নাম ধারণ করে এবং ভৈরববাজারের নিকট মেঘনা নাম ধারণ করে বঙ্গোপসাগরে পতিত হয়েছে।', NULL, 4, '26th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f5d955966c91a5940158d3dfcf1a8693'),
(7792, 744, 'NIPORT কি?', 'জনসংখ্যা বিষয়ক গবেষণা প্রতিষ্ঠান', NULL, 'পোলট্রি ফার্ম বিষয়ক গবেষণা প্রতিষ্ঠান', NULL, 'নদীবন্দর বিষয়ক গবেষণা প্রতিষ্ঠান', NULL, 'বন্দর বিষয়ক গবেষণা প্রতিষ্ঠান', NULL, 'A', 'NIPORT এর পূর্ণরূপ National Institute of Population Research and Training। এটি জনসংখ্যা বিষয়ক গবেষণা প্রতিষ্ঠান। ১৯৭৭ সালে ন্যাশনাল ইনস্টিটিউট অব পপুলেশন ট্রেনিং (NIPOT) নামে প্রতিষ্ঠিত হয় এবং পরে এটির নাম NIPORT করা হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '67c8f7699bf9676cee0518a4d26cfad4'),
(7793, 724, 'সংবিধানের কোন অনুচ্ছেদে \"রাষ্ট্র ও গণজীবনের সর্বস্তরে নারী পুরুষের সমান অধিকার লাভ করিবেন\" বলা আছে?', '১০ নং অনুচ্ছেদে', NULL, '২১ (২) নং অনুচ্ছেদে', NULL, '২৭ নং অনুচ্ছেদে', NULL, '২৮ (২) নং অনুচ্ছেদে', NULL, 'D', 'গণপ্রজাতন্ত্রী বাংলাদেশ সংবিধানের তৃতীয় ভাগের ২৮(২) নং অনুচ্ছেদে রাষ্ট্র ও গণজীবনের সর্বস্তরে নারীপুরুষের সমান অধিকার বিষয়ে বলা হয়েছে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '366e333fec1737ff1525ff77be60e3c0'),
(7794, 706, 'UNDP রিপোর্ট সেপ্টেম্বর ২০০৫ সাল মোতাবেক বাংলাদেশের মাথাপিছু আয় কত?', '৪৪৪ ডলার', NULL, '৭৭০ ডলার', NULL, '১০৭০ ডলার', NULL, '১৭৭০ ডলার', NULL, 'A', 'UNDP রিপোর্ট সেপ্টেম্বর ২০০৫ সাল মোতাবেক বাংলাদেশের মাথাপিছু আয় ছিল ৪৪৪ ডলার। বর্তমানে বাংলাদেশের মাথাপিছু আয় ২৮২৪ মার্কিন ডলার।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fdc85b1f754bd57c1c6ccb052706c372'),
(7795, 682, 'স্বাধীনতা যুদ্ধে অবদানের জন্যে \"বীরপ্রতীক\" উপাধি লাভ করে কতজন?', '৭ জন', NULL, '৬৮ জন', NULL, '১৭৫ জন', NULL, '৪২৬ জন', NULL, 'D', 'বাংলাদেশের স্বাধীনতা যুদ্ধে অবদান রাখার জন্য মোট ৬৭৬ জনকে বীরত্বসূচক উপাধি প্রদান করা হয়। এর মধ্যে ৭ জনকে বীরশ্রেষ্ঠ, ৬৮ জনকে বীর উত্তম, ১৭৫ জনকে বীর বিক্রম এবং ৪২৬ জনকে বীর প্রতীক উপাধি প্রদান করা হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ad6e84f7d3f4c681f3cf86497a692f17'),
(7796, 696, 'বাংলাদেশের ইক্ষু গবেষণা ইনস্টিটিউট কোথায় অবস্থিত?', 'দিনাজপুর', NULL, 'গোপালপুর', NULL, 'পাকশী', NULL, 'ঈশ্বরদী', NULL, 'D', 'পাবনা জেলার ঈশ্বরদীতে বাংলাদেশ ইক্ষু গবেষণা ইনস্টিটিউট অবস্থিত। বর্তমানে এর নাম বাংলাদেশ সুগারক্রপ রিসার্চ ইনস্টিটিউট।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd568516f44865b0daab94e3093ae1e74'),
(7797, 750, 'মিলেনিয়াম ডেভেলপমেন্ট গোল অর্জন করার কথা কোন সময়ে?', '২০১০ সালে', NULL, '২০১৫ সালে', NULL, '২০২০ সালে', NULL, '২০২৫ সালে', NULL, 'B', 'মিলেনিয়াম ডেভেলপমেন্ট গোল (MDG) ২০০০ সালে অনুষ্ঠিত সহস্রাব্দ উন্নয়ন সম্মেলনে গৃহীত হয়। যাতে বিশ্ববাসীর জন্য ২০১৫ সালের মধ্যে অর্জনযোগ্য ৮টি লক্ষ্য নির্ধারণ করা হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5e100f4f4ccbe024cda52c3af0213d98'),
(7798, 682, 'রাজারবাগ পুলিশ লাইনে \"দুর্জয়\" ভাস্কর্যটির শিল্পী কে?', 'হামিদুর রহমান', NULL, 'মৃণাল হক', NULL, 'শামিম শিকদার', NULL, 'নভেরা আহমেদ', NULL, 'B', 'দুর্জয় ভাস্কর্যটির শিল্পী মৃণাল হক। তার অন্যান্য গুরুত্বপূর্ণ শিল্পকর্ম হচ্ছে মতিঝিল বিমান অফিসের সামনের বলাকা এবং রাজশাহী বিশ্ববিদ্যালয়ের গোল্ডেন জুবিলি টাওয়ার।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e9b1fbaab9604bff18a4fa93b0f73117'),
(7799, 744, 'চট্টগ্রাম-কক্সবাজার সাবমেরিন কেবলস অপটিক্যাল ফাইবার স্থাপন করার জন্য বাংলাদেশ সরকারকে কত দূরত্বের ব্যয় বহন করতে হবে?', '৭০০ কিমি', NULL, '৫৭০ কিমি', NULL, '৩০০ কিমি', NULL, '১৭০ কিমি', NULL, 'D', 'চট্টগ্রাম থেকে কক্সবাজার পর্যন্ত অপটিক্যাল ফাইবার স্থাপনের জন্য ১৭০ কিমি দূরত্বের ব্যয় সরকারকে বহন করতে হয়। ২১ মে ২০০৬ সাবমেরিন ক্যাবল উদ্বোধনের মাধ্যমে বাংলাদেশ তথ্যপ্রযুক্তির এ মহাসড়কে যুক্ত হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ef88aa426f9cb6a3f605a6db8330d15c'),
(7800, 682, 'রাজেন্দ্রপুর সেনানিবাসে অবস্থিত মুক্তিযুদ্ধের স্মৃতিস্তম্ভের নাম কি?', 'বিজয়স্তম্ভ', NULL, 'বিজয়কেতন', NULL, 'স্বাধীনতা সোপান', NULL, 'রক্ত সোপান', NULL, 'B', 'রাজেন্দ্রপুর সেনানিবাসে অবস্থিত মুক্তিযুদ্ধের স্মৃতিস্তম্ভের নাম বিজয়কেতন।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fc77d1c7de71f5feda5fcbc58a2876ed'),
(7801, 750, 'বাংলাদেশের পোস্টাল একাডেমি কোথায় অবস্থিত?', 'রাজশাহী', NULL, 'ঢাকা', NULL, 'চট্টগ্রাম', NULL, 'খুলনা', NULL, 'A', 'ডাক বিভাগের কর্মকর্তা-কর্মচারীদের প্রশিক্ষণ দানের লক্ষ্যে ১৯৮৬ সালে রাজশাহীতে একটি পোস্টাল একাডেমি স্থাপন করা হয়েছে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f0e931abbc9d2f13460c9589f765bd5a'),
(7802, 750, 'প্রস্তাবিত পদ্মা সেতুর দৈর্ঘ্য কত কিমি?', '৫.০৩', NULL, '৬.০৩', NULL, '৪.৮', NULL, '৬.৮', NULL, 'B', 'পদ্মা সেতুর দৈর্ঘ্য ৬.১৫ কিলোমিটার। ২৭তম বিসিএসের সময় প্রস্তাবিত দৈর্ঘ্য ছিল ৬.০৩ কিমি।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8ed3bf70956723ea7abf00e9f8470646'),
(7803, 749, 'বাংলাদেশে সর্বপ্রথম কোন মহিলা টেস্টটিউব শিশুর মা হন?', 'পারভীন ফাতেমা', NULL, 'ফিরোজা বেগম', NULL, 'রওশন জাহান', NULL, 'কানিজ ফাতেমা', NULL, 'B', '৩০ মে ২০০১ ধানমণ্ডির সেন্ট্রাল হসপিটালে জন্মলাভ করে হীরা, মণি ও মুক্তা নামে ৩টি টেস্ট টিউব শিশু। এদের মা ছিলেন ফিরোজা বেগম।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c09ae6eb9707884c59ebba9f9761f73c'),
(7804, 695, 'বাংলাদেশ জাতিসংঘের কততম সদস্য?', '১৩৬ তম', NULL, '১৩৭ তম', NULL, '১৩৮ তম', NULL, '১৩৯ তম', NULL, 'A', 'বাংলাদেশ জাতিসংঘের ১৩৬তম সদস্য। ১৭ সেপ্টেম্বর ১৯৭৪ জাতিসংঘের ২৯তম অধিবেশনে ৩টি দেশ সদস্যপদ লাভ করে। বাংলাদেশ ১৩৬তম, গ্রানাডা ১৩৭তম এবং গিনি বিসাউ ১৩৮তম সদস্যপদ লাভ করে।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6f52132e1d9c0aacb03eaa3115bafa85'),
(7805, 682, 'কেন্দ্রীয় শহীদ মিনারের স্থপতি কে?', 'তানভীর কবীর', NULL, 'হামিদুর রহমান', NULL, 'হামিদুজ্জামান', NULL, 'অস্কার বাদল', NULL, 'B', '১৯৫২ সালের ২১ ফেব্রুয়ারির ভাষা শহিদদের স্মরণে হামিদুর রহমানের নকশা ও পরিকল্পনায় ১৯৫৭ সালের নভেম্বর মাসে দ্বিতীয় বারের মতো শহিদ মিনারের নির্মাণ কাজ শুরু হয় এবং ১৯৫৮ সালের ২১ ফেব্রুয়ারি উদ্ধোধন করা হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '42aa84a9311ca2b10d9b734471936c30'),
(7806, 749, 'জাতিসংঘ সাধারণ পরিষদের প্রথম বাংলাদেশী সভাপতি কে?', 'বি এ সিদ্দিকী', NULL, 'খাজা ওয়াসিউদ্দিন', NULL, 'হুমায়ুন রশীদ চৌধুরী', NULL, 'শমসের মবিন চৌধুরী', NULL, 'C', 'হুমায়ুন রশীদ চৌধুরী জাতিসংঘের সাধারণ পরিষদের ৩৯তম অধিবেশনে বাংলাদেশ প্রতিনিধি দলের নেতৃত্ব দেন। ১৯৮৬ সালের ১৬ ডিসেম্বর তিনি জাতিসংঘের সাধারণ পরিষদের ৪১তম অধিবেশনের সভাপতির দায়িত্ব লাভ করেন।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dd748f07f1421af56a6be6e863aa523a'),
(7807, 682, 'স্বাধীনতা যুদ্ধে অবদান রাখার জন্য কতজন মহিলাকে বীরপ্রতীক উপাধিতে ভূষিত করা হয়?', '৫ জন', NULL, '৭ জন', NULL, '২ জন', NULL, '৬ জন', NULL, 'C', 'বাংলাদেশের স্বাধীনতা যুদ্ধে বীরত্বসূচক অবদানের জন্য বাংলাদেশ সরকার দুজন মহিলাকে বীর প্রতীক খেতাবে ভূষিত করে। তারা হচ্ছেন ক্যাপ্টেন সেতারা বেগম এবং মোসাম্মৎ তারামন বেগম।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6f7c270e71f499894ff1eaf142f89eec'),
(7808, 719, 'কর্মসংস্থান ব্যাংক প্রতিষ্ঠিত হয় কোন সনে?', '১৯৯৫', NULL, '১৯৯৬', NULL, '১৯৯৮', NULL, '২০০১', NULL, 'C', 'শিক্ষিত বেকার যুবকদের কর্মসংস্থানের লক্ষ্যে ১৯৯৮ সালের ৩০ জুন প্রতিষ্ঠিত হয় কর্মসংস্থান ব্যাংক। এর সদর দপ্তর ঢাকার মতিঝিলে অবস্থিত।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7927a6db0fe5f178aedacb6ad95966dd'),
(7809, 700, 'লোকসংখ্যার দিক থেকে বাংলাদেশ বিশ্বের কততম স্থানে?', '৫ম', NULL, '৭ম', NULL, '৮ম', NULL, '১০ম', NULL, 'C', 'UNFPA এর জনসংখ্যা বিষয়ক রিপোর্ট ২০০৪ অনুযায়ী বাংলাদেশ বিশ্বের ৭ম জনসংখ্যার দেশ এবং UNFPA এর জনসংখ্যা রিপোর্ট ২০০৫ এ বাংলাদেশের অবস্থান দাঁড়ায় অষ্টমে। সর্বশেষ ২০২৩ সালের UNFPA রিপোর্ট মতে বাংলাদেশ বিশ্বের অষ্টম জনসংখ্যার দেশ।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'efed53e3dfd90fceb8cd193cd97ea260'),
(7810, 681, 'সেন্ট মার্টিন দ্বীপের আয়তন কত বর্গ কিলোমিটার?', '৮', NULL, '১০', NULL, '১২', NULL, '১৪', NULL, 'A', 'বাংলাদেশের একমাত্র প্রবাল দ্বীপ সেন্ট মার্টিনের আয়তন ৮ বর্গকিলোমিটার। দ্বীপটির স্থানীয় নাম নারিকেল জিঞ্জিরা।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b3f1a476301c1527c23cae073c0872da'),
(7811, 750, 'বাংলাদেশে পরমাণু শক্তি কমিশন গঠিত হয় কোন সনে?', '১৯৭২', NULL, '১৯৭৩', NULL, '১৯৭৫', NULL, '১৯৯৭', NULL, 'B', 'বাংলাদেশের একমাত্র পরমাণু শক্তি গবেষণা ও উন্নয়ন প্রতিষ্ঠান ১৯৭৩ সালের ২৭ ফেব্রুয়ারি প্রতিষ্ঠিত হয়।', NULL, 176, '27th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e4250105b1f4fdde60fa4f21a854a884'),
(7812, 681, 'কোন গোষ্ঠী থেকে বাঙালি জাতির প্রধান অংশ গড়ে উঠেছে?', 'নেগ্রিটো', NULL, 'ভোটচীন', NULL, 'দ্রাবিড়', NULL, 'অস্ট্রিক', NULL, 'D', 'বাঙালি একটি সংকর জাতি। নৃতাত্ত্বিক বিচারে অনার্য ভাষাভাষী কোল, শবর, পুলিন্দ, হাড়ি, ডোম, চণ্ডাল প্রভৃতি বাংলার আদিম অধিবাসী, যারা অস্ট্রিক বা অস্ট্রো-এশিয়াটিক গোষ্ঠীর অন্তর্ভুক্ত। বাঙালি জাতির প্রধান অংশ গড়ে উঠেছে অস্ট্রিক বা অনার্য গোষ্ঠী থেকে।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1923d32b21b55f794f8e50f64e5b64c5'),
(7813, 681, 'ঢাকায় সর্বপ্রথম কবে বাংলার রাজধানী স্থাপিত হয়?', '১২০৬ খ্রিস্টাব্দে', NULL, '১৩১০ খ্রিস্টাব্দে', NULL, '১৬১০ খ্রিস্টাব্দে', NULL, '১৫২৬ খ্রিস্টাব্দে', NULL, 'C', 'ঢাকায় সর্বপ্রথম বাংলার রাজধানী স্থাপিত হয় ১৬১০ খ্রিস্টাব্দে। সুবেদার ইসলাম খান বিহারের রাজমহল থেকে ঢাকায় সর্বপ্রথম রাজধানী স্থানান্তর করেন এবং নামকরণ করেন জাহাঙ্গীরনগর।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9174ea9da05461371361631207294e4f'),
(7814, 684, 'ঐতিহাসিক ২১-দফা দাবীর প্রথম দাবিটি কি ছিল?', 'বাংলাকে অন্যতম রাষ্ট্রভাষা', NULL, 'প্রাদেশিক স্বায়ত্তশাসন', NULL, 'পূর্ববাংলার অর্থনৈতিক বৈষম্য দূরীকরণ', NULL, 'বিনা ক্ষতিপূরণে জমিদারী উচ্ছেদ', NULL, 'A', '১৯৫৪ সালে পূর্ববঙ্গ প্রাদেশিক নির্বাচনে অংশগ্রহণের জন্য যুক্তফ্রন্ট থেকে ২১টি প্রতিশ্রুতি সম্বলিত যে নির্বাচনী মেনিফেস্টো ঘোষণা করা হয় তাই ২১ দফা নামে পরিচিত। উক্ত দফায় ১ম দফা: বাংলাকে পাকিস্তানের অন্যতম রাষ্ট্রভাষা হিসেবে স্বীকৃতি দেয়া।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '54c720a2d69345db57ffe42fc88fdbb8'),
(7815, 682, 'অপরাজেয় বাংলা কবে উদ্বোধন করা হয়?', '১৬ ডিসেম্বর, ১৯৭৯', NULL, '২৬ ডিসেম্বর, ১৯৭৯', NULL, '১ জানুয়ারি, ১৯৮০', NULL, '২১ ফেব্রুয়ারি, ১৯৮০', NULL, 'A', 'ত্রিভুজাকৃতি ভূমির সামান্য কিছু ওপরে বন্দুক কাঁধে নারী ও পুরুষের সম্মিলিতভাবে মুক্তিযুদ্ধে অংশগ্রহণের ও বিজয়ের প্রতীক \"অপরাজেয় বাংলা\" ঢাকা বিশ্ববিদ্যালয়ের কলাভবন চত্বরে অবস্থিত। এটি উদ্বোধন করা হয় ১৬ ডিসেম্বর, ১৯৭৯। এর স্থপতি সৈয়দ আব্দুল্লাহ খালেদ।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'afc0422c682717909a94c8b27099905f'),
(7816, 682, 'জাতীয় স্মৃতিসৌধের উচ্চতা কত?', '৪৬.৫ মি', NULL, '৪৬ মি', NULL, '৪৫.৫ মি', NULL, '৪৫ মি', NULL, 'A', 'ঢাকার সাভারের নবীনগরে অবস্থিত জাতীয় স্মৃতিসৌধের উচ্চতা ৪৬.৫ মিটার। ১৬ ডিসেম্বর, ১৯৭২ এর ভিত্তিপ্রস্তর স্থাপন করেন বঙ্গবন্ধু শেখ মুজিবুর রহমান এবং ১৬ ডিসেম্বর, ১৯৮২ তৎকালীন রাষ্ট্রপতি হুসেইন মুহম্মদ এরশাদ এটি উদ্বোধন করেন। এর স্থপতি সৈয়দ মাইনুল হোসেন।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b557e37173def314d6438bf1b0b39714'),
(7817, 704, 'হাজংদের অধিবাস কোথায়?', 'ময়মনসিংহ ও নেত্রকোণা', NULL, 'কক্সবাজার ও রামু', NULL, 'রংপুর ও দিনাজপুর', NULL, 'সিলেট ও মণিপুর', NULL, 'A', 'হাজংদের অধিবাস ময়মনসিংহ, নেত্রকোণা, শেরপুর ও সিলেট অঞ্চলে। হাজংরা পিতৃতান্ত্রিক সমাজের অন্তর্ভুক্ত।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '09641f1664ebb3c355f612ec8c95583c'),
(7818, 681, 'নিঝুম দ্বীপের আয়তন কত?', '৮০ ব.মা.', NULL, '৮২ ব.মা.', NULL, '৮৫ ব.মা.', NULL, '৯০ ব.মা.', NULL, 'D', 'নিঝুম দ্বীপ মেঘনা নদীর মোহনায় অবস্থিত। ১৯৬০ সালে নোয়াখালীর মাঝিরা এটি আবিষ্কার করেন। এর পুরনো নাম বাউলার চর। নিঝুম দ্বীপের আয়তন ৯১ বর্গ.কি.মি. বা ৩৫ বর্গ মাইল। (প্রায় ৯০ ব.মা.)', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0931617ab20259eb582979ee7c8c1c22'),
(7819, 744, 'বাংলাদেশে গ্রামের সংখ্যা কত?', '৮৫৪৫০টি', NULL, '৮৪৫০০টি', NULL, '৮৫৫০০টি', NULL, '৮৩৯০০টি', NULL, 'A', '২০২২ সালের ৬ষ্ঠ জনশুমারি অনুযায়ী বাংলাদেশের গ্রামের সংখ্যা ৮৭৩৯১টি। ৪,৪৮৪টি ইউনিয়ন, ৫৯,৯৯০টি মৌজা। (দ্রষ্টব্য: ২৮তম বিসিএসের সময় ৮৫৪৫০টি ছিল)', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dc7d81b450dab1b65257b0eb3770aad4'),
(7820, 726, 'বাংলাদেশের প্রথম জাতীয় সংসদ নির্বাচন কবে হয়?', '৭ মার্চ, ১৯৭৩', NULL, '৫ মার্চ, ১৯৭৩', NULL, '৬ এপ্রিল, ১৯৭৩', NULL, '১১ এপ্রিল, ১৯৭৩', NULL, 'A', 'বাংলাদেশের প্রথম জাতীয় সংসদ নির্বাচন অনুষ্ঠিত হয় ৭ মার্চ, ১৯৭৩।', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '22a097820b036e21700c84dfab3343ef'),
(7821, 748, 'বাংলাদেশের সবচেয়ে ছোট ইউনিয়ন কোনটি?', 'সেন্টমার্টিন', NULL, 'লালপুর', NULL, 'হিলি', NULL, 'লালমোহন', NULL, 'A', 'ষষ্ঠ জনশুমারি ও গৃহগণনা রিপোর্ট-২০২২ অনুসারে বাংলাদেশের ক্ষুদ্রতম ইউনিয়ন হচ্ছে হাজীপুর, দৌলতখান (ভোলা)। (দ্রষ্টব্য: ২৮তম বিসিএসের সময় সেন্টমার্টিন ছিল সবচেয়ে ছোট ইউনিয়ন)', NULL, 177, '28th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e96337535460c27e2917eb414064834d'),
(7822, 750, 'ঢাকা বিশ্ববিদ্যালয় কত সালে প্রতিষ্ঠিত হয়েছে?', '১৯১১ সালে', NULL, '১৯২১ সালে', NULL, '১৯৩১ সালে', NULL, '১৯৪১ সালে', NULL, 'B', '১৯২০ সালে ভারতীয় বিধান পরিষদে গৃহীত ঢাকা বিশ্ববিদ্যালয় আইন অনুসারে ১৯২১ সালের ১ জুলাই ঢাকা বিশ্ববিদ্যালয় প্রতিষ্ঠিত হয়। ঢাকা বিশ্ববিদ্যালয়ের প্রথম চ্যান্সেলর লর্ড ডানডাস (জেসিআই) এবং প্রথম ভাইস চ্যান্সেলর পি জে (ফিলিপ জোসেফ) হার্টজ।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '61a96b12efdfff3d8889fb1f3525b6c5'),
(7823, 750, 'বাংলাদেশে কয়টি সরকারি বিশ্ববিদ্যালয় রয়েছে?', '১৪টি', NULL, '২৪টি', NULL, '৩৪টি', NULL, '৫০টি', NULL, 'D', 'বাংলাদেশে একাডেমিক কার্যক্রম চলছে এমন সরকারি বিশ্ববিদ্যালয় ৫৩টি। (দ্রষ্টব্য: ২৯তম বিসিএসের সময় ৫০টি ছিল)', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '62cbff49013fd237e45067ba8d690b7f'),
(7824, 681, 'বঙ্গভঙ্গের সময় ভারতের গভর্নর জেনারেল কে ছিলেন?', 'লর্ড কার্জন', NULL, 'লর্ড ওয়েলেসলি', NULL, 'লর্ড ডালহৌসি', NULL, 'লর্ড মাউন্টব্যাটেন', NULL, 'A', 'লর্ড কার্জন ১৮৯৯ সালে ভারতের ভাইসরয় নিযুক্ত হন। তিনি ১৯০৫ সালে বেঙ্গল প্রেসিডেন্সিকে বিভক্ত করলে নবগঠিত পূর্ববাংলা ও আসাম প্রদেশের প্রথম লেফটেন্যান্ট গভর্নর নিযুক্ত হন মি. ব্রামফিল্ড ফুলার।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1e740fc34c441292db85a57aa4e70557'),
(7825, 748, 'বাংলাদেশের ক্ষুদ্রতম ইউনিয়ন পরিষদ কোনটি?', 'সেন্টমার্টিন', NULL, 'সাতগ্রাম', NULL, 'মুজিবনগর', NULL, 'চৌদ্দগ্রাম', NULL, 'A', 'প্রদত্ত অপশনগুলোর মধ্যে সেন্টমার্টিন বাংলাদেশের সবচেয়ে ছোট ইউনিয়ন। টেকনাফ থেকে ৪৮ কিলোমিটার দূরে অবস্থিত সেন্টমার্টিন বাংলাদেশের একমাত্র প্রবাল দ্বীপ।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ea524992bf0a8086c30ea5ede876c6be'),
(7826, 725, 'বাংলাদেশের প্রথম রাষ্ট্রপতির নাম কি?', 'সৈয়দ নজরুল ইসলাম', NULL, 'তাজউদ্দীন আহমদ', NULL, 'শেখ মুজিবুর রহমান', NULL, 'ক্যাপটেন মনসুর আলী', NULL, 'C', '১৯৭১ সালের ১০ এপ্রিল বঙ্গবন্ধু শেখ মুজিবুর রহমানকে তার অবর্তমানে রাষ্ট্রপতি এবং সশস্ত্র বাহিনী ও মুক্তিযুদ্ধের সর্বাধিনায়ক করে সরকার গঠন করা হয়। সৈয়দ নজরুল ইসলাম ছিলেন মুজিবনগর সরকারের অস্থায়ী রাষ্ট্রপতি।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '01fe41e2e9dd4052cc663ad2d513df04'),
(7827, 681, 'সুলতানী আমলে বাংলার রাজধানীর নাম কি?', 'সোনারগাঁ', NULL, 'জাহাঙ্গীরনগর', NULL, 'ঢাকা', NULL, 'গৌড়', NULL, 'A', 'সুলতানী আমলে (১৩৩৮-১৩৫২) খ্রিষ্টাব্দ পর্যন্ত বাংলার রাজধানী ছিল সোনারগাঁ আর (১৪১৮-১৫৬৫) খ্রিষ্টাব্দ পর্যন্ত বাংলার রাজধানী ছিল গৌড়।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ade49dc4ba28b7c7f3b8d014583edadc'),
(7828, 692, 'বাংলাদেশের মুক্তিযুদ্ধের প্রধান সেনাপতি কে ছিলেন?', 'শেখ মুজিবুর রহমান', NULL, 'জেনারেল আতাউল গনি ওসমানি', NULL, 'তাজউদ্দিন আহমদ', NULL, 'ক্যাপটেন মনসুর আলী', NULL, 'B', '১৯৭১ সালের ১০ এপ্রিল মুজিবনগরে গঠিত বাংলাদেশ সরকারের সিদ্ধান্তক্রমে ১১ এপ্রিল ১৯৭১ জেনারেল আতাউল গণি ওসমানীকে বাংলাদেশ সশস্ত্র বাহিনী ও মুক্তিবাহিনীর প্রধান সেনাপতি নিযুক্ত করা হয়।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5e17394e6a252d47d4bcb7e7ead22acd'),
(7829, 744, 'পার্বত্য চট্টগ্রামে কয়টি জেলা আছে?', '৩টি', NULL, '৫টি', NULL, '৭টি', NULL, '৯টি', NULL, 'A', 'আশির দশকের প্রথমদিকে দেশব্যাপী প্রশাসনিক সংস্কারের অংশ হিসেবে পার্বত্য চট্টগ্রামকে ৩টি স্বতন্ত্র জেলায় বিভক্ত করা হয়। জেলাগুলো হচ্ছে- ১. রাঙামাটি, ২. খাগড়াছড়ি, ৩. বান্দরবান।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '01e9714534e2faeb86a0acb880be02e4'),
(7830, 692, 'মুক্তিযুদ্ধের সময় বাংলাদেশকে কয়টি সেক্টরে ভাগ করা হয়েছিল?', '৪টি', NULL, '৭টি', NULL, '১১টি', NULL, '১৪টি', NULL, 'C', 'জেনারেল এম. এ. জি ওসমানী আনুষ্ঠানিকভাবে সশস্ত্র বাহিনী এবং মুক্তিবাহিনীর প্রধান সেনাপতির দায়িত্ব গ্রহণ করে মুক্তিযুদ্ধ পরিচালনার সামরিক কৌশল হিসেবে তৎকালীন পূর্ব পাকিস্তানের সমগ্র ভৌগোলিক এলাকাকে ১১টি সেক্টরে ভাগ করেন।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1f8df61348940f9a0c93b6256cf809ed'),
(7831, 681, 'টেকনাফ কোন নদীর তীরে অবস্থিত?', 'পদ্মা', NULL, 'যমুনা', NULL, 'নাফ', NULL, 'কর্ণফুলী', NULL, 'C', 'নাফ নদীর তীরে অবস্থিত টেকনাফ কক্সবাজার জেলার একটি উপজেলা। বাংলাদেশের সর্ব দক্ষিণ-পূর্ব সীমান্তে এ উপজেলাটির অবস্থান। মিয়ানমার থেকে বাংলাদেশকে (কক্সবাজার) পৃথক করেছে এ নদীটি। এ নদীর দৈর্ঘ্য ৫৬ কিমি।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '399c950c82e23b66039fc2fca8ee358b'),
(7832, 681, 'গৌড়ের সোনা মসজিদ কার আমলে নির্মিত হয়?', 'ফখরুদ্দিন মোবারক শাহ', NULL, 'হোসেন শাহ', NULL, 'শায়েস্তা খাঁ', NULL, 'ঈশা খাঁ', NULL, 'B', 'গৌড়ের সোনা মসজিদ নির্মিত হয় হোসেন শাহ-এর আমলে। তার পুরো নাম আলাউদ্দিন হোসেন শাহ। তিনি হোসেন শাহী বংশের শাসক ছিলেন।', NULL, 178, '29th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '971c75f7a5c5085ddb86e48eab010324'),
(7833, 681, 'বখতিয়ার খিলজি বাংলা জয় করেন কোন সালে?', '১২১২', NULL, '১২০০', NULL, '১২০৪', NULL, '১২১১', NULL, 'C', '১২০৪ সালে বখতিয়ার খিলজি অশ্ব বিক্রেতার বেশে অতর্কিতে লক্ষ্মণ সেনের রাজধানী নদীয়া আক্রমণ করলে লক্ষ্মণ সেন পলায়ন করে এবং বখতিয়ার খিলজি বাংলায় মুসলিম শাসনের সূত্রপাত ঘটান।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '589e0da03af34ad83f19cf5becc6255e'),
(7834, 681, 'প্রাচীন চন্দ্রদ্বীপের বর্তমান নাম কি?', 'মালদ্বীপ', NULL, 'সন্দ্বীপ', NULL, 'হাতিয়া', NULL, 'বরিশাল', NULL, 'D', 'সুপ্রাচীনকালে বর্তমান বৃহত্তর বরিশাল অঞ্চল \"চন্দ্রদ্বীপ\" নামে পরিচিত ছিল। বিভিন্ন ইতিহাসবিদ তাদের রচিত গ্রন্থে চন্দ্রদ্বীপ নামকরণ সম্পর্কে ভিন্ন ভিন্ন অভিমত ব্যক্ত করেন।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c9c6545710d6eb473ef05bfbb3b456f'),
(7835, 682, 'গণপ্রজাতন্ত্রী বাংলাদেশের মনোগ্রামে কতটি তারকা চিহ্ন রয়েছে?', '৪টি', NULL, '৫টি', NULL, '৬টি', NULL, '২টি', NULL, 'A', 'গণপ্রজাতন্ত্রী বাংলাদেশের মনোগ্রামে ৪টি তারকা রয়েছে। এ মনোগ্রামে রয়েছে লাল রঙের মাঝে হলুদ রঙের বাংলাদেশের মানচিত্র। বৃত্তের উপর দিকে লেখা \"গণপ্রজাতন্ত্রী বাংলাদেশ\", নিচে লেখা \"সরকার\"। লেখার দুপাশে দুটি করে মোট ৪টি তারকাচিহ্ন রয়েছে।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0226b4e1d59b5d5b15e27563ccbb7b76'),
(7836, 750, 'বাংলাদেশের নদী গবেষণা ইনস্টিটিউট কোথায়?', 'ফরিদপুর', NULL, 'চাঁদপুর', NULL, 'চট্টগ্রাম', NULL, 'নারায়ণগঞ্জ', NULL, 'A', 'পানিসম্পদ মন্ত্রণালয়ের অধীনে স্বায়ত্তশাসিত প্রতিষ্ঠান হিসেবে নদী গবেষণা ইনস্টিটিউট প্রথম ঢাকায় প্রতিষ্ঠিত হয়। পরবর্তীতে ফরিদপুরের হারুকান্দিতে এটি স্থানান্তর করা হয়।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7af24b2333e3829d6a01defc20ee40d4'),
(7837, 681, 'সাগরকন্যা কোন এলাকার ভৌগোলিক নাম?', 'টেকনাফ', NULL, 'কক্সবাজার', NULL, 'পটুয়াখালী', NULL, 'খুলনা', NULL, 'C', 'কুয়াকাটা বাংলাদেশের একমাত্র সমুদ্র সৈকত, যেখান থেকে সূর্যোদয় ও সূর্যাস্ত গভীরভাবে অবলোকন করা যায়। সমুদ্র সৈকতটি পটুয়াখালী জেলার কলাপাড়া উপজেলার লতাচাপলি ইউনিয়নের অন্তর্গত। কুয়াকাটা স্থানীয়ভাবে \"সাগরকন্যা\" নামে পরিচিত।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9134b5a69dcce4f0e56af19942318625'),
(7838, 727, 'বাংলাদেশের নির্বাহী বিভাগ থেকে বিচার বিভাগ কবে পৃথক করা হয়?', '৩১-১০-০৭', NULL, '১-১১-০৭', NULL, '৩-১১-০৭', NULL, '১-১০-০৭', NULL, 'B', '১৯৯৫ সালের ১৯ নভেম্বর বিসিএস (বিচার) অ্যাসোসিয়েশনের সাবেক মহাসচিব ও সাবজজ মোহাম্মদ মাজদার হোসেন ও ৪৪০ জন বিচারক বাংলাদেশ সরকারকে বিবাদী করে একটি রিট মামলা করলে নির্বাহী বিভাগ থেকে বিচার বিভাগ পৃথক করার দাবি নতুন মাত্রা পায়। ১ নভেম্বর, ২০০৭ বিচার বিভাগকে নির্বাহী বিভাগ থেকে পৃথক করা হয়।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'eae4f4318a0631c6454e38c4b528b04a'),
(7839, 685, '৬-দফা দাবি কোথায় উত্থাপিত হয়?', 'ঢাকা', NULL, 'লাহোর', NULL, 'দিল্লি', NULL, 'চট্টগ্রাম', NULL, 'B', 'ভারত-পাকিস্তান যুদ্ধ (৬-২৭ সেপ্টেম্বর, ১৯৬৫) সমাপ্তির পর উভয় দেশের মধ্যে \"তাসখন্দ চুক্তি\" (১০ জানুয়ারি, ১৯৬৬) স্বাক্ষরের পটভূমিকায় ১৯৬৬ সালের ৫-৬ ফেব্রুয়ারি, লাহোরে অনুষ্ঠিত বিরোধী দলের এক সম্মেলনে বঙ্গবন্ধু শেখ মুজিবুর রহমান ৬ দফা দাবি উত্থাপন করেন।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5790602fd7270b04cb0fae16638f9ab3'),
(7840, 711, 'দেশের প্রথম ঔষধ পার্ক কোথায় স্থাপিত হচ্ছে?', 'গজারিয়া', NULL, 'গাজীপুর', NULL, 'সাভার', NULL, 'ভালুকা', NULL, 'A', 'মুন্সিগঞ্জের গজারিয়া উপজেলার বাউসিয়া এলাকায় ২০০ একর জমিতে ঔষধ শিল্পপার্ক স্থাপিত হচ্ছে।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e63514e1b131380410ae620855541628'),
(7841, 752, 'ক্রিকেটে বাংলাদেশ কোন সালে টেস্ট মর্যাদা পায়?', '১৯৯৮', NULL, '১৯৯৯', NULL, '২০০০', NULL, '২০০১', NULL, 'C', '২০০০ সালের ২৬ জুন দশম টেস্ট খেলুড়ে দেশ হিসেবে বাংলাদেশ টেস্ট মর্যাদা লাভ করে।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '58626fd1cc532fccdbf79ac7fd8dd627'),
(7842, 682, 'বাংলাদেশের জাতীয় ফল কোনটি?', 'আম', NULL, 'কাঁঠাল', NULL, 'কলা', NULL, 'পেঁপে', NULL, 'B', 'বাংলাদেশের জাতীয় ফল কাঁঠালের আদি নিবাস ভারতের পশ্চিমঘাট পর্বতমালা। সারা বাংলাদেশে জন্মালেও নওগাঁ, দিনাজপুর, সাভার, মধুপুর ও সিলেট কাঁঠালের প্রধান এলাকা। আর আমগাছ হলো বাংলাদেশের জাতীয় বৃক্ষ।', NULL, 179, '30th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f81e0f8ede44c0576d3236f01010f411'),
(7843, 750, 'বাংলাদেশের লোকশিল্প জাদুঘর কোথায় অবস্থিত?', 'ময়নামতি', NULL, 'সোনারগাঁ', NULL, 'ঢাকা', NULL, 'পাহাড়পুর', NULL, 'B', 'বাংলাদেশের লোকশিল্পের অতীত কীর্তিসমূহ (নক্‌শী কাঁথা, মাটির পাত্র, বেত, কাঁসা, মসলিন বস্ত্র, তৈজসপত্র ইত্যাদি) সংরক্ষণের জন্য নারায়ণগঞ্জ জেলার সোনারগাঁওয়ে লোকশিল্প জাদুঘর স্থাপন করা হয়েছে। ১৯৯৬ সালের ৬ অক্টোবর সোনারগাঁও লোক ও কারুশিল্প ফাউন্ডেশনের নাম পরিবর্তন করে \"শিল্পাচার্য জয়নুল আবেদিন\" জাদুঘর করা হয়েছে।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bedd17e8b53a564973caa9e4b52cd7b2'),
(7844, 700, 'জাতিসংঘের জনসংখ্যা সংক্রান্ত রিপোর্ট ১৯৯৪ অনুযায়ী জনসংখ্যার দিক দিয়ে বাংলাদেশের স্থান কত?', 'সপ্তম', NULL, 'নবম', NULL, 'একাদশ', NULL, 'ত্রয়োদশ', NULL, 'A', 'জাতিসংঘ জনসংখ্যা তহবিল (UNFPA) প্রতিবছরের মতো ২০২২ সালেও \"বাংলাদেশের জনসংখ্যা ২০২২ ও বিশ্ব প্রতিবেদন\" প্রকাশ করে। ১৯৯৪ সালের রিপোর্ট অনুযায়ী জনসংখ্যার দিক দিয়ে বাংলাদেশের স্থান ছিল সপ্তম।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'af1372a56bfdad2ba95ff37244cd0cfb'),
(7845, 750, 'ঢাকা বিশ্ববিদ্যালয় কবে প্রতিষ্ঠিত হয়?', '১৯২১', NULL, '১৯২৫', NULL, '১৯২৯', NULL, '১৯৩৩', NULL, 'A', '১৯২০ সালে ভারতীয় বিধান পরিষদে গৃহীত ঢাকা বিশ্ববিদ্যালয় আইন অনুসারে ১৯২১ সালের ১ জুলাই ঢাকা বিশ্ববিদ্যালয় প্রতিষ্ঠিত হয়। ঢাকা বিশ্ববিদ্যালয়ের প্রথম চ্যান্সেলর লর্ড ডানডাস (জেসিআই) এবং প্রথম ভাইস চ্যান্সেলর পি জে (ফিলিপ জোসেফ) হার্টজ।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dc393fd8a1d3fde466675a4f95a0f8e9'),
(7846, 725, 'বাংলাদেশের সংবিধানের কত অনুচ্ছেদ অনুযায়ী বাংলাদেশ সরকারি কর্ম কমিশন গঠিত হয়?', '১৩৭', NULL, '১৩৮', NULL, '১৪৭', NULL, '১৫০', NULL, 'A', 'বাংলাদেশের সংবিধানের ১৩৭-১৪১ নং অনুচ্ছেদে সরকারী কর্ম কমিশন সম্পর্কে আলোচনা করা হয়েছে। সংবিধানের ১৩৭ নং ধারায় বলা হয়েছে, \"আইনের দ্বারা বাংলাদেশের জন্য এক বা একাধিক সরকারী কর্ম কমিশন প্রতিষ্ঠার বিধান করা যাইবে।\"', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '03d776d245a1ce1da425822b7a2bcb1b'),
(7847, 681, 'কে বাংলার সাল গণনা শুরু করেন?', 'লক্ষ্মণ সেন', NULL, 'ইলিয়াস শাহ', NULL, 'বিজয় সেন', NULL, 'আকবর', NULL, 'D', 'বাংলা সনের প্রবর্তক সম্রাট আকবর রাজস্ব মন্ত্রী টোডরমলের পরামর্শে ৯৬৩ হিজরিকে ৯৬৩ সাল ধরে গণনা শুরু করে। কৃষিকাজের সুবিধার্থে মোগল সম্রাট আকবর ১৫৮৪ খ্রিষ্টাব্দের ১০/১১ মার্চ বাংলা সন প্রবর্তন করেন।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7058056bf46085f0b6211900c0a696a2'),
(7848, 682, 'গম্ভীরা বাংলাদেশের কোন অঞ্চলের লোকসঙ্গীত?', 'চট্টগ্রাম', NULL, 'রাঙ্গামাটি', NULL, 'চাঁপাইনবাবগঞ্জ', NULL, 'জামালপুর', NULL, 'C', 'রাজশাহী ও চাঁপাইনবাবগঞ্জ এলাকায় এ সঙ্গীতের প্রচলন রয়েছে। সমাজের নানা অসঙ্গতি তুলে ধরা ও এ সম্পর্কে নানা করণীয় দিক অত্যন্ত সুন্দরভাবে সঙ্গীতের মধ্যে উপস্থাপনই সারাদেশে গম্ভীরার সুপরিচিতির কারণ।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd9609d57b28d5916a587260255e3dabf'),
(7849, 704, 'বাংলাদেশে কয়টি উপজাতীয় প্রতিষ্ঠান আছে?', '৬টি', NULL, '৫টি', NULL, '৪টি', NULL, '৩টি', NULL, 'A', 'বাংলাদেশে বর্তমানে উপজাতীয় (ক্ষুদ্র নৃ-গোষ্ঠী) সাংস্কৃতিক প্রতিষ্ঠান রয়েছে ৮টি। (দ্রষ্টব্য: ৩১তম বিসিএসের সময় ৬টি ছিল)', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9ef28686338cc36c60e2ab467bcec87a'),
(7850, 744, 'রেলপথে ঢাকা থেকে খুলনার দূরত্ব কত?', '৬২৭ কি.মি.', NULL, '৫২৯ কি.মি.', NULL, '৪২০ কি.মি.', NULL, '৩০৭ কি.মি.', NULL, 'C', 'বাংলাদেশে রেলওয়ে ইনফরমেশন বুক-এর তথ্য মতে রেলপথে ঢাকা থেকে খুলনার দূরত্ব ৪১২ কিমি। (দ্রষ্টব্য: ৩১তম বিসিএসের সময় ৪২০ কিমি ছিল)', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5dbb2b704b6a5f59363505f39e801865'),
(7851, 717, 'নিম্নলিখিত কোন দেশ থেকে বাংলাদেশ বর্তমানে সবচেয়ে বেশি সাহায্য পায়?', 'মার্কিন যুক্তরাষ্ট্র', NULL, 'জাপান', NULL, 'দক্ষিণ কোরিয়া', NULL, 'জার্মানি', NULL, 'B', 'অর্থনৈতিক সমীক্ষা-২০২২ অনুযায়ী বাংলাদেশ ২০২১-২২ অর্থ বছরে দেশ হিসেবে সবচেয়ে বেশি সাহায্য পায় জাপান থেকে। তবে সংস্থা হিসেবে সবচেয়ে বেশি সাহায্য পেয়েছে IDA থেকে।', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cca1e3f87e4b2516f394bb76a158a54f'),
(7852, 750, 'বাংলাদেশ কোন সাল থেকে শান্তিরক্ষা বাহিনীতে কাজ করছে?', '১৯৮২', NULL, '১৯৮৫', NULL, '১৯৭৫', NULL, '১৯৭৯', NULL, 'A', 'জাতিসংঘ তথ্য কেন্দ্র প্রকাশিত \"বাংলাদেশ ও জাতিসংঘ: সহযোগিতার তিন দশক\" সাময়িকী এবং বাংলাদেশ সশস্ত্র বাহিনী প্রকাশিত ক্রোড়পত্র অনুসারে বাংলাদেশ ১৯৮৮ সালে UNIIMOG ও UNTAG-এ যোগদানের মধ্য দিয়ে শান্তিরক্ষা বাহিনীতে কাজ শুরু করে। (দ্রষ্টব্য: ৩১তম বিসিএসের সময় ১৯৮২ ছিল)', NULL, 5, '31st BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9afe1ecee7fb13841a026985415e650d'),
(7853, 752, 'প্রথম বাংলাদেশী এভারেস্ট বিজয়ী মুসা ইব্রাহীম কোন সালে মাউন্ট এভারেস্ট শৃঙ্গে আরোহণ করেন?', '২০০৮', NULL, '২০১১', NULL, '২০০৯', NULL, '২০১০', NULL, 'D', 'প্রথম বাংলাদেশী হিসেবে মুসা ইব্রাহীম ২৩ মে, ২০১০ মাউন্ট এভারেস্ট শৃঙ্গে আরোহণ করেন। তিনি লালমনিরহাটের অধিবাসী। তার এভারেস্ট বিজয়ের মধ্য দিয়ে বাংলাদেশ ৬৭তম এভারেস্টজয়ী দেশ হিসেবে আত্মপ্রকাশ করে।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '31f7c3420b28bbdffaedb16914ed8952'),
(7854, 681, 'তামাবিল সীমান্তের সাথে ভারতের কোন শহরটি অবস্থিত?', 'করিমগঞ্জ', NULL, 'খোয়াই', NULL, 'পেট্রাপোল', NULL, 'ডাউকি', NULL, 'D', 'সিলেটের গোয়াইনঘাটের তামাবিল সীমান্তের স্থলবন্দরটি ভারতের মেঘালয় প্রদেশের ডাউকি শহর ঘেঁষে অবস্থিত। বেনাপোল স্থলবন্দরটি ভারতের পশ্চিমবঙ্গের পেট্রাপোল সীমান্তের সাথে লাগানো।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '82877776d32c3b10dcce45405775e3ba'),
(7855, 750, 'BTRC এর ইংরেজি পূর্ণরূপ কোনটি?', 'Bangladesh Telephone Regulatory Commission', NULL, 'Bangladesh Telecommunication Regulatory Commission', NULL, 'Bangladesh Telecom Regulatory Commission', NULL, 'Bangladesh Telephone and Telegraph Regulatory Commission', NULL, 'B', 'BTRC এর ইংরেজি পূর্ণরূপ Bangladesh Telecommunication Regulatory Commission বা বাংলাদেশ টেলিযোগাযোগ নিয়ন্ত্রণ কমিশন। এটি প্রতিষ্ঠিত হয় ১৬ এপ্রিল ২০০১ সালে।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a2a2b82eb70499ab210f56aff34175ff'),
(7856, 744, 'বাংলাদেশ রেলওয়ের সর্ববৃহৎ কারখানা কোথায়?', 'চট্টগ্রাম', NULL, 'পাকশি', NULL, 'সৈয়দপুর', NULL, 'আখাউড়া', NULL, 'C', '১৮৭০ সালে নীলফামারী জেলার সৈয়দপুরে ১১০ একর জমির উপর প্রতিষ্ঠিত হয় দেশের বৃহত্তম রেলওয়ে কারখানা- সৈয়দপুর রেলওয়ে কারখানা।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a46c168e29f4853bfc54b60786af0c90'),
(7857, 713, 'বাংলাদেশের White gold কোনটি?', 'ইলিশ', NULL, 'পাট', NULL, 'রূপা', NULL, 'চিংড়ি', NULL, 'D', 'বাংলাদেশে অপ্রচলিত পণ্যের মধ্যে চিংড়ি মাছ রপ্তানি করে বিপুল পরিমাণ বৈদেশিক মুদ্রা অর্জন করে। এ জন্য বাংলাদেশের চিংড়ি সম্পদকে \"White gold\" বলা হয়।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '17a173be209047a5e51ae5d360e19e20'),
(7858, 681, 'বাংলাদেশের কোন জেলাটি বাংলাদেশ-ভারত সীমান্তের মধ্যে নয়?', 'পঞ্চগড়', NULL, 'সাতক্ষীরা', NULL, 'হবিগঞ্জ', NULL, 'কক্সবাজার', NULL, 'D', 'বাংলাদেশের সীমান্তবর্তী জেলা মোট ৩২টি। ভারতের সাথে ৩০টি এবং মিয়ানমারের সাথে ৩টি জেলার সীমান্ত রয়েছে। কক্সবাজারের সাথে ভারতের কোনো সীমানা নেই, এটি মিয়ানমারের সাথে সীমান্তবর্তী।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ffb16b9a586ad2fb40505e0269970803'),
(7859, 696, '\"সোনালিকা\" ও \"আকবর\" বাংলাদেশের কৃষি ক্ষেত্রে কিসের নাম?', 'উন্নত কৃষি যন্ত্রপাতির নাম', NULL, 'উন্নত জাতের ধানের নাম', NULL, 'দুটি কৃষি বিষয়ক বেসরকারি সংস্থার নাম', NULL, 'উন্নত জাতের গমের নাম', NULL, 'D', 'বাংলাদেশের কৃষি ক্ষেত্রে \"সোনালিকা\" ও \"আকবর\" দুটি উন্নতজাতের গমের নাম। এরূপ আরো কতিপয় উন্নত জাতের গমের মধ্যে অগ্রণী, আনন্দ, কাঞ্চন, দোয়েল, বরকত, বলাকা, জোপাটিকা, ইনিয়া-৬৬ প্রভৃতি প্রধান।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fa34d0ee31541c34b678b4791ee9af68'),
(7860, 750, '\"আলোকিত মানুষ চাই\" এটি কোন প্রতিষ্ঠানের স্লোগান?', 'জাতীয় গ্রন্থ কেন্দ্র', NULL, 'বিশ্বসাহিত্য কেন্দ্র', NULL, 'সুশাসনের জন্য নাগরিক', NULL, 'পাবলিক লাইব্রেরী', NULL, 'B', '\"আলোকিত মানুষ চাই\" এটি বিশ্বসাহিত্য কেন্দ্রের স্লোগান। বিশ্বসাহিত্য কেন্দ্র প্রতিষ্ঠা হয় ১৯৮২ সালে এবং এর প্রতিষ্ঠাতা অধ্যাপক আবদুল্লাহ আবু সায়ীদ।', NULL, 180, '32nd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b2d09aa19770c82fac9134f83e6998a4'),
