(7876, 681, 'পূর্বাশা দ্বীপের অপর নাম কি?', 'নিঝুম দ্বীপ', NULL, 'সন্দ্বীপ', NULL, 'দক্ষিণ তালপট্টি', NULL, 'কুতুবদিয়া', NULL, 'C', 'দক্ষিণ তালপট্টি দ্বীপ সাতক্ষীরা জেলার শ্যামনগর উপজেলার অন্তর্গত। ভারতে দ্বীপটিকে \"নিউমুর দ্বীপ\" আবার কখনও \"পূর্বাশা\" নামে অভিহিত করা হয়।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b7aac21d048f77c9e33303c3849f3d40'),
