(7878, 681, 'বাংলাদেশের সেন্টমার্টিন দ্বীপ কোন জেলায়?', 'ভোলা', NULL, 'নোয়াখালী', NULL, 'চট্টগ্রাম', NULL, 'কক্সবাজার', NULL, 'D', 'কক্সবাজার জেলায় সেন্টমার্টিন দ্বীপ। বাংলাদেশের সর্ব দক্ষিণ পূর্বে অবস্থিত। সেন্টমার্টিন দ্বীপের অপর নাম \"নারিকেল জিনজিরা\"। এটি বাংলাদেশের একমাত্র প্রবাল দ্বীপ।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c5e43ea024bd6999d0936d390c40935'),
(7879, 713, 'বাংলাদেশের সর্বাধিক বৈদেশিক মুদ্রা অর্জনকারী বিষয় কি?', 'প্রবাসী শ্রমিক', NULL, 'পাট', NULL, 'রেডিমেড গার্মেন্টস', NULL, 'চামড়া', NULL, 'C', '২০২২-২৩ অর্থবছরে ৪ হাজার ৬৯৯ কোটি ডলারের তৈরি পোশাক রপ্তানি হয়েছে। রেডিমেড গার্মেন্টস বাংলাদেশের সর্বাধিক বৈদেশিক মুদ্রা অর্জনকারী খাত।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a46f071581bc0d82ec66cc83e2c74a99'),
(7880, 750, '\"শালবন বিহার\" কোথায়?', 'গাজীপুর', NULL, 'মধুপুর', NULL, 'রাজবাড়ী', NULL, 'কুমিল্লার ময়নামতি পাহাড়ের পাশে', NULL, 'D', '\"শালবন বিহার\" ময়নামতির প্রত্নতাত্ত্বিক খনন স্থানগুলোর মধ্যে সবচেয়ে গুরুত্বপূর্ণ প্রত্নস্থল। কুমিল্লার কাছে কোটবাড়ির বর্তমান বাংলাদেশ পল্লী উন্নয়ন একাডেমীর লাগোয়া লালমাই পাহাড়ের মধ্যবর্তী এলাকায় এর অবস্থান।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3aaef734a7d6e49604150f80add4c42a'),
(7881, 682, '\"সাবাস বাংলাদেশ\" ভাস্কর্যটি কোথায় অবস্থিত?', 'টিএসসি মোড়ে', NULL, 'ঢাকা বিশ্ববিদ্যালয়ে', NULL, 'রেসকোর্স ময়দানে', NULL, 'রাজশাহী বিশ্ববিদ্যালয়ে', NULL, 'D', '\"সাবাস বাংলাদেশ\" ভাস্কর্যটি বাংলাদেশের মুক্তিযুদ্ধের স্মৃতিবিজড়িত ভাস্কর্যগুলোর অন্যতম। এ ভাস্কর্যটি রাজশাহী বিশ্ববিদ্যালয়ে অবস্থিত। ভাস্কর্যটির স্থপতি নিতুন কুণ্ডু।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c576fd88a5516df5a240ab907a12650a'),
(7882, 752, 'এশিয়া কাপ ক্রিকেট, ২০১২ কোন স্টেডিয়ামে অনুষ্ঠিত হয়?', 'বঙ্গবন্ধু জাতীয় স্টেডিয়াম', NULL, 'শেরে বাংলা জাতীয় স্টেডিয়াম', NULL, 'বাংলাদেশ আর্মি স্টেডিয়াম', NULL, 'রাজশাহী স্টেডিয়াম', NULL, 'B', '২০১২ সালের ১১-১২ মার্চ ১১তম এশিয়া কাপ ক্রিকেট বাংলাদেশের শেরে বাংলা জাতীয় স্টেডিয়াম, মিরপুরে অনুষ্ঠিত হয়।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ddf51734b7c5c5782638ad5b4d822664'),
(7883, 682, 'বাংলাদেশের জাতীয় দিবস কবে?', '১৬ ডিসেম্বর', NULL, '৭ মার্চ', NULL, '২৬ মার্চ', NULL, '১৭ এপ্রিল', NULL, 'C', '২৬ মার্চ হলো বাংলাদেশের স্বাধীনতা ও জাতীয় দিবস। ১৬ ডিসেম্বর বিজয় দিবস, ২১ ফেব্রুয়ারি শহীদ দিবস ও আন্তর্জাতিক মাতৃভাষা দিবস।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '34fb638a980ee6ad7083f7db35b987f8'),
(7884, 750, 'শ্রীলঙ্কার মুদ্রার নাম কি?', 'ডলার', NULL, 'পাউন্ড', NULL, 'টাকা', NULL, 'রূপী', NULL, 'D', 'শ্রীলঙ্কার মুদ্রার নাম শ্রীলঙ্কান রুপি। এছাড়া ভারত, নেপাল, পাকিস্তান, মরিশাস, সিচেলিস এর মুদ্রা রুপি।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b709e24676169c6d66a947b7faebebd7'),
(7885, 750, 'সার্ক-এর সদস্য দেশ কয়টি?', '৬', NULL, '৭', NULL, '৮', NULL, '৯', NULL, 'C', 'সার্কভুক্ত দেশ ৮টি। দেশগুলো হলো: বাংলাদেশ, ভারত, পাকিস্তান, শ্রীলংকা, নেপাল, ভুটান, মালদ্বীপ ও আফগানিস্তান।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '53bef8f45c49caf69980ea45ed721bb3'),
(7886, 692, 'বাংলাদেশের প্রথম প্রধান সেনাপতি কে ছিলেন?', 'মে. জে. জিয়াউর রহমান', NULL, 'মে. জে. সফিউল্লাহ', NULL, 'লে. জে. এইচ. এম এরশাদ', NULL, 'জে. আতাউল গনি ওসমানী', NULL, 'D', 'বাংলাদেশ সশস্ত্রবাহিনী ও মুক্তিবাহিনীর প্রধান সেনাপতি জে. আতাউল গনি ওসমানী। ১৯৭১ সালের ১০ এপ্রিল গঠিত অস্থায়ী সরকারের প্রধান সেনাপতির দায়িত্ব তাঁকে দেয়া হয়।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '02196b7e70944b0482d98208d6a4a8d7'),
(7887, 722, 'বাংলাদেশের রাজধানী কোথায়?', 'ঢাকা উত্তর', NULL, 'ঢাকা দক্ষিণ', NULL, 'ঢাকা', NULL, 'শেরে বাংলা নগর', NULL, 'C', 'বাংলাদেশ সংবিধানের ৫(১) অনুচ্ছেদ অনুযায়ী ঢাকা বাংলাদেশের রাজধানী।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f57f9848794f959b6671d290c532e1cd'),
