(7889, 753, 'বাংলাদেশের কোন ছবি সম্প্রতি \"কলকাতা ফিল্ম ফেস্টিভাল\" পুরস্কার লাভ করে?', 'ওরা এগার জন', NULL, 'গেরিলা', NULL, 'আবার তোরা মানুষ হ', NULL, 'স্টপ জেনোসাইড', NULL, 'B', '২০১১ সালের ১০-১৭ নভেম্বর ভারতের কলকাতায় অনুষ্ঠিত ১৭তম কলকাতা ফিল্ম ফেস্টিভালে সেরা চলচ্চিত্রের পুরস্কার নেটপ্যাক লাভ করে বাংলাদেশের চলচ্চিত্র \"গেরিলা\"।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7ca8e8fb58c2d197ee64892b7405e276'),
(7890, 727, 'বাংলাদেশের আপিল বিভাগের মোট বিচারক কতজন?', '১১', NULL, '২১', NULL, '৯', NULL, '১৫', NULL, 'C', 'সংবিধান অনুযায়ী আপিল বিভাগে বিচারপতির সংখ্যা বাড়ানোর এখতিয়ার রয়েছে একমাত্র রাষ্ট্রপতির। বর্তমান আপিল বিভাগে বিচারক সংখ্যা ৯ জন।', NULL, 181, '33rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6bac0108c4d489906a278a2818df9b05'),
(7891, 750, 'For which of the following disciplines Nobel Prize is awarded?', 'Physics and Chemistry', NULL, 'Physiology or Medicine', NULL, 'Literature, Peace and Economics', NULL, 'All of the above', NULL, 'D', 'সুইডিশ বিজ্ঞানী আলফ্রেড বার্নার্ড নোবেল তার উইলকৃত অর্থ থেকে পাঁচটি ক্ষেত্রে পুরস্কার প্রদানের ঘোষণা দিয়ে যান। বর্তমানে নোবেল পুরস্কার প্রদান করা হয় ৬টি ক্ষেত্রে- সাহিত্য, পদার্থবিদ্যা, রসায়নশাস্ত্র, অর্থনীতি, চিকিৎসাবিজ্ঞান ও শান্তি।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '46890d9149009aa1e8b94b39acf3d210'),
(7892, 752, 'Badminton is the national sport of-', 'Malaysia', NULL, 'Scotland', NULL, 'China', NULL, 'Nepal', NULL, 'A', 'ইন্দোনেশিয়ার জাতীয় খেলা ব্যাডমিন্টন। মালয়েশিয়ার জাতীয় খেলা সেপাক তাকরাও নামক একটি খেলা যা অনেকটা ব্যাডমিন্টনের মতো।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4060d39b9b37f410850e814144a1dfd0'),
(7893, 691, '১৯৭১ সনের কত তারিখে মুজিবনগরে স্বাধীন বাংলাদেশের অস্থায়ী সরকার গঠিত হয়?', '৭ মার্চ, ১৯৭১', NULL, '২৬ মার্চ, ১৯৭১', NULL, '১০ এপ্রিল, ১৯৭১', NULL, '১৬ ডিসেম্বর, ১৯৭১', NULL, 'C', '১৯৭০ সালের ৭ ডিসেম্বর অনুষ্ঠিত জাতীয় পরিষদের নির্বাচনে বিজয়ী সদস্যগণ ১০ এপ্রিল, ১৯৭১ ভারতের আগরতলায় একত্রিত হয়ে একটি সরকার গঠন করার বিষয়ে সর্বসম্মত সিদ্ধান্তে উপনীত হন।', NULL, 182, '34th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f615d14cef68c0bbc88cd17941b1dc88'),
