(7939, 685, '৬ দফা দাবি পেশ করা হয়:', '১৯৭০ সালে', NULL, '১৯৬৬ সালে', NULL, '১৯৬৫ সালে', NULL, '১৯৬৯ সালে', NULL, 'B', '১৯৬৬ সালের ৫-৬ ফেব্রুয়ারি লাহোরে শেখ মুজিবুর রহমান পূর্ব পাকিস্তানের স্বায়ত্তশাসন প্রতিষ্ঠার লক্ষ্যে বাঙালি জাতির মুক্তির সনদ বা ম্যাগনাকার্টা নামে পরিচিত \"৬ দফা দাবি\" পেশ করেন।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e286ff2137ba8d63be008fbd1f6b7018'),
(7940, 689, 'বঙ্গবন্ধুর ১৯৭১ সালের ৭ মার্চ ভাষণের সময়কালে পূর্ব পাকিস্তানে যে আন্দোলন চলছিল সেটি হলো:', 'ইসলামাবাদের সামরিক সরকার পদত্যাগের আন্দোলন', NULL, 'পূর্ব পাকিস্তানের অসহযোগ আন্দোলন', NULL, 'প্রেসিডেন্ট ইয়াহিয়ার পদত্যাগ আন্দোলন', NULL, 'মার্শাল ল পদত্যাগের আন্দোলন', NULL, 'B', '১ মার্চ ১৯৭১ ইয়াহিয়া খান পূর্ব ঘোষিত ৩ মার্চের ঢাকায় পাকিস্তান জাতীয় পরিষদের ডাকা অধিবেশন স্থগিত করেন। ঐ স্থগিতাদেশের প্রতিবাদে সেদিন থেকে ২৫ মার্চ মুক্তিযুদ্ধ শুরুর পূর্ব মুহূর্ত পর্যন্ত পূর্ব পাকিস্তান জুড়ে চলে অসহযোগ আন্দোলন।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dd7a569668f758ee115d9eaebfd57a2c'),
(7941, 690, '২৬ মার্চ, ১৯৭১-এর স্বাধীনতা ঘোষণা বঙ্গবন্ধু জারী করেন-', 'বেতার/রেডিওর মাধ্যমে', NULL, 'ওয়্যারলেসের মাধ্যমে', NULL, 'টেলিগ্রামের মাধ্যমে', NULL, 'টেলিভিশনের মাধ্যমে', NULL, 'B', '১৯৭১ সালের মার্চের মধ্যরাতে অর্থাৎ ২৬ মার্চের প্রথম প্রহরে বঙ্গবন্ধু শেখ মুজিবুর রহমানকে তাঁর ধানমণ্ডির ৩২ নম্বর বাড়ি থেকে গ্রেফতার করা হয়। গ্রেফতারের পূর্বে বঙ্গবন্ধু ইপিআরের ওয়্যারলেসের মাধ্যমে বাংলাদেশের স্বাধীনতা ঘোষণা করেন।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e44b22becef0ce610807793e6326d470'),
(7942, 696, 'বাংলাদেশে রোপা আমন ধান কাটা হয়–', 'আষাঢ়-শ্রাবণ মাসে', NULL, 'ভাদ্র-আশ্বিন মাসে', NULL, 'অগ্রহায়ণ-পৌষ মাসে', NULL, 'মাঘ-ফাল্গুন', NULL, 'C', 'বাংলাদেশে রোপা আমন ধান কাটা হয় অগ্রহায়ণ-পৌষ মাসে (নভেম্বর-জানুয়ারি)। আউশ ধান কাটা হয় জুলাই-আগস্টে আর বোরো ধান কাটা হয় এপ্রিল-মে মাসে।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0c3906fbca698535b64e1bc087514277'),
(7943, 681, 'সুন্দরবন-এর কত শতাংশ বাংলাদেশের ভৌগোলিক সীমার মধ্যে পড়েছে?', '৫০%', NULL, '৫৮%', NULL, '৬২%', NULL, '৬৬%', NULL, 'C', 'সুন্দরবন বাংলাদেশের খুলনা, সাতক্ষীরা ও বাগেরহাট এবং পশ্চিমবঙ্গের দক্ষিণ চব্বিশ পরগণা জেলাজুড়ে বিস্তৃত। এ বনভূমির মোট আয়তন ১০,০০০ বর্গ কিলোমিটার, যার মধ্যে বাংলাদেশ অংশে পড়েছে ৬,০১৭ বর্গ কিলোমিটার। অর্থাৎ শতকরা হিসেবে তা ৬০%-এর একটু বেশি।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1786abc82b80df908615c64afe0b9db1'),
(7944, 750, 'MDG-এর অন্যতম লক্ষ্য কি?', 'দেশ থেকে পোলিও নির্মূল', NULL, 'HIV/AIDS নির্মূল করা', NULL, 'যক্ষ্মা নির্মূল করা', NULL, 'ক্ষুধা ও দারিদ্র্য দূর করা', NULL, 'D', '২০০০ সালের সেপ্টেম্বরে জাতিসংঘ আয়োজিত সহস্রাব্দ শীর্ষ বৈঠকে ২০১৫ সালের মধ্যে ৮টি লক্ষ্য পূরণের সিদ্ধান্ত গ্রহণ করা হয়, যা সহস্রাব্দ উন্নয়ন লক্ষ্য বা MDG নামে পরিচিত। MDG-এর ৮টি লক্ষ্যের প্রথম লক্ষ্য হলো ক্ষুধা ও দারিদ্র্য দূর করা।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3f5906d109e8736a65aa9633c9d95e08'),
(7945, 730, 'তত্ত্বাবধায়ক সরকার ব্যবস্থা সংবিধানের কততম সংশোধনীর মাধ্যমে রদ করা হয়েছে?', '১২তম', NULL, '১৩তম', NULL, '১৪তম', NULL, '১৫তম', NULL, 'D', '৩০ জুন ২০১১ সংবিধানের ১৫তম সংশোধনীর মাধ্যমে তত্ত্বাবধায়ক সরকার ব্যবস্থা রদ করা হয়। এ ব্যবস্থা প্রণয়ন করা হয়েছিল ২৭ মার্চ ১৯৯৬ সংবিধানের ১৩তম সংশোধনীর মাধ্যমে।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ba51600e6130a290731274da247d5377'),
(7946, 726, 'বাংলাদেশের জাতীয় সংসদ কয় কক্ষবিশিষ্ট?', 'এক কক্ষ', NULL, 'দুই বা দ্বিকক্ষ', NULL, 'তিন কক্ষ', NULL, 'বহুকক্ষ বিশিষ্ট', NULL, 'A', 'যে কোনো দেশের আইন পরিষদ এক কক্ষ অথবা দ্বিকক্ষ হয়ে থাকে। বাংলাদেশের জাতীয় সংসদ এক কক্ষ বিশিষ্ট। আর পার্শ্ববর্তী দেশ ভারতের আইনসভা দ্বিকক্ষ বিশিষ্ট।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e0769dd9436f0365248d93c55ce315ef'),
(7947, 681, 'ভারতের কতটি \"ছিটমহল\" বাংলাদেশের ভৌগোলিক সীমায় অন্তর্ভুক্ত হয়েছে?', '১৬২টি', NULL, '১১১টি', NULL, '৫১টি', NULL, '১০১টি', NULL, 'B', '২০১৫ সালে উভয় দেশের মধ্যে এ ছিটমহল বিনিময় হয়। এ বিনিময়ের মাধ্যমে বাংলাদেশের ভূখণ্ডে ভারতের ১১১টি আর ভারতের ভূখণ্ডে বাংলাদেশের ৫১টি ছিটমহল অন্তর্ভুক্ত হয়।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6330d8fc915d0087ad741ae90b4346ea'),
(7948, 681, 'বাংলাদেশের ভৌগোলিক অবস্থান কোনটি?', '২২°-৩০\' ২০°-৩৪\' দক্ষিণ অক্ষাংশে', NULL, '৮০°-৩১\' ৪০°-৯০\' দ্রাঘিমাংশে', NULL, '৩৪°-২৫\' ৩৮\' উত্তর অক্ষাংশে', NULL, '৮৮°-০১\' থেকে ৯২°-৪১\' পূর্ব দ্রাঘিমাংশে', NULL, 'D', 'কোনো দেশের ভৌগোলিক অবস্থান বলতে অক্ষরেখা ও দ্রাঘিমা রেখাভিত্তিক অবস্থানকে বোঝায়। বাংলাদেশ ৮৮°-০১\' থেকে ৯২°-৪১\' পূর্ব দ্রাঘিমারেখা এবং ২০°-৩৪\' থেকে ২৬°৩৮\' উত্তর অক্ষরেখার মধ্যে অবস্থিত।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd9da40817f0c1181112f941c543f988d'),
(7949, 701, 'বাংলাদেশে প্রথম আদমশুমারি অনুষ্ঠিত হয় কবে?', '১৯৭২ সালে', NULL, '১৯৭৩ সালে', NULL, '১৯৭৪ সালে', NULL, '১৯৭৭ সালে', NULL, 'C', 'স্বাধীন বাংলাদেশের প্রথম আদমশুমারি অনুষ্ঠিত হয় ১৯৭৪ সালে। বাংলাদেশে সর্বশেষ ষষ্ঠ জনশুমারি ও গৃহগণনা অনুষ্ঠিত হয় ২০২২ সালে।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '490da841c50411f5f45c651e93dfd3e9'),
(7950, 704, 'কোন উপজাতি বা ক্ষুদ্র নৃ-গোষ্ঠীর ধর্ম ইসলাম?', 'রাখাইন', NULL, 'মারমা', NULL, 'পাঙন', NULL, 'খিয়াং', NULL, 'C', 'বাংলাদেশে বর্তমানে ৫০টি নৃ-গোষ্ঠী বসবাস করে। এর মধ্যে একমাত্র পাঙন উপজাতিই ধর্মীয়ভাবে মুসলমান। পাঙন উপজাতিরা মৌলভীবাজার জেলার কমলগঞ্জ উপজেলায় বসবাস করে।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '43de2520d1a9f62582d1e8f8def95b6b'),
(7951, 681, 'ঢাকার \"ধোলাই খাল\" কে খনন করেন?', 'পরিবিবি', NULL, 'ইসলাম খান', NULL, 'শায়েস্তা খান', NULL, 'ঈশা খান', NULL, 'B', '১৬০৮-১৬১০ খ্রিষ্টাব্দে বাংলার প্রথম মুঘল সুবাদার ইসলাম খান \"ধোলাই খাল\" খনন করেন। এ খালটি বালু নদীকে বুড়িগঙ্গা নদীর সাথে যুক্ত করেছিল।', NULL, 7, '36th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0ad97bed99364f7d4ccc3fe2002e1fd3'),
