(7983, 726, 'বাংলাদেশের কোন জাতীয় সংসদে প্রধানমন্ত্রীর প্রশ্নোত্তর পর্ব চালু হয়?', 'প্রথম', NULL, 'দ্বিতীয়', NULL, 'সপ্তম', NULL, 'অষ্টম', NULL, 'C', '১৯৯৬ সালের ১২ জুন সপ্তম জাতীয় সংসদ নির্বাচনে বিজয় লাভ করে বাংলাদেশ আওয়ামী লীগ সরকার গঠন করে। এ সপ্তম জাতীয় সংসদে সর্বপ্রথম প্রধানমন্ত্রীর প্রশ্নোত্তর পর্ব চালু করা হয়।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6287c67dd8c2448e617007f9f415ab8c'),
(7984, 726, 'মাত্র ১টি সংসদীয় আসন–', 'লক্ষ্মীপুর জেলায়', NULL, 'মেহেরপুর জেলায়', NULL, 'ঝালকাঠী জেলায়', NULL, 'রাঙ্গামাটি জেলায়', NULL, 'D', 'বাংলাদেশের জাতীয় সংসদের মোট আসন সংখ্যা ৩৫০। বাংলাদেশে সর্বনিম্ন সংখ্যক সংসদীয় আসন রয়েছে পার্বত্য তিন জেলা বান্দরবান, খাগড়াছড়ি ও রাঙ্গামাটিতে মাত্র ১টি করে।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3465a11d5afd02b9bdb80aac2006e57d'),
(7985, 753, 'বাংলাদেশের মুক্তিযুদ্ধের পটভূমিকায় নির্মিত \"ধীরে বহে মেঘনা\" চলচ্চিত্রের নির্মাতা কে?', 'আলমগীর কবির', NULL, 'খান আতাউর রহমান', NULL, 'হুমায়ূন আহমেদ', NULL, 'সুভাষ দত্ত', NULL, 'A', '\"ধীরে বহে মেঘনা\" চলচ্চিত্রটি নির্মাণ করেছেন আলমগীর কবির। এটি বাংলাদেশের মুক্তিযুদ্ধের পটভূমিতে নির্মিত একটি উল্লেখযোগ্য চলচ্চিত্র।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd51c3755cc1c94ea3e38baa660bc648b'),
(7986, 726, 'জাতীয় সংসদে \"কাস্টিং ভোট\" কি?', 'সংসদ নেতার ভোট', NULL, 'হুইপের ভোট', NULL, 'স্পিকারের ভোট', NULL, 'রাষ্ট্রপতির ভোট', NULL, 'C', 'পরস্পরবিরোধী পক্ষদ্বয়ের ভোট সমান হলে জয়পরাজয় নির্ধারণের জন্য সভাপতি যে ভোট দিয়ে থাকেন তাকে \"কাস্টিং ভোট\" বলে। বাংলাদেশের জাতীয় সংসদের কাস্টিং ভোট হলো স্পিকারের ভোট।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0210114ef3b66d5eef8658e7af406398'),
(7987, 744, 'NILG এর পূর্ণরূপ-', 'National Information Legal Guide', NULL, 'National Institute of Local Government', NULL, 'National Identity Licence Guide', NULL, 'National Industrial League Group', NULL, 'B', 'NILG-এর পূর্ণরূপ National Institute of Local Government (জাতীয় স্থানীয় সরকার ইনস্টিটিউট)। এটি বাংলাদেশের স্থানীয় সরকার ব্যবস্থায় সম্পৃক্ত মানব সম্পদের উন্নয়নে নিয়োজিত একটি প্রতিষ্ঠান।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f72c63c85cb8f5e9fa138c9efc562581'),
(7988, 744, 'বাংলাদেশ সিভিল সার্ভিসের ক্যাডার সংখ্যা–', '২৬', NULL, '২৭', NULL, '২৮', NULL, '৩১', NULL, 'A', '১৩ সেপ্টেম্বর ২০১৮ বিসিএস ইকোনমিক ক্যাডারকে বিলুপ্ত করে প্রশাসন ক্যাডারের সাথে একীভূত করলে বর্তমানে বাংলাদেশ সিভিল সার্ভিসের ক্যাডার সংখ্যা দাঁড়ায় ২৬টিতে।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5e8569342dbc72d8f9585012a96fc711'),
