(7990, 681, 'অবস্থান অনুসারে বাংলাদেশের টারশিয়ারি পাহাড়কে কত ভাগে ভাগ করা হয়?', '২ ভাগে', NULL, '৪ ভাগে', NULL, '৫ ভাগে', NULL, '৮ ভাগে', NULL, 'A', 'বাংলাদেশের দক্ষিণ-পূর্ব, উত্তর ও উত্তর-পূর্বাঞ্চলের পাহাড়সমূহ এ অঞ্চলের অন্তর্ভুক্ত। এ অঞ্চলের পাহাড়সমূহকে দুই ভাগে ভাগ করা হয়েছে। যথা: ক. দক্ষিণ-পূর্বাঞ্চলের পাহাড়সমূহ ও খ. উত্তর ও উত্তর-পূর্বাঞ্চলের পাহাড়সমূহ।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '691dd89b7738708267bd78ad48218c13'),
(7991, 695, 'বাংলাদেশকে স্বীকৃতিদানকারী প্রথম অনারব মুসলিম দেশ কোনটি?', 'ইন্দোনেশিয়া', NULL, 'মালয়েশিয়া', NULL, 'মালদ্বীপ', NULL, 'পাকিস্তান', NULL, 'C', 'বাংলাদেশকে স্বীকৃতি দানকারী প্রথম দেশ ভুটান, প্রথম ইউরোপের দেশ পূর্ব জার্মানি। প্রথম অনারব মুসলিম দেশ সেনেগাল, প্রথম আরব দেশ ইরাক।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2839555c7f298bb38edfcfcdc5fbe938'),
(7992, 682, 'বাংলাদেশে মর্যাদা অনুসারে ৩য় বীরত্বসূচক খেতাব–', 'বীরপ্রতীক', NULL, 'বীরশ্রেষ্ঠ', NULL, 'বীরউত্তম', NULL, 'বীরবিক্রম', NULL, 'D', 'স্বাধীনতার পর ১৯৭২ সালের ১৪ ফেব্রুয়ারি মন্ত্রিপরিষদ সভায় চারটি বীরত্বসূচক খেতাবের নামকরণ করা হয়। সর্বোচ্চ পদমর্যাদার খেতাব বীরশ্রেষ্ঠ, উচ্চ পদমর্যাদার খেতাব বীরউত্তম, প্রশংসনীয় পদমর্যাদার খেতাব বীরবিক্রম এবং বীরত্বসূচক প্রশংসাপত্রের খেতাব বীরপ্রতীক।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '85f8466aa297f25c31461a46a0c1cfc4'),
(7993, 752, 'ক্রিকেটে বাংলাদেশ টেস্ট মর্যাদা পায়–', '১৯৯৭ সালে', NULL, '১৯৯৯ সালে', NULL, '২০০১ সালে', NULL, '২০০০ সালে', NULL, 'D', 'বাংলাদেশ টেস্ট ক্রিকেটের দশম সদস্য হিসেবে টেস্ট খেলার মর্যাদা পায় ২৬ জুন ২০০০। বাংলাদেশ ১৫ জুন ১৯৯৭ ওয়ানডে ক্রিকেট খেলার মর্যাদা লাভ করে।', NULL, 8, '37th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2e1523788964a78576c770a75472b26b'),
(7994, 681, 'প্রাচীন বাংলার হরিকেল জনপদ অঞ্চলভুক্ত এলাকা-', 'রাজশাহী', NULL, 'দিনাজপুর', NULL, 'খুলনা', NULL, 'চট্টগ্রাম', NULL, 'D', 'গৌড়, বঙ্গ, পুণ্ড্র, হরিকেল, সমতট, বরেন্দ্র, তাম্রলিপ্ত ও চন্দ্রদ্বীপ প্রভৃতি জনপদ নিয়ে গড়ে ওঠে প্রাচীন বাংলা। তন্মধ্যে হরিকেল জনপদ গড়ে উঠেছিল সিলেট ও চট্টগ্রামের অংশবিশেষ নিয়ে।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fe84a4ed119536847a94fd531de27dfe'),
(7995, 681, 'নিচের মোগল সম্রাটদের মধ্যে কে প্রথম আত্মজীবনী লিখেছিলেন?', 'আকবর', NULL, 'বাবর', NULL, 'শাহজাহান', NULL, 'হুমায়ুন', NULL, 'B', 'মুঘল সাম্রাজ্যের প্রতিষ্ঠাতা জহিরউদ্দিন মুহম্মদ বাবর তুর্কি ভাষায় \"তুজুক-ই-বাবুরী\" বা বাবরনামা নামে তার জীবন স্মৃতি রচনা করেন। তিনিই প্রথম আত্মজীবনী রচনাকারী মুঘল সম্রাট।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5d945bb572772b83836f15f436c277cb'),
(7996, 685, 'ঐতিহাসিক ছয় দফা ঘোষণা করা হয় ১৯৬৬ সালের-', 'ফেব্রুয়ারিতে', NULL, 'মে মাসে', NULL, 'জুলাই মাসে', NULL, 'আগস্টে', NULL, 'A', '১৯৬৬ সালের ৫-৬ ফেব্রুয়ারি লাহোরে শেখ মুজিবুর রহমান পূর্ব পাকিস্তানের স্বায়ত্তশাসন প্রতিষ্ঠার লক্ষ্যে বাঙালি জাতির মুক্তির সনদ বা ম্যাগনাকার্টা নামে পরিচিত \"৬ দফা দাবি\" পেশ করেন।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'aeb0acbf4f88fa766b11b1991c7638b8'),
(7997, 691, 'মুজিবনগর সরকারের ত্রাণ ও পুনর্বাসন মন্ত্রী কে ছিলেন?', 'ক্যাপ্টেন এম মনসুর আলী', NULL, 'তাজউদ্দীন আহমদ', NULL, 'এ.এইচ. এম কামারুজ্জামান', NULL, 'খন্দকার মোশতাক আহমদ', NULL, 'C', '১০ এপ্রিল ১৯৭১ গঠিত বাংলাদেশের প্রথম সরকার তথা মুজিবনগর সরকারের স্বরাষ্ট্র, সাহায্য ও পুনর্বাসন মন্ত্রী ছিলেন এ. এইচ. এম. কামারুজ্জামান।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c86ddd2f08e12aded7419c8b47c0fe9'),
(7998, 683, 'কিসের ভিত্তিতে পূর্ব বাংলায় ভাষা আন্দোলন হয়েছিল?', 'দ্বি-জাতি তত্ত্ব', NULL, 'সামাজিক চেতনা', NULL, 'অসাম্প্রদায়িকতা', NULL, 'বাঙালি জাতীয়তাবাদ', NULL, 'D', 'পাকিস্তান সৃষ্টির পর যখন বাংলা ভাষা ও সংস্কৃতির উপর প্রথম আঘাত আসে, তখন বাঙালি জনগণ বিশেষ করে যুবসম্প্রদায় ভাষা, সাহিত্য ও সংস্কৃতি রক্ষার জন্য ঐক্যবদ্ধ সংগ্রামে ঝাঁপিয়ে পড়ে। মূলত তখন থেকেই বাঙালি জাতীয়তাবাদের ভিত্তিতে গড়ে ওঠা পূর্ব বাংলার ভাষা আন্দোলন পরবর্তীতে স্বাধীন সার্বভৌম বাংলাদেশ জন্মের পথ সুগম করে।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b926a1d1ff243bb4118b2b38600f6c79'),
(7999, 684, '১৯৫৪ সালের পূর্ববাংলা প্রাদেশিক পরিষদ নির্বাচনে যুক্ত ছিলেন না–', 'শেরে বাংলা এ কে ফজলুল হক', NULL, 'হোসেন শহীদ সোহরাওয়ার্দী', NULL, 'মাওলানা আবদুল হামিদ খান ভাসানী', NULL, 'নবাব স্যার সলিমুল্লাহ', NULL, 'D', '১৯৫৪ সালের নির্বাচনে মুসলিম লীগের বিরুদ্ধে বিজয় নিশ্চিত করতে \"যুক্তফ্রন্ট\" গঠিত হয়। নবাব স্যার সলিমুল্লাহ ১৯০৬ সালে \"অল ইন্ডিয়া মুসলিম লীগ\" প্রতিষ্ঠা করেন।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a6ecd3e515c65aa496cec93e468afb5c'),
(8000, 696, 'জুম চাষ হয়-', 'বরিশালে', NULL, 'ময়মনসিংহে', NULL, 'খাগড়াছড়িতে', NULL, 'দিনাজপুরে', NULL, 'C', 'জুম বা স্থানান্তর চাষাবাদ সাধারণভাবে \"সুইডেন চাষাবাদ\" বা জঙ্গল পরিষ্কার ও পোড়ানো চাষাবাদ হিসেবে পরিচিত। জুম চাষ পার্বত্য অঞ্চলের (রাঙামাটি, খাগড়াছড়ি ও বান্দরবান) ক্ষুদ্র-নৃগোষ্ঠীদের জীবন-জীবিকার প্রধান অবলম্বন।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3b49ec7d0310109311064407c20001a0'),
