(8020, 695, 'পার্বত্য চট্টগ্রাম শান্তিচুক্তি কত সালে স্বাক্ষরিত হয়?', '১৯৯৩', NULL, '১৯৯৭', NULL, '১৯৯৯', NULL, '২০০১', NULL, 'B', 'তৎকালীন সরকার ও জনসংহতি সমিতির মধ্যে ২ ডিসেম্বর, ১৯৯৭ ঐতিহাসিক পার্বত্য চট্টগ্রাম শান্তিচুক্তি স্বাক্ষরিত হয়।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a75bd7ea7bb30cc7ee1c1a5cd653fd20'),
