(8023, 712, 'বাংলাদেশ বর্তমানে সর্বাধিক পরিমাণ অর্থের বিভিন্ন পণ্য আমদানি করে-', 'ভারত থেকে', NULL, 'চীন থেকে', NULL, 'জাপান থেকে', NULL, 'সিঙ্গাপুর থেকে', NULL, 'B', 'দেশভিত্তিক আমদানি পণ্যের পর্যালোচনা করলে দেখা যায় যে, ২০০৬-০৭ অর্থবছর থেকে ২০২২-২৩ অর্থবছর পর্যন্ত দেশের আমদানির ক্ষেত্রে চীনের শীর্ষ অবস্থান অব্যাহত রয়েছে।', NULL, 9, '38th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4d4a99b154a843d14187cf774e498dc1'),
(8024, 681, 'আলাউদ্দিন হোসেন শাহ্ কখন বৃহত্তর বাংলা শাসন করেন?', '১৪৯৮-১৫১৬ খ্রিস্টাব্দ', NULL, '১৪৯৮-১৫১৭ খ্রিস্টাব্দ', NULL, '১৪৯৮-১৫১৮ খ্রিস্টাব্দ', NULL, '১৪৯৮-১৫১৯ খ্রিস্টাব্দ', NULL, 'D', 'মধ্যযুগে বাংলার সর্বশ্রেষ্ঠ নরপতি, বাংলার আকবর খ্যাত আলাউদ্দিন হোসেন শাহ ১৪৯৩ সালে বাংলার মসনদে অধিষ্ঠিত হন। তিনি ১৪৯৮ সালে কামতাপুর রাজ্যে অভিযান চালিয়ে সফল হন। এ দৃষ্টিকোণ থেকে তিনি বৃহত্তর বাংলা শাসন করেন ১৪৯৮-১৫১৯ সাল পর্যন্ত।', NULL, 10, '40th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0df39089ce898cb909513331612b28ed'),
