(8084, 681, 'নওগাঁ জেলার পাহাড়পুরে অবস্থিত \"সোমপুর বিহার\" এর প্রতিষ্ঠাতা কে?', 'গোপাল', NULL, 'ধর্মপাল', NULL, 'মহীপাল', NULL, 'বিগ্রহপাল', NULL, 'B', 'নওগাঁ জেলার পাহাড়পুরে অবস্থিত সোমপুর বিহার বা সোমপুর মহাবিহার। পালবংশের দ্বিতীয় রাজা শ্রী ধর্মপাল দেব (৭৮১-৮২১) অষ্টম শতকের শেষের দিকে বা নবম শতকে এই বিহারটি তৈরি করছিলেন।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7d5f4765bd729e5e3a717604e6b68650'),
(8085, 725, 'বাংলাদেশ সরকারী কর্ম কমিশন সংবিধানের কত অনুচ্ছেদ অনুযায়ী গঠিত?', '১৩৬', NULL, '১৩৭', NULL, '১৩৮', NULL, '১৪০', NULL, 'B', 'সরকারী কর্ম কমিশন একটি স্বায়ত্তশাসিত সংস্থা যার দায়িত্ব সরকারি চাকরিতে নিয়োগ সংক্রান্ত দায়িত্ব পালন করা। বাংলাদেশের সংবিধানের ১৩৭ অনুচ্ছেদে সরকারী কর্ম কমিশন গঠনের সাংবিধানিক বাধ্যবাধকতা বর্ণিত আছে।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '13ad44696cc757fec557266308cbcf8c'),
