(8091, 682, 'মুক্তিযুদ্ধভিত্তিক নভেল কোনটি?', 'ক্রীতদাসের হাসি', NULL, 'জীবন ও রাজনৈতিক বাস্তবতা', NULL, 'কান্নাপর্ব', NULL, 'প্রদোষে প্রাকৃতজন', NULL, 'B', '\"জীবন ও রাজনৈতিক বাস্তবতা\" বাঙালি লেখক শহীদুল জহির রচিত বাংলা উপন্যাস। বাংলাদেশের স্বাধীনতা যুদ্ধের পটভূমিতে রচিত এটি একটি নাতিদীর্ঘ উপন্যাস।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ec839501a32d95dfb151ea5f0dc3261'),
(8092, 717, 'ডিসেম্বর ২০২০ এ অনুষ্ঠিত বাংলাদেশ-ভারত দ্বিপাক্ষিক ভার্চুয়াল শীর্ষ সম্মেলনে কয়টি সমঝোতা স্মারক স্বাক্ষরিত হয়?', '৩টি', NULL, '৫টি', NULL, '৭টি', NULL, '৯টি', NULL, 'C', '১৭ ডিসেম্বর, ২০২০ বাংলাদেশের প্রধানমন্ত্রী শেখ হাসিনা ও ভারতের প্রধানমন্ত্রী নরেন্দ্র মোদির মধ্যে ভার্চুয়াল বৈঠক অনুষ্ঠিত হয়। দুই দেশের মধ্যে একটি চুক্তি, চারটি সমঝোতা স্মারক (MoU), একটি প্রটোকল ও একটি ToR সহ মোট ৭টি স্বাক্ষরিত হয়।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4265d0c803a0aba81e14433b12c8feb5'),
(8093, 681, 'বাংলা আদি অধিবাসীগণ কোন ভাষাভাষী ছিলেন?', 'বাংলা', NULL, 'সংস্কৃত', NULL, 'হিন্দি', NULL, 'অস্ট্রিক', NULL, 'D', 'সমগ্র বাঙালি জনগোষ্ঠীকে দুইভাগে ভাগ করা যায়। যথা- প্রাক-আর্য (অনার্য) জনগোষ্ঠী এবং আর্য জনগোষ্ঠী। বাংলার আদি জনপদগুলোর ভাষা ছিল অস্ট্রিক।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bd974f24596439c2f07853824bccd06b'),
(8094, 696, 'বাংলাদেশের প্রথম সামুদ্রিক গ্যাসক্ষেত্র কোনটি?', 'হাতিয়া প্রণালী', NULL, 'জাফোর্ড পয়েন্ট', NULL, 'সাঙ্গু ভ্যালি', NULL, 'মাতারবাড়ি', NULL, 'C', 'সাঙ্গু গ্যাসক্ষেত্র বাংলাদেশের একটি প্রাকৃতিক গ্যাসক্ষেত্র। ১৯৯৬ সালে অগভীর সমুদ্রে, চট্টগ্রামের সলিমপুরের কাছে স্থলভাগ থেকে ৫০ কি.মি. দূরত্বে বঙ্গোপসাগরে এই গ্যাসক্ষেত্র আবিষ্কার করা হয়। এটি বাংলাদেশের একমাত্র সামুদ্রিক গ্যাসক্ষেত্র।', NULL, 184, '42nd BCS Special(Health)', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a95e71765ba4e23042fdc5603ad9271e'),
