(8106, 708, 'বাংলাদেশ সরকার কোন খাত থেকে সর্বোচ্চ রাজস্ব আয় করে?', 'আয়কর', NULL, 'ভূমিকর', NULL, 'আমদানি-রপ্তানি শুল্ক', NULL, 'মূল্য সংযোজন কর', NULL, 'D', '২০২১-২২ অর্থবছরে বেশি রাজস্ব আদায় হয়েছে মূল্য সংযোজন কর থেকে। এই খাত থেকে আদায় হয়েছে ১ লাখ ২৭ হাজার ৫৬৮ কোটি টাকা। ভ্যাটের পর আয়কর থেকে আদায় হয়েছে ১ লাখ ৫ হাজার ৩২৫ কোটি টাকা।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '50c675059b69ed283d14a39643816f0c'),
(8107, 719, 'বাংলাদেশের কোনটি ব্যাংক নোট নয়?', '২ টাকা', NULL, '১০ টাকা', NULL, '৫০ টাকা', NULL, '১০০ টাকা', NULL, 'A', 'বাংলাদেশের ২ ধরনের নোট আছে- সরকারি ও ব্যাংক নোট। বাংলাদেশের সরকারি নোট ৩টি- ১, ২ ও ৫ টাকার নোট। সরকারি নোটে অর্থ সচিবের স্বাক্ষর থাকে। ব্যাংক নোট ৭টি- ১০, ২০, ৫০, ১০০, ২০০, ৫০০ এবং ১০০০ টাকার নোট।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd6e8758d912ffafc49310a1313e1275c'),
(8108, 748, 'বাংলাদেশে কোন সালে বয়স্ক ভাতা চালু হয়?', '১৯৯৫', NULL, '১৯৯৬', NULL, '১৯৯৭', NULL, '১৯৯৮', NULL, 'D', 'প্রধানমন্ত্রী শেখ হাসিনা সামাজিক নিরাপত্তা খাতের অংশ হিসেবে ১৯৯৮ সালে বয়স্কভাতা কর্মসূচি চালু করেন। ১৯৯৭-৯৮ অর্থবছর হতে প্রাথমিকভাবে দেশের সকল ইউনিয়ন পরিষদের প্রতিটি ওয়ার্ডে ১০ জন দরিদ্র বয়োজ্যেষ্ঠ ব্যক্তিকে প্রতিমাসে ১০০ টাকা হারে ভাতা প্রদানের আওতায় আনা হয়।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0b86d087641dab2fecfe3b09e2a4d86b'),
