(8183, 696, 'ইউরিয়া সারের কাঁচামাল কী?', 'প্রাকৃতিক গ্যাস', NULL, 'চুনাপাথর', NULL, 'মিথেন গ্যাস', NULL, 'ইলমেনাইট', NULL, 'C', 'ইউরিয়া সারের প্রধান কাঁচামাল মিথেন গ্যাস। ইউরিয়া উদ্ভিদের নাইট্রোজেন সরবরাহ করে এবং উদ্ভিদের বৃদ্ধি সাধন করে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e66af7716dcaf2fed66f647d85bdb613'),
(8184, 727, 'কোনটি বিচার বিভাগের কাজ নয়?', 'আইনের প্রয়োগ', NULL, 'আইনের ব্যাখ্যা', NULL, 'সংবিধানের ব্যাখ্যা', NULL, 'সংবিধান প্রণয়ন', NULL, 'D', 'সংবিধান প্রণয়ন করে গণপরিষদ বা আইন পরিষদ। আইন পরিষদ সংবিধান সংশোধনও করে থাকে। বিচার বিভাগ সংবিধান ও আইনের ব্যাখ্যা প্রদান করে এবং আইন অনুযায়ী অপরাধীর শাস্তি প্রদান করে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c175fd2ed9a533f13a4887d2b5266768'),
(8185, 742, 'পারিবারিক আদালত অধ্যাদেশ কত সালে জারি হয়?', '১৯৮০ সালে', NULL, '১৯৮১ সালে', NULL, '১৯৮৫ সালে', NULL, '১৯৯১ সালে', NULL, 'C', 'পারিবারিক আদালত অধ্যাদেশ জারি করা হয় ১৯৮৫ সালে। পরিবারের প্রতিটি সদস্যের আইনগত সমস্যার বিচার নিষ্পত্তি সম্পর্কিত অধ্যাদেশ এটি।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '10c83ee4ec03fd09aad8650453c22ab5'),
(8186, 750, '\"গণহত্যা জাদুঘর\" কোথায় অবস্থিত?', 'ঢাকা', NULL, 'চট্টগ্রাম', NULL, 'কুমিল্লা', NULL, 'খুলনা', NULL, 'D', 'গণহত্যা জাদুঘর খুলনায় অবস্থিত। এ জাদুঘরের নাম \"১৯৭১ গণহত্যা নির্যাতন আর্কাইভ ও জাদুঘর\"। ২০১৪ সালের ১৭ মে খুলনায় এ জাদুঘর যাত্রা শুরু করে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '445ad93cb8f2f9397fae0f258eacf140'),
(8187, 749, 'নভেরা আহমেদের পরিচয় কী হিসাবে?', 'কবি', NULL, 'নাট্যকার', NULL, 'কণ্ঠশিল্পী', NULL, 'ভাস্কর', NULL, 'D', 'বাংলাদেশের অন্যতম আধুনিক ভাস্কর নভেরা আহমেদ। তিনি ১৯৩৯ সালে জন্মগ্রহণ করেন। তাঁর অন্যতম প্রধান ভাস্কর্য হলো চাইল্ড ফিলোসফার, কাউ অ্যান্ড টু ফিগার্স।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '264eaf80a9d2e7c20badccde7e79c48c'),
(8188, 744, 'আয়তনে বাংলাদেশের সবচেয়ে বড় জেলা কোনটি?', 'রাঙ্গামাটি', NULL, 'বরিশাল', NULL, 'চট্টগ্রাম', NULL, 'ময়মনসিংহ', NULL, 'A', 'আয়তনে বাংলাদেশের বৃহত্তম জেলা রাঙ্গামাটি। এর আয়তন ৬১১৬ বর্গকিলোমিটার।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '40baa21d8ffa27ff9847947067ce42bf'),
(8189, 681, 'কোন এলাকাকে \"Marine Protected Area\" (MPA) ঘোষণা করা হয়েছে?', 'সেন্টমার্টিন', NULL, 'সেন্টমার্টিন এবং এর আশেপাশের এলাকা', NULL, 'পটুয়াখালী ও বরগুনা', NULL, 'হিরন পয়েন্ট', NULL, 'B', '\"Marine Protected Area\" (MPA) ঘোষণা করা হয়েছে সেন্টমার্টিন এবং এর আশেপাশের এলাকাকে। প্রবাল দ্বীপের সংরক্ষণ, জীববৈচিত্র্য হ্রাস রোধে ১৭৪৩ বর্গ কি.মি. এলাকাকে MPA ঘোষণা করা হয়েছে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '542ab4ddc2a97983022c2769d95b64be'),
(8190, 716, 'বাংলাদেশের ভৌগলিক নির্দেশক পণ্য কয়টি?', '৯ (নয়) টি', NULL, '১০ (দশ) টি', NULL, '১১ (এগার) টি', NULL, '১২ (বার) টি', NULL, 'D', 'বর্তমানে মোট ভৌগলিক নির্দেশক (GI) পণ্য ২১টি। প্রথম GI পণ্য মসলিন শাড়ি এবং সর্বশেষ ২১তম GI পণ্য কুষ্টিয়ার তিলের খাঁজা।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f3ab830d25de0c7a71c051cf67db36ca');
