(8191, 704, 'ক্ষুদ্র নৃ-গোষ্ঠী \"মনিপুরী\" বাংলাদেশের কোন জেলায় বেশি বসবাস করে?', 'সিলেট', NULL, 'মৌলভীবাজার', NULL, 'হবিগঞ্জ', NULL, 'সুনামগঞ্জ', NULL, 'B', 'গৃহগণনা ও জনশুমারি-২০২২ অনুযায়ী সবচেয়ে বেশি মনিপুরী বসবাস করে মৌলভীবাজারে।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9d5b0f3bcc71783861b0353f3450da86'),
(8192, 701, 'বাংলাদেশের ষষ্ঠ জাতীয় জনশুমারি ও গৃহগণনা কোন সময়ে অনুষ্ঠিত হয়?', '১০ জুন থেকে ১৬ জুন, ২০২২', NULL, '১৫ জুন থেকে ২১ জুন, ২০২২', NULL, '১৫ জুলাই থেকে ২১ জুলাই, ২০২২', NULL, '২০ জুলাই থেকে ২৬ জুলাই, ২০২২', NULL, 'B', 'ষষ্ঠ জনশুমারি ও গৃহগণনা অনুষ্ঠিত হয় ১৫ জুন ২০২২ থেকে ২১ জুন ২০২২ পর্যন্ত। এটি দেশের প্রথম ডিজিটাল জনশুমারি।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '15912715ae911235b6a2ae4aae23020c'),
(8193, 750, 'কূটনৈতিক ক্ষেত্রে অবদানের জন্য গত ২০২০ সালে প্রবর্তিত পুরস্কারের নাম কী?', 'বঙ্গবন্ধু ডিপ্লোমেটিক অ্যাওয়ার্ড ফর এক্সিলেন্স', NULL, 'বঙ্গবন্ধু ডিপ্লোমেটিক এক্সিলেন্স অ্যাওয়ার্ড', NULL, 'বাংলাদেশ ডিপ্লোমেটিক অ্যাওয়ার্ড ফর এক্সিলেন্স', NULL, 'বঙ্গবন্ধু ডিপ্লোমেটিক অ্যাওয়ার্ড', NULL, 'A', 'কূটনৈতিক ক্ষেত্রে অবদানের জন্য ২০২০ সালে বঙ্গবন্ধু ডিপ্লোমেটিক অ্যাওয়ার্ড ফর এক্সিলেন্স অ্যাওয়ার্ড প্রবর্তন করা হয়। বঙ্গবন্ধুর শান্তিকামী কূটনৈতিক দর্শনকে পুনরুজ্জীবিত করার জন্য এ পুরস্কার প্রবর্তন করা হয়।', NULL, 14, '45th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '93f0af5d50568aea3769ec5fcd738ffc'),
(8194, 681, 'পাহাড়পুরের \"সোমপুর মহাবিহার\" বাংলার কোন শাসন আমলের স্থাপত্য কীর্তির নিদর্শন?', 'মৌর্য', NULL, 'পাল', NULL, 'গুপ্ত', NULL, 'চন্দ্র', NULL, 'B', 'সোমপুর মহাবিহার পাল শাসনামলের নিদর্শন। এটি একটি বৌদ্ধবিহার। পাল বংশের দ্বিতীয় রাজা শ্রী ধর্মপাল দেব অষ্টম/নবম শতকে এই বিহার তৈরি করেছিলেন।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a65f2fd9486f682b79108eba38e31588'),
(8195, 691, 'মুজিবনগর সরকারকে গার্ড অব অনার নেতৃত্ব দেন কে?', 'মোহাম্মদ সোলায়মান', NULL, 'আব্দুল খালেক', NULL, 'মাহবুব উদ্দিন আহমেদ', NULL, 'শৈলেন্দ্র কিশোর চৌধুরী', NULL, 'C', 'মুজিবনগর সরকারকে গার্ড অব অনার নেতৃত্ব দেন মাহবুব উদ্দিন আহমেদ। ১৯৭১ সালে ১৭ এপ্রিল মুজিবনগর সরকার শপথ গ্রহণ করে মেহেরপুর জেলার বৈদ্যনাথ তলায়।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '628bf01aa4c98790a59976a4ad019e81'),
(8196, 685, 'ঐতিহাসিক ৬-দফা দাবিতে কোন দুটি বিষয় কেন্দ্রীয় সরকারের হাতে রাখার প্রস্তাব ছিল?', 'বৈদেশিক বাণিজ্য ও প্রতিরক্ষা', NULL, 'অর্থ ও পররাষ্ট্র', NULL, 'স্বরাষ্ট্র ও পরিকল্পনা', NULL, 'প্রতিরক্ষা ও পররাষ্ট্র', NULL, 'D', '১৯৬৬ সালের ৫ ও ৬ ফেব্রুয়ারি লাহোরে বঙ্গবন্ধু শেখ মুজিবুর রহমান ৬ দফা দাবি পেশ করেন। ৬ দফার ২য় দফাতে বলা হয় কেন্দ্রীয় সরকারের ক্ষমতা দুটি ক্ষেত্রে সীমাবদ্ধ থাকবে- দেশ রক্ষা ও বৈদেশিক নীতি।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5f014c8309137382f9aad9d67209da0b'),
(8197, 681, 'বাংলার প্রাচীন জনপদ হরিকেল এর বর্তমান নাম কী?', 'সিলেট ও চট্টগ্রাম', NULL, 'ঢাকা ও ময়মনসিংহ', NULL, 'কুমিল্লা ও নোয়াখালী', NULL, 'রাজশাহী ও রংপুর', NULL, 'A', 'বর্তমান বাংলাদেশের বৃহত্তর সিলেট অঞ্চল এবং চট্টগ্রাম বিভাগের চট্টগ্রাম, কক্সবাজার, রাঙামাটি, বান্দরবান, খাগড়াছড়ি ও ভারতের ত্রিপুরা রাজ্য এই হরিকেল জনপদের অন্তর্ভুক্ত ছিল।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '59a8fb03a42ac5d4a8f9ae87ec61d5b1'),
(8198, 700, 'বাংলাদেশের কোন বিভাগে জনসংখ্যার ঘনত্ব সবচেয়ে কম?', 'সিলেট', NULL, 'খুলনা', NULL, 'বরিশাল', NULL, 'চট্টগ্রাম', NULL, 'C', 'বাংলাদেশ জনশুমারি ও গৃহগণনা ২০২২ অনুযায়ী জনসংখ্যার ঘনত্ব সবচেয়ে কম বরিশালে এবং সবচেয়ে ঘনত্ব বেশি ঢাকায়। বরিশালে প্রতি বর্গকিলোমিটার জনসংখ্যা ৬৮৮ জন।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6d035658a0b095aec1fdbf0f9427eac1'),
(8199, 712, 'ট্রেডিং কর্পোরেশন অব বাংলাদেশ কোন মন্ত্রণালয়ের আওতাভুক্ত?', 'পরিকল্পনা', NULL, 'শিল্প', NULL, 'বাণিজ্য', NULL, 'অর্থ', NULL, 'C', 'Trading Corporation of Bangladesh (TCB) বাণিজ্য মন্ত্রণালয়ের আওতাভুক্ত একটি শাখা। ১৯৭২ সালে খাদ্য ও সংস্থার ঘাটতি মেটাতে TCB প্রতিষ্ঠা করা হয়।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '62ecfe4ccd9f71197f7944645e068eca'),
(8200, 708, 'বাংলাদেশ সরকার কোন উৎস থেকে সর্বোচ্চ রাজস্ব আয় করে?', 'ভূমি রাজস্ব', NULL, 'মূল্য সংযোজন কর', NULL, 'আয়কর', NULL, 'আমদানি শুল্ক', NULL, 'B', 'বাংলাদেশ সরকার মূল্য সংযোজন কর (VAT) থেকে সর্বোচ্চ রাজস্ব আয় করে। ২০২২-২০২৩ অর্থ বছরে এ খাত থেকে বাংলাদেশ ৮৩ হাজার ৩৮১ কোটি টাকা রাজস্ব আয় করে।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '097e8de17c6f880ade67b4f83584bd37'),
