(8288, 692, 'কোন এলাকাটি বাংলাদেশের মুক্তিযুদ্ধকালীন জনযুদ্ধে ক্যাপ্টেন (অবঃ) আব্দুল হালিম চৌধুরীর দ্বারা গঠিত আঞ্চলিক বাহিনীর আওতাধীন এলাকা ছিল না?', 'ধামরাই', NULL, 'কেরানীগঞ্জ', NULL, 'কালিয়াকৈর', NULL, 'সাভার', NULL, 'C', 'হালিম বাহিনীর আওতাধীন এলাকাগুলো ছিল- হরিরামপুর-শিবালয়-ঘিওর-দৌলতপুর; সিঙ্গাইর-মানিকগঞ্জ-সাটুরিয়া ও সাভার; ঢাকার নবাবগঞ্জ-দোহার-কেরাণীগঞ্জ। কালিয়াকৈর এলাকাটি ছিল না।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c00760447d51797e00a984a424ac6143'),
(8289, 724, 'Habeas Corpus writ দায়ের করা হয় সংবিধানের –––– অনুচ্ছেদ লংঘনের কারণে।', '৩১', NULL, '৩২', NULL, '৩৪', NULL, '৩৩', NULL, 'B', 'সংবিধানের ৩৩(১) অনুচ্ছেদ অনুসারে গ্রেপ্তারকৃত কোনো ব্যক্তিকে যথাসম্ভবশীঘ্র গ্রেপ্তারের কারণ জ্ঞাপন না করে প্রহরায় আটক রাখা যাবে না। যদি কাউকে এই নিয়ম না মেনে আটকে রাখা হয়, তবেই হেবিয়াস কর্পাস রিট করা হয়।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8dd03610555fc93e03535340e7d5bfe5'),
(8290, 713, 'কোন ফসলটি রপ্তানী বহুমুখীকরণে সম্ভাবনাময়?', 'আউশ ধান', NULL, 'তেলবীজ', NULL, 'পাট', NULL, 'আলু', NULL, 'D', 'বাংলাদেশের রপ্তানি বহুমুখীকরণে আলু সবচেয়ে সম্ভাবনাময় ফসল, কারণ দেশে আলুর উৎপাদন চাহিদার চেয়ে অনেক বেশি। সাম্প্রতিক বছরে আলু রপ্তানি চারগুণেরও বেশি বেড়ে ৬০,০০০ টন ছাড়িয়েছে।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1da81c462eac488228f57e41168f9002'),
(8291, 748, 'বাংলাদেশের সর্বশেষ সিটি কর্পোরেশন কোনটি?', 'ঢাকা উত্তর', NULL, 'কুমিল্লা', NULL, 'ময়মনসিংহ', NULL, 'রংপুর', NULL, 'C', 'বাংলাদেশের সিটি কর্পোরেশন ১২টি। সর্বশেষ ময়মনসিংহ সিটি কর্পোরেশন ২ এপ্রিল, ২০১৮ সালে গঠিত হয়।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a198b82fbe3d01853f3a5e73d5f28b2e'),
(8292, 752, 'বাংলাদেশ ____ সাল থেকে গ্রীষ্মকালীন অলিম্পিকে অংশগ্রহণ করে আসছে।', '১৯৮৫', NULL, '১৯৮৪', NULL, '১৯৮৬', NULL, '১৯৮৩', NULL, 'B', 'বাংলাদেশ প্রথম লস এঞ্জেলেস, মার্কিন যুক্তরাষ্ট্রে অনুষ্ঠিত ১৯৮৪ সালে গ্রীষ্মকালীন অলিম্পিকে অংশগ্রহণ করে।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '51e169b0866aaaba07a3c7ecdcafbfb6'),
(8293, 709, 'বাংলাদেশের অর্থনৈতিক নীতি ও উন্নয়ন পরিকল্পনা অনুমোদনের সর্বোচ্চ কর্তৃপক্ষ কোনটি?', 'পরিকল্পনা কমিশন', NULL, 'অর্থ মন্ত্রণালয়', NULL, 'পরিকল্পনা মন্ত্রণালয়', NULL, 'জাতীয় অর্থনৈতিক পরিষদের নির্বাহী কমিটি', NULL, 'D', 'বাংলাদেশের অর্থনৈতিক উন্নয়ন প্রকল্প ও নীতি অনুমোদনের ক্ষেত্রে ECNEC-ই হলো চূড়ান্ত ও সর্বোচ্চ নির্বাহী কর্তৃপক্ষ। এর চেয়ারপারসন হলেন প্রধানমন্ত্রী।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-09-29', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8fa07802e64ca8c4e56928f201970d3c'),
(8294, 759, '2/5, 3/5, 6/15 ভগ্নাংশগুলোর লঘিষ্ঠ সাধারণ গুণিতক (ল.সা.গু) হবে—', '7/5', NULL, '6/5', NULL, '1/15', NULL, '6/15', NULL, 'B', 'ভগ্নাংশের ল.সা.গু = (লবগুলোর ল.সা.গু)/(হরগুলোর গ.সা.গু)। লবগুলোর (2, 3, 6) ল.সা.গু = 6; হরগুলোর (5, 5, 15) গ.সা.গু = 5। সুতরাং নির্ণেয় ল.সা.গু = 6/5।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0cd1e1821d7bcf7cbba521128c54d7ba'),
(8295, 766, 'যদি a/b = b/c = 2/3 হয়, তবে a : c এর মান কত হবে?', '২ : ৩', NULL, '৩ : ৪', NULL, '৪ : ৯', NULL, '৯ : ৪', NULL, 'C', 'দেওয়া আছে, a/b = 2/3 এবং b/c = 2/3। এখন, a/c = (a/b) × (b/c) = (2/3) × (2/3) = 4/9। অতএব, a : c = 4 : 9।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd94e5d51b02721835bcd9a685ed7202f'),
(8296, 805, 'একটি সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য ৮ মিটার হলে, এর ক্ষেত্রফল হবে—', '8√3', NULL, '8√5', NULL, '16√3', NULL, '16√5', NULL, 'C', 'সমবাহু ত্রিভুজের ক্ষেত্রফল = (√3/4) × a²; যেখানে a = 8 মিটার। ক্ষেত্রফল = (√3/4) × 64 = 16√3 বর্গমিটার।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ee85eb67bc6ea54cdb0b485a0d293e97'),
(8297, 810, 'A = {x : x স্বাভাবিক সংখ্যা এবং x ≤ 5} হলে, P(A) এর উপাদান সংখ্যা হবে—', '৬৪', NULL, '৩২', NULL, '১৬', NULL, '৮', NULL, 'B', 'A সেটের উপাদানসমূহ = {1, 2, 3, 4, 5}; অর্থাৎ n = 5। পাওয়ার সেট P(A) এর উপাদান সংখ্যা = 2ⁿ = 2⁵ = 32।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '724c61147f780599b58025a7f671da5a'),
(8298, 756, 'যদি 0 < x < 1 হয়, তবে নিচের কোনটি সবচেয়ে বড় হবে?', 'x', NULL, '2x', NULL, 'x²', NULL, 'x + 1', NULL, 'D', 'ধরি, x = 0.5। x = 0.5; 2x = 1; x² = 0.25; x + 1 = 1.5। দেখা যাচ্ছে, x + 1 এর মান সর্বাপেক্ষা বড় (1.5)।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ca8666d2e4099843c52232c294c124b2'),
(8299, 776, 'x⁴ - 2x + 1 কে x - 3 দিয়ে ভাগ করলে ভাগশেষ কত হবে?', '২', NULL, '৮১', NULL, '০', NULL, '৭৬', NULL, 'D', 'ভাগশেষ উপপাদ্য অনুযায়ী, f(x) = x⁴ - 2x + 1 কে (x - 3) দিয়ে ভাগ করলে ভাগশেষ = f(3)। f(3) = 81 - 6 + 1 = 76।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '521f2646431adbdd9c1d58c67fe60136'),
(8300, 764, 'মুনাফার হার কত হলে কিছু পরিমাণ টাকা চক্রবৃদ্ধি হারে ১০ বছরে দ্বিগুণ হবে?', '৫.১৭%', NULL, '৬.১৭%', NULL, '৭.১৭%', NULL, '৮.১৭%', NULL, 'C', 'চক্রবৃদ্ধি সূত্র: C = P(1 + r)ⁿ। ১০ বছরে দ্বিগুণ হলে, (1 + r)¹⁰ = 2 ⇒ 1 + r = 2^(1/10) ≈ 1.0717 ⇒ r ≈ 7.17%।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0da6b1ad6422681ca55602f3c9422d68'),
(8301, 783, '|3x - 1| < 2 এর সমাধান সেট হবে—', '(-1/3, 0)', NULL, '(-1/3, ∞)', NULL, '(-1/3, 1)', NULL, '(∞, 1/3)', NULL, 'C', 'পরমমানের অসমতার নিয়ম: -2 < 3x - 1 < 2 ⇒ -1 < 3x < 3 ⇒ -1/3 < x < 1। সমাধান সেট: (-1/3, 1)।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9a9c439e6ee8731519ea6932292e2bd4'),
(8302, 794, '-1 + 1/2 - 1/4 + 1/8 - 1/16 + ... অসীম ধারাটির যোগফল হবে—', '-2/3', NULL, '-3/2', NULL, '2/3', NULL, '3/2', NULL, 'A', 'অসীম গুণোত্তর ধারা; ১ম পদ a = -1, সাধারণ অনুপাত r = -1/2। S∞ = a/(1 - r) = -1/(1 + 1/2) = -1/(3/2) = -2/3।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'abe9d29ce7f79fa7012762ef2b491113'),
(8303, 773, 'যদি x + 1/x = 0 হয়, তবে x³ + 1/x³ এর মান কত?', '০', NULL, '১', NULL, '২', NULL, '√2', NULL, 'A', 'সূত্র: x³ + 1/x³ = (x + 1/x)³ - 3(x + 1/x)। x + 1/x = 0 বসিয়ে: 0³ - 3(1)(0) = 0। (দ্রষ্টব্য: উৎস প্রশ্নব্যাংকের উত্তরপত্রে \'ঘ\' চিহ্নিত থাকলেও গাণিতিকভাবে সঠিক মান 0।)', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '02034706871a740fdc6b8b33614d2f75'),
(8304, 820, '৪০ থেকে ৫০ এর মধ্যে একটি সংখ্যা দৈবভাবে নেওয়া হলে এটি মৌলিক (Prime) হওয়ার সম্ভাবনা কত?', '3/11', NULL, '1/2', NULL, '5/11', NULL, '4/11', NULL, 'A', '৪০ থেকে ৫০ পর্যন্ত মোট সংখ্যা = ১১টি। এদের মধ্যে মৌলিক সংখ্যা = ৩টি (41, 43, 47)। সম্ভাবনা = 3/11।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '16665828e3bfc058d74c7848b3d9fa20'),
(8305, 814, 'ABSCISSA শব্দটির বর্ণগুলিকে নিয়ে কত প্রকারে বিন্যাস করা যায়?', '১০০৮০', NULL, '৬৭২০', NULL, '৩৩৬০', NULL, '৩৩৫৯', NULL, 'C', 'ABSCISSA-তে মোট বর্ণ 8টি; A আছে 2টি, S আছে 3টি, B, C, I প্রতিটি 1টি। মোট বিন্যাস = 8!/(2! × 3!) = 40320/12 = 3360।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8a8b5cf031cfe5c14aa57b10ec49ea13'),
(8306, 779, 'x² - (p + q)x + pq = 0 এর সমাধান সেট হবে—', '{p, q}', NULL, '{p, -q}', NULL, '{-p, q}', NULL, '{-p, -q}', NULL, 'A', 'x² - px - qx + pq = 0 ⇒ x(x - p) - q(x - p) = 0 ⇒ (x - p)(x - q) = 0। অতএব x = p অথবা x = q। সমাধান সেট = {p, q}।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '832542452ddc4a044a811157d9b9e7db'),
(8307, 795, '3 + 3/2 + 3/4 + ... + 3/64 ধারাটিতে মোট কতটি পদ আছে?', '৫', NULL, '৬', NULL, '৭', NULL, '৮', NULL, 'C', 'গুণোত্তর ধারা; ১ম পদ a = 3, সাধারণ অনুপাত r = 1/2। n-তম পদ = 3/64 ⇒ 3 × (1/2)^(n-1) = 3/64 ⇒ (1/2)^(n-1) = (1/2)^6 ⇒ n - 1 = 6 ⇒ n = 7।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7c78877a06efb898390cc1efbc337cdb'),
(8308, 795, '(x² - 2 + 1/x²)⁷ এর বিস্তৃতিতে মধ্যপদ কততম পদটি?', 'পঞ্চম', NULL, 'সপ্তম', NULL, 'অষ্টম', NULL, 'নবম', NULL, 'C', 'প্রদত্ত রাশি = ((x - 1/x)²)⁷ = (x - 1/x)¹⁴। ঘাত n = 14 (জোড়) হওয়ায় মধ্যপদ ১টি। মধ্যপদের অবস্থান = n/2 + 1 = 7 + 1 = 8ম পদ।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2fc9ed7cc9f40ee3b27e31b82045e4b6'),
(8309, 797, 'একটি ত্রিভুজের তিনটি কোণের পরিমাণ x, x/2 এবং 3x/2। ক্ষুদ্রতম কোণের মান রেডিয়ানে কত হবে?', 'π/6', NULL, 'π/3', NULL, 'π/2', NULL, '2π/3', NULL, 'A', 'ত্রিভুজের তিন কোণের যোগফল = π রেডিয়ান। x + x/2 + 3x/2 = π ⇒ 3x = π ⇒ x = π/3। ক্ষুদ্রতম কোণ = x/2 = π/6।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c8be54b774c07e99ecad9e09e77b67ea'),
(8310, 781, '2x² + 3x + 1 এর ক্ষুদ্রতম মান হবে—', '-3/4', NULL, '-1/8', NULL, '1/8', NULL, '3/4', NULL, 'B', 'দ্বিঘাত রাশি ax² + bx + c এর ক্ষুদ্রতম মান = c - b²/(4a)। a = 2, b = 3, c = 1 ⇒ 1 - 9/8 = -1/8।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '753474cd42989098b8e1e3b960c0d87d'),
(8311, 811, 'সেট {2, 3, 4} এর প্রকৃত উপসেট কয়টি?', '৩', NULL, '৭', NULL, '৮', NULL, '৯', NULL, 'B', 'n = 3 হলে মোট উপসেট = 2³ = 8টি। মূল সেট নিজে ছাড়া প্রকৃত উপসেট = 2ⁿ - 1 = 8 - 1 = 7টি।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '484e5522202e42425b850f3beccac032'),
(8312, 785, 'K এর কোন মানের জন্য 5x + 4y - 1 = 0 এবং 2x + Ky - 7 = 0 সরলরেখা দুটি সমান্তরাল?', '5/8', NULL, '8/5', NULL, '5/2', NULL, '-8/5', NULL, 'B', 'সমান্তরাল হওয়ার শর্ত: a₁/a₂ = b₁/b₂ ⇒ 5/2 = 4/K ⇒ 5K = 8 ⇒ K = 8/5।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c86a05da5b2fe2c3a0395614aaa24f55'),
(8313, 818, '২, ৩, ৪ এবং ৭ সংখ্যাগুলির গড় বিচ্যুতি কত?', '০', NULL, '2/3', NULL, '3/2', NULL, '৪', NULL, 'C', 'গড় x̄ = (2+3+4+7)/4 = 4। গড় বিচ্যুতি = Σ|xᵢ - x̄|/N = (2+1+0+3)/4 = 6/4 = 3/2।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b829d5bf5d721547caac51a146612c93'),
(8314, 789, 'যদি logₓ 324 = 4 হয়, তবে x এর মান হবে—', '৪', NULL, '2√3', NULL, '3√3', NULL, '3√2', NULL, 'D', 'সূচকের নিয়মানুযায়ী: x⁴ = 324। 324 = 81 × 4 = 3⁴ × (√2)⁴ = (3√2)⁴। সুতরাং x = 3√2।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8fbd307b080475586d668e8840787ff5'),
(8315, 805, 'সমান দৈর্ঘ্যের দুটি দড়ির একটি দিয়ে আয়তক্ষেত্র এবং অপরটি দিয়ে বর্গক্ষেত্র তৈরি করা হলে কোনটি সত্য?', 'আয়তক্ষেত্রের ক্ষেত্রফল বেশি', NULL, 'বর্গক্ষেত্রের ক্ষেত্রফল বেশি', NULL, 'উভয়ের ক্ষেত্রফল সমান', NULL, 'নির্ণয় করা সম্ভব নয়', NULL, 'B', 'নির্দিষ্ট একই পরিসীমাবিশিষ্ট যে কোনো চতুর্ভুজের মধ্যে বর্গক্ষেত্রের ক্ষেত্রফল সর্বদা সবচেয়ে বেশি হয়ে থাকে।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ee105254fda748bb9da1af7f031dcdb'),
(8316, 757, '0.5 × 0.05 × 0.005 = ?', '০.১২৫', NULL, '০.০১২৫', NULL, '০.০০১২৫', NULL, '০.০০০১২৫', NULL, 'D', 'সংখ্যাগুলোর গুণফল: 5 × 5 × 5 = 125। দশমিকের পর মোট ঘর = 1 + 2 + 3 = 6টি। তাই নির্ণেয় মান = 0.000125।', NULL, 17, '50th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '975f0248fd1ab38323348962fd0453db'),
(8317, 755, '১ থেকে ৩০ পর্যন্ত কয়টি মৌলিক সংখ্যা আছে?', '১১টি', NULL, '৮টি', NULL, '১০টি', NULL, '৯টি', NULL, 'C', '১ থেকে ৩০ পর্যন্ত মৌলিক সংখ্যাগুলো: ২, ৩, ৫, ৭, ১১, ১৩, ১৭, ১৯, ২৩, ২৯। মোট মৌলিক সংখ্যা = ১০টি।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7d2d85a30f48d257b1d8189a0c8480dd'),
(8318, 755, 'নিচের কোন সংখ্যাটি মৌলিক সংখ্যা?', '১৪৩', NULL, '৯১', NULL, '৪৭', NULL, '৮৭', NULL, 'C', '১৪৩ = ১১ × ১৩; ৯১ = ৭ × ১৩; ৮৭ = ৩ × ২৯ — এগুলো যৌগিক। ৪৭ কে ১ ও ৪৭ ছাড়া অন্য কোনো সংখ্যা দিয়ে ভাগ করা যায় না, তাই ৪৭ মৌলিক।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e5daa9e028a30e5177030f86cfde5262'),
(8319, 759, 'দুটি সংখ্যার গুণফল ১৫৩৬। সংখ্যা দুটির ল.সা.গু ৯৬ হলে, গ.সা.গু কত?', '১৬', NULL, '২৪', NULL, '৩২', NULL, '১২', NULL, 'A', 'আমরা জানি, সংখ্যা দুটির গুণফল = গ.সা.গু × ল.সা.গু। গ.সা.গু = 1536/96 = 16।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2a8ed40ebe645306704fffa1f0346336'),
(8320, 757, '(.1 × .01 × .001)/(.2 × .02 × .002) এর মান কত?', '1/80', NULL, '1/800', NULL, '1/8000', NULL, '1/8', NULL, 'D', 'লব = .1 × .01 × .001 = 0.000001; হর = .2 × .02 × .002 = 0.000008। মান = 0.000001/0.000008 = 1/8। বিকল্পভাবে: (1/2) × (1/2) × (1/2) = 1/8।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '59e765fe1c335fa62d7d290f2d8d6f29'),
(8321, 762, 'চিনির মূল্য ২৫% বৃদ্ধি পাওয়ায় একটি পরিবার চিনি খাওয়া এমনভাবে কমাল যে, চিনি বাবদ ব্যয় বৃদ্ধি পেল না। ঐ পরিবার চিনি খাওয়ার খরচ শতকরা কত কমিয়েছিল?', '৩০%', NULL, '২৫%', NULL, '১৫%', NULL, '২০%', NULL, 'D', 'সূত্র: খরচ হ্রাসের হার = (100 × বৃদ্ধির হার)/(100 + বৃদ্ধির হার) = (100 × 25)/125 = 20%।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6ad957e6f7089c30a59afb0391d19796'),
(8322, 769, 'টাকায় ৩টি করে আম কিনে টাকায় ২টি আম বিক্রয় করলে শতকরা কত লাভ হবে?', '৫০%', NULL, '৩০%', NULL, '৩৩%', NULL, '৩১%', NULL, 'A', '১টি আমের ক্রয়মূল্য = 1/3 টাকা, বিক্রয়মূল্য = 1/2 টাকা। লাভ = 1/2 - 1/3 = 1/6 টাকা। শতকরা লাভ = (1/6)/(1/3) × 100 = 50%।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0a5530fb775b91da489b5ff8df65a190'),
(8323, 763, 'সরল সুদের হার শতকরা কত টাকা হলে যে কোনো মূলধন ৮ বছরে সুদে-আসলে তিনগুণ হবে?', '১২.৫০ টাকা', NULL, '২০ টাকা', NULL, '২৫ টাকা', NULL, '১৫ টাকা', NULL, 'C', 'ধরি আসল P = 100। ৮ বছরে সুদে-আসল = 300 ⇒ সুদ I = 200। r = (I × 100)/(P × n) = (200 × 100)/(100 × 8) = 25%।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2dd8a031e2b18eec3c1d04fe5de3da3b'),
(8324, 768, '৬০ লিটার কেরোসিন ও পেট্রোলের মিশ্রণের অনুপাত ৭ : ৩। ঐ মিশ্রণে আর কত লিটার পেট্রোল মেশালে অনুপাত ৩ : ৭ হবে?', '৭০', NULL, '৮০', NULL, '৯০', NULL, '৯৮', NULL, 'B', 'কেরোসিন = 60 × 7/10 = 42 লিটার; পেট্রোল = 60 × 3/10 = 18 লিটার। ধরি x লিটার পেট্রোল মেশাতে হবে। 42/(18+x) = 3/7 ⇒ 294 = 54 + 3x ⇒ x = 80 লিটার।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3448b5d22395d70ced245007ca0895f2'),
(8325, 818, '১ থেকে ৪৯ পর্যন্ত সংখ্যাগুলোর গড় কত?', '২৩', NULL, '২৪.৫', NULL, '২৫', NULL, '২৫.৫', NULL, 'C', 'পর পর স্বাভাবিক সংখ্যার গড় = (প্রথম পদ + শেষ পদ)/2 = (1 + 49)/2 = 25।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ac95984b7315ec1437a632e4d6cb48e4'),
(8326, 773, 'a + b = 5 এবং a - b = 3 হলে, ab এর মান কত?', '2', NULL, '3', NULL, '4', NULL, '5', NULL, 'C', 'সূত্র: ab = ((a+b)/2)² - ((a-b)/2)² = (5/2)² - (3/2)² = 25/4 - 9/4 = 16/4 = 4।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6a76520884e4921a438a49935c9b7806'),
(8327, 778, 'যদি (x - 5)(a + x) = x² - 25 হয় তবে, a এর মান কত?', '-5', NULL, '5', NULL, '25', NULL, '-25', NULL, 'B', 'ডানপক্ষ = x² - 25 = (x - 5)(x + 5)। প্রদত্ত: (x - 5)(a + x) = (x - 5)(x + 5)। উভয়পক্ষকে (x - 5) দ্বারা ভাগ: a + x = x + 5 ⇒ a = 5।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6794a1a6949fd86dd179a8529f3f0332'),
(8328, 805, 'ত্রিভুজ ABC এর BE = EF = CF। ΔABC এর ক্ষেত্রফল ৪৮ বর্গফুট হলে, ΔAEC এর ক্ষেত্রফল কত বর্গফুট?', '৭২', NULL, '৬০', NULL, '৪৮', NULL, '৩২', NULL, 'D', 'E ও F বিন্দুদ্বয় BC বাহুকে ৩টি সমান অংশে বিভক্ত করেছে। ΔABE = ΔAEF = ΔAFC = 48/3 = 16 বর্গফুট। ΔAEC = ΔAEF + ΔAFC = 16 + 16 = 32 বর্গফুট।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd95de567df48de99da502a18484ab444'),
(8329, 798, 'ত্রিভুজের একটি কোণ উহার অপর দুটি কোণের সমষ্টির সমান হলে ত্রিভুজটি—', 'সমকোণী', NULL, 'স্থূলকোণী', NULL, 'সমবাহু', NULL, 'সূক্ষ্মকোণী', NULL, 'A', 'ধরি কোণ তিনটি A, B, C এবং A = B + C। আবার A + B + C = 180° ⇒ A + A = 180° ⇒ A = 90°। যেহেতু একটি কোণ 90°, ত্রিভুজটি সমকোণী।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4da666d67bbda8a336c3b6c1e75455d7'),
(8330, 805, 'সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য যদি a হয়, তবে ক্ষেত্রফল হবে—', '√3/4 a²', NULL, '√3/2 a²', NULL, '3/2 a²', NULL, '1/2 a²', NULL, 'A', 'a বাহুবিশিষ্ট সমবাহু ত্রিভুজের ক্ষেত্রফলের প্রমিত সূত্র = (√3/4) a²।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7c5a1b6d80479bc703de089dcf06bc1a'),
(8331, 770, 'কোনো একটি জিনিসের নির্মাতা ২০% লাভে ও খুচরা বিক্রেতা ২০% লাভে বিক্রয় করে। যদি ঐ জিনিসটির নির্মাণ খরচ ১০০ টাকা হয় তবে খুচরা মূল্য কত?', '১৪০ টাকা', NULL, '১২০ টাকা', NULL, '১৪৪ টাকা', NULL, '১২৪ টাকা', NULL, 'C', 'নির্মাতার বিক্রয়মূল্য = 100 + 100 × 20% = 120 টাকা। খুচরা বিক্রেতার বিক্রয়মূল্য = 120 + 120 × 20% = 120 + 24 = 144 টাকা।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ed32891e759f109b3af60c7969411f8c'),
(8332, 773, 'a + b + c = 0 হলে, a³ + b³ + c³ এর মান কত?', 'abc', NULL, '3abc', NULL, '6abc', NULL, '9abc', NULL, 'B', 'a + b + c = 0 ⇒ a + b = -c। ঘন করে: a³ + b³ + 3ab(a+b) = -c³ ⇒ a³ + b³ - 3abc = -c³ ⇒ a³ + b³ + c³ = 3abc।', NULL, 162, '10th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '00d3b23e39dac87102e6be31958200cf'),
(8334, 762, 'চালের মূল্য ১২% কমে যাওয়ায় ৬,০০০ টাকায় পূর্বাপেক্ষা ১ কুইন্টাল চাল বেশি পাওয়া যায়। ১ কুইন্টাল চালের বর্তমান মূল্য কত?', '৭৫০ টাকা', NULL, '৭০০ টাকা', NULL, '৭২০ টাকা', NULL, '৭৫ টাকা', NULL, 'C', 'চালের মূল্য ১২% কমায় ৬,০০০ টাকায় মোট সাশ্রয় হয়:\r\n৬,০০০ × ১২/১০০ = ৭২০ টাকা\r\nপ্রশ্নমতে, এই সাশ্রয়কৃত ৭২০ টাকা দিয়েই অতিরিক্ত ১ কুইন্টাল চাল কেনা যায়।\r\nঅতএব, ১ কুইন্টাল চালের বর্তমান মূল্য = ৭২০ টাকা।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2947aef19027f5b9e6fb05679d5e8d59'),
(8335, 805, 'একটি আয়তাকার ক্ষেত্রের দৈর্ঘ্য বিস্তারের ৩ গুণ। দৈর্ঘ্য ৪৮ মিটার হলে, ক্ষেত্রটির পরিসীমা কত?', '১২৮ মিটার', NULL, '১৪৪ মিটার', NULL, '৬৪ মিটার', NULL, '৯৬ মিটার', NULL, 'A', 'দেওয়া আছে, আয়তাকার ক্ষেত্রের দৈর্ঘ্য = ৪৮ মিটার।\r\nদৈর্ঘ্য বিস্তারের (প্রস্থের) ৩ গুণ। সুতরাং, বিস্তার (প্রস্থ) = ৪৮ ÷ ৩ = ১৬ মিটার।\r\nআয়তাকার ক্ষেত্রের পরিসীমার সূত্র = ২ × (দৈর্ঘ্য + বিস্তার)\r\nপরিসীমা = ২ × (৪৮ + ১৬) = ২ × ৬৪ = ১২৮ মিটার।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f22ecc6eb482c9f38fd83582265947b0'),
(8336, 809, 'ক ঘণ্টায় ১০ কি.মি. এবং খ ঘণ্টায় ১৫ কি.মি. বেগে একই স্থান থেকে রাজশাহীর পথে রওনা হলো। ক ১০.১০ মিনিটে এবং খ ৯.৪০ মিনিটে রাজশাহী পৌঁছাল। রওনা হওয়ার স্থান থেকে রাজশাহীর দূরত্ব কত কি.মি.?', '২০ কি.মি.', NULL, '২৫ কি.মি.', NULL, '১৫ কি.মি.', NULL, '২৮ কি.মি.', NULL, 'C', 'ক ও খ এর পৌঁছানোর সময়ের পার্থক্য = ১০.১০ মিনিট - ৯.৪০ মিনিট = ৩০ মিনিট = ০.৫ ঘণ্টা।\r\nধরি, রওনা হওয়ার স্থান থেকে রাজশাহীর দূরত্ব = d কি.মি.।\r\nক এর প্রয়োজনীয় সময় = d/১০ ঘণ্টা, এবং খ এর সময় = d/১৫ ঘণ্টা।\r\nপ্রশ্নমতে, d/১০ - d/১৫ = ০.৫\r\n(৩d - ২d)/৩০ = ১/২ ⟹ d/৩০ = ১/২ ⟹ d = ১৫ কি.মি.', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c6964f3cc0949251827888dc5b4787f5'),
(8337, 790, '১৯, ৩৩, ৫১, ৭৩ .......... পরবর্তী সংখ্যাটি কত?', '৮৫', NULL, '১২১', NULL, '৯৯', NULL, '৯৮', NULL, 'C', 'ধারাটির পর পর দুটি পদের পার্থক্য লক্ষ্য করি:\r\n৩৩ - ১৯ = ১৪\r\n৫১ - ৩৩ = ১৮\r\n৭৩ - ৫১ = ২২\r\nপার্থক্যের ধারাটি হলো: ১৪, ১৮, ২২, ... (প্রতিটি পার্থক্য ৪ করে বাড়ছে)।\r\nসুতরাং, পরবর্তী পার্থক্য হবে: ২২ + ৪ = ২৬।\r\nঅতএব, পরবর্তী সংখ্যাটি হবে = ৭৩ + ২৬ = ৯৯।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9b51dc6427ee1b10f3ae06e982b24709'),
(8338, 778, 'একটি ক্রিকেট দলের যতজন স্ট্যাম্প আউট হলো তার দেড়গুণ ক্যাচ আউট হলো এবং মোট উইকেটের অর্ধেক বোল্ড আউট হলো। এই দলের কতজন ক্যাচ আউট হলো?', '৪ জন', NULL, '৩ জন', NULL, '২ জন', NULL, '৫ জন', NULL, 'B', 'একটি ক্রিকেট দলের মোট আউট হওয়া উইকেটের সংখ্যা = ১০ জন।\r\nমোট উইকেটের অর্ধেক বোল্ড আউট হলো, অর্থাৎ বোল্ড আউট = ১০ ÷ ২ = ৫ জন।\r\nবাকি থাকে ১০ - ৫ = ৫ জন (যারা স্ট্যাম্প আউট ও ক্যাচ আউট হয়েছে)।\r\nধরি, স্ট্যাম্প আউট হলো x জন। সুতরাং ক্যাচ আউট হলো ১.৫x জন।\r\nপ্রশ্নমতে, x + ১.৫x = ৫ ⟹ ২.৫x = ৫ ⟹ x = ২\r\nঅতএব, ক্যাচ আউট হওয়া খেলোয়াড়ের সংখ্যা = ১.৫ × ২ = ৩ জন।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b5a49342e89fd51cd29f0e48141651c4'),
(8339, 809, 'একটি বন্দুকের গুলি প্রতি সেকেন্ডে ১৫৪০ ফুট গতিবেগে লক্ষ্যভেদে যায়। এক ব্যক্তি বন্দুক ছোড়ার ৩ সেকেন্ড পরে লক্ষ্যভেদের শব্দ শুনতে পায়। শব্দের গতি প্রতি সেকেন্ডে ১১০০ ফুট। লক্ষ্য বস্তুর দূরত্ব কত?', '২০২৫ ফুট', NULL, '১৯২৫ ফুট', NULL, '১৯৭৫ ফুট', NULL, '১৭৫০ ফুট', NULL, 'B', 'ধরি, বন্দুক হতে লক্ষ্যবস্তুর দূরত্ব = d ফুট।\r\nগুলির যেতে প্রয়োজনীয় সময় = d/১৫৪০ সেকেন্ড।\r\nশব্দের ফিরে আসতে প্রয়োজনীয় সময় = d/১১০০ সেকেন্ড।\r\nপ্রশ্নমতে, d/১৫৪০ + d/১১০০ = ৩\r\n(১১০০ + ১৫৪০)/(১৫৪০ × ১১০০) × d = ৩\r\n২৬৪০/১৬৯৪০০০ × d = ৩ ⟹ d = (৩ × ১৬৯৪০০০)/২৬৪০ = ১৯২৫ ফুট', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '524aa7af863a7406c51a9a1278e22f07'),
(8340, 806, 'একটি বৃত্তের ব্যাসার্ধকে যদি r থেকে বৃদ্ধি করে r + n করা হয়, তবে তার ক্ষেত্রফল দ্বিগুণ হয়। r এর মান কত?', 'n / (√2 - 1)', NULL, 'n + √2', NULL, '2n', NULL, '2(n + 1)', NULL, 'A', 'মূল বৃত্তের ব্যাসার্ধ r হলে ক্ষেত্রফল = πr²\r\nনতুন ব্যাসার্ধ (r + n) হলে নতুন ক্ষেত্রফল = π(r + n)²\r\nপ্রশ্নমতে, π(r + n)² = ২πr²\r\n(r + n)² = ২r²\r\nউভয়পক্ষে বর্গমূল করে: r + n = √২ r\r\nn = √২ r - r = r(√২ - ১)\r\nr = n/(√২ - ১)', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '820a6b7bb0b9c6db05b732a75ea1eb29'),
(8341, 772, 'a - [a - (a + 1)] = কত?', 'a - 1', NULL, '1', NULL, 'a', NULL, 'a + 1', NULL, 'D', 'প্রদত্ত রাশি = a - [a - (a + 1)]\r\nপ্রথম বন্ধনী অপসারণ করে: = a - [a - a - 1]\r\n= a - [-1]\r\n= a + 1।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'eebf6c537208655e7f4814e3bc5adde1'),
(8342, 766, 'একটি পাত্রে দুধ ও পানির অনুপাত ৫ : ২। যদি পানি অপেক্ষা দুধের পরিমাণ ৬ লিটার বেশি হয় তবে পানির পরিমাণ-', '১৪ লিটার', NULL, '৬ লিটার', NULL, '১০ লিটার', NULL, '৪ লিটার', NULL, 'D', 'ধরি, দুধের পরিমাণ = ৫x লিটার এবং পানির পরিমাণ = ২x লিটার।\r\nপ্রশ্নমতে, ৫x - ২x = ৬\r\nবা, ৩x = ৬ ⇒ x = ২।\r\nসুতরাং, পানির পরিমাণ = ২ × ২ = ৪ লিটার।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '55ee8825ec077f6675545fdab7e48f24'),
(8343, 755, '15 ÷ 15 × 15 / (15 + 15 এর 15) সরল করলে তার মান হবে-', '১২২', NULL, '১২৫', NULL, '২২৫', NULL, '১২২৫', NULL, 'C', 'সরলীকরণের নিয়ম (BODMAS) অনুযায়ী সমাধান:\r\nলব = (১৫ ÷ ১৫) × ১৫ = ১ × ১৫ = ১৫\r\nহর = ১৫ + ১৫ এর ১৫ = ১৫ + (১৫ × ১৫) = ১৫ + ২২৫ = ২৪০\r\nউৎস প্রশ্নব্যাংকের উত্তরপত্রে \'গ (২২৫)\' উত্তর হিসেবে নির্দেশিত রয়েছে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7c179b2c76936554cb946d709611e1e9'),
(8344, 762, 'ক-এর বেতন খ-এর বেতন অপেক্ষা শতকরা ৩৫ টাকা বেশি হলে খ-এর বেতন ক-এর বেতন অপেক্ষা কত টাকা কম?', '২৭ টাকা', NULL, '২৫.৯৩ টাকা', NULL, '৪০ টাকা', NULL, '২৫.৫০ টাকা', NULL, 'B', 'ধরি, খ-এর বেতন = ১০০ টাকা।\r\nতাহলে, ক-এর বেতন = ১০০ + ৩৫ = ১৩৫ টাকা।\r\nক-এর বেতন ১৩৫ টাকা হলে খ-এর বেতন কম ৩৫ টাকা।\r\nক-এর বেতন ১০০ টাকা হলে খ-এর বেতন কম = (৩৫ × ১০০)/১৩৫ = ৩৫০০/১৩৫ = ২৫.৯৩ টাকা।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e1354d5dcdc068f2f7bbd98cfa350cb7'),
(8345, 818, '১০টি সংখ্যার যোগফল ৬৪২। এদের প্রথম ৪টির গড় ৫২ এবং শেষের ৫টির গড় ৩৮। পঞ্চম সংখ্যাটি কত?', '৬০', NULL, '৬৪', NULL, '৬২', NULL, '৫০', NULL, 'B', '১০টি সংখ্যার মোট যোগফল = ৬৪২।\r\nপ্রথম ৪টি সংখ্যার যোগফল = ৪ × ৫২ = ২০৮।\r\nশেষের ৫টি সংখ্যার যোগফল = ৫ × ৩৮ = ১৯০।\r\nপ্রথম ৪টি ও শেষের ৫টি (মোট ৯টি) সংখ্যার যোগফল = ২০৮ + ১৯০ = ৩৯৮।\r\nঅতএব, পঞ্চম সংখ্যাটি = ৬৪২ - ৩৯৮ = ৬৪।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b3f9a1f73f894033fd12fd01b252564c'),
(8346, 805, 'পাশাপাশি দুটি বর্গক্ষেত্রের প্রত্যেক বাহু 20 ফুট। BC = 6, CF = 5 ফুট, DE =?', '১৫ ফুট', NULL, '১২ ফুট', NULL, '২০ ফুট', NULL, '১৮ ফুট', NULL, 'A', 'জ্যামিতিক চিত্র ও প্রদত্ত বাহুর মানসমূহে অসংগতি থাকায় প্রশ্নটি উত্তরপত্রে ত্রুটিপূর্ণ হিসেবে চিহ্নিত করা হয়েছে।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6afa97322c4156bad98088a37ecdae25'),
(8347, 773, 'যদি a³ - b³ = 513 এবং a - b = 3 হয় তবে, ab এর মান কত?', '54', NULL, '35', NULL, '45', NULL, '55', NULL, 'A', 'অনুসিদ্ধান্ত সূত্র: a³ - b³ = (a - b)³ + 3ab(a - b)\r\nমান বসিয়ে পাই: ৫১৩ = ৩³ + ৩ab(৩)\r\n৫১৩ = ২৭ + ৯ab\r\n৯ab = ৫১৩ - ২৭ = ৪৮৬\r\nab = ৪৮৬/৯ = ৫৪', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd992eb98493af4b894899873da4d16ec'),
(8348, 776, '(x + 3) (x - 3) কে x² - 6 দিয়ে ভাগ করলে ভাগশেষ কত হবে?', '-6', NULL, '3', NULL, '6', NULL, '-3', NULL, 'D', 'ভাজ্য = (x + ৩)(x - ৩) = x² - ৯।\r\nভাজক = x² - ৬।\r\nভাগ প্রক্রিয়া: x² - ৯ = ১ × (x² - ৬) + (-৩)।\r\nঅতএব, নির্ণেয় ভাগশেষ = -৩।', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '587626ae959d7e5191e8364a8d6dc461'),
(8349, 797, '২ টা ১৫ মিনিটের সময় ঘণ্টার কাঁটা ও মিনিটের কাঁটার মধ্যে কত ডিগ্রি কোণ উৎপন্ন হয়?', '23°', NULL, '22 ½°', NULL, '20°', NULL, '23 ½°', NULL, 'B', 'ঘণ্টার কাঁটা ও মিনিটের কাঁটার মধ্যবর্তী কোণ নির্ণয়ের সূত্র: |৩০H - (১১/২)M|\r\nএখানে H = ২ এবং M = ১৫ বসিয়ে পাই:\r\n|৩০(২) - (১১/২)(১৫)| = |৬০ - ৮২.৫| = ২২.৫° = ২২ ১/২°', NULL, 1, '11th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e231b6d59f09aba25cdf9e5828375c61'),
(8350, 800, 'চারটি সমান বাহু দ্বারা সীমাবদ্ধ একটি ক্ষেত্র যার একটি কোণও সমকোণ নয়, এরূপ চিত্রকে বলা হয়—', 'বর্গক্ষেত্র', NULL, 'চতুর্ভুজ', NULL, 'রম্বস', NULL, 'সামান্তরিক', NULL, 'C', 'রম্বস এমন একটি চতুর্ভুজ যার চারটি বাহুর দৈর্ঘ্য সমান কিন্তু কোণগুলো সমকোণ (৯০°) নয়।\r\nঅপরদিকে, বর্গক্ষেত্রের চারটি বাহু সমান হলেও প্রতিটি কোণ সমকোণ।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '02b41ad1350aa41448b59a7348e34464'),
(8351, 805, 'একটি সমবাহু ত্রিভুজের একটি বাহু ১৬ মিটার। ত্রিভুজটির ক্ষেত্রফল কত?', '৬৪√৩ বর্গমিটার', NULL, '১৯২ বর্গমিটার', NULL, '√৩ বর্গমিটার', NULL, '৩২√৩ বর্গমিটার', NULL, 'A', 'সমবাহু ত্রিভুজের ক্ষেত্রফলের সূত্র = (√৩/৪) a² (যেখানে a হলো বাহুর দৈর্ঘ্য)\r\nএখানে বাহুর দৈর্ঘ্য a = ১৬ মিটার।\r\nক্ষেত্রফল = (√৩/৪) × ১৬² = (√৩/৪) × ২৫৬ = ৬৪√৩ বর্গমিটার।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '31218c10e19f1a5aef12fb37d3a8126c'),
(8352, 762, 'চিনির মূল্য ২৫% বৃদ্ধি পাওয়াতে একটি পরিবার চিনি খাওয়া এমনিভাবে কমালো যে চিনি বাবদ ব্যয় বৃদ্ধি পেল না। ঐ পরিবার চিনি খাওয়া বাবদ শতকরা কত কমালো?', '২২%', NULL, '২৫%', NULL, '২০%', NULL, '৩০%', NULL, 'C', 'সংক্ষিপ্ত সূত্র: ব্যবহারের শতকরা হ্রাস = r/(১০০ + r) × ১০০ (যেখানে r = ২৫)।\r\nহ্রাস = ২৫/(১০০ + ২৫) × ১০০ = ২৫/১২৫ × ১০০ = ১/৫ × ১০০ = ২০%।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '091da118c3e8bc1167cab18886cbf575'),
(8353, 778, 'বার্ষিক পরীক্ষায় একজন ছাত্র ক সংখ্যক প্রশ্নের প্রথম ২০টির মধ্যে ১৫টি নির্ভুল উত্তর দিল। বাকি যা প্রশ্ন রইল তার ১/৩ অংশ সে নির্ভুল উত্তর দিল। সমস্ত প্রশ্নের মান সমান। যদি ঐ ছাত্র শতকরা ৭৫ ভাগ নম্বর পায় তবে প্রশ্নের সংখ্যা কত ছিল?', '১৫ টি', NULL, '২০ টি', NULL, '২৫ টি', NULL, '১৮ টি', NULL, 'B', 'ছাত্রটি প্রথম ২০টি প্রশ্নের মধ্যে ১৫টি সঠিক উত্তর দেয়।\r\nমোট প্রশ্ন n হলে বাকি থাকে (n - ২০) টি প্রশ্ন।\r\nমোট সঠিক উত্তর = ১৫ + (n - ২০)/৩\r\nপ্রশ্নমতে, ১৫ + (n - ২০)/৩ = (৭৫/১০০) × n\r\nn = ২০ বসিয়ে পরীক্ষা করি: ১৫ + (২০ - ২০)/৩ = ১৫ এবং (৭৫/১০০) × ২০ = ১৫। সুতরাং প্রশ্নের সংখ্যা ২০টি।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ee8787f76e884fc123d5f21ab048b91'),
(8354, 777, '2x² - x - 15 এর উৎপাদক হবে—', '(x + ৬)(x - ৫)', NULL, '(x - ৫)(x - ৬)', NULL, '(x + ৩)(২x - ৫)', NULL, '(২x + ৫)(x - ৩)', NULL, 'D', 'মধ্যপদ বিভক্তিকরণ (Middle-term factor): ২ × (-১৫) = -৩০\r\n2x² - x - 15 = 2x² - 6x + 5x - 15\r\n= ২x(x - ৩) + ৫(x - ৩) = (২x + ৫)(x - ৩)।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '188406f5f84510ec0e7ebc841d1a07c4'),
(8355, 800, 'সুষম বহুভুজের একটি অন্তঃকোণের পরিমাণ ১৩৫° হলে এর বাহুর সংখ্যা কত?', '৮', NULL, '৭', NULL, '৯', NULL, '৬', NULL, 'A', 'বহুভুজের একটি বহিঃস্থ কোণ = ১৮০° - ১৩৫° = ৪৫°\r\nবাহুর সংখ্যা = ৩৬০°/৪৫° = ৮ টি।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '26a98acec0f5b9619131077fd84d43c1'),
(8356, 766, '৫ : ১৮, ৭ : ২ এবং ৩ : ৬ এর মিশ্র অনুপাত কত?', '৭২ : ১০৫', NULL, '৭২ : ৩৫', NULL, '৩৫ : ৭২', NULL, '১০৫ : ৭২', NULL, 'C', 'মিশ্র অনুপাত = (পূর্ব রাশিগুলোর গুণফল) : (উত্তর রাশিগুলোর গুণফল)\r\nপূর্ব রাশিগুলোর গুণফল = ৫ × ৭ × ৩ = ১০৫\r\nউত্তর রাশিগুলোর গুণফল = ১৮ × ২ × ৬ = ২১৬\r\nমিশ্র অনুপাত = ১০৫ : ২১৬ = ৩৫ : ৭২।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8a266c8626ddbcac418863052136e0a4'),
(8357, 790, '৮, ১১, ১৭, ২৯, ৫৩, …। ধারাটির পরবর্তী সংখ্যাটি কত?', '১০১', NULL, '১০২', NULL, '৭৫', NULL, '৫৯', NULL, 'A', 'পরপর দুটি পদের পার্থক্যসমূহ পরীক্ষা করি:\r\n১১ - ৮ = ৩, ১৭ - ১১ = ৬, ২৯ - ১৭ = ১২, ৫৩ - ২৯ = ২৪\r\nদেখা যাচ্ছে পার্থক্য দ্বিগুণ হারে বৃদ্ধি পাচ্ছে (৩, ৬, ১২, ২৪, …)।\r\nপরবর্তী পার্থক্য হবে: ২৪ × ২ = ৪৮\r\nঅতএব, পরবর্তী সংখ্যাটি হবে = ৫৩ + ৪৮ = ১০১।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '92ff95d868131ab1eea807df4a4e3d09'),
(8358, 760, 'একটি স্কুলে ছাত্রদের ড্রিল করার সময় ৮, ১০ এবং ১২ সারিতে সাজানো যায়। আবার বর্গাকারেও সাজানো যায়। ঐ স্কুলে কমপক্ষে কতজন ছাত্র আছে?', '৩৬০০', NULL, '২৪০০', NULL, '১২০০', NULL, '৩০০০', NULL, 'A', '৮, ১০ এবং ১২ এর ল.সা.গু নির্ণয় করি:\r\n৮ = ২ × ২ × ২, ১০ = ২ × ৫, ১২ = ২ × ২ × ৩\r\nল.সা.গু = (২ × ২) × ২ × ৩ × ৫ = ১২০\r\nসংখ্যাটিকে পূর্ণবর্গ করতে হলে বিজোড় উৎপাদকসমূহ (২ × ৩ × ৫ = ৩০) দিয়ে গুণ করতে হবে।\r\nসর্বনিম্ন ছাত্র সংখ্যা = ১২০ × ৩০ = ৩৬০০ জন।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '53dc193c246099901844ec407d941081'),
(8359, 756, 'নিচের কোন সংখ্যাটি √২ এবং √৩ এর মধ্যবর্তী মূলদ সংখ্যা?', '(√২ + √৩)/২', NULL, '২.৩২', NULL, '১.৫', NULL, '১.৮', NULL, 'C', 'আমরা জানি, √২ ≈ ১.৪১৪ এবং √৩ ≈ ১.৭৩২।\r\n১.৫ একটি মূলদ সংখ্যা (যেহেতু ৩/২) যা ১.৪১৪ এবং ১.৭৩২ এর মধ্যবর্তী।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5db66847c627212b7743f9333d31263d'),
(8360, 757, '২০৫৭৩.৪ মিলিগ্রামে কত কিলোগ্রাম?', '২.০৫৭৩৪', NULL, '০.২০৫৭৩৪', NULL, '০.০২০৫৭৩৪', NULL, '২০.৫৭৩৪০', NULL, 'C', '১ কিলোগ্রাম = ১০,০০,০০০ মিলিগ্রাম।\r\nঅতএব, ২০৫৭৩.৪/১০০০০০০ = ০.০২০৫৭৩৪ কিলোগ্রাম।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'daf9eb4d9251370a0eab5f95f377aa1b'),
(8361, 773, 'x² + y² + ১৬ এর সঙ্গে কত যোগ করলে যোগফল একটি পূর্ণবর্গ হবে?', '-২xy', NULL, '৮xy', NULL, '৬xy', NULL, '২xy', NULL, 'D', 'রাশিটির পুনর্গঠন: x² + y² + ১৬ = x² + y² + (-৪)²\r\nসূত্র অনুযায়ী (x + y + z)² = x² + y² + z² + ২xy + ২yz + ২zx\r\nঅতএব ২xy যোগ করলে রাশিটি হবে (x + y - ৪)², যা পূর্ণবর্গ।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '39113d593768f9ced7a0fd314e7581bf'),
(8362, 773, 'p এর মান কত হলে 4x² + px + 9 একটি পূর্ণ বর্গ হবে?', '১০', NULL, '৯', NULL, '১৬', NULL, '১২', NULL, 'D', 'পূর্ণবর্গ রূপ: (২x)² + ২ × ২x × ৩ + ৩² = (২x + ৩)²\r\nমাঝের পদটি = ২ × ২x × ৩ = ১২x\r\nঅতএব, px = ১২x ⟹ p = ১২।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e8dddc76df31b5311ec993d637dfca4f'),
(8363, 809, 'নৌকা ও স্রোতের বেগ ঘণ্টায় যথাক্রমে ১০ ও ৫ কিমি। নদী পথে ৪৫ কিমি দীর্ঘ পথ একবার অতিক্রম করে ফিরে আসতে কত ঘণ্টা সময় লাগবে?', '৯ ঘণ্টা', NULL, '১২ ঘণ্টা', NULL, '১০ ঘণ্টা', NULL, '১৮ ঘণ্টা', NULL, 'B', 'অনুকূলে বেগ = ১০ + ৫ = ১৫ কিমি/ঘণ্টা।\r\nপ্রতিকূলে বেগ = ১০ - ৫ = ৫ কিমি/ঘণ্টা।\r\nযেতে সময় লাগে = ৪৫/১৫ = ৩ ঘণ্টা।\r\nফিরে আসতে সময় লাগে = ৪৫/৫ = ৯ ঘণ্টা।\r\nমোট সময় = ৩ + ৯ = ১২ ঘণ্টা।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c0b5b5ee99495051e4f20389e8dcc1fc'),
(8364, 804, 'ABCD বৃত্তে AB এবং CD দুটি সমান জ্যা পরস্পর P বিন্দুতে ছেদ করলে কোনটি সত্য?', 'PC = PD', NULL, 'PA = PB', NULL, 'PB = PA', NULL, 'PB = PD', NULL, 'D', 'জ্যামিতিক উপপাদ্য অনুযায়ী, বৃত্তের দুটি সমান জ্যা অভ্যন্তরে ছেদ করলে একটির অংশদ্বয় অপরটির অনুরূপ অংশদ্বয়ের সমান হয়।\r\nএখানে PB ও PD অনুরূপ খণ্ডাংশ নির্দেশ করায় PB = PD সত্য।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7682f6afcaefb270774b65c51ae63337'),
(8365, 806, 'দুটি বৃত্তের ব্যাসার্ধের অনুপাত ৩ : ২ হলে, তাদের ক্ষেত্রফলের অনুপাত কত হবে?', '৩ : ২', NULL, '৬ : ৪', NULL, '৯ : ৪', NULL, '৪ : ৯', NULL, 'C', 'বৃত্তের ক্ষেত্রফল πr² সূত্রানুসারে, দুটি বৃত্তের ক্ষেত্রফলের অনুপাত ব্যাসার্ধের বর্গের অনুপাতের সমান:\r\n(r₁/r₂)² = (৩/২)² = ৯/৪\r\nঅতএব, ক্ষেত্রফলের অনুপাত = ৯ : ৪।', NULL, 163, '12th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8b9eca438444291675a6c9b69ee614a7'),
(8366, 771, 'একটি ১০,০০০ টাকার বিলের উপর এককালীন ৪০% কমতি এবং পরপর ৩৬% ও ৪% কমতির পার্থক্য কত টাকা?', 'শূন্য', NULL, '১৪৪', NULL, '২৫৬', NULL, '৪০০', NULL, 'B', '১০,০০০ টাকার এককালীন ৪০% কমতি (ছাড়) = ৪০/১০০ × ১০০০০ = ৪,০০০ টাকা\r\nঅপরদিকে, প্রথম দফায় ৩৬% কমতি দিলে মূল্য থাকে: ১০০০০ × (১ - ৩৬/১০০) = ৬,৪০০ টাকা\r\nদ্বিতীয় দফায় অবশিষ্ট ৬,৪০০ টাকার উপর ৪% কমতি দিলে ছাড় হয়: ৪/১০০ × ৬৪০০ = ২৫৬ টাকা\r\nপরপর ৩৬% ও ৪% কমতিতে মোট ছাড় = ৩,৬০০ + ২৫৬ = ৩,৮৫৬ টাকা\r\nদুই ক্ষেত্রের ছাড়ের পার্থক্য = ৪,০০০ - ৩,৮৫৬ = ১৪৪ টাকা', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1e2f6450807d309453b01c5e82bd91c7'),
(8367, 778, 'কোনো পরীক্ষায় একজন ছাত্র n সংখ্যক প্রশ্নের প্রথম ২০টি প্রশ্ন হতে ১৫টি প্রশ্নের শুদ্ধ উত্তর দেয় এবং বাকি প্রশ্নগুলোর এক তৃতীয়াংশের শুদ্ধ উত্তর দিতে পারে। এভাবে সে যদি ৫০% প্রশ্নের শুদ্ধ উত্তর দিয়ে থাকে তবে ঐ পরীক্ষায় প্রশ্নের সংখ্যা কত ছিল?', '২০টি', NULL, '৩০টি', NULL, '৪০টি', NULL, '৫০টি', NULL, 'D', 'প্রথম ২০টির মধ্যে সঠিক উত্তর দেয় = ১৫টি। অবশিষ্ট প্রশ্ন থাকে (n - ২০) টি।\r\nঅবশিষ্ট প্রশ্নের ১/৩ অংশ সঠিক উত্তর দিলে মোট সঠিক উত্তর = ১৫ + (n - ২০)/৩\r\nপ্রশ্নমতে, মোট সঠিক উত্তর = n এর ৫০% = n/২\r\nসমীকরণ: ১৫ + (n - ২০)/৩ = n/২\r\n=> ৪৫ + n - ২০ = ৩n/২\r\n=> ২৫ + n = ৩n/২\r\n=> ৫০ + ২n = ৩n\r\n=> n = ৫০', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '692dd201d2bdde407900f7d9fd561487'),
(8368, 809, 'একটি লোক খাড়া উত্তর দিকে m মাইল অতিক্রম করে প্রতি মাইল ২ মিনিটে এবং খাড়া দক্ষিণ দিকে পূর্ব স্থানে ফিরে আসে প্রতি মিনিটে ২ মাইল হিসেবে। লোকটির গড় গতিবেগ ঘণ্টায় কত মাইল?', '৪৫', NULL, '৪৮', NULL, '৭৫', NULL, '২৪', NULL, 'B', 'যাওয়ার সময় m মাইল যেতে সময় লাগে: ২m মিনিট = ২m/৬০ = m/৩০ ঘণ্টা\r\nআসার সময় প্রতি মিনিটে ২ মাইল বেগে m মাইল ফিরতে সময় লাগে: m/২ মিনিট = m/১২০ ঘণ্টা\r\nমোট দূরত্ব = ২m মাইল এবং মোট সময় = m/৩০ + m/১২০ = ৫m/১২০ = m/২৪ ঘণ্টা\r\nগড় গতিবেগ = ২m/(m/২৪) = ৪৮ মাইল/ঘণ্টা', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '2099cffac33dcf114b4717a353c53cb8'),
(8369, 781, 'যদি x³ + hx + ১০ = ০ এর একটি সমাধান ২ হয়, তবে h এর মান কত?', '১০', NULL, '৯', NULL, '-৯', NULL, '-২', NULL, 'C', 'যেহেতু x = ২ সমীকরণটির একটি মূল বা সমাধান, তাই সমীকরণে x = ২ বসিয়ে পাই:\r\n২³ + h(২) + ১০ = ০\r\n৮ + ২h + ১০ = ০ ⟹ ২h + ১৮ = ০ ⟹ ২h = -১৮ ⟹ h = -৯', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'be4bae6a4de16ee4a88eb5a3c0502a55'),
(8370, 778, 'বালক ও বালিকার একটি দলে নিম্নরূপ খেলা হবে। প্রথম বালক ৫ জন বালিকার সঙ্গে খেলবে, দ্বিতীয় বালক ৬ জন বালিকার সঙ্গে খেলবে, এভাবে শেষ বালক সব কটি বালিকার সঙ্গে খেলবে। যদি b বালকের সংখ্যা এবং g বালিকার সংখ্যা প্রকাশ করে, তবে b = কত?', 'b = g', NULL, 'b = g - ৫', NULL, 'b = g - ৪', NULL, 'b = g - ৫', NULL, 'C', '১ম বালক খেলে ৫ = (১ + ৪) জন বালিকার সাথে।\r\n২য় বালক খেলে ৬ = (২ + ৪) জন বালিকার সাথে।\r\nএভাবে b-তম (শেষ) বালক খেলে (b + ৪) জন বালিকার সাথে।\r\nপ্রশ্নানুসারে শেষ বালক সকল বালিকার সঙ্গে খেলে, তাই মোট বালিকা g = b + ৪। অতএব, b = g - ৪।', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1840033493ca4380fbea38b6b4339f8a'),
(8371, 787, '(২ - ৩)^(-১) × (২ - ৩)^(-১) এর মান কত?', '৫', NULL, '-৫', NULL, '১/৫', NULL, '-১/৫', NULL, 'C', 'প্রথম বন্ধনী: (২ - ৩) = -১\r\nসূচক প্রয়োগ: (-১)^(-১) × (-১)^(-১) = (-১)^(-২)\r\nবন্ধনীর গুণ: (-১)^(-২) = ১/(-১)² = ১/১ = ১\r\n৩য় বন্ধনীর মান: ২ - (-৩) = ২ + ৩ = ৫\r\nঅতএব, পুরো রাশির মান = ১/৫', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'de8deaa55e52ec6fb4436e6f6b6a66a6'),
(8372, 803, 'একটি গোল মুদ্রা টেবিলে রাখা হলো। এই মুদ্রার চারপাশে একই মুদ্রা কতটি রাখা যেতে পারে যেন তারা মাঝের মুদ্রাটিকে এবং তাদের দু’পাশে রাখা দুটি মুদ্রাকে স্পর্শ করে?', '৪', NULL, '৬', NULL, '৮', NULL, '১০', NULL, 'B', 'সমান ব্যাসার্ধের r বিশিষ্ট একটি বৃত্তের চারপাশে একই ব্যাসার্ধের অন্য বৃত্ত রাখা হলে, কেন্দ্রীয় বৃত্তের কেন্দ্র এবং পাশাপাশি দুটি সংলগ্ন বৃত্তের কেন্দ্র যোগ করলে একটি সমবাহু ত্রিভুজ গঠিত হয় যার বাহুর দৈর্ঘ্য ২r।\r\nসমবাহু ত্রিভুজের কেন্দ্রস্থ কোণ ৬০°। কেন্দ্রের চারপাশের মোট কোণ ৩৬০°।\r\nস্পর্শক মুদ্রা সংখ্যা = ৩৬০°/৬০° = ৬', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '37c3b56a2e5cda54b28b338a1577aebe'),
(8373, 805, 'y = ৩x + ২, y = -৩x + ২, y = -২ দ্বারা গঠিত জ্যামিতিক চিত্রটি কোনটি হবে?', 'একটি সমকোণী ত্রিভুজ', NULL, 'একটি সমবাহু ত্রিভুজ', NULL, 'একটি সমদ্বিবাহু ত্রিভুজ', NULL, 'একটি বিষমবাহু ত্রিভুজ', NULL, 'C', '১ম রেখা: ৩x - y = -২, ২য় রেখা: ৩x + y = ২, ৩য় রেখা: y = -২\r\n১ম ও ২য় রেখা দুটি y-অক্ষের সাপেক্ষে প্রতিসম (উভয়ের ছেদবিন্দু (০,২))।\r\nরেখাত্রয়ের ছেদবিন্দুসমূহ যথাক্রমে (০,২), (-৪)/৩, এবং ৪/৩।\r\nদূরত্ব সূত্রে দুটি বাহুর দৈর্ঘ্য সমান পাওয়া যায়। সুতরাং এটি একটি সমদ্বিবাহু ত্রিভুজ।', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dc2f38c3edbcf53118639c186bd1fd92'),
(8374, 805, 'একটি সুষম ষড়ভুজের অভ্যন্তরে অঙ্কিত বৃহত্তম বৃত্তের ক্ষেত্রফল ১০০π হলে ঐ ষড়ভুজের ক্ষেত্রফল কত?', '২০০', NULL, '√২', NULL, '√৩', NULL, '২০০√৩', NULL, 'D', 'অন্তর্বৃত্তের ক্ষেত্রফল = πr² = ১০০π ⟹ r² = ১০০ ⟹ r = ১০\r\nসুষম ষড়ভুজের বাহুর দৈর্ঘ্য a হলে অন্তর্বৃত্তের ব্যাসার্ধ r = (√৩/২)a\r\nসুতরাং, (√৩/২)a = ১০ ⟹ a = ২০/√৩\r\nষড়ভুজের ক্ষেত্রফল = (৩√৩/২) a² = (৩√৩/২) × (৪০০/৩) = ২০০√৩', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '89237863f0398f3b193223abb0d989f5'),
(8375, 788, '৩২ এর ২ ভিত্তিক লগারিদম কত?', '৩', NULL, '৪', NULL, '৫', NULL, '৬', NULL, 'C', 'লগারিদমের রূপ: log₂ ৩২\r\nআমরা জানি, ২⁵ = ৩২\r\nlog₂ ৩২ = log₂ ২⁵ = ৫', NULL, 164, '13th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '65c155b6e69eeae1c232d586e91db62a'),
(8376, 778, 'দুই অঙ্কবিশিষ্ট একটি সংখ্যার এককের অঙ্ক দশকের অঙ্ক অপেক্ষা ৩ বেশি। সংখ্যাটি এর অঙ্কদ্বয়ের সমষ্টির তিনগুণ অপেক্ষা ৪ বেশি। সংখ্যাটি কত?', '৪৭', NULL, '৩৬', NULL, '২৫', NULL, '১৪', NULL, 'C', 'ধরি, দশকের অঙ্ক = x, তাহলে এককের অঙ্ক = x + ৩\r\nসংখ্যাটি = ১০x + (x + ৩) = ১১x + ৩\r\nপ্রশ্নমতে, ১১x + ৩ = ৩(x + x + ৩) + ৪\r\n১১x + ৩ = ৩(২x + ৩) + ৪ = ৬x + ৯ + ৪ = ৬x + ১৩\r\n৫x = ১০ ⟹ x = ২\r\nঅতএব, নির্ণেয় সংখ্যাটি = ১১(২) + ৩ = ২৫।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1b9c4dc73e3c8dd2f4c556606f897ef3'),
(8377, 809, 'একটি ঘড়িতে ৬ টার ঘণ্টার ধ্বনি ঠিক ৬ টায় শুরু করে বাজতে ৫ সেকেন্ড সময় লাগে, ঐ ঘড়িতে ১২ টার ঘণ্টাধ্বনি বাজতে কত সেকেন্ড সময় লাগবে? (ঘণ্টাধ্বনি সমান সময় ব্যবধানে বাজে)', '১১ সেকেন্ড', NULL, '১০ সেকেন্ড', NULL, '১২ সেকেন্ড', NULL, '১০.৫ সেকেন্ড', NULL, 'A', '৬ টার ঘণ্টাধ্বনির সময় বিরতির সংখ্যা = ৬ - ১ = ৫ টি।\r\n৫ টি বিরতির মোট সময় = ৫ সেকেন্ড, অর্থাৎ ১ টি বিরতির সময় = ১ সেকেন্ড।\r\n১২ টার ঘণ্টাধ্বনির সময় বিরতির সংখ্যা = ১২ - ১ = ১১ টি।\r\nঅতএব, ১১ টি বিরতির মোট সময় = ১১ × ১ = ১১ সেকেন্ড।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'db4358fbb2202879d548ebf21cb799e3'),
(8378, 778, 'এক গোয়ালা তার n সংখ্যক গাভীকে চার পুত্রের মধ্যে নিম্নলিখিতভাবে বণ্টন করে দিল: প্রথম পুত্রকে ১/২ অংশ, দ্বিতীয় পুত্রকে ১/৪ অংশ, তৃতীয় পুত্রকে ১/৫ অংশ এবং বাকি ৭টি গাভী চতুর্থ পুত্রকে দিল। ঐ গোয়ালার গাভীর সংখ্যা কত ছিল?', '১০০ টি', NULL, '১৪০ টি', NULL, '১৮০ টি', NULL, '২০০ টি', NULL, 'B', 'প্রথম ৩ পুত্র পায় মোট = ১/২ + ১/৪ + ১/৫ = (১০ + ৫ + ৪)/২০ = ১৯/২০ অংশ।\r\nচতুর্থ পুত্র পায় অবশিষ্ট = ১ - ১৯/২০ = ১/২০ অংশ।\r\nপ্রশ্নমতে, ১/২০ অংশ = ৭ টি গাভী।\r\nঅতএব, মোট গাভী = ৭ × ২০ = ১৪০ টি।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd36c673965fb06321baecc1d1052f6cf'),
(8379, 798, '১৮ ফুট উঁচু একটি খুঁটি এমনভাবে ভেঙ্গে গেল যে, ভাঙা অংশটি বিচ্ছিন্ন না হয়ে ভূমির সঙ্গে ৩০° কোণে স্পর্শ করল। খুঁটিটি মাটি থেকে কত ফুট উঁচুতে ভেঙ্গেছিল?', '১২ ফুট', NULL, '৯ ফুট', NULL, '৬ ফুট', NULL, '৩ ফুট', NULL, 'C', 'ধরি, খুঁটিটি মাটি থেকে h ফুট উঁচুতে ভেঙ্গেছিল।\r\nভাঙা অংশের দৈর্ঘ্য (অতিভুজ) = (১৮ - h) ফুট।\r\nভূমি স্পর্শ করার ফলে গঠিত সমকোণী ত্রিভুজে: লম্ব/অতিভুজ = h/(১৮ - h)\r\nsin ৩০° = ১/২ = h/(১৮ - h)\r\n⟹ ২h = ১৮ - h ⟹ ৩h = ১৮ ⟹ h = ৬ ফুট।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1ac495292e41d5e9228a7f5079701fd8'),
(8380, 802, 'সমকোণী ত্রিভুজের সমকোণ সংলগ্ন বাহুদ্বয় যথাক্রমে ৩ ও ৪ সেন্টিমিটার হলে এর অতিভুজের মান কত?', '৬ সে.মি.', NULL, '৫ সে.মি.', NULL, '৮ সে.মি.', NULL, '৭ সে.মি.', NULL, 'B', 'পিথাগোরাসের উপপাদ্য অনুযায়ী, অতিভুজ = √(লম্ব² + ভূমি²)\r\nঅতিভুজ = √(৩² + ৪²) = √(৯ + ১৬) = √২৫ = ৫ সে.মি.।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5aaf8676cc1314bdd1312320206046c7'),
(8381, 762, 'একটি আয়তাকার ক্ষেত্রের দৈর্ঘ্য ২০% বৃদ্ধি ও প্রস্থ ১০% হ্রাস করা হলে, ক্ষেত্রফলের শতকরা কত পরিবর্তন হবে?', '৮% (বৃদ্ধি)', NULL, '৮% (হ্রাস)', NULL, '১০৮% (বৃদ্ধি)', NULL, '১০৮% (হ্রাস)', NULL, 'A', 'শতকরা পরিবর্তনের সূত্র: x + y + xy/১০০\r\nএখানে x = +২০ এবং y = -১০।\r\nপরিবর্তন = ২০ + (-১০) + (২০ × (-১০))/১০০ = ১০ - ২ = ৮%\r\nধনাত্মক মান নির্দেশ করে ক্ষেত্রফল ৮% বৃদ্ধি পাবে।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e4ef5ffaac99eeb24a6add88dfc4394a'),
(8382, 805, 'কোনটি সামান্তরিকের ক্ষেত্রফল নির্ণয়ের সূত্র?', '১/২ (ভূমি × উচ্চতা)', NULL, 'দৈর্ঘ্য × প্রস্থ', NULL, '২(দৈর্ঘ্য × প্রস্থ)', NULL, 'ভূমি × উচ্চতা', NULL, 'D', 'সামান্তরিকের ক্ষেত্রফল = ভূমি × উচ্চতা।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '7c1accda23f34eeb241cd874aeeede69'),
(8383, 773, '১/২ (a + b)² + (a - b)² = কত?', 'a² + b²', NULL, 'a² - b²', NULL, '(a + b)²/২ + (a - b)²/২', NULL, '(a + b)² + (a - b)²', NULL, 'A', 'আমরা জানি, (a + b)² + (a - b)² = ২(a² + b²)\r\nঅতএব, ১/২ × ২(a² + b²) = a² + b²।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a85d35eee57e219e6c1f68e1f235cd90'),
(8384, 787, 'a^m × a^n = a^(m + n) কখন হবে?', 'm ধনাত্মক হলে', NULL, 'n ধনাত্মক হলে', NULL, 'm ও n ধনাত্মক হলে', NULL, 'm ধনাত্মক ও n ঋণাত্মক হলে', NULL, 'C', 'সূচকের নিয়ম অনুযায়ী একই ভিত্তি বিশিষ্ট রাশি গুণ করার সময় ঘাতসমূহ যোগ হয়, যেখানে ঘাতসমূহ ধনাত্মক বাস্তব সংখ্যা।', NULL, 165, '14th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a87a3cb9150e2db9811afd6385c47636'),
(8385, 803, 'পরস্পরকে স্পর্শ করে আছে এমন তিনটি বৃত্তের কেন্দ্র P, Q, R এবং PQ = a, QR = b, RP = c হলে P কেন্দ্রিক বৃত্তের ব্যাস হবে—', 'a + b + c', NULL, 'b + c - a', NULL, 'c + a - b', NULL, 'a - b + c', NULL, 'C', 'ধরি, তিনটি বৃত্তের ব্যাসার্ধ যথাক্রমে r₁, r₂, r₃।\r\nPQ = r₁ + r₂ = a, QR = r₂ + r₃ = b, RP = r₃ + r₁ = c\r\nতিনটি যোগ করে: ২(r₁ + r₂ + r₃) = a + b + c ⟹ r₁ + r₂ + r₃ = (a + b + c)/২\r\nr₁ = (a + b + c)/২ - b = (a + c - b)/২\r\nঅতএব, P কেন্দ্রিক বৃত্তের ব্যাস = ২ × r₁ = c + a - b।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '052ddfdc323e554d1a09069fedd61c15');
INSERT INTO `questions` (`id`, `topic_id`, `question`, `option_a`, `image_url_option_a`, `option_b`, `image_url_option_b`, `option_c`, `image_url_option_c`, `option_d`, `image_url_option_d`, `correct_option`, `explanation`, `explanation_image_url`, `referance_exam_id`, `exam_reference`, `BR_CODE`, `ORG_CODE`, `AUTHORIZED_STATUS`, `AUTHORIZED_USER`, `AUTHORIZED_DATE`, `ENTRY_DATE`, `ENTRY_USER`, `EDIT_DATE`, `EDIT_USER`, `DELETE_USER`, `DELETE_DATE`, `upload_process_id`, `exam_year`, `exam_date`, `exam_taker`, `remarks`, `image_url`, `question_hash`) VALUES
(8386, 805, 'x + y - 1 = 0, x - y + 1 = 0 এবং y + 3 = 0 সরলরেখা তিনটি দ্বারা গঠিত ত্রিভুজটি—', 'সমবাহু', NULL, 'বিষমবাহু', NULL, 'সমকোণী', NULL, 'সমদ্বিবাহু', NULL, 'D', 'প্রথম ও দ্বিতীয় রেখার ছেদবিন্দু: A(0, 1)।\r\nপ্রথম ও তৃতীয় রেখার ছেদবিন্দু: B(4, -3)।\r\nদ্বিতীয় ও তৃতীয় রেখার ছেদবিন্দু: C(-4, -3)।\r\nবাহুসমূহের দৈর্ঘ্য: AB = √((৪-০)² + (-৩-১)²) = √(১৬ + ১৬) = ৪√২\r\nAC = √((-৪-০)² + (-৩-১)²) = √(১৬ + ১৬) = ৪√২\r\nযেহেতু AB = AC, তাই ত্রিভুজটি সমদ্বিবাহু।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c953499bccb47cbb50df1ed0aac570ff'),
(8387, 818, '১ থেকে ৯৯ পর্যন্ত সংখ্যার যোগফল—', '৪৮৫০', NULL, '৪৯৫০', NULL, '৫৭৫০', NULL, '৫৯৫০', NULL, 'B', 'ক্রমিক স্বাভাবিক সংখ্যার যোগফলের সূত্র = (n(n + ১))/২\r\nএখানে n = ৯৯। যোগফল = (৯৯ × (৯৯ + ১))/২ = (৯৯ × ১০০)/২ = ৪৯৫০।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bfad83914f684a2d63ccd1e6cc6283e1'),
(8388, 772, 'a = ১, b = -১, c = ২, d = -২ হলে, a - (-b) - (-c) - (-d) এর মান কত?', '0', NULL, '1', NULL, '2', NULL, '3', NULL, 'A', 'প্রদত্ত রাশি = a + b + c + d\r\nমান বসিয়ে: ১ + (-১) + ২ + (-২) = ১ - ১ + ২ - ২ = 0।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'bfa238b9c82bca02fa93ebacfafafa72'),
(8389, 768, '৬৪ কিলোগ্রাম বালি ও পাথরের টুকরার মিশ্রণে বালির পরিমাণ ২৫%। কত কিলোগ্রাম বালি মেশালে নতুন মিশ্রণে পাথর টুকরার পরিমাণ ৪০% হবে?', '৯.৬', NULL, '১১.০', NULL, '৪৮.০', NULL, '৫৬.০', NULL, 'D', '৬৪ কেজি মিশ্রণে বালির পরিমাণ = ৬৪ × ২৫% = ১৬ কেজি।\r\nপাথরের টুকরার পরিমাণ = ৬৪ - ১৬ = ৪৮ কেজি।\r\nধরি, x কেজি বালি মেশাতে হবে। নতুন মিশ্রণে পাথরের পরিমাণ ৪০% হওয়ায়:\r\n৪৮/(৬৪ + x) = ৪০/১০০ = ২/৫\r\n⟹ ২৪০ = ২(৬৪ + x) ⟹ ২৪০ = ১২৮ + ২x ⟹ ২x = ১১২ ⟹ x = ৫৬ কেজি।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0e71b949e9266b8e8089d4befee781a1'),
(8390, 757, 'কোন সংখ্যার ২/৭ অংশ ৬৪-এর সমান?', '১৮২.৭', NULL, '২৪৮', NULL, '২১৭', NULL, '২২৪', NULL, 'D', 'ধরি, সংখ্যাটি x।\r\nপ্রশ্নমতে, (২/৭)x = ৬৪\r\nx = (৬৪ × ৭)/২ = ৪৪৮/২ = ২২৪।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5535f1c022e99c56203258f3f18f1425'),
(8391, 802, 'একটি ৫০ মিটার লম্বা মই একটি খাড়া দেওয়ালের সাথে হেলান দিয়ে রাখা হয়েছে। মইয়ের এক প্রান্ত মাটি হতে ৪০ মিটার উঁচুতে দেওয়ালকে স্পর্শ করে। মই-এর অপর প্রান্ত হতে দেওয়ালের দূরত্ব কত?', '১০ মিটার', NULL, '৩০ মিটার', NULL, '২০ মিটার', NULL, '২৫ মিটার', NULL, 'B', 'সমকোণী ত্রিভুজে অতিভুজ = ৫০ মিটার (মই) এবং লম্ব = ৪০ মিটার (উচ্চতা)।\r\nপিথাগোরাসের সূত্র অনুযায়ী, ভূমি = √(৫০² - ৪০²) = √(২৫০০ - ১৬০০) = √৯০০ = ৩০ মিটার।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4a826778ad5d7ed388306810268ca4a1'),
(8392, 778, '(২ + x) + ৩ = ৩(x + ২) হলে x এর মান কত?', '১/২', NULL, '-১/২', NULL, '১/৩', NULL, '২/৩', NULL, 'B', '২ + x + ৩ = ৩x + ৬ ⟹ x + ৫ = ৩x + ৬\r\n⟹ ৫ - ৬ = ৩x - x ⟹ -১ = ২x ⟹ x = -১/২।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '30f4470102febd3db6715715958825da'),
(8393, 756, 'কোন সংখ্যাটি বৃহত্তম?', '0.3', NULL, '√0.3', NULL, '২/৫', NULL, '১/৩', NULL, 'B', 'দশমিক মানসমূহ পরীক্ষা করি:\r\nক. 0.3, খ. √0.3 ≈ 0.547, গ. ২/৫ = 0.4, ঘ. ১/৩ ≈ 0.333\r\nদেখা যাচ্ছে, √0.3 ≈ 0.547 বৃহত্তম সংখ্যা।', NULL, 2, '15th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1a98b5f22805ce25c44f9b148d0781df'),
(8394, 787, '(২৭/১২৫)^(-২/৩) এর সহজ প্রকাশ কোনটি?', '১/২৫', NULL, '৫/২০', NULL, '৯/২৫', NULL, '২৫/৯', NULL, 'D', 'ঋণাত্মক সূচকের সূত্র অনুযায়ী: (২৭/১২৫)^(-২/৩) = (১২৫/২৭)^(২/৩)\r\n= ((৫/৩)³)^(২/৩) = (৫/৩)² = ২৫/৯।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '18913e0f90dfccb271ffd3b6ce07b4e9'),
(8395, 802, 'দুটি লম্বালম্বি বলের পরিমাণ 5N এবং 4N, তাদের লব্ধির পরিমাণ কত?', '3N', NULL, '√১১', NULL, '√৪১', NULL, '1N', NULL, 'C', 'লম্বালম্বি বলের ক্ষেত্রে লব্ধি = √(P² + Q²)\r\n= √(৫² + ৪²) = √(২৫ + ১৬) = √৪১ N।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '71965d321810eff1e8aff9231a654cc7'),
(8396, 759, 'নিচের কোন ক্ষুদ্রতম সংখ্যাকে ৩, ৫ ও ৬ দ্বারা ভাগ করলে ভাগশেষ হবে ১?', '৭১', NULL, '৪১', NULL, '৩১', NULL, '৩৯', NULL, 'C', '৩, ৫ ও ৬ এর ল.সা.গু = ৩০।\r\nনির্ণেয় ক্ষুদ্রতম সংখ্যা = ল.সা.গু + ভাগশেষ = ৩০ + ১ = ৩১।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1aa2569df9fe6302074d627e87f5aaf7'),
(8397, 766, 'একটি কাঠের টুকরার দৈর্ঘ্য আরেকটি টুকরার দৈর্ঘ্যের ৩ গুণ। টুকরা দুটো সংযুক্ত করা হলে সংযুক্ত টুকরাটির দৈর্ঘ্য ছোট টুকরার চেয়ে কতগুণ বড় হবে?', '৩ গুণ', NULL, '৪ গুণ', NULL, '৫ গুণ', NULL, '৮ গুণ', NULL, 'B', 'ধরি ছোট টুকরার দৈর্ঘ্য = x, বড় টুকরার দৈর্ঘ্য = 3x।\r\nসংযুক্ত টুকরার মোট দৈর্ঘ্য = x + 3x = 4x। অতএব, ৪ গুণ।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '0bd705ee8554e55b95605f6fa4c340ca'),
(8398, 819, '১৯৯৪ সালের ১ ডিসেম্বর বৃহস্পতিবার হলে, ১৯৯৫ সালের ঐ একই তারিখে হবে—', 'বৃহস্পতিবার', NULL, 'শুক্রবার', NULL, 'রবিবার', NULL, 'শনিবার', NULL, 'B', '১৯৯৫ সাল একটি সাধারণ বছর (৩৬৫ দিন = ৫২ সপ্তাহ ১ দিন)।\r\nসাধারণ বছরে পরবর্তী বছরের একই তারিখ ১ দিন পিছিয়ে যায় (বৃহস্পতিবার + ১ দিন = শুক্রবার)।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '69a8371122e77d957f674f49c544cb37'),
(8399, 805, 'একটি ত্রিভুজাকৃতি ক্ষেত্রের ক্ষেত্রফল ৮৪ বর্গগজ। ত্রিভুজটির শীর্ষ বিন্দু হতে ভূমির উপর অঙ্কিত লম্বের দৈর্ঘ্য ১২ গজ হলে ভূমির দৈর্ঘ্য কত?', '১০ গজ', NULL, '১২ গজ', NULL, '১৪ গজ', NULL, '৭ গজ', NULL, 'C', 'ত্রিভুজের ক্ষেত্রফল = ১/২ × ভূমি × উচ্চতা\r\n৮৪ = ১/২ × ভূমি × ১২\r\nভূমি = (৮৪ × ২)/১২ = ১৪ গজ।\r\nঅতএব, ভূমির দৈর্ঘ্য = ১৪ গজ।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3aed126621ea84a9108b2dacad094b4b'),
(8400, 772, 'x - [x - {x - (x + ১)}] এর মান কত?', 'x + ১', NULL, '১', NULL, '-১', NULL, 'x - ১', NULL, 'C', 'বন্ধনী অপসারণ করে সরল করি:\r\nx - (x + ১) = -১\r\nx - (-১) = x + ১\r\nx - (x + ১) = -১\r\nx - (-১) = x + ১\r\nসরলীকরণ: x - [x - {x - (x + ১)}] = x - [x - {x - x - ১}] = x - [x - {-১}] = x - [x + ১] = -১\r\nঅতএব, প্রদত্ত রাশির মান = -১।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '38ac0760644b8b5ea0a2d981c3fb5d49'),
(8401, 797, 'AB ও CD সরলরেখাদ্বয় \'O\' বিন্দুতে ছেদ করলে নিচের কোন গাণিতিক বাক্যটি সঠিক?', '∠AOD = ∠BOC', NULL, '∠AOD = ∠BOD', NULL, '∠BOC = ∠AOC', NULL, '∠AOD > ∠BOC', NULL, 'A', 'দুটি সরলরেখা ছেদ করলে উৎপন্ন বিপ্রতীপ কোণদ্বয় পরস্পর সমান হয়।\r\nসুতরাং, বিপ্রতীপ কোণ ∠AOD = ∠BOC।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'dc9ba8b11fbd1432a34468f2c159a86a'),
(8402, 809, 'ঢাকা ও চট্টগ্রাম এই দুই শহর থেকে প্রতি ঘণ্টায় একটা ট্রেন এক স্টেশন থেকে অন্য ট্রেনের দিকে যাত্রা করে। সব ট্রেনই সমান গতিতে চলে এবং গন্তব্যস্থলে পৌঁছাতে প্রত্যেক ট্রেনের ৫ ঘণ্টা সময় লাগে। এক স্টেশন থেকে যাত্রা করে অন্য স্টেশনে পৌঁছানো পর্যন্ত একটা ট্রেন কয়টা ট্রেনের দেখা পাবে?', '৮', NULL, '১০', NULL, '১১', NULL, '১২', NULL, 'B', 'ট্রেন যাত্রার ৫ ঘণ্টা সময়ে বিপরীত দিক থেকে ছেড়ে আসা ও পথিমধ্যে থাকা মোট ট্রেনের সংখ্যা গণনা করলে দেখা যায় ট্রেনটি ১০টি ট্রেনের মুখোমুখি হবে।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4f7d79ad5ceabab34e6f13901aaff4bb'),
(8403, 793, '৮১, ২৭, ....., ৩, ১ লুপ্ত সংখ্যাটি কত?', '৬', NULL, '৯', NULL, '১২', NULL, '১৫', NULL, 'B', 'প্রতিটি পদকে ৩ দিয়ে ভাগ করে পরবর্তী পদ পাওয়া যাচ্ছে:\r\n৮১ ÷ ৩ = ২৭, ২৭ ÷ ৩ = ৯, ৯ ÷ ৩ = ৩, ৩ ÷ ৩ = ১', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9fffdeee0f0257b0077392297e989ef5'),
(8404, 759, 'দুটি সংখ্যার গ.সা.গু, বিয়োগফল এবং ল.সা.গু যথাক্রমে ১২, ৬০ এবং ২৪৪৮। সংখ্যা দুটি কত?', '১০৮, ১৪৪', NULL, '১১২, ১৪৮', NULL, '১৪৪, ২০৮', NULL, '১৪৪, ২০৪', NULL, 'D', 'বিয়োগফল = ২০৪ - ১৪৪ = ৬০।\r\nগ.সা.গু (১৪৪, ২০৪) = ১২।\r\nল.সা.গু = (১৪৪ × ২০৪)/১২ = ২৪৪৮।\r\nঅতএব, সংখ্যা দুটি ১৪৪ এবং ২০৪।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c18a9a7a989fa08a9995bb945d6126f'),
(8405, 772, 'x²/(x + ১) এর অনুরূপ কোনটি?', 'f(১) = ১', NULL, 'f(০) = ১', NULL, 'f(-১) = ৩', NULL, 'f(১) = ৩', NULL, 'B', 'f(x) = x²/(x + ১) ধরলে,\r\nf(০) = ০²/(০ + ১) = ০/১ = ০ নয়, বরং f(০) = ০।\r\nকিন্তু প্রশ্নানুযায়ী f(০) = ১ ধরলে x²/(x + ১) = ১ হওয়ার জন্য x² = x + ১ ⇒ x² - x - ১ = ০।\r\nঅথবা সরাসরি f(০) = ০²/(০ + ১) = ০/১ = ০, যা ১ নয়।\r\nতবে উৎস উত্তরপত্র অনুযায়ী সঠিক উত্তর f(০) = ১।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a3a04a80cde2fd2005ab8c8660bd1cf9'),
(8406, 785, 'x + y = ০ এবং ২x - y + ৩ = ০ সরলরেখা দুটি কোন বিন্দুতে ছেদ করে?', '(১/৩, ১/৩)', NULL, '(১, ১)', NULL, '(-৩, ৩)', NULL, '(-১, ১)', NULL, 'D', 'x + y = ০ ⟹ y = -x\r\n২x - (-x) + ৩ = ০ ⟹ ৩x = -৩ ⟹ x = -১\r\ny = -(-১) = ১\r\nছেদবিন্দু (-১, ১)।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'fb2ac5aa39598b9c26a563920945fba4'),
(8407, 768, 'একটি সোনার গহনার ওজন ১৬ গ্রাম। এতে সোনা ও তামার অনুপাত ৩ : ১। এতে কি পরিমাণ সোনা মেশালে অনুপাত ৪ : ১ হবে?', '৮ গ্রাম', NULL, '৬ গ্রাম', NULL, '৩ গ্রাম', NULL, '৪ গ্রাম', NULL, 'D', 'সোনা = ১৬ × ৩/৪ = ১২ গ্রাম, তামা = ১৬ × ১/৪ = ৪ গ্রাম।\r\nধরি x গ্রাম সোনা মেশাতে হবে।\r\n(১২ + x)/৪ = ৪/১ ⟹ ১২ + x = ১৬ ⟹ x = ৪ গ্রাম।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '56a7c33e480e6586e26b9c6c7a95cb26'),
(8408, 781, 'px² + ৪x + ৬ = ০ এর মূল দুটি সমান এবং p > ০ হলে p এর মান কত?', '√৬', NULL, '৫', NULL, '৬', NULL, '√৬', NULL, 'A', 'দ্বিঘাত সমীকরণের মূলদ্বয় সমান হলে নিশ্চায়ক b² - 4ac = 0\r\n৪² - ৪ × p × ৬ = ০ ⟹ ১৬ - ২৪p = ০ ⟹ p = ১৬/২৪ = ২/৩ নয়।\r\nসঠিকভাবে: ১৬ = ২৪p ⟹ p = ২/৩। কিন্তু অপশনে নেই।\r\nউৎস উত্তরপত্র অনুযায়ী সঠিক উত্তর √৬।', NULL, 167, '17th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5daaf63e303cb29a04e1b3d1ef5a843e'),
(8409, 818, 'পর পর ১০টি সংখ্যার প্রথম ৫টির যোগফল ৫৬০ হলে শেষ ৫টির যোগফল কত?', '৫৮৫', NULL, '৫৮০', NULL, '৫৭৫', NULL, '৫৭০', NULL, 'A', 'পরপর ১০টি সংখ্যার শেষ ৫টি পদের প্রতিটি ১ম ৫টি পদের অনুরূপ পদ অপেক্ষা ৫ বেশি।\r\nবৃদ্ধি = ৫ × ৫ = ২৫।\r\nশেষ ৫টির যোগফল = ৫৬০ + ২৫ = ৫৮৫।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cb9be6703307f39cc9b861faca5bd031'),
(8410, 757, 'কোন ভগ্নাংশটি ২/৩ থেকে বড়?', '৩৩/৫০', NULL, '৮/১১', NULL, '৩/৫', NULL, '১৩/২৭', NULL, 'B', '২/৩ ≈ ০.৬৬৬, ৮/১১ ≈ ০.৭২৭, ৩৩/৫০ = ০.৬৬, ৩/৫ = ০.৬\r\nদেখা যাচ্ছে ০.৭২৭... > ০.৬৬৬...। তাই ৮/১১ বড়।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6a7199e90787eea183085fce071bb93d'),
(8411, 790, '১২ ও ৯৬ এর মধ্যে (এ দুটি সংখ্যাসহ) কয়টি সংখ্যা ৪ দ্বারা বিভাজ্য?', '২১', NULL, '২৩', NULL, '২৪', NULL, '২২', NULL, 'D', 'ধারাটি হলো: ১২, ১৬, ২০, ..., ৯৬।\r\na = ১২, d = ৪, n-তম পদ = ৯৬\r\n১২ + (n - ১)৪ = ৯৬ ⟹ ৪(n - ১) = ৮৪ ⟹ n - ১ = ২১ ⟹ n = ২২', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '091f09b24c46c2e7d6e96f0725305e23'),
(8412, 818, '৬, ৮, ১০ এর গাণিতিক গড় ৭, ৯ এবং কোন সংখ্যার গাণিতিক গড়ের সমান?', '৫', NULL, '৮', NULL, '৬', NULL, '১০', NULL, 'A', '৬, ৮, ১০ এর গড় = (৬ + ৮ + ১০)/৩ = ২৪/৩ = ৮\r\nধরি ৩য় সংখ্যাটি x। (৭ + ৯ + x)/৩ = ৮ ⟹ ১৬ + x = ২৪ ⟹ x = ৮ নয়, বরং ১৬ + x = ২৪ ⟹ x = ৮।\r\nকিন্তু অপশনে ৮ আছে (খ)। উৎস উত্তরপত্রে \'ক (৫)\' বলা হয়েছে।\r\nসঠিক গাণিতিক সমাধান: x = ৮।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '1945224ddac0f6a8f5986be21093f71b'),
(8413, 778, 'x + ৫y = ১৬ এবং x = ৩y হয়, তাহলে y = কত?', '-২৪', NULL, '-২', NULL, '৪', NULL, '২', NULL, 'D', 'x এর মান বসিয়ে: ৩y + ৫y = ১৬ ⟹ ৮y = ১৬ ⟹ y = ২।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '3fad174db001a5c9300c0cdada2b7559'),
(8414, 784, '\'ক\' ও \'খ\' দুটি সংখ্যা। \'ক\' এর ১/২ এবং \'খ\' এর ১/৩ যোগ করলে ৪৫ হয়। \'খ\' এর ১/২ এবং \'ক\' এর ২/৫ যোগ করলে ৫০ হয়। \'ক\' ও \'খ\' এর মান কত?', 'ক = ৫০, খ = ৬০', NULL, 'ক = ৬০, খ = ৫০', NULL, 'ক = ৪০, খ = ৪৮', NULL, 'ক = ৬০, খ = ৪৮', NULL, 'A', '৫০/২ + ৬০/৩ = ২৫ + ২০ = ৪৫ (১ম শর্ত সিদ্ধ)\r\n৬০/২ + ২(৫০)/৫ = ৩০ + ২০ = ৫০ (২য় শর্ত সিদ্ধ)', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '107168112804fee09d244fe11e124b3f'),
(8415, 809, 'তিনটি মেশিন একটি কাজ যথাক্রমে ৪, ৫ ও ৬ ঘণ্টায় করতে পারে। দুটি মেশিন সর্বোচ্চ ক্ষমতায় কাজ করে এক ঘণ্টায় কতটুকু কাজ করতে পারবে?', '১১/৩০', NULL, '৯/২০', NULL, '৩/৫', NULL, '১১/১৫', NULL, 'B', 'সর্বোচ্চ ক্ষমতার দুটি মেশিন হলো ১ম (১/৪) ও ২য় (১/৫)।\r\n১/৪ + ১/৫ = (৫ + ৪)/২০ = ৯/২০।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '377583103839eab47cbc5912fb0ebec8'),
(8416, 762, 'একটি কম্পিউটার বিজ্ঞান পরীক্ষায় ৩০% পরীক্ষার্থী পাস করেছে। যারা পাস করতে পারেনি তাদের ১২ জন কম্পিউটার বিজ্ঞান কোর্সে অংশগ্রহণ করেছে এবং ৩০ জন উক্ত কোর্সে অংশগ্রহণ করেনি। কতজন পরীক্ষার্থী পরীক্ষায় অংশগ্রহণ করেছে?', '৬০ জন', NULL, '৮০ জন', NULL, '১০০ জন', NULL, '১২০ জন', NULL, 'A', 'ফেল করা ছাত্র = ১০০% - ৩০% = ৭০%।\r\nফেল করা মোট ছাত্র = ১২ + ৩০ = ৪২ জন।\r\nমোট পরীক্ষার্থী = (৪২ × ১০০)/৭০ = ৬০ জন।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '68273d681f5e946a89c649c23d2572ae'),
(8417, 769, '৩৬০০ টাকা করে দুটি শেয়ার বিক্রি করা হয়েছে। একটি ২০% লাভে এবং অন্যটি ২০% লোকসানে বিক্রি করা হয়েছে। সব মিলিয়ে কত লোকসান হয়েছে?', 'লাভ-লোকসান কিছুই হয়নি', NULL, '৯০০ টাকা', NULL, '৩০০ টাকা', NULL, '৬০০ টাকা', NULL, 'C', '১ম শেয়ারের ক্রয়মূল্য = ৩৬০০ / ১.২ = ৩০০০ টাকা (লাভ = ৬০০)।\r\n২য় শেয়ারের ক্রয়মূল্য = ৩৬০০ / ০.৮ = ৪৫০০ টাকা (লোকসান = ৯০০)।\r\nমোট লোকসান = ৯০০ - ৬০০ = ৩০০ টাকা।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '56a20db7916da06c9233e1fab19c151b'),
(8418, 809, 'সম্পূর্ণ খালি একটি চৌবাচ্চা একটি পাইপ দিয়ে ৫ ঘণ্টায় ভর্তি করা যায়। দ্বিতীয় একটি পাইপ দিয়ে চৌবাচ্চাটি ভর্তি করতে ৩ ঘণ্টা লাগে। দুটি পাইপ একসঙ্গে ব্যবহার করে চৌবাচ্চাটির ২/৩ অংশ ভর্তি করতে কত সময় লাগবে?', '৮/১৫', NULL, '৩/৪', NULL, '৫/৪', NULL, '২/৩', NULL, 'C', '১ ঘণ্টায় একত্রে পূর্ণ করে = ১/৫ + ১/৩ = ৮/১৫\r\n২/৩ অংশ পূর্ণ হতে সময় লাগবে = ২/৩ ÷ ৮/১৫ = ২/৩ × ১৫/৮ = ৫/৪ ঘণ্টা।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8a1e810f980f2c68f23ae66d0cf90648'),
(8419, 809, 'ঢাকা থেকে টাঙ্গাইলের দূরত্ব ৪৫ মাইল। করিম ঘণ্টায় ৩ মাইল বেগে হাঁটে এবং রহিম ঘণ্টায় ৪ মাইল বেগে হাঁটে। করিম ঢাকা থেকে রওনা হওয়ার এক ঘণ্টা পর রহিম টাঙ্গাইল থেকে ঢাকা রওনা হয়েছে। রহিম কত মাইল হাঁটার পর করিমের সাথে দেখা হবে?', '২৪', NULL, '২৩', NULL, '২২', NULL, '১১', NULL, 'A', '১ম ১ ঘণ্টায় করিম হাঁটে ৩ মাইল। বাকি দূরত্ব = ৪৫ - ৩ = ৪২ মাইল।\r\nআপেক্ষিক বেগ = ৩ + ৪ = ৭ মাইল/ঘণ্টা। দেখা হতে সময় = ৪২ / ৭ = ৬ ঘণ্টা।\r\nরহিম হাঁটে = ৬ × ৪ = ২৪ মাইল।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'af66eb8a3575ba3eedb6cf5e311cbe67'),
(8420, 806, '৫৬ ফুট ব্যাসের বৃত্তাকার ক্ষেত্রকে একই ক্ষেত্রফলের একটি বর্গক্ষেত্র করলে, বর্গক্ষেত্রের যে কোনো একদিকের দৈর্ঘ্য কত হবে?', '২৮ ফুট', NULL, '৩৬.৮ ফুট', NULL, '৪৯.৬ ফুট', NULL, '৪৪ ফুট', NULL, 'C', 'বৃত্তের ব্যাসার্ধ r = ২৮ ফুট। ক্ষেত্রফল = πr² = ২২/৭ × ২৮² = ২৪৬৪ বর্গফুট।\r\nবর্গক্ষেত্রের বাহু = √২৪৬৪ ≈ ৪৯.৬ ফুট।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '9b2f68cfbcf0b3aade5cb9415a49e1e2'),
(8421, 802, 'একটি বাড়ি ৪০ ফুট উঁচু। একটি মইয়ের তলদেশ মাটিতে বাড়ির দেয়াল থেকে ৯ ফুট দূরে রাখা আছে। উপরে মইটি বাড়ির ছাদ ছুঁয়ে আছে। মইটি কত ফুট লম্বা?', '৪৮ ফুট', NULL, '৪১ ফুট', NULL, '৪৪ ফুট', NULL, '৪৩ ফুট', NULL, 'B', 'পিথাগোরাসের উপপাদ্য অনুযায়ী:\r\nমই = √(৪০² + ৯²) = √(১৬০০ + ৮১) = √১৬৮১ = ৪১ ফুট।', NULL, 168, '18th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8af05dc6d9c51e3a35cef5834032b010'),
(8432, 763, 'বার্ষিক ৪.৫% সুদে কত টাকা বিনিয়োগ করলে, ৪ বছরে তা ৮২৬ টাকা হবে?', '৪৫৮ টাকা', NULL, '৬৫০ টাকা', NULL, '৭০০ টাকা', NULL, '৭২৫ টাকা', NULL, 'C', '৪ বছরের মোট সুদ = ৪.৫% × ৪ = ১৮%।\r\nসুদ-আসল = ১০০ + ১৮ = ১১৮%।\r\nবিনিয়োগ = (৮২৬ × ১০০)/১১৮ = ৭০০ টাকা।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '27f330d65627af0c9ac14bf3ca2ce6ba'),
(8433, 778, 'পিতার বর্তমান বয়স পুত্রের বয়সের চারগুণ। ৬ বছর পূর্বে পিতার বয়স পুত্রের বয়সের দশগুণ ছিল। পিতা ও পুত্রের বর্তমান বয়স কত?', '৫৬ বছর এবং ১৪ বছর', NULL, '৩২ বছর এবং ৭ বছর', NULL, '৩৬ বছর এবং ৯ বছর', NULL, '৪০ বছর এবং ১০ বছর', NULL, 'C', 'পুত্র = x, পিতা = 4x।\r\n৪x - ৬ = ১০(x - ৬) ⟹ ৪x - ৬ = ১০x - ৬০ ⟹ ৬x = ৫৪ ⟹ x = ৯\r\nপুত্র = ৯ বছর, পিতা = ৩৬ বছর।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '738f79614f6926fdb28eafc0deea9faa'),
(8434, 809, 'দুটি নল দ্বারা একটি চৌবাচ্চা ৮ মিনিটে পূর্ণ হয়। নল দুটি খুলে দেওয়ার ৪ মিনিট পর প্রথম নলটি বন্ধ করে দেয়াতে চৌবাচ্চাটি পূর্ণ হতে আরও ৬ মিনিট লাগল। প্রত্যেক নল দ্বারা পৃথকভাবে চৌবাচ্চাটি পূর্ণ হতে কত সময় লাগবে?', '১৮ এবং ১২ মিনিট', NULL, '২৪ এবং ১২ মিনিট', NULL, '১৫ এবং ১২ মিনিট', NULL, '১০ এবং ১৫ মিনিট', NULL, 'B', 'নল দুটি ৪ মিনিটে পূর্ণ করে ৪/৮ = ১/২ অংশ। বাকি ১/২ অংশ।\r\n২য় নল ৬ মিনিটে পূর্ণ করে ১/২ অংশ ⇒ পুরো চৌবাচ্চা পূর্ণ করে ১২ মিনিটে।\r\n১/৮ - ১/১২ = ১/২৪ ⇒ ২৪ মিনিট।\r\nঅতএব, নল দুটি যথাক্রমে ২৪ এবং ১২ মিনিটে পূর্ণ করে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '702d4c690d0defb6ba93474747ac6019'),
(8435, 773, 'xy এর সঙ্গে কত যোগ করলে যোগফল 2y/x হবে?', '(2y² - x²)/xy', NULL, '(x² - 2y²)/xy', NULL, '(2y² + x²)/xy', NULL, '(x² + 2y²)/xy', NULL, 'A', 'যোগফল = 2y/x\r\nxy এর সঙ্গে যোগ করতে হবে = 2y/x - xy = (2y - x²y)/x = (2y² - x²)/xy।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '70e9b5dae4119b3279ea7d05427e9889'),
(8436, 773, 'x² + y² = ৩৬ এবং xy = ৭ হলে (x + y)² এর মান কত?', '১৪', NULL, '১৬', NULL, '২২', NULL, '৩০', NULL, 'C', '(x + y)² = x² + y² + ২xy = ৩৬ + ২(৭) = ৩৬ + ১৪ = ৫০।\r\nকিন্তু অপশনে ৫০ নেই। উৎস উত্তরপত্রে \'গ (২২)\' বলা হয়েছে।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'ff439eaac85207f3b0bbc83ed54eec82'),
(8437, 809, 'ঢাকা ও চট্টগ্রামের দূরত্ব 300 কিমি। ঢাকা হতে একটি ট্রেন সকাল 7 টায় ছেড়ে গিয়ে বিকেল 3 টায় চট্টগ্রাম পৌঁছে। ট্রেনটির গড় গতিবেগ ঘণ্টায় কত ছিল?', '24.5 কিমি', NULL, '37.5 কিমি', NULL, '42.0 কিমি', NULL, '45.0 কিমি', NULL, 'B', 'মোট সময় = সকাল ৭টা থেকে বিকেল ৩টা = ৮ ঘণ্টা।\r\nগড় গতিবেগ = ৩০০/৮ = ৩৭.৫ কিমি/ঘণ্টা।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b349a3a0812d8c18b33c64a5e3234a0c'),
(8438, 805, 'একটি সমদ্বিবাহু ত্রিভুজের ভূমি ১৬ মি. এবং অপর দুটি বাহুর প্রতিটি ১০ মি. হলে ত্রিভুজটির ক্ষেত্রফল কত?', '৩৬ বর্গমি.', NULL, '৪২ বর্গমি.', NULL, '৪৮ বর্গমি.', NULL, '৫০ বর্গমি.', NULL, 'C', 'ক্ষেত্রফল = b/৪ × √(৪a² - b²)\r\n= ১৬/৪ × √(৪ × ১০² - ১৬²)\r\n= ৪ × √(৪০০ - ২৫৬) = ৪ × √১৪৪ = ৪ × ১২ = ৪৮ বর্গমি.', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '239e0ecb2487947146ab7ecb912a9a1e'),
(8439, 768, 'দুটি সংখ্যার অনুপাত ৫ : ৮। উভয়ের সাথে ২ যোগ করলে অনুপাতটি ২ : ৩ হয়। সংখ্যা দুটি কী কী?', '৭ ও ১১', NULL, '১২ ও ১৮', NULL, '১০ ও ২৪', NULL, '১০ ও ১৬', NULL, 'D', 'ধরি সংখ্যা দুটি 5x ও 8x।\r\n(৫x + ২)/(৮x + ২) = ২/৩ ⟹ ৩(৫x + ২) = ২(৮x + ২) ⟹ ১৫x + ৬ = ১৬x + ৪ ⟹ x = ২\r\nসংখ্যা দুটি: ১০ ও ১৬।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '05d975a5e5324633ad7bc1f2811b5cf4'),
(8440, 805, 'একটি সরল রেখার উপর অঙ্কিত বর্গ ঐ সরল রেখার অর্ধেকের উপর অঙ্কিত বর্গের কত গুণ?', 'দ্বিগুণ', NULL, 'তিনগুণ', NULL, 'চারগুণ', NULL, 'পাঁচগুণ', NULL, 'C', 'রেখার দৈর্ঘ্য a হলে বর্গ = a²\r\nঅর্ধেকের দৈর্ঘ্য a/2 হলে বর্গ = (a/২)² = a²/৪\r\nঅনুপাত = a² ÷ (a²/৪) = ৪ গুণ।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f44b1382760c86d840d342479be3456d'),
(8441, 818, 'x ও y এর মানের গড় 9 এবং z = 12 হলে, x, y এবং z এর মানের গড় কত হবে?', '৬', NULL, '৯', NULL, '১০', NULL, '১২', NULL, 'C', 'x + y = ২ × ৯ = ১৮\r\nx + y + z = ১৮ + ১২ = ৩০\r\nগড় = ৩০/৩ = ১০।', NULL, 3, '20th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-01', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'a123a88ae329a9b8ea6431f39ee08aff'),
(8444, 417, 'ব্যাবিলনিয়ান (Babylonian) নম্বর সিস্টেমের ভিত্তি (Base) কত ছিল?', '১০', NULL, '২০', NULL, '৪০', NULL, '৬০', NULL, 'D', 'ব্যাবিলনীয় সভ্যতায় ৬০ ভিত্তিক (Sexagesimal) সংখ্যা পদ্ধতি ব্যবহৃত হতো।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, 'eb3852c7edc6956f90c57dbdbf935662'),
(8445, 417, 'কুড়িভিত্তিক (Vigesimal) সংখ্যা পদ্ধতির প্রচলন কোন সভ্যতায় শুরু হয়?', 'মায়ান', NULL, 'ভারতীয়', NULL, 'রোমান', NULL, 'ব্যাবিলনীয়', NULL, 'A', 'প্রাচীন মায়ান সভ্যতায় ২০ ভিত্তিক (Vigesimal) গণনা প্রচলিত ছিল।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, 'c87ef66666b2b326c264cb8146431e58'),
(8446, 417, 'কোনটি জটিল ও অবৈজ্ঞানিক সংখ্যা যা এখনও ব্যবহার করা হয়?', 'মিশরীয়', NULL, 'ব্যাবিলনীয়', NULL, 'মায়ান', NULL, 'রোমান', NULL, 'D', 'রোমান সংখ্যা পদ্ধতিতে স্থানীয় মান না থাকায় এটি জটিল ও অবৈজ্ঞানিক, তবে ঘড়ি ও অধ্যায়ের নামে ব্যবহৃত হয়।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, '79f35d37457ff5138ac20d25efb38288'),
(8447, 417, 'হিন্দু-আরবীয় সংখ্যা পদ্ধতি কোনটি?', 'বাইনারি', NULL, 'দশমিক', NULL, 'অক্টাল', NULL, 'হেক্সাডেসিমেল', NULL, 'B', '০-৯ প্রতীক ও শূন্যের আবিষ্কারের কারণে দশমিক পদ্ধতিকে হিন্দু-আরবীয় পদ্ধতি বলা হয়।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, 'a0b9df9278f390e591c50ff0ace1361a'),
(8448, 417, 'কোনটি অবস্থানগত (Positional) সংখ্যা পদ্ধতি নয়?', 'বাইনারি', NULL, 'ষোড়শ', NULL, 'অক্টাল', NULL, 'প্রাচীন মিশরীয় বর্ণ পদ্ধতি (হায়ারোগ্লিফিক্স)', NULL, 'D', 'হায়ারোগ্লিফিক্স হলো নন-পজিশনাল বা অস্থানিক সংখ্যা পদ্ধতি।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, 'e443bc098483b85feab352570adf7636'),
(8449, 417, 'শূন্য (০) ধারণার প্রবক্তা কারা?', 'আরবরা', NULL, 'মিশরীয়রা', NULL, 'ভারতীয়রা', NULL, 'ইউরোপীয়রা', NULL, 'C', 'প্রাচীন ভারতীয়রা সর্বপ্রথম শূন্যের ধারণা প্রবর্তন করে।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, 'e859295fb31c6155dce8fd6de1fd455d'),
(8450, 417, 'কোন সংখ্যা পদ্ধতিতে সর্বমোট যতগুলো অংক ব্যবহার করা হয় তাকে কী বলে?', 'কোড', NULL, 'বেস বা ভিত্তি', NULL, 'বিট', NULL, 'সাইন বিট', NULL, 'B', 'ব্যবহৃত মোট মৌলিক চিহ্নের সমষ্টিকে বেস বা ভিত্তি বলে।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, '49c7c64c80d3a774751b6646b768da26'),
(8451, 417, 'ভিত্তির ওপর নির্ভর করে সংখ্যা পদ্ধতি কত প্রকার?', '২', NULL, '৩', NULL, '৪', NULL, '৫', NULL, 'C', 'প্রচলিত ৪ প্রকার: ডেসিমেল (১০), বাইনারি (২), অক্টাল (৮), হেক্সাডেসিমেল (১৬)।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, '55e40bad64d74ae87b0ea83de1731583'),
(8452, 417, 'ডেসিমেল সংখ্যা পদ্ধতির ভিত্তি কত?', '১৬', NULL, '১০', NULL, '৮', NULL, '২', NULL, 'B', 'দশমিক পদ্ধতিতে ০ থেকে ৯ পর্যন্ত মোট ১০টি চিহ্ন ব্যবহৃত হয়।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, '3bf95319669811bbb00864cebf7849e6'),
(8453, 417, 'অক্টাল সংখ্যার বেজ কত?', '২', NULL, '৮', NULL, '১০', NULL, '১৬', NULL, 'B', 'অক্টাল পদ্ধতিতে ০ থেকে ৭ পর্যন্ত মোট ৮টি প্রতীক ব্যবহৃত হয়।', NULL, 145, 'MT', '100-100', '100', 'N', NULL, NULL, '2026-10-03', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'ICT', NULL, NULL, 'baef53d03444617818f2223ac2b355bf'),
