(8905, 869, 'একটি প্রতিষ্ঠানের ৪০% কর্মচারী আন্ডারগ্রাজুয়েট, অবশিষ্ট কর্মচারীদের ৫০% গ্রাজুয়েট এবং অবশিষ্ট ১৮০ জন পোস্টগ্রাজুয়েট। প্রতিষ্ঠানটির কতজন কর্মচারী গ্রাজুয়েট?', '১৮০', NULL, '২৪০', NULL, '৩০০', NULL, '৩৬০', NULL, 'A', 'মোট = ১০০%। ৪০% আন্ডারগ্রাজুয়েট → অবশিষ্ট ৬০%। এর ৫০% গ্রাজুয়েট = ৩০%, বাকি ৩০% পোস্টগ্রাজুয়েট = ১৮০ জন। অর্থাৎ ৩০% = ১৮০ → গ্রাজুয়েটও ৩০% = ১৮০ জন।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '5608a2e8dae091d228be5589b1716bfb'),
(8906, 831, 'যদি ROSE কে লেখা হয় 6821, CHAIR কে লেখা হয় 73456 এবং PREACH কে লেখা হয় 961473, তাহলে SEARCH এর কোড কত?', '246173', NULL, '214673', NULL, '214763', NULL, '216473', NULL, 'B', 'ROSE = 6821 → R=6, O=8, S=2, E=1। CHAIR = 73456 → C=7, H=3, A=4, I=5। PREACH = 961473 → P=9, R=6, E=1, A=4, C=7, H=3 (যাচাই)। SEARCH = S(2), E(1), A(4), R(6), C(7), H(3) = 214673।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '4a5d692853c75ce3199624c79e7051f3'),
