(8908, 828, '‘ঙ, ঞ, ণ, ...’ ধারার পরবর্তী অক্ষর কী হবে?', 'ঠ', NULL, 'ম', NULL, 'ন', NULL, 'র', NULL, 'C', 'বাংলা ব্যঞ্জনবর্ণের ক্রম: ঙ (৫ম), ঞ (১০ম), ণ (১৫ম) → অর্থাৎ প্রতি ধাপে ৫টি করে এগোচ্ছে। পরবর্তী = ২০তম বর্ণ = ন।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b9ad76c8df742c36fe2a742a1c34f998'),
(8909, 869, '\'A\' \'B\' এর চেয়ে দ্বিগুণ কাজ করতে পারে; তারা দু’জন একত্রে একটি কাজ ১৪ দিনে শেষ করতে পারে। \'A\' একা কাজটি কতদিনে করতে পারবে?', '১২ দিনে', NULL, '২৪ দিনে', NULL, '২১ দিনে', NULL, '১৫ দিনে', NULL, 'C', 'ধরি B একা x দিনে করে, A একা x/২ দিনে করে। একত্রে: ১/x + ২/x = ১/১৪ → ৩/x = ১/১৪ → x = ৪২। A = ৪২/২ = ২১ দিন।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'cbc65df79baae531f3f5e3c35ffad9db'),
(8910, 828, 'নিচের কোন শব্দটি ভিন্ন ধরনের?', 'চাঁদ', NULL, 'প্লুটো', NULL, 'মঙ্গল', NULL, 'পৃথিবী', NULL, 'A', 'প্লুটো, মঙ্গল ও পৃথিবী গ্রহ; চাঁদ উপগ্রহ। ২০০৬ সালে প্লুটো গ্রহের মর্যাদা হারালেও প্রশ্নানুযায়ী ভিন্ন শব্দ চাঁদ।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '217b5a4a65e593282b899d9c4cf1fa5f'),
(8911, 823, '\'DRIVE is to LICENCE as BREATHE is to __.\' এই বক্তব্যের শূন্যস্থানে কোন বিকল্পটি বসবে?', 'OXYGEN', NULL, 'ATMOSPHERE', NULL, 'WINDPIPE', NULL, 'INHALE', NULL, 'A', 'গাড়ি চালানোর জন্য যেমন লাইসেন্স প্রয়োজন, তেমনি শ্বাস নেওয়ার জন্য অক্সিজেন প্রয়োজন।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '54d0442a04276ab5c7d51af7c5668d44'),
(8912, 825, '‘প্রতিযোগিতা’য় সবসময় কী থাকে?', 'topic', NULL, 'examination', NULL, 'party', NULL, 'participant', NULL, 'D', 'প্রতিযোগিতায় সবসময় অংশগ্রহণকারী (participant) থাকবেই, অন্যথায় এটি প্রতিযোগিতা হবে না।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd9b96dd27f8fb0f3dd67361da7f62778'),
