(8914, 830, 'DC DE FE ?? HG HI সিরিজের প্রশ্নবোধক চিহ্নের স্থানে কোন বিকল্পটি বসবে?', 'DE', NULL, 'ED', NULL, 'FG', NULL, 'GF', NULL, 'C', 'সিরিজ: DC, DE, FE, ?, HG, HI → প্রতি জোড়ায় দ্বিতীয় অক্ষরটি পরবর্তী জোড়ার প্রথম অক্ষরের সাথে মিলছে। DC→DE→FE→FG→HG→HI। তাই ? = FG।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '8eef53c33380e56c3d3ad032ab429926'),
(8915, 835, 'এক ব্যক্তি ৫ মাইল পশ্চিমে, ২ মাইল দক্ষিণে, এর পর আবার ৫ মাইল পশ্চিমে যায়। যাত্রাস্থান থেকে তার সরাসরি দূরত্ব কত?', '৮ মাইল', NULL, '১৫ মাইল', NULL, '১২ মাইল', NULL, 'উপরের কোনটিই নয়', NULL, 'D', 'মোট পশ্চিম = ৫+৫ = ১০, দক্ষিণ = ২। সরাসরি দূরত্ব = √(১০²+২²) = √১০৪ ≈ ১০.২ মাইল → কোন অপশনেই নেই → D।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'd1ae5f4eb42e4194987f068e4ff4180a'),
(8916, 828, 'নিচের শব্দগুলোর মধ্যে ৩টি সমগোত্রীয়। কোন শব্দটি আলাদা?', 'Conventional', NULL, 'Peculiar', NULL, 'Conservative', NULL, 'Traditional', NULL, 'B', 'Conventional, Conservative, Traditional — তিনটিই রক্ষণশীলতার সমার্থক। Peculiar অর্থ অদ্ভুত — আলাদা।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'e368b45ef345ba8eb9c74d7f88018539'),
(8917, 832, 'একটি ছবি দেখিয়ে তিন্নী বললো, ‘সে আমার দাদার একমাত্র ছেলের ছেলে’ ছবির ছেলেটির সাথে তিন্নীর সম্পর্ক কী?', 'ভাই', NULL, 'চাচা', NULL, 'ছেলে', NULL, 'কোন সম্পর্ক নেই', NULL, 'A', 'আমার দাদার একমাত্র ছেলে = আমার বাবা। বাবার ছেলে = আমার ভাই।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'f8dddfdb41cbe8280db6ef5b9d3cd2db'),
(8918, 863, '[চিত্র প্যাটার্ন - V/W উল্টো - চিত্র প্রয়োজন]', '[চিত্র A]', NULL, '[চিত্র B]', NULL, '[চিত্র C]', NULL, '[চিত্র D]', NULL, 'A', '১ম ও ২য় চিত্রে V ও W; ৩য় চিত্রে উল্টো V; তাই পরের চিত্রে উল্টো W হবে।', NULL, 12, '43rd BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', 'চিত্র প্রয়োজন', NULL, '0c3a5e61f75f1ce02f3cbbe68c72689d'),
(8919, 863, '[চিত্র প্যাটার্ন - চিত্র প্রয়োজন]', '১', NULL, '২', NULL, '৩', NULL, '৪', NULL, 'B', '১ম চিত্রে ত্রিভুজটি ২য় চিত্রে দাগাঙ্কিত ত্রিভুজ এবং ৩য় চিত্রের চতুর্ভুজটি ৪র্থ চিত্রে দাগাঙ্কিত চতুর্ভুজ হবে।', NULL, 13, '44th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', 'চিত্র প্রয়োজন', NULL, 'd4591156a3ac0025fe355e499d60ab27'),
(8920, 833, 'P এবং Q দুই ভাই। R এবং S দুই বোন। P এর ছেলে হলো S এর ভাই। তাহলে Q হলো R এর–', 'পুত্র', NULL, 'ভাই', NULL, 'পিতা', NULL, 'চাচা', NULL, 'D', 'P ও Q ভাই; R ও S বোন। P-এর ছেলে = S-এর ভাই → অর্থাৎ P ও S-এর বাবা একই? আসলে P = S-এর বাবা (কারণ P-এর ছেলে S-এর ভাই)। R ও S বোন → R-ও P-এর সন্তান। Q = P-এর ভাই = R-এর চাচা।', NULL, 13, '44th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '6c1499ca50881af0d8e17246e92f3122'),
(8921, 823, 'স্টেপলারের সাথে যেমন স্টেপল, সুচের সাথে তেমন-', 'ছিদ্র', NULL, 'কাপড়', NULL, 'সুতা', NULL, 'সেলাই মেশিন', NULL, 'C', 'স্টেপলারের সাথে যেমন স্টেপল যুক্ত, তেমনি সুচের সাথে সুতা যুক্ত।', NULL, 13, '44th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, '50c462c026b9ae0d0f092bbad1b80d62'),
