(8954, 869, 'একজন মহিলা বলছেন, \"আপনি যদি আমার নিজের বয়সকে উল্টে দেন তাহলে তা আমার স্বামীর বয়সকে নির্দেশ করে। তিনি আমার থেকে বয়সে বড় এবং আমাদের বয়সের পার্থক্য আমাদের মোট বয়সের যোগফলের এগারো ভাগের একভাগ।\" মহিলার বয়স কত?', '২৩ বছর', NULL, '৩৪ বছর', NULL, '৪৫ বছর', NULL, 'কোনোটিই নয়', NULL, 'C', 'মহিলার বয়স ৪৫ → স্বামীর বয়স ৫৪ (উল্টো)। সমষ্টি = ৯৯; ৯৯-এর ১/১১ = ৯; পার্থক্য = ৫৪ − ৪৫ = ৯ — শর্ত সিদ্ধ।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'c044bee8c45926a843f09e80855c0539'),
(8955, 851, 'যদি একটি কামান থেকে নিম্নলিখিত ৪টি বস্তুকে অনুভূমিক ভাবে নিক্ষেপ করা হয়, তবে কোনটি সবচেয়ে বেশি দূরে উড়ে যাবে?', '[চিত্র A]', NULL, '[চিত্র B]', NULL, '[চিত্র C]', NULL, '[চিত্র D]', NULL, 'C', 'গোলাকৃতি বস্তুর আয়তন কম হওয়ায় বাতাসের বাধা কম → সবচেয়ে বেশি দূরে যাবে।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', 'চিত্র প্রয়োজন', NULL, '22ce6696a25db7ff8b23d4944f8d3e92'),
(8956, 869, 'একটি সভায় ১৫ জন লোক রয়েছে এবং তারা সকলেই সভা শেষে একে অপরের সাথে করমর্দন করে। মোট কতটি করমর্দন হবে?', '২১০', NULL, '১০৫', NULL, '২২৫', NULL, '১৯৬', NULL, 'B', 'nC2 = ১৫×১৪/২ = ১০৫টি করমর্দন।', NULL, 15, '46th BCS', '100-100', '100', 'N', NULL, NULL, '2026-10-04', 'softadmin', NULL, NULL, NULL, NULL, '1', 2026, NULL, 'e360', NULL, NULL, 'b0093cc73b6463fc9418f79c3469833e'),
